window.CVICNE_OTAZKY = {"rozpis":{"GenAI-1.1.1":1,"GenAI-1.1.2":2,"GenAI-1.1.3":1,"GenAI-1.1.4":1,"GenAI-1.2.1":1,"GenAI-1.2.2":1,"GenAI-2.1.1":2,"GenAI-2.1.2":1,"GenAI-2.1.3":1,"GenAI-2.2.1":1,"GenAI-2.2.2":1,"GenAI-2.2.3":1,"GenAI-2.2.4":1,"GenAI-2.2.5":1,"GenAI-2.3.1":1,"GenAI-2.3.2":1,"GenAI-3.1.1":1,"GenAI-3.1.2":1,"GenAI-3.1.3":1,"GenAI-3.1.4":1,"GenAI-3.2.1":1,"GenAI-3.2.2":2,"GenAI-3.2.3":1,"GenAI-3.3.1":1,"GenAI-3.4.1":1,"GenAI-4.1.1":1,"GenAI-4.1.2":1,"GenAI-4.1.3":1,"GenAI-4.2.1":1,"GenAI-4.2.2":1,"GenAI-5.1.1":1,"GenAI-5.1.2":1,"GenAI-5.1.3":1,"GenAI-5.1.4":1,"GenAI-5.2.1":1,"GenAI-5.2.2":1,"GenAI-5.2.3":1},"kapitoly":{"1":"Úvod do generativní AI pro testování softwaru","2":"Prompt engineering pro efektivní testování","3":"Řízení rizik generativní AI v testování","4":"Testovací infrastruktura postavená na LLM","5":"Zavedení generativní AI v testovací organizaci"},"lo":{"GenAI-1.1.1":{"k":"K1","text":"Recall different types of AI: symbolic AI, classical machine learning, deep learning, and generative AI"},"GenAI-1.1.2":{"k":"K2","text":"Explain the basics of generative AI and large language models"},"GenAI-1.1.3":{"k":"K2","text":"Distinguish between foundation, instruction-tuned and reasoning LLMs"},"GenAI-1.1.4":{"k":"K2","text":"Write and execute a given prompt addressing a test task using a multimodal LLM model"},"GenAI-1.2.1":{"k":"K2","text":"Give examples of key LLM capabilities for test tasks"},"GenAI-1.2.2":{"k":"K2","text":"Compare interaction models when using GenAI for software testing"},"GenAI-2.1.1":{"k":"K2","text":"Give examples of the structure of prompts used in generative AI for software testing"},"GenAI-2.1.2":{"k":"K2","text":"Differentiate core prompting techniques for software testing"},"GenAI-2.1.3":{"k":"K2","text":"Distinguish between system prompts and user prompts"},"GenAI-2.2.1":{"k":"K3","text":"Apply generative AI to test analysis tasks"},"GenAI-2.2.2":{"k":"K3","text":"Apply generative AI to test design and test implementation tasks"},"GenAI-2.2.3":{"k":"K3","text":"Apply generative AI to automated regression testing"},"GenAI-2.2.4":{"k":"K3","text":"Apply generative AI to test monitoring and control task"},"GenAI-2.2.5":{"k":"K3","text":"Select and apply appropriate prompting techniques for a given context and test task"},"GenAI-2.3.1":{"k":"K2","text":"Understand the metrics for evaluating the results of generative AI on test tasks"},"GenAI-2.3.2":{"k":"K2","text":"Give examples of techniques for evaluating and iteratively refining prompts"},"GenAI-3.1.1":{"k":"K1","text":"Recall the definitions of hallucinations, reasoning errors and biases in Generative AI systems"},"GenAI-3.1.2":{"k":"K3","text":"Identify hallucinations, reasoning errors and biases in LLM output"},"GenAI-3.1.3":{"k":"K2","text":"Summarize mitigation techniques for GenAI hallucinations, reasoning errors and biases in software test tasks"},"GenAI-3.1.4":{"k":"K1","text":"Recall mitigation techniques for non-deterministic behavior of LLMs"},"GenAI-3.2.1":{"k":"K2","text":"Explain key data privacy and security risks associated with using generative AI in software testing"},"GenAI-3.2.2":{"k":"K2","text":"Give examples of data privacy and vulnerabilities in using Generative AI in software testing"},"GenAI-3.2.3":{"k":"K2","text":"Summarize mitigation strategies to protect data privacy and enhance security in Generative AI for software testing"},"GenAI-3.3.1":{"k":"K2","text":"Explain the impact of task characteristics and model usage on the energy consumption of Generative AI in software testing"},"GenAI-3.4.1":{"k":"K1","text":"Recall examples of AI regulations, standards and best practice frameworks relevant to Generative AI in software testing"},"GenAI-4.1.1":{"k":"K2","text":"Explain key architectural components and concepts of LLM-powered test infrastructure"},"GenAI-4.1.2":{"k":"K2","text":"Summarize Retrieval-Augmented Generation"},"GenAI-4.1.3":{"k":"K2","text":"Explain the role and application of LLM-powered agents in automating test processes"},"GenAI-4.2.1":{"k":"K2","text":"Explain the fine-tuning of language models for specific test tasks"},"GenAI-4.2.2":{"k":"K2","text":"Explain LLMOps and its role in deploying and managing LLMs for test tasks"},"GenAI-5.1.1":{"k":"K1","text":"Recall the risks of shadow AI"},"GenAI-5.1.2":{"k":"K2","text":"Explain the key aspects to consider when defining a Generative AI strategy for software testing"},"GenAI-5.1.3":{"k":"K2","text":"Summarize key criteria for selecting LLMs/SLMs for software test tasks in a given context"},"GenAI-5.1.4":{"k":"K1","text":"Recall key phases in the adoption of Generative AI in a test organization"},"GenAI-5.2.1":{"k":"K2","text":"Explain the essential skills and knowledge areas required for testers to work effectively with generative AI in test processes"},"GenAI-5.2.2":{"k":"K1","text":"Recall strategies for cultivating AI skills within test teams to support the adoption of Generative AI in test activities"},"GenAI-5.2.3":{"k":"K1","text":"Recognize how test processes and responsibilities shift within a test organization when adopting Generative AI"}},"lokalni":false,"otazky":[{"id":"CG-1.1.1-01","n":null,"lo":"GenAI-1.1.1","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A bank's loan approval engine checks the applicant's age, income and repayment history against a table of conditions written by business analysts. The engine does not learn from data. Which type of AI does this engine represent?<\/p>","m":["Symbolic AI","Deep learning","Classical machine learning","Generative AI"],"vys":{"a":"Correct. Symbolic AI represents knowledge with symbols and logical rules defined by humans to mimic decision-making (syllabus 1.1.1).","b":"Incorrect. Deep learning uses neural networks that learn features from data; no learning takes place here (syllabus 1.1.1).","c":"Incorrect. Classical machine learning learns from prepared data and selected features; this engine does not learn from data (syllabus 1.1.1).","d":"Incorrect. Generative AI creates new content using deep learning; the engine only evaluates predefined rules (syllabus 1.1.1)."},"obecne":"Rules written by people and no learning from data are the defining traits of symbolic AI."},"cz":{"q":"<p>Systém banky pro schvalování úvěrů porovnává věk, příjem a historii splácení žadatele s tabulkou podmínek, kterou sepsali business analytici. Systém se z dat neučí. Jaký typ AI tento systém představuje?<\/p>","m":["Symbolická AI","Hluboké učení","Klasické strojové učení","Generativní AI"],"vys":{"a":"Správně. Symbolická AI reprezentuje znalost symboly a logickými pravidly, která definoval člověk, a tím napodobuje rozhodování (sylabus 1.1.1).","b":"Nesprávně. Hluboké učení používá neuronové sítě, které se příznaky učí z dat. Tady žádné učení neprobíhá (sylabus 1.1.1).","c":"Nesprávně. Klasické strojové učení se učí z připravených dat a vybraných příznaků. Tento systém se z dat neučí (sylabus 1.1.1).","d":"Nesprávně. Generativní AI vytváří nový obsah pomocí hlubokého učení. Systém jen vyhodnocuje předem daná pravidla (sylabus 1.1.1)."},"obecne":"Pravidla zapsaná člověkem a žádné učení z dat jsou rozlišující znaky symbolické AI."},"kap":{"c":"1.1.1","nazev":"1.1.1 Spektrum AI: symbolická AI, klasické strojové učení, hluboké učení a generativní AI","href":"kapitola-1/vyklad.html#oddil-1-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.1-02","n":null,"lo":"GenAI-1.1.1","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following is a typical part of classical machine learning that deep learning does NOT require users to perform manually?<\/p>","m":["Using the trained model for predictions","Selecting the features the model uses","Validating the results of the model","Providing data to learn from"],"vys":{"a":"Incorrect. Both approaches use the trained model to make predictions; this is not a difference (syllabus 1.1.1).","b":"Correct. Classical machine learning requires feature selection, while deep learning learns features from data automatically (syllabus 1.1.1).","c":"Incorrect. The syllabus notes that deep learning may still require human validation of results (syllabus 1.1.1).","d":"Incorrect. Both approaches are data-driven and need data to learn from (syllabus 1.1.1)."},"obecne":"The difference between classical machine learning and deep learning lies in who defines the features."},"cz":{"q":"<p>Která z následujících činností je typickou součástí klasického strojového učení, ale u hlubokého učení ji uživatel ručně dělat NEMUSÍ?<\/p>","m":["Použití natrénovaného modelu k předpovědím","Výběr příznaků, které model používá","Ověření výsledků modelu","Poskytnutí dat, ze kterých se model učí"],"vys":{"a":"Nesprávně. Oba přístupy používají natrénovaný model k předpovědím, nejde o rozdíl (sylabus 1.1.1).","b":"Správně. Klasické strojové učení vyžaduje výběr příznaků, hluboké učení se příznaky učí z dat samo (sylabus 1.1.1).","c":"Nesprávně. Sylabus uvádí, že i hluboké učení může vyžadovat ověření výsledků člověkem (sylabus 1.1.1).","d":"Nesprávně. Oba přístupy jsou řízené daty a data potřebují (sylabus 1.1.1)."},"obecne":"Klasické ML a hluboké učení se liší v tom, kdo určuje příznaky."},"kap":{"c":"1.1.1","nazev":"1.1.1 Spektrum AI: symbolická AI, klasické strojové učení, hluboké učení a generativní AI","href":"kapitola-1/vyklad.html#oddil-1-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.1-03","n":null,"lo":"GenAI-1.1.1","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which statement about generative AI is CORRECT?<\/p>","m":["It generates content by evaluating logical rules defined by domain experts.","It only assigns existing data items to predefined categories.","It uses deep learning techniques to create new content based on patterns learned from training data.","It requires a separate training phase before it can be used for each test task."],"vys":{"a":"Incorrect. Logical rules defined by experts describe symbolic AI (syllabus 1.1.1).","b":"Incorrect. Assigning data to categories is a typical classification task, e.g. defect categorization with classical machine learning, not content generation (syllabus 1.1.1).","c":"Correct. Generative AI uses deep learning to create new text, images or code by mimicking patterns from its training data (syllabus 1.1.1).","d":"Incorrect. The syllabus highlights that pre-trained models can be applied directly without an additional training phase (syllabus 1.1.1)."},"obecne":"Generative AI = deep learning + creation of new content."},"cz":{"q":"<p>Které tvrzení o generativní AI je SPRÁVNÉ?<\/p>","m":["Vytváří obsah vyhodnocováním logických pravidel, která definovali odborníci.","Pouze zařazuje existující data do předem daných kategorií.","Používá techniky hlubokého učení a vytváří nový obsah podle vzorců naučených z trénovacích dat.","Před použitím pro každou testovací úlohu vyžaduje samostatnou fázi trénování."],"vys":{"a":"Nesprávně. Logická pravidla od odborníků popisují symbolickou AI (sylabus 1.1.1).","b":"Nesprávně. Zařazování dat do kategorií je klasifikační úloha, například kategorizace defektů klasickým ML, ne tvorba obsahu (sylabus 1.1.1).","c":"Správně. Generativní AI používá hluboké učení a vytváří nový text, obrázky nebo kód napodobením vzorců z trénovacích dat (sylabus 1.1.1).","d":"Nesprávně. Sylabus zdůrazňuje, že předtrénované modely lze použít přímo bez další fáze trénování (sylabus 1.1.1)."},"obecne":"Generativní AI = hluboké učení + tvorba nového obsahu."},"kap":{"c":"1.1.1","nazev":"1.1.1 Spektrum AI: symbolická AI, klasické strojové učení, hluboké učení a generativní AI","href":"kapitola-1/vyklad.html#oddil-1-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.1-04","n":null,"lo":"GenAI-1.1.1","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which type of AI is BEST described by the following: it uses neural networks to learn features automatically from large and complex datasets such as images or audio, although humans may still annotate data and validate results?<\/p>","m":["Classical machine learning","Generative AI","Symbolic AI","Deep learning"],"vys":{"a":"Incorrect. Classical machine learning requires manual feature selection (syllabus 1.1.1).","b":"Incorrect. Generative AI builds on deep learning, but its defining trait is the creation of new content, which the description does not mention (syllabus 1.1.1).","c":"Incorrect. Symbolic AI does not learn from data; it uses rules and symbols (syllabus 1.1.1).","d":"Correct. This matches the syllabus description of deep learning, including the note on human involvement (syllabus 1.1.1)."},"obecne":"Automatic learning of features with neural networks is the defining trait of deep learning."},"cz":{"q":"<p>Který typ AI NEJLÉPE odpovídá popisu: používá neuronové sítě, které se samy učí příznaky z velkých a složitých dat, jako jsou obrázky nebo zvuk, ačkoli člověk může stále anotovat data a ověřovat výsledky?<\/p>","m":["Klasické strojové učení","Generativní AI","Symbolická AI","Hluboké učení"],"vys":{"a":"Nesprávně. Klasické strojové učení vyžaduje ruční výběr příznaků (sylabus 1.1.1).","b":"Nesprávně. Generativní AI na hlubokém učení staví, ale jejím rozlišujícím znakem je tvorba nového obsahu, o které popis nemluví (sylabus 1.1.1).","c":"Nesprávně. Symbolická AI se z dat neučí, používá pravidla a symboly (sylabus 1.1.1).","d":"Správně. Popis odpovídá hlubokému učení podle sylabu, včetně poznámky o zapojení člověka (sylabus 1.1.1)."},"obecne":"Automatické učení příznaků neuronovými sítěmi je rozlišující znak hlubokého učení."},"kap":{"c":"1.1.1","nazev":"1.1.1 Spektrum AI: symbolická AI, klasické strojové učení, hluboké učení a generativní AI","href":"kapitola-1/vyklad.html#oddil-1-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.1-05","n":null,"lo":"GenAI-1.1.1","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>According to the syllabus, what is the key advantage of using generative AI for software testing?<\/p>","m":["Pre-trained models can be applied directly to test tasks without an additional training phase.","Generative AI eliminates the risks associated with other AI approaches.","Generated outputs are deterministic, so they can be compared exactly with expected results.","Generative AI removes the need for testers to review the test basis."],"vys":{"a":"Correct. The syllabus names this as the key advantage, while noting that it comes with risks (syllabus 1.1.1).","b":"Incorrect. The syllabus explicitly states that the advantage comes with risks, covered in chapter 3 (syllabus 1.1.1).","c":"Incorrect. LLMs show non-deterministic behavior (syllabus 1.1.2).","d":"Incorrect. LLMs support analysis of the test basis; they do not replace the tester's review (syllabus 1.2.1)."},"obecne":"Pre-trained models usable without extra training is the key advantage; risks remain."},"cz":{"q":"<p>Co je podle sylabu hlavní výhodou použití generativní AI pro testování softwaru?<\/p>","m":["Předtrénované modely lze použít přímo na testovací úlohy bez další fáze trénování.","Generativní AI odstraňuje rizika spojená s jinými přístupy k AI.","Vygenerované výstupy jsou deterministické, takže je lze přesně porovnat s očekávanými výsledky.","Generativní AI odstraňuje potřebu, aby tester revidoval testovací bázi."],"vys":{"a":"Správně. Sylabus to uvádí jako hlavní výhodu a zároveň upozorňuje na rizika (sylabus 1.1.1).","b":"Nesprávně. Sylabus výslovně uvádí, že výhoda s sebou nese rizika, kterým se věnuje kapitola 3 (sylabus 1.1.1).","c":"Nesprávně. LLM se chovají nedeterministicky (sylabus 1.1.2).","d":"Nesprávně. LLM analýzu testovací báze podporují, revizi testerem nenahrazují (sylabus 1.2.1)."},"obecne":"Hlavní výhoda: předtrénovaný model bez dalšího trénování. Rizika zůstávají."},"kap":{"c":"1.1.1","nazev":"1.1.1 Spektrum AI: symbolická AI, klasické strojové učení, hluboké učení a generativní AI","href":"kapitola-1/vyklad.html#oddil-1-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-01","n":null,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A tester pastes the same test case description, once in English and once in Czech, into a tokenizer. The Czech version produces noticeably more tokens. Which explanation is MOST plausible?<\/p>","m":["The Czech text is converted into embeddings before it is tokenized, which adds tokens.","The tokenizer splits less common words, such as inflected words with diacritics, into more sub-word units.","The context window is smaller for Czech text, so the tokenizer must use shorter tokens.","The model translates the Czech text into English and counts tokens of both versions."],"vys":{"a":"Incorrect. Tokenization comes first; embeddings are then created for the tokens (syllabus 1.1.2).","b":"Correct. Tokens can be characters, sub-words or words; words that are rare in the tokenizer's vocabulary are split into more pieces (syllabus 1.1.2).","c":"Incorrect. The context window limits how many tokens the model considers; it does not change how text is split (syllabus 1.1.2).","d":"Incorrect. Tokenization splits the input text as it is; no translation step is involved (syllabus 1.1.2)."},"obecne":"Token count depends on how the tokenizer splits text, not on the number of words."},"cz":{"q":"<p>Tester vloží do tokenizéru stejný popis testovacího případu jednou anglicky a jednou česky. Česká verze má výrazně víc tokenů. Které vysvětlení je NEJPRAVDĚPODOBNĚJŠÍ?<\/p>","m":["Český text se před tokenizací převede na embeddingy, což přidá tokeny.","Tokenizér rozděluje méně častá slova, například skloňovaná slova s diakritikou, na víc částí slov.","Kontextové okno je pro český text menší, takže tokenizér musí použít kratší tokeny.","Model český text přeloží do angličtiny a počítá tokeny obou verzí."],"vys":{"a":"Nesprávně. Tokenizace je první krok, embeddingy se vytvářejí až pro tokeny (sylabus 1.1.2).","b":"Správně. Token může být znak, část slova nebo slovo. Slova, která ve slovníku tokenizéru nejsou častá, se rozdělí na víc kousků (sylabus 1.1.2).","c":"Nesprávně. Kontextové okno omezuje, kolik tokenů model bere v úvahu, nemění způsob dělení textu (sylabus 1.1.2).","d":"Nesprávně. Tokenizace dělí vstupní text tak, jak je. Žádný překlad neprobíhá (sylabus 1.1.2)."},"obecne":"Počet tokenů závisí na tom, jak tokenizér text dělí, ne na počtu slov."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-02","n":null,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>An LLM analysing defect reports treats the words 'defect', 'bug' and 'fault' as closely related. Which concept BEST explains this?<\/p>","m":["The context window stores a list of synonyms for frequently used words.","Non-deterministic behavior makes the model choose between similar words at random.","The embeddings of these tokens are positioned close to each other in a high-dimensional vector space.","Tokenization merges words with similar meaning into a single token."],"vys":{"a":"Incorrect. The context window limits the amount of preceding text considered; it is not a synonym store (syllabus 1.1.2).","b":"Incorrect. Non-determinism causes variation in outputs, not an understanding of related meanings (syllabus 1.1.2).","c":"Correct. Embeddings encode semantic relationships, and tokens with similar meaning have embeddings close together (syllabus 1.1.2).","d":"Incorrect. Tokenization splits text into units; it does not merge words by meaning (syllabus 1.1.2)."},"obecne":"Meaning and similarity are captured by embeddings."},"cz":{"q":"<p>LLM při analýze reportů o defektech zachází se slovy 'defect', 'bug' a 'fault' jako s úzce souvisejícími. Který pojem to NEJLÉPE vysvětluje?<\/p>","m":["Kontextové okno ukládá seznam synonym pro často používaná slova.","Nedeterministické chování způsobuje, že model mezi podobnými slovy vybírá náhodně.","Embeddingy těchto tokenů leží ve vícerozměrném vektorovém prostoru blízko sebe.","Tokenizace slučuje slova s podobným významem do jednoho tokenu."],"vys":{"a":"Nesprávně. Kontextové okno omezuje množství předchozího textu, není to úložiště synonym (sylabus 1.1.2).","b":"Nesprávně. Nedeterminismus způsobuje rozdílné výstupy, ne porozumění příbuzným významům (sylabus 1.1.2).","c":"Správně. Embeddingy zachycují významové vztahy a tokeny s podobným významem mají blízké vektory (sylabus 1.1.2).","d":"Nesprávně. Tokenizace text dělí na jednotky, neslučuje slova podle významu (sylabus 1.1.2)."},"obecne":"Význam a podobnost slov zachycují embeddingy."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-03","n":null,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>An LLM generates an automated API test that looks professional, but it calls an endpoint that does not exist in the system under test. No API specification was given in the prompt. Which characteristic of LLMs BEST explains this result?<\/p>","m":["The context window was too large, so the model lost track of the prompt.","Embeddings are fixed during inference, so the model cannot learn new endpoints.","Tokenization split the endpoint name incorrectly, so the name was changed.","The transformer produces statistically plausible sequences of tokens, which are not necessarily correct."],"vys":{"a":"Incorrect. A larger context window helps the model keep more context; the prompt here was short (syllabus 1.1.2).","b":"Incorrect. The issue is not learning during inference but generating plausible content without the real specification (syllabus 1.1.2).","c":"Incorrect. Tokenization does not alter content; the endpoint was invented by the model (syllabus 1.1.2).","d":"Correct. The model predicts the most plausible continuation based on training data and the prompt; plausible is not necessarily correct (syllabus 1.1.2)."},"obecne":"Plausible is not necessarily correct; outputs must be verified."},"cz":{"q":"<p>LLM vygeneruje automatizovaný test API, který vypadá profesionálně, ale volá endpoint, který v testovaném systému neexistuje. Specifikace API v promptu nebyla. Která vlastnost LLM tento výsledek NEJLÉPE vysvětluje?<\/p>","m":["Kontextové okno bylo příliš velké, takže model ztratil přehled o promptu.","Embeddingy jsou během inference pevné, takže se model nemůže naučit nové endpointy.","Tokenizace chybně rozdělila název endpointu, a ten se proto změnil.","Transformer vytváří statisticky pravděpodobné posloupnosti tokenů, které nemusí být správné."],"vys":{"a":"Nesprávně. Větší kontextové okno pomáhá udržet víc kontextu. Prompt byl navíc krátký (sylabus 1.1.2).","b":"Nesprávně. Problémem není učení během inference, ale generování plauzibilního obsahu bez skutečné specifikace (sylabus 1.1.2).","c":"Nesprávně. Tokenizace obsah nemění. Endpoint si model vymyslel (sylabus 1.1.2).","d":"Správně. Model předpovídá nejpravděpodobnější pokračování podle trénovacích dat a promptu. Pravděpodobné neznamená správné (sylabus 1.1.2)."},"obecne":"Pravděpodobné neznamená správné, výstupy je nutné ověřit."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-04","n":null,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A tester runs the same prompt twice with identical input data and receives two different sets of test cases. Which explanation is CORRECT?<\/p>","m":["LLM inference is probabilistic and depends on hyperparameter settings.","The model was retrained between the two runs using the first result.","The context window was cleared, so the second run used different training data.","The tokenizer splits the same text into different tokens on each run."],"vys":{"a":"Correct. Non-deterministic behavior is caused mainly by the probabilistic nature of inference and hyperparameter settings (syllabus 1.1.2).","b":"Incorrect. Using a model does not retrain it; the variation comes from inference (syllabus 1.1.2).","c":"Incorrect. The context window does not contain training data; it limits the text considered when generating (syllabus 1.1.2).","d":"Incorrect. Tokenization of the same text with the same tokenizer is consistent; the variation comes from token selection during generation (syllabus 1.1.2)."},"obecne":"Non-determinism: same input, different outputs, caused by probabilistic inference and hyperparameters."},"cz":{"q":"<p>Tester spustí dvakrát stejný prompt se stejnými vstupními daty a dostane dvě různé sady testovacích případů. Které vysvětlení je SPRÁVNÉ?<\/p>","m":["Inference LLM je pravděpodobnostní a závisí na nastavení hyperparametrů.","Model byl mezi oběma běhy přetrénován s využitím prvního výsledku.","Kontextové okno se vymazalo, takže druhý běh použil jiná trénovací data.","Tokenizér rozdělí stejný text při každém běhu na jiné tokeny."],"vys":{"a":"Správně. Nedeterministické chování způsobuje hlavně pravděpodobnostní povaha inference a nastavení hyperparametrů (sylabus 1.1.2).","b":"Nesprávně. Používáním se model nepřetrénovává. Rozdíl vzniká při inferenci (sylabus 1.1.2).","c":"Nesprávně. Kontextové okno neobsahuje trénovací data. Omezuje text, který model bere v úvahu při generování (sylabus 1.1.2).","d":"Nesprávně. Stejný tokenizér rozdělí stejný text stejně. Rozdíl vzniká při výběru tokenů během generování (sylabus 1.1.2)."},"obecne":"Nedeterminismus: stejný vstup, různé výstupy. Příčinou je pravděpodobnostní inference a hyperparametry."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-05","n":null,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A tester gives an LLM a very long test execution log and asks for a list of all failures. Failures recorded near the beginning of the log are missing from the answer. Which action BEST addresses the cause of this problem?<\/p>","m":["Replace the log with screenshots of the test runner so that a multimodal model can process it.","Reduce the input to the relevant parts or split the log into segments that fit within the context window.","Ask the model to tokenize the log more carefully before answering.","Run the same prompt again, because the next answer will probably include all failures."],"vys":{"a":"Incorrect. Images are also converted into tokens and embeddings, so the context window limit remains (syllabus 1.1.4).","b":"Correct. The log exceeds the context window, so earlier content is not considered; giving the model less or segmented input addresses this (syllabus 1.1.2).","c":"Incorrect. Tokenization is not influenced by instructions in the prompt, and it is not the cause (syllabus 1.1.2).","d":"Incorrect. Repeating the prompt does not change the context window limit; the same information is still lost (syllabus 1.1.2)."},"obecne":"Content that does not fit into the context window is not considered by the model."},"cz":{"q":"<p>Tester dá LLM velmi dlouhý log z provedení testů a požádá o seznam všech selhání. Selhání zapsaná blízko začátku logu v odpovědi chybějí. Který krok NEJLÉPE řeší příčinu problému?<\/p>","m":["Nahradit log snímky obrazovky z nástroje pro spouštění testů, aby ho zpracoval multimodální model.","Zmenšit vstup na relevantní části nebo rozdělit log na úseky, které se vejdou do kontextového okna.","Požádat model, aby log před odpovědí tokenizoval pečlivěji.","Spustit stejný prompt znovu, protože další odpověď nejspíš bude obsahovat všechna selhání."],"vys":{"a":"Nesprávně. I obrázky se převádějí na tokeny a embeddingy, takže limit kontextového okna zůstává (sylabus 1.1.4).","b":"Správně. Log přesahuje kontextové okno, takže starší obsah model nebere v úvahu. Menší nebo rozdělený vstup to řeší (sylabus 1.1.2).","c":"Nesprávně. Tokenizaci instrukce v promptu neovlivní a není příčinou (sylabus 1.1.2).","d":"Nesprávně. Opakování promptu nemění limit kontextového okna. Stejná informace se ztratí znovu (sylabus 1.1.2)."},"obecne":"Co se nevejde do kontextového okna, model nebere v úvahu."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-06","n":null,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which statement about increasing the size of an LLM's context window is CORRECT?<\/p>","m":["It makes the model's outputs deterministic because more context is available.","It reduces the number of tokens needed to represent the same input text.","It helps the model maintain coherence over longer passages but increases computational complexity and processing time.","It removes the need to verify outputs because the model sees all relevant information."],"vys":{"a":"Incorrect. Non-determinism comes from probabilistic inference and hyperparameters, not from context size (syllabus 1.1.2).","b":"Incorrect. The number of tokens depends on tokenization, not on the size of the context window (syllabus 1.1.2).","c":"Correct. The syllabus describes both the benefit (coherence over long text, e.g. large test logs) and the cost (computation and time) (syllabus 1.1.2).","d":"Incorrect. Generated text remains plausible but not necessarily correct, regardless of context size (syllabus 1.1.2)."},"obecne":"Larger context window: more coherence, more computation."},"cz":{"q":"<p>Které tvrzení o zvětšení kontextového okna LLM je SPRÁVNÉ?<\/p>","m":["Díky většímu kontextu jsou výstupy modelu deterministické.","Snižuje počet tokenů potřebných k reprezentaci stejného vstupního textu.","Pomáhá modelu udržet souvislost v delších textech, ale zvyšuje výpočetní náročnost a dobu zpracování.","Odstraňuje potřebu ověřovat výstupy, protože model vidí všechny relevantní informace."],"vys":{"a":"Nesprávně. Nedeterminismus vychází z pravděpodobnostní inference a hyperparametrů, ne z velikosti kontextu (sylabus 1.1.2).","b":"Nesprávně. Počet tokenů závisí na tokenizaci, ne na velikosti kontextového okna (sylabus 1.1.2).","c":"Správně. Sylabus popisuje přínos (souvislost v dlouhém textu, například ve velkých testovacích lozích) i cenu (výpočet a čas) (sylabus 1.1.2).","d":"Nesprávně. Vygenerovaný text je pravděpodobný, ale ne nutně správný, bez ohledu na velikost kontextu (sylabus 1.1.2)."},"obecne":"Větší kontextové okno: víc souvislostí, víc výpočtu."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-07","n":null,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>In which situation is a small language model (SLM) the MOST appropriate choice instead of a large language model?<\/p>","m":["The team needs to process screenshots, audio recordings and text in one prompt.","The team needs the largest possible context window to analyse complete specifications.","The team needs high-quality answers to open questions from many different domains.","The team needs a lightweight model for one focused task, such as classifying log lines on a server with limited computing resources."],"vys":{"a":"Incorrect. This requires a multimodal model; being small is not the relevant property (syllabus 1.1.4).","b":"Incorrect. Nothing in the syllabus links SLMs to large context windows; their benefit is being compact and focused (syllabus 1.1.2).","c":"Incorrect. Broad, multi-domain tasks favour LLMs with more parameters and wider training (syllabus 1.1.2).","d":"Correct. SLMs have fewer parameters and are designed for lightweight and focused GenAI solutions (syllabus 1.1.2)."},"obecne":"SLM = fewer parameters, lightweight, focused."},"cz":{"q":"<p>Ve které situaci je malý jazykový model (SLM) NEJVHODNĚJŠÍ volbou místo velkého jazykového modelu?<\/p>","m":["Tým potřebuje v jednom promptu zpracovat snímky obrazovky, zvukové nahrávky a text.","Tým potřebuje co největší kontextové okno pro analýzu kompletních specifikací.","Tým potřebuje kvalitní odpovědi na otevřené otázky z mnoha různých oborů.","Tým potřebuje lehký model pro jednu zaměřenou úlohu, například třídění řádků logu na serveru s omezeným výpočetním výkonem."],"vys":{"a":"Nesprávně. To vyžaduje multimodální model. Velikost modelu tu není podstatná vlastnost (sylabus 1.1.4).","b":"Nesprávně. Sylabus SLM s velkým kontextovým oknem nespojuje. Jejich přínos je kompaktnost a zaměření (sylabus 1.1.2).","c":"Nesprávně. Široké úlohy napříč obory svědčí LLM s víc parametry a širším tréninkem (sylabus 1.1.2).","d":"Správně. SLM mají méně parametrů a jsou navržené jako lehká a zaměřená řešení GenAI (sylabus 1.1.2)."},"obecne":"SLM = méně parametrů, lehké, zaměřené řešení."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-08","n":null,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":2,"ok":[0,2],"en":{"q":"<p>Which TWO statements about tokens and tokenization are CORRECT?<\/p>","m":["The number of tokens in an input determines how much of the context window it uses.","Each token always corresponds to exactly one word.","Punctuation marks and special characters can be represented as separate tokens.","Tokens are vectors that capture the semantic meaning of words.","Tokenization takes place after the model has generated its response."],"vys":{"a":"Correct. The context window is measured in tokens (syllabus 1.1.2).","b":"Incorrect. A token can be a character, a sub-word or a word (syllabus 1.1.2).","c":"Correct. Tokenization breaks text into units that may be as small as a character, including punctuation (syllabus 1.1.2).","d":"Incorrect. Vectors that capture meaning are embeddings, not tokens (syllabus 1.1.2).","e":"Incorrect. The model first tokenizes the input so that it can process it (syllabus 1.1.2)."},"obecne":"Tokens are units of text; embeddings are their vectors; the context window is measured in tokens."},"cz":{"q":"<p>Která DVĚ tvrzení o tokenech a tokenizaci jsou SPRÁVNÁ?<\/p>","m":["Počet tokenů ve vstupu určuje, jakou část kontextového okna vstup zabere.","Každý token vždy odpovídá právě jednomu slovu.","Interpunkce a speciální znaky mohou být samostatnými tokeny.","Tokeny jsou vektory, které zachycují význam slov.","Tokenizace probíhá až poté, co model vygeneruje odpověď."],"vys":{"a":"Správně. Kontextové okno se měří v tokenech (sylabus 1.1.2).","b":"Nesprávně. Token může být znak, část slova nebo slovo (sylabus 1.1.2).","c":"Správně. Tokenizace dělí text na jednotky, které mohou být malé jako jeden znak, včetně interpunkce (sylabus 1.1.2).","d":"Nesprávně. Vektory s významem jsou embeddingy, ne tokeny (sylabus 1.1.2).","e":"Nesprávně. Model vstup nejdřív tokenizuje, aby ho mohl zpracovat (sylabus 1.1.2)."},"obecne":"Tokeny jsou jednotky textu, embeddingy jejich vektory, kontextové okno se měří v tokenech."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-09","n":null,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which statement BEST describes how an LLM produces its answer during inference?<\/p>","m":["It first generates embeddings and then converts them back into the original training texts.","It repeatedly predicts the next token, using relationships between tokens learned during training.","It applies grammar rules written by linguists to assemble a sentence.","It looks up a stored answer that matches the prompt in its training data."],"vys":{"a":"Incorrect. Embeddings represent tokens numerically; the model does not reconstruct training texts (syllabus 1.1.2).","b":"Correct. During inference, LLMs predict the next token in a sequence using learned relationships (syllabus 1.1.2).","c":"Incorrect. Hand-written rules describe symbolic AI, not LLMs (syllabus 1.1.1).","d":"Incorrect. LLMs generate new text; they do not retrieve stored answers (syllabus 1.1.2)."},"obecne":"Inference = next-token prediction, token by token."},"cz":{"q":"<p>Které tvrzení NEJLÉPE popisuje, jak LLM při inferenci vytváří odpověď?<\/p>","m":["Nejdřív vytvoří embeddingy a ty pak převede zpět na původní trénovací texty.","Opakovaně předpovídá další token a využívá přitom vztahy mezi tokeny naučené při trénování.","Použije gramatická pravidla sepsaná lingvisty a z nich sestaví větu.","Vyhledá v trénovacích datech uloženou odpověď, která odpovídá promptu."],"vys":{"a":"Nesprávně. Embeddingy reprezentují tokeny číselně. Model trénovací texty nerekonstruuje (sylabus 1.1.2).","b":"Správně. Při inferenci LLM předpovídá další token v posloupnosti podle naučených vztahů (sylabus 1.1.2).","c":"Nesprávně. Ručně psaná pravidla popisují symbolickou AI, ne LLM (sylabus 1.1.1).","d":"Nesprávně. LLM vytvářejí nový text, nevyhledávají uložené odpovědi (sylabus 1.1.2)."},"obecne":"Inference = předpověď dalšího tokenu, jeden po druhém."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.3-01","n":null,"lo":"GenAI-1.1.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A test team needs an LLM to generate test data records that follow an exact JSON schema with the team's field naming conventions. The task requires no complex analysis. Which type of LLM is the BEST fit?<\/p>","m":["Foundation LLM","Vision-language model","Instruction-tuned LLM","Reasoning LLM"],"vys":{"a":"Incorrect. Foundation LLMs typically need further adaptation to meet specific task requirements such as a fixed format (syllabus 1.1.3).","b":"Incorrect. The task involves no visual input (syllabus 1.1.4).","c":"Correct. Instruction-tuned LLMs are optimised for task adherence and instruction following, which suits strict format requirements (syllabus 1.1.3).","d":"Incorrect. Reasoning LLMs target multi-step problem-solving; this task mainly needs precise instruction following (syllabus 1.1.3)."},"obecne":"Exact format and clear instructions point to an instruction-tuned LLM."},"cz":{"q":"<p>Testovací tým potřebuje, aby LLM vygeneroval záznamy testovacích dat přesně podle schématu JSON s konvencemi pojmenování polí, které tým používá. Úloha nevyžaduje složitou analýzu. Který typ LLM se hodí NEJLÉPE?<\/p>","m":["Základní (foundation) LLM","Model pro obraz a jazyk","LLM vyladěný na instrukce","Uvažující (reasoning) LLM"],"vys":{"a":"Nesprávně. Základní LLM obvykle potřebují další přizpůsobení, aby splnily konkrétní požadavky, jako je pevný formát (sylabus 1.1.3).","b":"Nesprávně. Úloha nemá žádný vizuální vstup (sylabus 1.1.4).","c":"Správně. LLM vyladěné na instrukce jsou optimalizované na dodržení úlohy a plnění instrukcí, což odpovídá přísným požadavkům na formát (sylabus 1.1.3).","d":"Nesprávně. Uvažující LLM míří na řešení problémů o více krocích. Tady jde hlavně o přesné plnění instrukcí (sylabus 1.1.3)."},"obecne":"Přesný formát a jasné instrukce vedou na LLM vyladěný na instrukce."},"kap":{"c":"1.1.3","nazev":"1.1.3 Základní, instrukční a uvažující LLM","href":"kapitola-1/vyklad.html#oddil-1-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.3-02","n":null,"lo":"GenAI-1.1.3","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which statement BEST describes how instruction-tuned LLMs are created?<\/p>","m":["They are trained from scratch only on tasks that require chain-of-thought reasoning.","They are created by adding hand-written rules on top of a foundation model.","They are derived from reasoning models by removing the intermediate reasoning steps.","They are derived from foundation models by fine-tuning on datasets that pair prompts with expected responses."],"vys":{"a":"Incorrect. Training on chain-of-thought tasks describes reasoning LLMs, which extend instruction-tuned models (syllabus 1.1.3).","b":"Incorrect. Hand-written rules are typical of symbolic AI; instruction tuning is a training process (syllabus 1.1.1, 1.1.3).","c":"Incorrect. The order is the opposite: reasoning LLMs build on instruction-tuned LLMs (syllabus 1.1.3).","d":"Correct. Instruction tuning fine-tunes a foundation model with prompt and response pairs to improve alignment with instructions (syllabus 1.1.3)."},"obecne":"Order of stages: foundation, instruction-tuned, reasoning."},"cz":{"q":"<p>Které tvrzení NEJLÉPE popisuje, jak vznikají LLM vyladěné na instrukce?<\/p>","m":["Trénují se od začátku pouze na úlohách, které vyžadují uvažování v řetězci kroků.","Vznikají přidáním ručně psaných pravidel nad základní model.","Vznikají z uvažujících modelů odstraněním mezikroků uvažování.","Vznikají ze základních modelů doladěním na datových sadách, které párují prompty s očekávanými odpověďmi."],"vys":{"a":"Nesprávně. Trénink na úlohách s řetězcem kroků popisuje uvažující LLM, které modely vyladěné na instrukce rozšiřují (sylabus 1.1.3).","b":"Nesprávně. Ručně psaná pravidla jsou typická pro symbolickou AI. Ladění na instrukce je proces trénování (sylabus 1.1.1, 1.1.3).","c":"Nesprávně. Pořadí je opačné: uvažující LLM stavějí na modelech vyladěných na instrukce (sylabus 1.1.3).","d":"Správně. Ladění na instrukce dolaďuje základní model na dvojicích prompt a odpověď, aby lépe odpovídal pokynům (sylabus 1.1.3)."},"obecne":"Pořadí fází: základní, vyladěný na instrukce, uvažující."},"kap":{"c":"1.1.3","nazev":"1.1.3 Základní, instrukční a uvažující LLM","href":"kapitola-1/vyklad.html#oddil-1-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.3-03","n":null,"lo":"GenAI-1.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A test manager wants an LLM to combine test results from several releases, defect reports and the history of code changes in order to recommend where to focus regression testing. Which type of LLM is MOST suitable, and why?<\/p>","m":["A reasoning LLM, because the task requires multi-step inference and synthesis of complex information.","Any type, because the three types differ only in the number of parameters.","An instruction-tuned LLM, because the main challenge of the task is following the output format.","A foundation LLM, because it was trained on the largest and most diverse dataset."],"vys":{"a":"Correct. Reasoning LLMs are suited to high-cognitive-load tasks involving intermediate reasoning steps and synthesis of complex information (syllabus 1.1.3).","b":"Incorrect. The types differ in their training stages and capabilities, not just in size (syllabus 1.1.3).","c":"Incorrect. Format is not the main challenge here; the task requires combining sources and drawing conclusions (syllabus 1.1.3).","d":"Incorrect. Broad pre-training does not make foundation LLMs well adapted to specific complex tasks; they typically need further adaptation (syllabus 1.1.3)."},"obecne":"Synthesis of multiple sources and drawing conclusions point to a reasoning LLM."},"cz":{"q":"<p>Test manažer chce, aby LLM propojil výsledky testů z několika vydání, reporty o defektech a historii změn kódu a doporučil, kam soustředit regresní testování. Který typ LLM je NEJVHODNĚJŠÍ a proč?<\/p>","m":["Uvažující LLM, protože úloha vyžaduje vícekrokové vyvozování a syntézu složitých informací.","Jakýkoli typ, protože tři typy se liší jen počtem parametrů.","LLM vyladěný na instrukce, protože hlavní obtíží úlohy je dodržení formátu výstupu.","Základní LLM, protože byl natrénován na největší a nejpestřejší sadě dat."],"vys":{"a":"Správně. Uvažující LLM se hodí na kognitivně náročné úlohy s mezikroky a syntézou složitých informací (sylabus 1.1.3).","b":"Nesprávně. Typy se liší fázemi trénování a schopnostmi, ne jen velikostí (sylabus 1.1.3).","c":"Nesprávně. Formát tu není hlavní obtíž. Úloha vyžaduje propojit zdroje a vyvodit závěry (sylabus 1.1.3).","d":"Nesprávně. Široké předtrénování nedělá ze základního modelu model přizpůsobený konkrétní složité úloze. Obvykle potřebuje další přizpůsobení (sylabus 1.1.3)."},"obecne":"Syntéza více zdrojů a vyvozování závěrů vedou na uvažující LLM."},"kap":{"c":"1.1.3","nazev":"1.1.3 Základní, instrukční a uvažující LLM","href":"kapitola-1/vyklad.html#oddil-1-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.3-04","n":null,"lo":"GenAI-1.1.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which statement about foundation LLMs is CORRECT?<\/p>","m":["They are specifically optimised to follow user instructions and output formats.","They are general-purpose models trained on vast and diverse data, and typically require further adaptation for specific tasks.","They are always the best choice for test tasks because they know the most.","They are trained only on source code and are therefore limited to test automation."],"vys":{"a":"Incorrect. Optimisation for instruction following is the result of instruction tuning (syllabus 1.1.3).","b":"Correct. Foundation LLMs are powerful and flexible but typically need further adaptation to meet specific task requirements (syllabus 1.1.3).","c":"Incorrect. The syllabus states that in testing, instruction-tuned and reasoning LLMs are used, chosen by task complexity (syllabus 1.1.3).","d":"Incorrect. Their training data is diverse, including text, code, images and other modalities (syllabus 1.1.3)."},"obecne":"Foundation LLM: general-purpose, flexible, needs adaptation."},"cz":{"q":"<p>Které tvrzení o základních (foundation) LLM je SPRÁVNÉ?<\/p>","m":["Jsou speciálně optimalizované na plnění instrukcí uživatele a formátů výstupu.","Jsou to univerzální modely natrénované na obrovských a pestrých datech a pro konkrétní úlohy obvykle potřebují další přizpůsobení.","Jsou pro testovací úlohy vždy nejlepší volbou, protože toho vědí nejvíc.","Jsou natrénované jen na zdrojovém kódu, a proto se omezují na automatizaci testů."],"vys":{"a":"Nesprávně. Optimalizace na plnění instrukcí je výsledkem ladění na instrukce (sylabus 1.1.3).","b":"Správně. Základní LLM jsou silné a flexibilní, ale pro konkrétní požadavky úlohy je obvykle nutné je dál přizpůsobit (sylabus 1.1.3).","c":"Nesprávně. Sylabus uvádí, že v testování se používají modely vyladěné na instrukce a uvažující modely podle složitosti úlohy (sylabus 1.1.3).","d":"Nesprávně. Jejich trénovací data jsou pestrá: text, kód, obrázky a další modality (sylabus 1.1.3)."},"obecne":"Základní LLM: univerzální, flexibilní, potřebuje přizpůsobení."},"kap":{"c":"1.1.3","nazev":"1.1.3 Základní, instrukční a uvažující LLM","href":"kapitola-1/vyklad.html#oddil-1-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.3-05","n":null,"lo":"GenAI-1.1.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which statement about selecting between instruction-tuned and reasoning LLMs for test tasks is CORRECT?<\/p>","m":["Reasoning LLMs should always be selected because they are the most advanced type.","Foundation LLMs should be preferred, because both other types are restricted versions of them.","The selection depends on the complexity and reasoning demands of the specific test task.","Instruction-tuned LLMs are not suitable for software testing because they cannot reason at all."],"vys":{"a":"Incorrect. More advanced does not mean better for every task; simple format-driven tasks do not need a reasoning LLM (syllabus 1.1.3).","b":"Incorrect. The other types are further specialised, not restricted; foundation LLMs typically need adaptation (syllabus 1.1.3).","c":"Correct. The syllabus states that the choice depends on the complexity and reasoning demands of the testing task (syllabus 1.1.3).","d":"Incorrect. The syllabus states that both instruction-tuned and reasoning LLMs are used in testing (syllabus 1.1.3)."},"obecne":"Model choice depends on task complexity."},"cz":{"q":"<p>Které tvrzení o volbě mezi LLM vyladěným na instrukce a uvažujícím LLM pro testovací úlohy je SPRÁVNÉ?<\/p>","m":["Vždy je třeba zvolit uvažující LLM, protože je to nejpokročilejší typ.","Přednost mají základní LLM, protože oba další typy jsou jejich omezené verze.","Volba závisí na složitosti a nárocích na uvažování konkrétní testovací úlohy.","LLM vyladěné na instrukce se pro testování nehodí, protože vůbec neumějí uvažovat."],"vys":{"a":"Nesprávně. Pokročilejší neznamená lepší pro každou úlohu. Jednoduché formátové úlohy uvažující LLM nepotřebují (sylabus 1.1.3).","b":"Nesprávně. Další typy jsou dál specializované, ne omezené. Základní LLM obvykle přizpůsobení potřebují (sylabus 1.1.3).","c":"Správně. Sylabus uvádí, že volba závisí na složitosti úlohy a nárocích na uvažování (sylabus 1.1.3).","d":"Nesprávně. Sylabus uvádí, že v testování se používají oba typy (sylabus 1.1.3)."},"obecne":"Volba modelu závisí na složitosti úlohy."},"kap":{"c":"1.1.3","nazev":"1.1.3 Základní, instrukční a uvažující LLM","href":"kapitola-1/vyklad.html#oddil-1-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.4-01","n":null,"lo":"GenAI-1.1.4","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester wants to check whether a screenshot of a payment confirmation page matches the expected result described in a test case. Which type of model is specifically designed to combine these two inputs?<\/p>","m":["A small language model","A text-only instruction-tuned LLM","A symbolic AI system","A vision-language model"],"vys":{"a":"Incorrect. Being small says nothing about the ability to process images (syllabus 1.1.2).","b":"Incorrect. A text-only model cannot process the screenshot (syllabus 1.1.4).","c":"Incorrect. Symbolic AI uses rules and symbols; it is not designed for image and text analysis (syllabus 1.1.1).","d":"Correct. Vision-language models integrate visual and textual information, e.g. to analyse consistency between text and image (syllabus 1.1.4)."},"obecne":"Image plus text points to a vision-language model."},"cz":{"q":"<p>Tester chce ověřit, zda snímek obrazovky s potvrzením platby odpovídá očekávanému výsledku popsanému v testovacím případu. Který typ modelu je speciálně určen ke spojení těchto dvou vstupů?<\/p>","m":["Malý jazykový model","Čistě textový LLM vyladěný na instrukce","Systém symbolické AI","Model pro obraz a jazyk (vision-language model)"],"vys":{"a":"Nesprávně. Malá velikost modelu nic neříká o schopnosti zpracovat obrázky (sylabus 1.1.2).","b":"Nesprávně. Čistě textový model snímek obrazovky nezpracuje (sylabus 1.1.4).","c":"Nesprávně. Symbolická AI používá pravidla a symboly, na analýzu obrazu a textu určená není (sylabus 1.1.1).","d":"Správně. Modely pro obraz a jazyk propojují vizuální a textovou informaci, například při analýze souladu textu a obrazu (sylabus 1.1.4)."},"obecne":"Obraz a text dohromady vedou na model pro obraz a jazyk."},"kap":{"c":"1.1.4","nazev":"1.1.4 Multimodální LLM a modely pro obraz a jazyk","href":"kapitola-1/vyklad.html#oddil-1-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.4-02","n":null,"lo":"GenAI-1.1.4","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>How does a multimodal LLM process an image that is submitted together with a text prompt?<\/p>","m":["The image is converted into embeddings, for example using a vision-language model, and processed by the transformer together with the text.","The image is split by the same text tokenizer into characters before processing.","The image is converted into plain text by character recognition, and only the text is processed.","The image is stored separately and the transformer processes only the text prompt."],"vys":{"a":"Correct. Tokenization is adapted for each data type; images are converted into embeddings before being processed in the transformer (syllabus 1.1.4).","b":"Incorrect. Tokenization is adapted to the modality; images are not treated as text characters (syllabus 1.1.4).","c":"Incorrect. Multimodal models process the visual information itself, not only extracted text (syllabus 1.1.4).","d":"Incorrect. The transformer processes the image representation along with the text (syllabus 1.1.4)."},"obecne":"Each modality has its own tokenization; images become embeddings."},"cz":{"q":"<p>Jak multimodální LLM zpracuje obrázek, který dostane spolu s textovým promptem?<\/p>","m":["Obrázek se převede na embeddingy, například pomocí modelu pro obraz a jazyk, a transformer ho zpracuje spolu s textem.","Obrázek se před zpracováním rozdělí stejným textovým tokenizérem na znaky.","Obrázek se rozpoznáním znaků převede na prostý text a zpracuje se jen tento text.","Obrázek se uloží zvlášť a transformer zpracuje jen textový prompt."],"vys":{"a":"Správně. Tokenizace se přizpůsobí každému druhu dat. Obrázky se převedou na embeddingy a ty zpracuje transformer (sylabus 1.1.4).","b":"Nesprávně. Tokenizace se přizpůsobuje modalitě. Obrázky se nezpracovávají jako textové znaky (sylabus 1.1.4).","c":"Nesprávně. Multimodální modely zpracují samotnou vizuální informaci, ne jen vytažený text (sylabus 1.1.4).","d":"Nesprávně. Transformer zpracuje reprezentaci obrázku spolu s textem (sylabus 1.1.4)."},"obecne":"Každá modalita má vlastní tokenizaci, obrázky se mění na embeddingy."},"kap":{"c":"1.1.4","nazev":"1.1.4 Multimodální LLM a modely pro obraz a jazyk","href":"kapitola-1/vyklad.html#oddil-1-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.4-03","n":null,"lo":"GenAI-1.1.4","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following is a typical task of vision-language models?<\/p>","m":["Generating unit tests from source code without any visual input.","Answering a question about the content of a screenshot, such as whether an error message is visible.","Transcribing audio recordings of review meetings into minutes.","Predicting defect-prone modules from code metrics."],"vys":{"a":"Incorrect. A text-only task does not need a vision-language model (syllabus 1.1.4).","b":"Correct. Visual question answering is one of the tasks the syllabus lists for vision-language models (syllabus 1.1.4).","c":"Incorrect. Audio transcription involves the audio modality, which is outside the visual and textual focus of vision-language models (syllabus 1.1.4).","d":"Incorrect. Prediction from code metrics is a typical use of classical machine learning (syllabus 1.1.1)."},"obecne":"Typical VLM tasks: image captioning, visual question answering, text and image consistency."},"cz":{"q":"<p>Která z následujících úloh je typická pro modely pro obraz a jazyk?<\/p>","m":["Generování jednotkových testů ze zdrojového kódu bez vizuálního vstupu.","Odpověď na otázku k obsahu snímku obrazovky, například zda je vidět chybová hláška.","Přepis zvukových nahrávek z revizních schůzek do zápisu.","Předpověď modulů náchylných k defektům z metrik kódu."],"vys":{"a":"Nesprávně. Čistě textová úloha model pro obraz a jazyk nepotřebuje (sylabus 1.1.4).","b":"Správně. Odpovídání na otázky k obrázku (visual question answering) je jedna z úloh, které sylabus u těchto modelů uvádí (sylabus 1.1.4).","c":"Nesprávně. Přepis zvuku pracuje se zvukovou modalitou, která je mimo zaměření modelů pro obraz a jazyk (sylabus 1.1.4).","d":"Nesprávně. Předpověď z metrik kódu je typické použití klasického strojového učení (sylabus 1.1.1)."},"obecne":"Typické úlohy VLM: popis obrázku, odpovídání na otázky k obrázku, soulad textu a obrazu."},"kap":{"c":"1.1.4","nazev":"1.1.4 Multimodální LLM a modely pro obraz a jazyk","href":"kapitola-1/vyklad.html#oddil-1-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.4-04","n":null,"lo":"GenAI-1.1.4","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A tester gives a multimodal LLM a screenshot of a form together with the related user story and asks it to list discrepancies. Which of the following is a realistic challenge of this approach?<\/p>","m":["The model can process the screenshot only if the user story is removed from the prompt.","The model will correct the user interface of the application automatically.","The model may misread small text or report interface elements that are not present.","Multimodal LLMs cannot be used to derive test cases from visual input."],"vys":{"a":"Incorrect. Multimodal models are designed to process image and text together (syllabus 1.1.4).","b":"Incorrect. The model analyses the inputs; it does not change the application (syllabus 1.1.4).","c":"Correct. Model outputs are plausible but not necessarily correct; misreading details is a typical challenge, so findings must be verified (syllabus 1.1.2, 1.1.4).","d":"Incorrect. The syllabus states that such models can generate test cases that combine text and visual cues (syllabus 1.1.4)."},"obecne":"Multimodal analysis brings benefits and challenges; results need human verification."},"cz":{"q":"<p>Tester dá multimodálnímu LLM snímek obrazovky formuláře spolu s příslušným uživatelským scénářem a požádá o seznam nesouladů. Které z následujícího je reálným úskalím tohoto postupu?<\/p>","m":["Model snímek zpracuje jen tehdy, když se uživatelský scénář z promptu odstraní.","Model uživatelské rozhraní aplikace automaticky opraví.","Model může špatně přečíst drobný text nebo nahlásit prvky rozhraní, které na snímku nejsou.","Multimodální LLM nelze použít k odvození testovacích případů z vizuálního vstupu."],"vys":{"a":"Nesprávně. Multimodální modely jsou navržené tak, aby zpracovaly obraz a text společně (sylabus 1.1.4).","b":"Nesprávně. Model vstupy analyzuje, aplikaci nemění (sylabus 1.1.4).","c":"Správně. Výstupy modelu jsou pravděpodobné, ale ne nutně správné. Chybné čtení detailů je typické úskalí, proto se zjištění ověřují (sylabus 1.1.2, 1.1.4).","d":"Nesprávně. Sylabus uvádí, že tyto modely umí vytvořit testovací případy kombinující text a vizuální podněty (sylabus 1.1.4)."},"obecne":"Multimodální analýza má přínosy i úskalí, výsledky ověřuje člověk."},"kap":{"c":"1.1.4","nazev":"1.1.4 Multimodální LLM a modely pro obraz a jazyk","href":"kapitola-1/vyklad.html#oddil-1-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.4-05","n":null,"lo":"GenAI-1.1.4","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>How can multimodal LLMs, especially those augmented with vision-language models, help increase test coverage?<\/p>","m":["By executing the same test cases on several devices in parallel.","By removing the need for a test basis, because the screenshot defines the expected behaviour.","By replacing reviews of user stories with automatic image comparison.","By generating test cases that combine textual data with visual cues from wireframes."],"vys":{"a":"Incorrect. Test execution on devices is not a capability of the model (syllabus 1.2.1).","b":"Incorrect. A screenshot shows actual behaviour; expected results still come from the test basis (syllabus 1.1.4).","c":"Incorrect. Multimodal models support the analysis of text and images together; they do not replace reviews (syllabus 1.1.4, 1.2.1).","d":"Correct. The syllabus states that such models can generate rich test cases that incorporate textual data and visual cues, increasing overall coverage (syllabus 1.1.4)."},"obecne":"Coverage grows when test cases use both text and visual information."},"cz":{"q":"<p>Jak mohou multimodální LLM, zejména ty doplněné o modely pro obraz a jazyk, pomoci zvýšit pokrytí testy?<\/p>","m":["Paralelním spouštěním stejných testovacích případů na několika zařízeních.","Odstraněním potřeby testovací báze, protože očekávané chování určuje snímek obrazovky.","Nahrazením revizí uživatelských scénářů automatickým porovnáním obrázků.","Generováním testovacích případů, které kombinují textová data s vizuálními podněty z wireframů."],"vys":{"a":"Nesprávně. Spouštění testů na zařízeních není schopnost modelu (sylabus 1.2.1).","b":"Nesprávně. Snímek ukazuje skutečné chování. Očekávané výsledky dál pocházejí z testovací báze (sylabus 1.1.4).","c":"Nesprávně. Multimodální modely podporují společnou analýzu textu a obrazu, revize nenahrazují (sylabus 1.1.4, 1.2.1).","d":"Správně. Sylabus uvádí, že tyto modely umí vytvořit testovací případy s textovými daty i vizuálními podněty, a tím zvýšit pokrytí (sylabus 1.1.4)."},"obecne":"Pokrytí roste, když testovací případy využijí text i vizuální informaci."},"kap":{"c":"1.1.4","nazev":"1.1.4 Multimodální LLM a modely pro obraz a jazyk","href":"kapitola-1/vyklad.html#oddil-1-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.1-01","n":null,"lo":"GenAI-1.2.1","k":"K2","body":1,"vyber":2,"ok":[0,2],"en":{"q":"<p>Which TWO of the following are examples of key LLM capabilities for test tasks?<\/p>","m":["Classifying anomalies found in test results according to severity and priority.","Guaranteeing that generated expected results are correct without further review.","Generating questions that help clarify ambiguous requirements with stakeholders.","Executing performance tests directly against the production environment.","Taking the final release decision instead of the test manager."],"vys":{"a":"Correct. Test result analysis includes summarising results and classifying anomalies by severity and priority (syllabus 1.2.1).","b":"Incorrect. LLMs can help generate expected results, but outputs are plausible, not necessarily correct (syllabus 1.1.2, 1.2.1).","c":"Correct. Requirements analysis includes generating meaningful questions for stakeholders (syllabus 1.2.1).","d":"Incorrect. Test execution is not among the listed capabilities; LLMs support automation by generating and improving scripts (syllabus 1.2.1).","e":"Incorrect. LLMs support testware creation and analysis; decisions remain with people (syllabus 1.2.1)."},"obecne":"LLMs help with analysis, design, data, automation, results and testware; they do not guarantee correctness or act autonomously."},"cz":{"q":"<p>Která DVĚ z následujících jsou příklady hlavních schopností LLM pro testovací úlohy?<\/p>","m":["Třídění anomálií nalezených ve výsledcích testů podle závažnosti a priority.","Zaručení správnosti vygenerovaných očekávaných výsledků bez další kontroly.","Generování otázek, které pomohou se stakeholdery vyjasnit nejednoznačné požadavky.","Spouštění výkonnostních testů přímo proti produkčnímu prostředí.","Konečné rozhodnutí o vydání místo test manažera."],"vys":{"a":"Správně. Analýza výsledků testů zahrnuje shrnutí a třídění anomálií podle závažnosti a priority (sylabus 1.2.1).","b":"Nesprávně. LLM pomáhají generovat očekávané výsledky, ale výstupy jsou pravděpodobné, ne nutně správné (sylabus 1.1.2, 1.2.1).","c":"Správně. Analýza požadavků zahrnuje generování otázek pro stakeholdery (sylabus 1.2.1).","d":"Nesprávně. Spouštění testů mezi uvedenými schopnostmi není. LLM automatizaci podporují generováním a vylepšováním skriptů (sylabus 1.2.1).","e":"Nesprávně. LLM podporují tvorbu testwaru a analýzu, rozhodnutí zůstávají na lidech (sylabus 1.2.1)."},"obecne":"LLM pomáhají s analýzou, návrhem, daty, automatizací, výsledky a testwarem. Správnost nezaručují a samostatně nerozhodují."},"kap":{"c":"1.2.1","nazev":"1.2.1 Hlavní schopnosti LLM pro testovací úlohy","href":"kapitola-1/vyklad.html#oddil-1-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.1-02","n":null,"lo":"GenAI-1.2.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A tester describes the premium calculation rules of an insurance product to an LLM and asks what premium the system should return for a 45-year-old client with a specific level of coverage. Which LLM capability is the tester using?<\/p>","m":["Test data generation","Test oracle generation","Test result analysis","Requirements analysis and improvement"],"vys":{"a":"Incorrect. The tester already has the input values; the question is about the expected output (syllabus 1.2.1).","b":"Correct. Determining the expected result for given inputs is test oracle generation (syllabus 1.2.1).","c":"Incorrect. No actual test results are being analysed (syllabus 1.2.1).","d":"Incorrect. The tester is not looking for ambiguities or gaps in the rules (syllabus 1.2.1)."},"obecne":"Expected results = test oracle."},"cz":{"q":"<p>Tester popíše LLM pravidla výpočtu pojistného pro pojistný produkt a zeptá se, jaké pojistné má systém vrátit pro 45letého klienta s určitou výší krytí. Kterou schopnost LLM tester využívá?<\/p>","m":["Generování testovacích dat","Generování testovacího orákula","Analýza výsledků testů","Analýza a zlepšování požadavků"],"vys":{"a":"Nesprávně. Vstupní hodnoty už tester má. Ptá se na očekávaný výstup (sylabus 1.2.1).","b":"Správně. Určení očekávaného výsledku pro dané vstupy je generování testovacího orákula (sylabus 1.2.1).","c":"Nesprávně. Neanalyzují se žádné skutečné výsledky testů (sylabus 1.2.1).","d":"Nesprávně. Tester v pravidlech nehledá nejednoznačnosti ani mezery (sylabus 1.2.1)."},"obecne":"Očekávané výsledky = testovací orákulum."},"kap":{"c":"1.2.1","nazev":"1.2.1 Hlavní schopnosti LLM pro testovací úlohy","href":"kapitola-1/vyklad.html#oddil-1-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.1-03","n":null,"lo":"GenAI-1.2.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following BEST illustrates the LLM capability 'test automation support'?<\/p>","m":["The LLM writes a summary of last night's regression run for the project manager.","The LLM generates customer records with boundary values for the date of birth.","The LLM suggests replacing brittle locators in existing UI test scripts with more stable ones.","The LLM lists the acceptance criteria of a user story that are not testable."],"vys":{"a":"Incorrect. Summarising a run is test result analysis or testware creation (syllabus 1.2.1).","b":"Incorrect. Creating records with boundary values is test data generation (syllabus 1.2.1).","c":"Correct. Improving existing test scripts by suggesting changes is part of test automation support (syllabus 1.2.1).","d":"Incorrect. Finding untestable criteria is requirements analysis and improvement (syllabus 1.2.1)."},"obecne":"Test automation support: generate scripts from test case descriptions and improve existing scripts."},"cz":{"q":"<p>Který z následujících příkladů NEJLÉPE ilustruje schopnost LLM 'podpora automatizace testů'?<\/p>","m":["LLM napíše pro projektového manažera shrnutí nočního regresního běhu.","LLM vygeneruje záznamy klientů s hraničními hodnotami data narození.","LLM navrhne nahradit křehké lokátory ve stávajících skriptech UI testů stabilnějšími.","LLM vypíše akceptační kritéria uživatelského scénáře, která nejsou testovatelná."],"vys":{"a":"Nesprávně. Shrnutí běhu je analýza výsledků testů nebo tvorba testwaru (sylabus 1.2.1).","b":"Nesprávně. Záznamy s hraničními hodnotami jsou generování testovacích dat (sylabus 1.2.1).","c":"Správně. Vylepšení stávajících testovacích skriptů návrhem změn patří k podpoře automatizace testů (sylabus 1.2.1).","d":"Nesprávně. Hledání netestovatelných kritérií je analýza a zlepšování požadavků (sylabus 1.2.1)."},"obecne":"Podpora automatizace: skripty z popisu testovacího případu a vylepšení stávajících skriptů."},"kap":{"c":"1.2.1","nazev":"1.2.1 Hlavní schopnosti LLM pro testovací úlohy","href":"kapitola-1/vyklad.html#oddil-1-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.1-04","n":null,"lo":"GenAI-1.2.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester gives an LLM an acceptance criterion: 'The system shall respond quickly when the user submits the form.' Which response from the LLM is an example of requirements analysis and improvement?<\/p>","m":["A Playwright script that submits the form and measures the response time.","A test summary report stating that all form tests have passed.","A set of 20 form submissions with random input values.","A note that 'quickly' is ambiguous, with a question asking the product owner for a measurable response time limit."],"vys":{"a":"Incorrect. Writing a script is test automation support (syllabus 1.2.1).","b":"Incorrect. A summary report is testware creation or test result analysis (syllabus 1.2.1).","c":"Incorrect. Creating input values is test data generation (syllabus 1.2.1).","d":"Correct. Identifying ambiguity and generating a clarifying question for stakeholders is requirements analysis and improvement (syllabus 1.2.1)."},"obecne":"Requirements analysis: ambiguities, inconsistencies, missing information, clarifying questions."},"cz":{"q":"<p>Tester dá LLM akceptační kritérium: 'Systém musí po odeslání formuláře reagovat rychle.' Která odpověď LLM je příkladem analýzy a zlepšování požadavků?<\/p>","m":["Skript v Playwright, který formulář odešle a změří dobu odezvy.","Report o testování s konstatováním, že všechny testy formuláře prošly.","Sada 20 odeslání formuláře s náhodnými vstupními hodnotami.","Upozornění, že slovo 'rychle' je nejednoznačné, a otázka pro product ownera na měřitelný limit doby odezvy."],"vys":{"a":"Nesprávně. Psaní skriptu je podpora automatizace testů (sylabus 1.2.1).","b":"Nesprávně. Report je tvorba testwaru nebo analýza výsledků testů (sylabus 1.2.1).","c":"Nesprávně. Tvorba vstupních hodnot je generování testovacích dat (sylabus 1.2.1).","d":"Správně. Odhalení nejednoznačnosti a otázka pro stakeholdera jsou analýza a zlepšování požadavků (sylabus 1.2.1)."},"obecne":"Analýza požadavků: nejednoznačnosti, rozpory, chybějící informace, otázky k vyjasnění."},"kap":{"c":"1.2.1","nazev":"1.2.1 Hlavní schopnosti LLM pro testovací úlohy","href":"kapitola-1/vyklad.html#oddil-1-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.1-05","n":null,"lo":"GenAI-1.2.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>The scope of a release changes after two sprints. A tester asks an LLM to revise the existing test plan to reflect the new scope. Which LLM capability does this represent?<\/p>","m":["Testware creation","Test data generation","Test case creation support","Test oracle generation"],"vys":{"a":"Correct. Testware creation includes creating documents such as test plans and keeping them updated as the project evolves (syllabus 1.2.1).","b":"Incorrect. No data sets are being produced (syllabus 1.2.1).","c":"Incorrect. The task concerns a planning document, not deriving test cases (syllabus 1.2.1).","d":"Incorrect. No expected results are being determined (syllabus 1.2.1)."},"obecne":"Testware creation covers creating and updating test plans, test reports and defect reports."},"cz":{"q":"<p>Rozsah vydání se po dvou sprintech změní. Tester požádá LLM, aby stávající plán testů upravil podle nového rozsahu. Kterou schopnost LLM to představuje?<\/p>","m":["Tvorba testwaru","Generování testovacích dat","Podpora tvorby testovacích případů","Generování testovacího orákula"],"vys":{"a":"Správně. Tvorba testwaru zahrnuje tvorbu dokumentů, jako jsou plány testů, a jejich aktualizaci podle vývoje projektu (sylabus 1.2.1).","b":"Nesprávně. Nevznikají žádné datové sady (sylabus 1.2.1).","c":"Nesprávně. Úloha se týká plánovacího dokumentu, ne odvození testovacích případů (sylabus 1.2.1).","d":"Nesprávně. Neurčují se žádné očekávané výsledky (sylabus 1.2.1)."},"obecne":"Tvorba testwaru zahrnuje tvorbu a aktualizaci plánů testů, reportů o testování a reportů o defektech."},"kap":{"c":"1.2.1","nazev":"1.2.1 Hlavní schopnosti LLM pro testovací úlohy","href":"kapitola-1/vyklad.html#oddil-1-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.2-01","n":null,"lo":"GenAI-1.2.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A business analyst without technical background wants quick explanations of boundary value analysis while exploring new requirements with the test team. Which way of using GenAI fits this need BEST?<\/p>","m":["A script that calls the LLM API in batch mode overnight","An AI chatbot with a conversational interface","A custom AI agent that performs the role of a test analyst","An LLM-powered testing application integrated into the CI pipeline"],"vys":{"a":"Incorrect. Batch processing does not give fast interactive feedback (syllabus 1.2.2).","b":"Correct. Chatbots give immediate responses, help clarify test concepts and are accessible to non-technical stakeholders (syllabus 1.2.2).","c":"Incorrect. AI agents are an advanced form of LLM-powered applications for defined roles; this need is simple and ad hoc (syllabus 1.2.2).","d":"Incorrect. Integrated applications automate well-defined tasks; they do not suit ad hoc questions from a non-technical user (syllabus 1.2.2)."},"obecne":"Ad hoc questions, fast feedback and non-technical users point to an AI chatbot."},"cz":{"q":"<p>Business analytik bez technického zázemí chce při zkoumání nových požadavků s testovacím týmem rychle vysvětlit analýzu hraničních hodnot. Který způsob využití GenAI této potřebě odpovídá NEJLÉPE?<\/p>","m":["Skript, který přes noc dávkově volá API LLM","AI chatbot s konverzačním rozhraním","Vlastní AI agent v roli test analytika","Testovací aplikace na LLM integrovaná do CI pipeline"],"vys":{"a":"Nesprávně. Dávkové zpracování nedává rychlou interaktivní zpětnou vazbu (sylabus 1.2.2).","b":"Správně. Chatboti dávají okamžité odpovědi, pomáhají vyjasnit testovací pojmy a zvládnou je i netechničtí stakeholdeři (sylabus 1.2.2).","c":"Nesprávně. AI agenti jsou pokročilá forma aplikací na LLM pro vymezené role. Tato potřeba je jednoduchá a ad hoc (sylabus 1.2.2).","d":"Nesprávně. Integrované aplikace automatizují přesně vymezené úlohy. Pro ad hoc dotazy netechnického uživatele se nehodí (sylabus 1.2.2)."},"obecne":"Ad hoc dotazy, rychlá zpětná vazba a netechnický uživatel vedou na AI chatbota."},"kap":{"c":"1.2.2","nazev":"1.2.2 AI chatboti a testovací aplikace postavené na LLM","href":"kapitola-1/vyklad.html#oddil-1-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.2-02","n":null,"lo":"GenAI-1.2.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which characteristic is MORE typical of LLM-powered testing applications than of AI chatbots?<\/p>","m":["Iterative refinement of outputs by the tester during a conversation.","A natural language interface for asking questions and receiving immediate answers.","Integration through APIs to automate well-defined tasks with greater customisation.","Support for onboarding new testers by giving quick access to testing knowledge."],"vys":{"a":"Incorrect. Iterative refinement through prompt chaining is described for chatbots (syllabus 1.2.2).","b":"Incorrect. A conversational interface with immediate answers describes AI chatbots (syllabus 1.2.2).","c":"Correct. LLM-powered testing applications integrate LLMs via APIs, offer customisation and scalability and automate defined tasks (syllabus 1.2.2).","d":"Incorrect. Onboarding is mentioned as a typical use of chatbots (syllabus 1.2.2)."},"obecne":"Integration via API, customisation and scalability are typical of LLM-powered testing applications."},"cz":{"q":"<p>Která vlastnost je typičtější pro testovací aplikace postavené na LLM než pro AI chatboty?<\/p>","m":["Postupné zpřesňování výstupů testerem v průběhu konverzace.","Rozhraní v přirozeném jazyce pro kladení otázek a okamžité odpovědi.","Integrace přes API pro automatizaci vymezených úloh s větší mírou přizpůsobení.","Podpora zaškolení nových testerů rychlým přístupem ke znalostem o testování."],"vys":{"a":"Nesprávně. Postupné zpřesňování řetězením promptů sylabus popisuje u chatbotů (sylabus 1.2.2).","b":"Nesprávně. Konverzační rozhraní s okamžitými odpověďmi popisuje AI chatboty (sylabus 1.2.2).","c":"Správně. Testovací aplikace na LLM integrují LLM přes API, nabízejí přizpůsobení a škálovatelnost a automatizují vymezené úlohy (sylabus 1.2.2).","d":"Nesprávně. Zaškolení sylabus uvádí jako typické využití chatbotů (sylabus 1.2.2)."},"obecne":"Integrace přes API, přizpůsobení a škálovatelnost jsou typické pro testovací aplikace na LLM."},"kap":{"c":"1.2.2","nazev":"1.2.2 AI chatboti a testovací aplikace postavené na LLM","href":"kapitola-1/vyklad.html#oddil-1-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.2-03","n":null,"lo":"GenAI-1.2.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which statement about prompt engineering and the two ways of interacting with LLMs in testing is CORRECT?<\/p>","m":["Prompt engineering matters only for LLM-powered applications, because chatbots understand any question.","Prompt engineering matters only for AI chatbots, because applications prepare the prompts automatically.","Prompt engineering is unnecessary in both cases once the model is large enough.","Both chatbots and LLM-powered applications need well-designed prompts to make accurate and relevant outputs more likely."],"vys":{"a":"Incorrect. Chatbot outputs also depend on clear, specific instructions (syllabus 1.2.2).","b":"Incorrect. Even prompts prepared by an application must be designed well; a weak prompt affects every run (syllabus 1.2.2).","c":"Incorrect. Model size does not remove the need for carefully designed prompts (syllabus 1.2.2).","d":"Correct. The syllabus states that, regardless of the interaction model, successful use requires strong prompt engineering (syllabus 1.2.2)."},"obecne":"Prompt engineering is needed for both interaction models."},"cz":{"q":"<p>Které tvrzení o prompt engineeringu a dvou způsobech práce s LLM v testování je SPRÁVNÉ?<\/p>","m":["Prompt engineering je důležitý jen u aplikací na LLM, protože chatbot porozumí jakékoli otázce.","Prompt engineering je důležitý jen u AI chatbotů, protože aplikace připravují prompty automaticky.","Prompt engineering není potřeba ani v jednom případě, pokud je model dost velký.","Chatboti i aplikace na LLM potřebují dobře navržené prompty, aby byly přesné a relevantní výstupy pravděpodobnější."],"vys":{"a":"Nesprávně. Výstupy chatbota také závisejí na jasných a konkrétních instrukcích (sylabus 1.2.2).","b":"Nesprávně. I prompt, který připravuje aplikace, musí být dobře navržený. Slabý prompt ovlivní každý běh (sylabus 1.2.2).","c":"Nesprávně. Velikost modelu potřebu pečlivě navržených promptů neodstraňuje (sylabus 1.2.2).","d":"Správně. Sylabus uvádí, že bez ohledu na způsob interakce vyžaduje úspěšné nasazení dobrý prompt engineering (sylabus 1.2.2)."},"obecne":"Prompt engineering potřebují oba způsoby práce s LLM."},"kap":{"c":"1.2.2","nazev":"1.2.2 AI chatboti a testovací aplikace postavené na LLM","href":"kapitola-1/vyklad.html#oddil-1-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.2-04","n":null,"lo":"GenAI-1.2.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A test team wants every new defect report in its test management tool to be automatically classified and linked to similar existing defects, without anyone opening a chat window. Which approach fits BEST?<\/p>","m":["An LLM-powered testing application integrated into the test management tool via an API","An AI chatbot that testers consult when they have time","A foundation LLM used without any integration","A rule-based script that matches keywords in defect titles"],"vys":{"a":"Correct. LLM-powered testing applications integrate LLMs via APIs to automate well-defined tasks such as defect analysis (syllabus 1.2.2).","b":"Incorrect. A chatbot requires a person to start each interaction; the team wants automation (syllabus 1.2.2).","c":"Incorrect. A model on its own is not integrated into the tool and does not perform the task automatically (syllabus 1.2.2).","d":"Incorrect. Keyword matching is a rule-based approach without the language capabilities of LLMs (syllabus 1.1.1)."},"obecne":"Automated, repeated, well-defined tasks inside a tool point to an LLM-powered testing application."},"cz":{"q":"<p>Testovací tým chce, aby se každý nový report o defektu v nástroji pro správu testů automaticky zařadil do kategorie a propojil s podobnými existujícími defekty, aniž by kdokoli otevíral chatovací okno. Který přístup se hodí NEJLÉPE?<\/p>","m":["Testovací aplikace na LLM integrovaná do nástroje pro správu testů přes API","AI chatbot, kterého se testeři zeptají, když mají čas","Základní LLM použitý bez jakékoli integrace","Pravidlový skript, který hledá klíčová slova v názvech defektů"],"vys":{"a":"Správně. Testovací aplikace na LLM integrují LLM přes API a automatizují vymezené úlohy, jako je analýza defektů (sylabus 1.2.2).","b":"Nesprávně. Chatbot vyžaduje, aby každou interakci zahájil člověk. Tým chce automatizaci (sylabus 1.2.2).","c":"Nesprávně. Samotný model není integrovaný do nástroje a úlohu automaticky neprovádí (sylabus 1.2.2).","d":"Nesprávně. Hledání klíčových slov je pravidlový přístup bez jazykových schopností LLM (sylabus 1.1.1)."},"obecne":"Automatizované, opakované a vymezené úlohy uvnitř nástroje vedou na testovací aplikaci na LLM."},"kap":{"c":"1.2.2","nazev":"1.2.2 AI chatboti a testovací aplikace postavené na LLM","href":"kapitola-1/vyklad.html#oddil-1-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.2-05","n":null,"lo":"GenAI-1.2.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>How do testers typically use prompt chaining when working with an AI chatbot?<\/p>","m":["They send the same prompt to several chatbots and keep the most frequent answer.","They refine the output step by step, using the result of one prompt as input for the next one in the conversation.","They connect the chatbot to the test framework through an API so that prompts run automatically.","They split a long document into tokens so that it fits into the context window."],"vys":{"a":"Incorrect. Comparing answers from several chatbots is not prompt chaining (syllabus 1.2.2).","b":"Correct. Prompt chaining lets testers iteratively refine outputs; the output of one prompt feeds the next (syllabus 1.2.2, Appendix D).","c":"Incorrect. API integration describes LLM-powered testing applications (syllabus 1.2.2).","d":"Incorrect. Splitting into tokens is tokenization, done by the model, not a prompting technique (syllabus 1.1.2)."},"obecne":"Prompt chaining in a chatbot = iterative refinement through a sequence of prompts."},"cz":{"q":"<p>Jak testeři obvykle využívají řetězení promptů (prompt chaining) při práci s AI chatbotem?<\/p>","m":["Pošlou stejný prompt několika chatbotům a ponechají nejčastější odpověď.","Výstup postupně zpřesňují tak, že výsledek jednoho promptu použijí jako vstup dalšího promptu v konverzaci.","Propojí chatbota s testovacím frameworkem přes API, aby se prompty spouštěly automaticky.","Rozdělí dlouhý dokument na tokeny, aby se vešel do kontextového okna."],"vys":{"a":"Nesprávně. Porovnání odpovědí více chatbotů není řetězení promptů (sylabus 1.2.2).","b":"Správně. Řetězení promptů umožňuje testerům výstupy postupně zpřesňovat. Výstup jednoho promptu je vstupem dalšího (sylabus 1.2.2, Appendix D).","c":"Nesprávně. Integrace přes API popisuje testovací aplikace na LLM (sylabus 1.2.2).","d":"Nesprávně. Dělení na tokeny je tokenizace, kterou provádí model. Není to technika promptování (sylabus 1.1.2)."},"obecne":"Řetězení promptů v chatbotu = postupné zpřesňování sledem promptů."},"kap":{"c":"1.2.2","nazev":"1.2.2 AI chatboti a testovací aplikace postavené na LLM","href":"kapitola-1/vyklad.html#oddil-1-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-01","n":null,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A tester writes a structured prompt to obtain test conditions for a claims portal of an insurance company. Which of the following lines belongs to the <b>context<\/b> component?<\/p>","m":["“Derive test conditions for the damage reporting form.”","“Use the attached business rules document and the list of claim types.”","“The portal is used by brokers on desktop browsers and is being extended with online damage reporting for household insurance.”","“Ignore rules that apply only to car insurance.”"],"vys":{"a":"Incorrect. This is the task itself, which is the instruction (syllabus 2.1.1).","b":"Incorrect. Attached documents are material the model works with, which is input data (syllabus 2.1.1).","c":"Correct. It gives background about the test object and the functionality to be tested, which is the context (syllabus 2.1.1).","d":"Incorrect. This restricts how the instruction is applied, which is a constraint (syllabus 2.1.1)."},"obecne":"Context provides background information that the LLM needs to determine the test conditions: the test object, the functionality and relevant circumstances."},"cz":{"q":"<p>Tester píše strukturovaný prompt, kterým chce získat testovací podmínky pro portál pojišťovny pro hlášení škod. Který z následujících řádků patří do komponenty <b>context<\/b>?<\/p>","m":["„Odvoď testovací podmínky pro formulář hlášení škody.“","„Použij přiložený dokument s obchodními pravidly a seznam typů škod.“","„Portál používají zprostředkovatelé v desktopových prohlížečích a nově se rozšiřuje o online hlášení škod u pojištění domácnosti.“","„Ignoruj pravidla, která platí jen pro pojištění vozidel.“"],"vys":{"a":"Špatně. Jde o samotnou úlohu, tedy instrukci (sylabus 2.1.1).","b":"Špatně. Přiložené dokumenty jsou materiál k práci, tedy vstupní data (sylabus 2.1.1).","c":"Správně. Popisuje pozadí: testovaný objekt a testovanou funkci, tedy kontext (sylabus 2.1.1).","d":"Špatně. Omezuje, jak se instrukce použije, jde tedy o omezení (sylabus 2.1.1)."},"obecne":"Kontext dává modelu informace o pozadí potřebné k určení testovacích podmínek: testovaný objekt, funkci a okolnosti."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-02","n":null,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A prompt for reviewing a requirements specification contains the line: “Only analyze requirements with the status ‘Approved’ and skip the reviewer comments.” Which component of a structured prompt does this line represent?<\/p>","m":["Output format","Input data","Instruction","Constraints"],"vys":{"a":"Incorrect. Nothing in the line describes the structure of the response (syllabus 2.1.1).","b":"Incorrect. The line does not provide any material; it states a rule about which material to use (syllabus 2.1.1).","c":"Incorrect. The task (analyze the specification) is stated elsewhere; this line only limits its scope (syllabus 2.1.1).","d":"Correct. The line restricts how the instruction is applied to the input data (syllabus 2.1.1)."},"obecne":"Constraints outline restrictions or special considerations and specify how instructions should be applied to input data."},"cz":{"q":"<p>Prompt pro revizi specifikace požadavků obsahuje řádek: „Analyzuj jen požadavky ve stavu ‚Schváleno‘ a vynech komentáře revidentů.“ Kterou komponentu strukturovaného promptu tento řádek představuje?<\/p>","m":["Output format (formát výstupu)","Input data (vstupní data)","Instruction (instrukce)","Constraints (omezení)"],"vys":{"a":"Špatně. Řádek nic neříká o podobě odpovědi (sylabus 2.1.1).","b":"Špatně. Řádek nedodává žádný materiál, určuje pravidlo, který materiál použít (sylabus 2.1.1).","c":"Špatně. Úloha (analyzovat specifikaci) je jinde, tento řádek jen omezuje rozsah (sylabus 2.1.1).","d":"Správně. Řádek omezuje, jak se instrukce použije na vstupní data (sylabus 2.1.1)."},"obecne":"Omezení popisují restrikce a zvláštní pravidla a určují, jak se instrukce použije na vstupní data."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-03","n":null,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A tester uses the following prompt several times:<\/p><pre>Role: Act as a test analyst for an e-commerce web shop.\nContext: The shop introduces pick-up points for parcels.\nInstruction: Generate test cases for selecting a pick-up point.\nInput data: &lt;user story and acceptance criteria AC1-AC3&gt;\nConstraints: Cover each acceptance criterion with at least one positive\nand one negative test case.<\/pre><p>The content is useful, but the test cases come back sometimes as a list, sometimes as a table and with different fields. Which component is missing and would MOST likely fix this problem?<\/p>","m":["Output format","An additional constraint to use boundary value analysis","More context about the shop","A more specific role"],"vys":{"a":"Correct. The prompt does not specify the expected structure of the response, so the model chooses it each time (syllabus 2.1.1).","b":"Incorrect. A test technique changes the content of the test cases, not their format (syllabus 2.1.1).","c":"Incorrect. More background would not define the shape of the output (syllabus 2.1.1).","d":"Incorrect. The role shapes perspective and tone, not the structure of the result (syllabus 2.1.1)."},"obecne":"Output format specifications denote the expected format, structure or characteristics of the response."},"cz":{"q":"<p>Tester několikrát použije tento prompt:<\/p><pre>Role: Act as a test analyst for an e-commerce web shop.\nContext: The shop introduces pick-up points for parcels.\nInstruction: Generate test cases for selecting a pick-up point.\nInput data: &lt;user story and acceptance criteria AC1-AC3&gt;\nConstraints: Cover each acceptance criterion with at least one positive\nand one negative test case.<\/pre><p>Obsah je užitečný, ale testovací případy se vracejí jednou jako seznam, jindy jako tabulka a s různými poli. Která komponenta chybí a NEJSPÍŠ by problém vyřešila?<\/p>","m":["Output format (formát výstupu)","Další omezení, aby použil analýzu hraničních hodnot","Víc kontextu o e-shopu","Konkrétnější role"],"vys":{"a":"Správně. Prompt neurčuje strukturu odpovědi, a tak ji model pokaždé volí sám (sylabus 2.1.1).","b":"Špatně. Technika testování mění obsah testovacích případů, ne jejich formát (sylabus 2.1.1).","c":"Špatně. Další informace o pozadí neurčí podobu výstupu (sylabus 2.1.1).","d":"Špatně. Role ovlivňuje perspektivu a tón, ne strukturu výsledku (sylabus 2.1.1)."},"obecne":"Formát výstupu určuje očekávanou podobu, strukturu a vlastnosti odpovědi."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-04","n":null,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>What is the MAIN purpose of the <b>role<\/b> component in a structured prompt for a test task?<\/p>","m":["It sets the temperature so that the answers are more creative.","It helps the LLM determine its responsibilities and adopt an appropriate tone and approach, for example as a test manager.","It defines which user of the chatbot is allowed to send prompts.","It describes the test object and the functionality to be tested."],"vys":{"a":"Incorrect. Temperature is a model parameter, not a prompt component (syllabus 2.1.1, 3.1).","b":"Correct. The role defines the perspective or persona the model should take (syllabus 2.1.1).","c":"Incorrect. The role is about the model's persona, not about access rights of users.","d":"Incorrect. This is the purpose of the context (syllabus 2.1.1)."},"obecne":"The role defines the perspective or persona of the model, such as tester, test manager or test automation engineer."},"cz":{"q":"<p>Jaký je HLAVNÍ účel komponenty <b>role<\/b> ve strukturovaném promptu pro testovací úlohu?<\/p>","m":["Nastavuje teplotu, aby byly odpovědi kreativnější.","Pomáhá modelu určit jeho odpovědnost a zvolit vhodný tón a přístup, například jako test manažer.","Určuje, který uživatel chatbota smí posílat prompty.","Popisuje testovaný objekt a testovanou funkci."],"vys":{"a":"Špatně. Teplota je parametr modelu, ne komponenta promptu (sylabus 2.1.1, 3.1).","b":"Správně. Role určuje perspektivu nebo personu modelu (sylabus 2.1.1).","c":"Špatně. Role se týká persony modelu, ne přístupových práv uživatelů.","d":"Špatně. To je účel kontextu (sylabus 2.1.1)."},"obecne":"Role určuje perspektivu nebo personu modelu, například tester, test manažer nebo inženýr automatizace testů."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-05","n":null,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A tester wants an LLM to derive acceptance criteria for a new standing order screen of an online banking application. Which of the following is an example of the <b>input data<\/b> component?<\/p>","m":["“List the acceptance criteria in Given-When-Then form, numbered AC1, AC2 and so on.”","“You are an experienced test analyst in retail banking.”","The GUI wireframe of the screen together with the rules for the amount and due-date fields.","“The bank is adding standing orders to its mobile and web channels.”"],"vys":{"a":"Incorrect. This describes the output format (syllabus 2.1.1).","b":"Incorrect. This is the role (syllabus 2.1.1).","c":"Correct. A wireframe and field rules are information needed to perform the task (syllabus 2.1.1, 2.2.1).","d":"Incorrect. This is background information, which is context (syllabus 2.1.1)."},"obecne":"Input data includes user stories, acceptance criteria, screenshots, code, existing test cases or output examples."},"cz":{"q":"<p>Tester chce, aby LLM odvodil akceptační kritéria pro novou obrazovku trvalého příkazu v internetovém bankovnictví. Co z následujícího je příkladem komponenty <b>input data<\/b>?<\/p>","m":["„Vypiš akceptační kritéria ve tvaru Given-When-Then, číslovaná AC1, AC2 a tak dále.“","„Jsi zkušený test analytik v retailovém bankovnictví.“","Wireframe obrazovky spolu s pravidly pro pole částka a den splatnosti.","„Banka přidává trvalé příkazy do mobilního a webového kanálu.“"],"vys":{"a":"Špatně. To popisuje formát výstupu (sylabus 2.1.1).","b":"Špatně. To je role (sylabus 2.1.1).","c":"Správně. Wireframe a pravidla polí jsou informace potřebné k provedení úlohy (sylabus 2.1.1, 2.2.1).","d":"Špatně. To je informace o pozadí, tedy kontext (sylabus 2.1.1)."},"obecne":"Vstupní data zahrnují uživatelské scénáře, akceptační kritéria, snímky obrazovky, kód, existující testovací případy nebo ukázky výstupu."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-06","n":null,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which of the following statements about the six-component prompt structure is correct?<\/p>","m":["The structure is only used in system prompts, never in user prompts.","The six components are role, context, instruction, input data, temperature and output format.","A prompt that contains all six components always produces correct results, so prompting techniques are not needed.","The structure is a basis that should be combined with prompting techniques depending on the task and the LLM used."],"vys":{"a":"Incorrect. User prompts should also be well structured, and a system prompt may contain parts of the structure (syllabus 2.1.3).","b":"Incorrect. The sixth component is constraints; temperature is a model parameter (syllabus 2.1.1).","c":"Incorrect. The structure improves clarity but does not guarantee correctness; techniques and evaluation are still needed (syllabus 2.1.1, 2.3).","d":"Correct. The syllabus states that the structure should be combined with prompting techniques depending on the task and the LLM (syllabus 2.1.1)."},"obecne":"The six components form the basic structure of a prompt, which is combined with prompting techniques."},"cz":{"q":"<p>Které z následujících tvrzení o šestisložkové struktuře promptu je správné?<\/p>","m":["Struktura se používá jen v systémových promptech, nikdy v uživatelských.","Šest komponent je role, kontext, instrukce, vstupní data, teplota a formát výstupu.","Prompt se všemi šesti komponentami dává vždy správné výsledky, takže techniky promptování nejsou potřeba.","Struktura je základ, který se kombinuje s technikami promptování podle úlohy a použitého LLM."],"vys":{"a":"Špatně. I uživatelské prompty mají být dobře strukturované a systémový prompt může obsahovat části struktury (sylabus 2.1.3).","b":"Špatně. Šestou komponentou jsou omezení; teplota je parametr modelu (sylabus 2.1.1).","c":"Špatně. Struktura zlepšuje jasnost, ale nezaručuje správnost; techniky i hodnocení jsou dál potřeba (sylabus 2.1.1, 2.3).","d":"Správně. Sylabus říká, že se struktura kombinuje s technikami promptování podle úlohy a LLM (sylabus 2.1.1)."},"obecne":"Šest komponent tvoří základní strukturu promptu, která se kombinuje s technikami promptování."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-07","n":null,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following is the BEST example of an <b>instruction<\/b> in a structured prompt for test design?<\/p>","m":["“Derive one test case for each boundary value of the transfer amount field described below.”","“Present the result as a table with ID, input and expected result.”","“The transfer feature is part of the mobile banking app for private clients.”","“Maybe you could have a look at the transfer feature if you have time.”"],"vys":{"a":"Correct. It is clear, imperative and concise and states the task and its requirement (syllabus 2.1.1).","b":"Incorrect. This is the output format (syllabus 2.1.1).","c":"Incorrect. This is context, not an instruction (syllabus 2.1.1).","d":"Incorrect. It is not imperative and does not state a clear task (syllabus 2.1.1)."},"obecne":"Instructions are clear, imperative and concise directives that include a task description and relevant requirements."},"cz":{"q":"<p>Co z následujícího je NEJLEPŠÍM příkladem <b>instrukce<\/b> ve strukturovaném promptu pro návrh testů?<\/p>","m":["„Pro každou hraniční hodnotu pole částka převodu popsaného níže odvoď jeden testovací případ.“","„Výsledek uveď jako tabulku s ID, vstupem a očekávaným výsledkem.“","„Funkce převodu je součástí mobilního bankovnictví pro fyzické osoby.“","„Možná by ses mohl podívat na funkci převodu, pokud budeš mít čas.“"],"vys":{"a":"Správně. Je jasná, v rozkazovacím způsobu, stručná a uvádí úlohu i požadavek (sylabus 2.1.1).","b":"Špatně. To je formát výstupu (sylabus 2.1.1).","c":"Špatně. To je kontext, ne instrukce (sylabus 2.1.1).","d":"Špatně. Není v rozkazovacím způsobu a neříká jasnou úlohu (sylabus 2.1.1)."},"obecne":"Instrukce je jasný, stručný pokyn v rozkazovacím způsobu s popisem úlohy a podstatnými požadavky."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-08","n":null,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Test conditions generated by an LLM for an invoicing application regularly mention a PDF export, although the application has no such feature and the input data do not mention it. Which change to the prompt is MOST appropriate?<\/p>","m":["Change the role to “senior test analyst with 20 years of experience”.","Add a constraint: use only functionality described in the input data and list any missing information as open questions.","Remove the input data so that the model relies on its general knowledge of invoicing.","Change the output format from a table to a numbered list."],"vys":{"a":"Incorrect. A more senior persona does not tell the model which functionality is in scope (syllabus 2.1.1).","b":"Correct. A constraint specifies how the instruction is applied to the input data and limits invented content (syllabus 2.1.1).","c":"Incorrect. Less input increases guessing; high-quality input is crucial (syllabus 2.2, 2.2.1).","d":"Incorrect. The format of the result does not influence which features the model invents (syllabus 2.1.1)."},"obecne":"Constraints help to specify how the instruction is applied to the input data, for example by forbidding content that is not in the test basis."},"cz":{"q":"<p>Testovací podmínky, které LLM generuje pro fakturační aplikaci, pravidelně zmiňují export do PDF, přestože aplikace takovou funkci nemá a vstupní data ji nezmiňují. Která změna promptu je NEJVHODNĚJŠÍ?<\/p>","m":["Změnit roli na „senior test analytik s 20 lety praxe“.","Přidat omezení: používej jen funkce popsané ve vstupních datech a chybějící informace uveď jako otevřené otázky.","Odstranit vstupní data, aby se model opíral o obecné znalosti fakturace.","Změnit formát výstupu z tabulky na číslovaný seznam."],"vys":{"a":"Špatně. Zkušenější persona modelu neřekne, které funkce jsou v rozsahu (sylabus 2.1.1).","b":"Správně. Omezení určuje, jak se instrukce použije na vstupní data, a brání vymýšlení (sylabus 2.1.1).","c":"Špatně. Méně vstupu zvyšuje hádání; kvalitní vstup je nezbytný (sylabus 2.2, 2.2.1).","d":"Špatně. Podoba výsledku neovlivní, které funkce si model vymýšlí (sylabus 2.1.1)."},"obecne":"Omezení pomáhají určit, jak se instrukce použije na vstupní data, například zákazem obsahu, který není v testovací bázi."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-09","n":null,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following pairs of prompt component and example is correct?<\/p>","m":["Context: “return the findings as JSON with the fields id, severity and description”","Role: “the system under test is a payment gateway used by 300 merchants”","Input data: “the attached performance test results and server monitoring logs from last night”","Constraints: “act as a test automation engineer”"],"vys":{"a":"Incorrect. This is the output format (syllabus 2.1.1).","b":"Incorrect. This describes the test object, which is context (syllabus 2.1.1).","c":"Correct. Results and logs are material for the task, so they are input data (syllabus 2.1.1).","d":"Incorrect. This is a role (syllabus 2.1.1)."},"obecne":"Each component answers a different question: who answers (role), about what (context), what to do (instruction), with what (input data), under which rules (constraints) and in which form (output format)."},"cz":{"q":"<p>Která z následujících dvojic komponenta promptu a příklad je správná?<\/p>","m":["Kontext: „nálezy vrať jako JSON s poli id, severity a description“","Role: „testovaný systém je platební brána, kterou používá 300 obchodníků“","Vstupní data: „přiložené výsledky výkonnostních testů a logy z monitoringu serverů z poslední noci“","Omezení: „jednej jako inženýr automatizace testů“"],"vys":{"a":"Špatně. To je formát výstupu (sylabus 2.1.1).","b":"Špatně. Popisuje testovaný objekt, tedy kontext (sylabus 2.1.1).","c":"Správně. Výsledky a logy jsou materiál pro úlohu, tedy vstupní data (sylabus 2.1.1).","d":"Špatně. To je role (sylabus 2.1.1)."},"obecne":"Každá komponenta odpovídá na jinou otázku: kdo odpovídá (role), o čem (kontext), co udělat (instrukce), s čím (vstupní data), podle jakých pravidel (omezení) a v jaké podobě (formát výstupu)."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.2-01","n":null,"lo":"GenAI-2.1.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A prompt contains three user stories, each followed by the Gherkin scenarios that the team wrote for it. At the end there is a fourth user story with the request to write Gherkin scenarios in the same style. Which prompting technique is used?<\/p>","m":["One-shot prompting","Prompt chaining","Meta prompting","Few-shot prompting"],"vys":{"a":"Incorrect. One-shot uses exactly one example; here there are three (syllabus 2.1.2).","b":"Incorrect. The task is not split into several prompts with checks between them (syllabus 2.1.2).","c":"Incorrect. The model is not asked to create or refine a prompt (syllabus 2.1.2).","d":"Correct. The prompt contains more than one example of the expected result (syllabus 2.1.2)."},"obecne":"Zero-shot, one-shot and few-shot differ only in the number of examples in the prompt: none, one, several."},"cz":{"q":"<p>Prompt obsahuje tři uživatelské scénáře, za každým jsou Gherkin scénáře, které k němu tým napsal. Na konci je čtvrtý uživatelský scénář s požadavkem napsat Gherkin scénáře ve stejném stylu. Jaká technika promptování je použita?<\/p>","m":["One-shot prompting","Prompt chaining","Meta prompting","Few-shot prompting"],"vys":{"a":"Špatně. One-shot používá právě jeden příklad, tady jsou tři (sylabus 2.1.2).","b":"Špatně. Úloha není rozdělená do více promptů s kontrolou mezi nimi (sylabus 2.1.2).","c":"Špatně. Model není žádán o vytvoření nebo vylepšení promptu (sylabus 2.1.2).","d":"Správně. Prompt obsahuje víc než jeden příklad očekávaného výsledku (sylabus 2.1.2)."},"obecne":"Zero-shot, one-shot a few-shot se liší jen počtem příkladů v promptu: žádný, jeden, několik."},"kap":{"c":"2.1.2","nazev":"2.1.2 Základní techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.2-02","n":null,"lo":"GenAI-2.1.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following BEST describes prompt chaining?<\/p>","m":["The task is broken into intermediate steps with separate prompts, and the result of each step is checked and refined before the next step.","The same prompt is sent several times and the most frequent answer is selected.","Several examples of the desired output are placed in one prompt so that the model follows the pattern.","The model is asked to write a better version of the tester's prompt."],"vys":{"a":"Correct. This is the definition in syllabus 2.1.2, including the check between steps.","b":"Incorrect. Repeating the same prompt is not decomposition of a task into steps (syllabus 2.1.2).","c":"Incorrect. This describes few-shot prompting (syllabus 2.1.2).","d":"Incorrect. This describes meta prompting (syllabus 2.1.2)."},"obecne":"Prompt chaining decomposes a complicated task into subtasks and checks the intermediate LLM outputs systematically."},"cz":{"q":"<p>Co z následujícího NEJLÉPE popisuje prompt chaining?<\/p>","m":["Úloha se rozdělí na mezikroky s vlastními prompty a výsledek každého kroku se před dalším krokem zkontroluje a upraví.","Stejný prompt se pošle několikrát a vybere se nejčastější odpověď.","Do jednoho promptu se vloží několik příkladů požadovaného výstupu, aby model dodržel vzor.","Model je požádán, aby napsal lepší verzi testerova promptu."],"vys":{"a":"Správně. Odpovídá definici v sylabu 2.1.2 včetně kontroly mezi kroky.","b":"Špatně. Opakování stejného promptu není rozklad úlohy na kroky (sylabus 2.1.2).","c":"Špatně. To popisuje few-shot prompting (sylabus 2.1.2).","d":"Špatně. To popisuje meta prompting (sylabus 2.1.2)."},"obecne":"Řetězení promptů rozkládá složitou úlohu na dílčí úlohy a systematicky kontroluje mezivýsledky modelu."},"kap":{"c":"2.1.2","nazev":"2.1.2 Základní techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.2-03","n":null,"lo":"GenAI-2.1.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which statement correctly describes meta prompting in software testing?<\/p>","m":["The tester writes detailed prompts manually without any help from the LLM to keep full control.","The LLM generates or refines prompts in an iterative cycle, and the tester evaluates and adjusts them, similar to pairing.","The prompt contains metadata about the test environment, such as versions and URLs.","The prompt tells the model to reason step by step before giving the final answer."],"vys":{"a":"Incorrect. The essence of meta prompting is that the LLM helps create the prompt (syllabus 2.1.2).","b":"Correct. Syllabus 2.1.2 describes meta prompting as co-creating prompts with the LLM, a form of pairing.","c":"Incorrect. Information about the environment is context or input data, not meta prompting (syllabus 2.1.1).","d":"Incorrect. This is chain-of-thought prompting, which the syllabus does not list as a core technique."},"obecne":"Meta prompting uses the LLM's knowledge of effective prompts; it saves effort and helps testers who are unsure how to write a prompt."},"cz":{"q":"<p>Které tvrzení správně popisuje meta prompting v testování softwaru?<\/p>","m":["Tester píše podrobné prompty ručně bez pomoci modelu, aby měl plnou kontrolu.","LLM v opakovaném cyklu vytváří nebo vylepšuje prompty a tester je posuzuje a upravuje, podobně jako při párové práci.","Prompt obsahuje metadata o testovacím prostředí, například verze a URL.","Prompt modelu říká, aby před konečnou odpovědí uvažoval krok za krokem."],"vys":{"a":"Špatně. Podstatou meta promptingu je, že prompt pomáhá vytvořit model (sylabus 2.1.2).","b":"Správně. Sylabus 2.1.2 popisuje meta prompting jako společnou tvorbu promptů s modelem, formu párové práce.","c":"Špatně. Informace o prostředí jsou kontext nebo vstupní data, ne meta prompting (sylabus 2.1.1).","d":"Špatně. To je chain-of-thought, kterou sylabus mezi základními technikami neuvádí."},"obecne":"Meta prompting využívá znalost modelu o účinných promptech; šetří práci a pomáhá testerům, kteří nevědí, jak prompt napsat."},"kap":{"c":"2.1.2","nazev":"2.1.2 Základní techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.2-04","n":null,"lo":"GenAI-2.1.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>What is the difference between zero-shot and one-shot prompting?<\/p>","m":["A zero-shot prompt has no structure; a one-shot prompt has all six components.","A zero-shot prompt is sent without a system prompt; a one-shot prompt is sent with one system prompt.","A zero-shot prompt contains no example and relies on the model's pre-existing knowledge; a one-shot prompt contains exactly one example of the expected result.","A zero-shot prompt gets no answer on the first attempt; a one-shot prompt gets an answer after one retry."],"vys":{"a":"Incorrect. A zero-shot prompt can be fully structured; it just has no example (syllabus 2.1.1, 2.1.2).","b":"Incorrect. The terms refer to examples in the prompt, not to system prompts (syllabus 2.1.2, 2.1.3).","c":"Correct. This matches syllabus 2.1.2.","d":"Incorrect. “Shot” means an example, not an attempt (syllabus 2.1.2)."},"obecne":"The number of examples distinguishes zero-shot (none), one-shot (one) and few-shot (several)."},"cz":{"q":"<p>Jaký je rozdíl mezi zero-shot a one-shot promptingem?<\/p>","m":["Zero-shot prompt nemá strukturu; one-shot prompt má všech šest komponent.","Zero-shot prompt se posílá bez systémového promptu; one-shot prompt s jedním systémovým promptem.","Zero-shot prompt neobsahuje žádný příklad a spoléhá na znalosti modelu; one-shot prompt obsahuje právě jeden příklad očekávaného výsledku.","Zero-shot prompt nedostane odpověď na první pokus; one-shot prompt ji dostane po jednom opakování."],"vys":{"a":"Špatně. Zero-shot prompt může být plně strukturovaný, jen nemá příklad (sylabus 2.1.1, 2.1.2).","b":"Špatně. Pojmy se týkají příkladů v promptu, ne systémových promptů (sylabus 2.1.2, 2.1.3).","c":"Správně. Odpovídá sylabu 2.1.2.","d":"Špatně. „Shot“ znamená příklad, ne pokus (sylabus 2.1.2)."},"obecne":"Počet příkladů rozlišuje zero-shot (žádný), one-shot (jeden) a few-shot (několik)."},"kap":{"c":"2.1.2","nazev":"2.1.2 Základní techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.2-05","n":null,"lo":"GenAI-2.1.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A test lead first asks an LLM to propose a prompt for generating test cases. She then adds three approved test cases from the team as examples to that prompt. Finally, she splits the work into two prompts, generating test cases and checking coverage, and reviews the output after each one. Which techniques did she use, in this order?<\/p>","m":["Meta prompting, prompt chaining, few-shot prompting","Zero-shot prompting, few-shot prompting, meta prompting","Prompt chaining, one-shot prompting, meta prompting","Meta prompting, few-shot prompting, prompt chaining"],"vys":{"a":"Incorrect. The techniques are right but the order is wrong (syllabus 2.2.5).","b":"Incorrect. The last step is a decomposition with checks, which is prompt chaining (syllabus 2.1.2).","c":"Incorrect. The first step is meta prompting and three examples mean few-shot (syllabus 2.1.2).","d":"Correct. The model created the prompt (meta), examples were added (few-shot), and the task was split with checks (chaining); syllabus 2.2.5 describes this combination."},"obecne":"The core techniques can be combined; the syllabus gives exactly this sequence as an example."},"cz":{"q":"<p>Vedoucí testů nejprve požádá LLM, aby navrhl prompt pro generování testovacích případů. Do tohoto promptu pak přidá tři schválené testovací případy týmu jako příklady. Nakonec práci rozdělí na dva prompty, generování testovacích případů a kontrolu pokrytí, a po každém výstup zkontroluje. Které techniky použila, v tomto pořadí?<\/p>","m":["Meta prompting, prompt chaining, few-shot prompting","Zero-shot prompting, few-shot prompting, meta prompting","Prompt chaining, one-shot prompting, meta prompting","Meta prompting, few-shot prompting, prompt chaining"],"vys":{"a":"Špatně. Techniky sedí, ale pořadí je špatně (sylabus 2.2.5).","b":"Špatně. Poslední krok je rozklad s kontrolami, tedy prompt chaining (sylabus 2.1.2).","c":"Špatně. Prvním krokem je meta prompting a tři příklady znamenají few-shot (sylabus 2.1.2).","d":"Správně. Model vytvořil prompt (meta), přidaly se příklady (few-shot) a úloha se rozdělila s kontrolami (chaining); tuto kombinaci popisuje sylabus 2.2.5."},"obecne":"Základní techniky lze kombinovat; sylabus uvádí právě tuto posloupnost jako příklad."},"kap":{"c":"2.1.2","nazev":"2.1.2 Základní techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.3-01","n":null,"lo":"GenAI-2.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A team builds an internal LLM assistant for testers. Every answer must use ISTQB terminology and must refuse to process personal data of clients. Where should these rules be placed?<\/p>","m":["In the system prompt, because it defines the behavior for the whole conversation and stays constant.","In the first user prompt only, because the model remembers it for the rest of the conversation in the same way as a system prompt.","In the output format of each answer, because formatting rules control the behavior.","In each user prompt, because the user prompt sets the rules for the entire session."],"vys":{"a":"Correct. Rules that apply to every interaction belong to the system prompt (syllabus 2.1.3).","b":"Incorrect. A user prompt is not the defined framework for the conversation; the syllabus places such rules in the system prompt (syllabus 2.1.3).","c":"Incorrect. Output format shapes the response structure, not behavioral rules such as data protection (syllabus 2.1.1).","d":"Incorrect. User prompts change with each interaction; the system prompt sets the rules for the session (syllabus 2.1.3)."},"obecne":"The system prompt is a predefined command set defining behavior and operational parameters for the entire conversation."},"cz":{"q":"<p>Tým staví interního LLM asistenta pro testery. Každá odpověď musí používat terminologii ISTQB a asistent musí odmítnout zpracovat osobní údaje klientů. Kam tato pravidla patří?<\/p>","m":["Do systémového promptu, protože určuje chování pro celou konverzaci a nemění se.","Jen do prvního uživatelského promptu, protože si ho model pamatuje po zbytek konverzace stejně jako systémový prompt.","Do formátu výstupu každé odpovědi, protože pravidla formátu řídí chování.","Do každého uživatelského promptu, protože ten nastavuje pravidla pro celou session."],"vys":{"a":"Správně. Pravidla platná pro každou interakci patří do systémového promptu (sylabus 2.1.3).","b":"Špatně. Uživatelský prompt není definovaný rámec konverzace; sylabus taková pravidla dává do systémového promptu (sylabus 2.1.3).","c":"Špatně. Formát výstupu tvaruje strukturu odpovědi, ne pravidla chování jako ochranu dat (sylabus 2.1.1).","d":"Špatně. Uživatelské prompty se mění s každou interakcí; pravidla pro session nastavuje systémový prompt (sylabus 2.1.3)."},"obecne":"Systémový prompt je předem daná sada pokynů, která určuje chování a provozní parametry pro celou konverzaci."},"kap":{"c":"2.1.3","nazev":"2.1.3 Systémový prompt a uživatelský prompt","href":"kapitola-2/vyklad.html#oddil-2-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.3-02","n":null,"lo":"GenAI-2.1.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following statements about a user prompt is correct?<\/p>","m":["It is usually hidden from the chatbot's user.","It changes with each interaction and forms the immediate context for the response.","It is defined once by the developer and stays constant for the whole session.","It overrides the system prompt, so the model ignores the system prompt once a user prompt is sent."],"vys":{"a":"Incorrect. User prompts are directly visible (syllabus 2.1.3).","b":"Correct. This matches syllabus 2.1.3.","c":"Incorrect. This describes a system prompt (syllabus 2.1.3).","d":"Incorrect. The model considers both the system prompt and the current user prompt together (syllabus 2.1.3)."},"obecne":"A user prompt is the actual input of the chatbot's user: questions, instructions or tasks for the current interaction."},"cz":{"q":"<p>Které z následujících tvrzení o uživatelském promptu je správné?<\/p>","m":["Uživatel chatbota ho obvykle nevidí.","Mění se s každou interakcí a tvoří bezprostřední kontext odpovědi.","Jednou ho definuje vývojář a po celou session se nemění.","Přepisuje systémový prompt, takže model po odeslání uživatelského promptu systémový prompt ignoruje."],"vys":{"a":"Špatně. Uživatelské prompty jsou přímo viditelné (sylabus 2.1.3).","b":"Správně. Odpovídá sylabu 2.1.3.","c":"Špatně. To popisuje systémový prompt (sylabus 2.1.3).","d":"Špatně. Model bere v úvahu systémový i aktuální uživatelský prompt zároveň (sylabus 2.1.3)."},"obecne":"Uživatelský prompt je skutečný vstup uživatele chatbota: otázky, pokyny nebo úlohy pro danou interakci."},"kap":{"c":"2.1.3","nazev":"2.1.3 Systémový prompt a uživatelský prompt","href":"kapitola-2/vyklad.html#oddil-2-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.3-03","n":null,"lo":"GenAI-2.1.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>The system prompt of a test assistant says that test cases must always be returned with the fields ID, preconditions, steps and expected result. A tester sends the user prompt: “Create test cases for changing the card limit.” What is the expected behavior?<\/p>","m":["The model ignores the field definition because the user prompt does not repeat it.","The model replaces the system prompt with the user prompt for the rest of the session.","The model creates test cases for the card limit and uses the fields defined in the system prompt, because it considers both prompts together.","The model asks the user to confirm the system prompt before answering."],"vys":{"a":"Incorrect. Rules in the system prompt apply to the whole conversation without repetition (syllabus 2.1.3).","b":"Incorrect. The system prompt stays constant throughout the interaction session (syllabus 2.1.3).","c":"Correct. The LLM generates responses by considering the unchanging system prompt and the current user prompt together (syllabus 2.1.3).","d":"Incorrect. The system prompt is not something the user confirms; it is predefined (syllabus 2.1.3)."},"obecne":"Typical usage: the system prompt is set once at the start, then successive user prompts are sent; both are considered for each response."},"cz":{"q":"<p>Systémový prompt testovacího asistenta říká, že testovací případy se mají vždy vracet s poli ID, předpoklady, kroky a očekávaný výsledek. Tester pošle uživatelský prompt: „Vytvoř testovací případy pro změnu limitu karty.“ Jaké chování se očekává?<\/p>","m":["Model definici polí ignoruje, protože ji uživatelský prompt neopakuje.","Model po zbytek session nahradí systémový prompt uživatelským.","Model vytvoří testovací případy pro limit karty s poli ze systémového promptu, protože bere v úvahu oba prompty zároveň.","Model před odpovědí požádá uživatele o potvrzení systémového promptu."],"vys":{"a":"Špatně. Pravidla ze systémového promptu platí pro celou konverzaci i bez opakování (sylabus 2.1.3).","b":"Špatně. Systémový prompt zůstává po celou session stejný (sylabus 2.1.3).","c":"Správně. Model tvoří odpověď s ohledem na neměnný systémový prompt i aktuální uživatelský prompt (sylabus 2.1.3).","d":"Špatně. Systémový prompt uživatel nepotvrzuje, je předem daný (sylabus 2.1.3)."},"obecne":"Typický postup: systémový prompt se nastaví jednou na začátku, pak přicházejí uživatelské prompty; pro každou odpověď se berou v úvahu oba."},"kap":{"c":"2.1.3","nazev":"2.1.3 Systémový prompt a uživatelský prompt","href":"kapitola-2/vyklad.html#oddil-2-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.3-04","n":null,"lo":"GenAI-2.1.3","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which of the following would be LEAST appropriate to place in the system prompt of an LLM-powered test assistant?<\/p>","m":["The role of the assistant as a professional software testing assistant.","The rule to answer concisely and in a formal tone.","The constraint not to speculate when information is missing.","The acceptance criteria of the user story the tester is working on today."],"vys":{"a":"Incorrect. A role is typical content of a system prompt (syllabus 2.1.3).","b":"Incorrect. This is an operational parameter, typical for a system prompt (syllabus 2.1.3).","c":"Incorrect. Constraints that apply to all answers fit into a system prompt (syllabus 2.1.3).","d":"Correct. Task-specific input that changes with each request belongs to the user prompt (syllabus 2.1.3)."},"obecne":"A system prompt may contain role, context and constraints valid for the whole conversation; task-specific data go into user prompts."},"cz":{"q":"<p>Co z následujícího by bylo NEJMÉNĚ vhodné umístit do systémového promptu testovacího asistenta postaveného na LLM?<\/p>","m":["Role asistenta jako profesionálního pomocníka pro testování softwaru.","Pravidlo odpovídat stručně a formálním tónem.","Omezení nespekulovat, když informace chybí.","Akceptační kritéria uživatelského scénáře, na kterém tester dnes pracuje."],"vys":{"a":"Špatně. Role je typický obsah systémového promptu (sylabus 2.1.3).","b":"Špatně. Jde o provozní parametr, typický pro systémový prompt (sylabus 2.1.3).","c":"Špatně. Omezení platná pro všechny odpovědi do systémového promptu patří (sylabus 2.1.3).","d":"Správně. Vstup specifický pro úlohu, který se mění s každým požadavkem, patří do uživatelského promptu (sylabus 2.1.3)."},"obecne":"Systémový prompt může obsahovat roli, kontext a omezení platné pro celou konverzaci; data konkrétní úlohy patří do uživatelských promptů."},"kap":{"c":"2.1.3","nazev":"2.1.3 Systémový prompt a uživatelský prompt","href":"kapitola-2/vyklad.html#oddil-2-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.3-05","n":null,"lo":"GenAI-2.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which statement BEST distinguishes the system prompt from the user prompt?<\/p>","m":["The system prompt is typically set by a developer or tester and is not visible to the chatbot's user in most interfaces; the user prompt is written by the user and is visible.","The system prompt contains the specific question of the current interaction; the user prompt contains the general rules.","The system prompt is used only by AI chatbots, the user prompt only by LLM-powered test applications.","The system prompt is generated by the LLM itself after the first user prompt."],"vys":{"a":"Correct. This matches syllabus 2.1.3.","b":"Incorrect. The roles are reversed (syllabus 2.1.3).","c":"Incorrect. Both kinds of prompts are used in interactions with LLMs regardless of the type of tool (syllabus 2.1.3).","d":"Incorrect. The system prompt is predefined, typically by a developer or tester (syllabus 2.1.3)."},"obecne":"System prompt: framework for the whole conversation, constant, usually hidden. User prompt: per-interaction input, changing, visible."},"cz":{"q":"<p>Které tvrzení NEJLÉPE odlišuje systémový prompt od uživatelského?<\/p>","m":["Systémový prompt obvykle nastavuje vývojář nebo tester a uživatel chatbota ho ve většině rozhraní nevidí; uživatelský prompt píše uživatel a je viditelný.","Systémový prompt obsahuje konkrétní otázku aktuální interakce; uživatelský prompt obecná pravidla.","Systémový prompt používají jen AI chatboti, uživatelský prompt jen testovací aplikace postavené na LLM.","Systémový prompt vygeneruje sám LLM po prvním uživatelském promptu."],"vys":{"a":"Správně. Odpovídá sylabu 2.1.3.","b":"Špatně. Role jsou prohozené (sylabus 2.1.3).","c":"Špatně. Oba druhy promptů se používají při práci s LLM bez ohledu na typ nástroje (sylabus 2.1.3).","d":"Špatně. Systémový prompt je předem daný, obvykle vývojářem nebo testerem (sylabus 2.1.3)."},"obecne":"Systémový prompt: rámec celé konverzace, neměnný, obvykle skrytý. Uživatelský prompt: vstup pro jednu interakci, proměnlivý, viditelný."},"kap":{"c":"2.1.3","nazev":"2.1.3 Systémový prompt a uživatelský prompt","href":"kapitola-2/vyklad.html#oddil-2-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.1-01","n":null,"lo":"GenAI-2.2.1","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>A product owner of an online shop delivers a user story with acceptance criteria for a loyalty program and admits that some criteria are vague. You want to use prompt chaining with human verification to make the acceptance criteria well-formed and actionable. Which sequence of prompts is MOST appropriate?<\/p><ol><li>Ask the LLM to evaluate whether each criterion is testable and to rewrite untestable ones.<\/li><li>Ask the LLM to identify ambiguous wording in the story and criteria.<\/li><li>Ask the LLM to evaluate whether the criteria cover the story completely and propose missing ones.<\/li><\/ol><p>After each step you verify and correct the result before the next prompt.<\/p>","m":["All three steps in one prompt, followed by one final review","2 – 1 – 3","1 – 2 – 3","3 – 2 – 1"],"vys":{"a":"Incorrect. This is not prompt chaining; intermediate results are not verified (syllabus 2.1.2).","b":"Correct. Ambiguities are resolved first, then testability is assessed on clean criteria, and completeness last (syllabus 2.2.1, HO-2.2.1b).","c":"Incorrect. Testability cannot be judged reliably while the wording is still ambiguous (syllabus 2.2.1, HO-2.2.1b).","d":"Incorrect. Proposing new criteria before clarifying the existing ones builds on vague wording (syllabus 2.2.1, HO-2.2.1b)."},"obecne":"Each step of the chain uses a verified result of the previous step; the syllabus order is ambiguities, testability, completeness."},"cz":{"q":"<p>Product owner e-shopu dodá uživatelský scénář s akceptačními kritérii pro věrnostní program a přizná, že některá kritéria jsou vágní. Chcete pomocí řetězení promptů s lidským ověřením dosáhnout dobře formulovaných a použitelných akceptačních kritérií. Která posloupnost promptů je NEJVHODNĚJŠÍ?<\/p><ol><li>Požádat LLM, aby posoudil testovatelnost každého kritéria a netestovatelná přepsal.<\/li><li>Požádat LLM, aby našel nejednoznačné formulace ve scénáři a kritériích.<\/li><li>Požádat LLM, aby posoudil, zda kritéria pokrývají scénář úplně, a navrhl chybějící.<\/li><\/ol><p>Po každém kroku výsledek ověříte a opravíte, než pošlete další prompt.<\/p>","m":["Všechny tři kroky v jednom promptu a na konci jedna kontrola","2 – 1 – 3","1 – 2 – 3","3 – 2 – 1"],"vys":{"a":"Špatně. To není řetězení promptů; mezivýsledky se neověřují (sylabus 2.1.2).","b":"Správně. Nejdřív se vyřeší nejednoznačnosti, pak se na vyčištěných kritériích posoudí testovatelnost a nakonec úplnost (sylabus 2.2.1, HO-2.2.1b).","c":"Špatně. Testovatelnost nelze spolehlivě posoudit, dokud jsou formulace nejednoznačné (sylabus 2.2.1, HO-2.2.1b).","d":"Špatně. Navrhovat nová kritéria před vyjasněním stávajících znamená stavět na vágních formulacích (sylabus 2.2.1, HO-2.2.1b)."},"obecne":"Každý krok řetězu pracuje s ověřeným výsledkem předchozího; pořadí podle sylabu je nejednoznačnosti, testovatelnost, úplnost."},"kap":{"c":"2.2.1","nazev":"2.2.1 Testovací analýza s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.1-02","n":null,"lo":"GenAI-2.2.1","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>A test manager uses the following prompt to prioritize test conditions for a payment module:<\/p><pre>Role: Act as a test manager in a bank.\nContext: Release of the payment module in three weeks.\nInstruction: Prioritize the test conditions.\nInput data: List of 25 test conditions with ID and description.\nConstraints: Consider the risk level.\nOutput format: Table with ID, priority and short rationale.<\/pre><p>The priorities look plausible but differ between runs and cannot be traced. Which improvement would MOST improve the prioritization?<\/p>","m":["Change the role to “experienced test manager specialized in risk management”.","Add to the output format a chart showing the number of conditions per priority.","Add risk likelihood and impact for each condition and the number of past defects to the input data, and state in the constraints how the risk level is calculated.","Replace the constraint with “Use best practices for risk-based testing”."],"vys":{"a":"Incorrect. The persona changes, but the model still lacks the risk information it needs (syllabus 2.2.1).","b":"Incorrect. Visualizing the result does not make the prioritization better founded (syllabus 2.1.1).","c":"Correct. With likelihood, impact and defect history the LLM can recommend traceable priorities (syllabus 2.2.1).","d":"Incorrect. A reference to unspecified best practices is vague and adds no information (syllabus 2.1.1)."},"obecne":"Prioritization by risk requires information on likelihood and impact; regulatory aspects, user-facing features and historical defects are further inputs."},"cz":{"q":"<p>Test manažer používá tento prompt k prioritizaci testovacích podmínek platebního modulu:<\/p><pre>Role: Act as a test manager in a bank.\nContext: Release of the payment module in three weeks.\nInstruction: Prioritize the test conditions.\nInput data: List of 25 test conditions with ID and description.\nConstraints: Consider the risk level.\nOutput format: Table with ID, priority and short rationale.<\/pre><p>Priority vypadají věrohodně, ale mezi běhy se liší a nedají se zpětně dohledat. Která úprava NEJVÍCE zlepší prioritizaci?<\/p>","m":["Změnit roli na „zkušený test manažer specializovaný na řízení rizik“.","Přidat do formátu výstupu graf s počtem podmínek podle priority.","Doplnit do vstupních dat pravděpodobnost a dopad u každé podmínky a počet dřívějších defektů a do omezení uvést, jak se úroveň rizika počítá.","Nahradit omezení větou „Použij osvědčené postupy testování založeného na rizicích“."],"vys":{"a":"Špatně. Persona se změní, ale modelu dál chybí informace o riziku (sylabus 2.2.1).","b":"Špatně. Vizualizace výsledku nezlepší podklad prioritizace (sylabus 2.1.1).","c":"Správně. S pravděpodobností, dopadem a historií defektů může LLM doporučit dohledatelné priority (sylabus 2.2.1).","d":"Špatně. Odkaz na nespecifikované osvědčené postupy je vágní a nepřidává informaci (sylabus 2.1.1)."},"obecne":"Prioritizace podle rizika potřebuje informace o pravděpodobnosti a dopadu; dalšími vstupy jsou regulace, uživatelské funkce a historie defektů."},"kap":{"c":"2.2.1","nazev":"2.2.1 Testovací analýza s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.1-03","n":null,"lo":"GenAI-2.2.1","k":"K3","body":2,"vyber":1,"ok":[3],"en":{"q":"<p>You create a multimodal prompt to derive acceptance criteria for a standing order screen. The input data are the user story, a GUI wireframe and business rules for the fields. You know that the wireframe is older than the business rules and may contradict them. Which constraint is MOST appropriate?<\/p>","m":["“Use only the wireframe, because the image is more precise than text.”","“Write at most five acceptance criteria.”","“Act as a UX designer and evaluate the visual design of the screen.”","“If the wireframe and the business rules contradict each other, the business rules take precedence; list every contradiction separately.”"],"vys":{"a":"Incorrect. It ignores the newer business rules and hides the known contradictions (syllabus 2.2.1).","b":"Incorrect. Limiting the number does not address the conflicting inputs and may reduce completeness (syllabus 2.2.1).","c":"Incorrect. This changes the role and the task away from acceptance criteria (syllabus 2.1.1).","d":"Correct. It tells the LLM how to apply the instruction to conflicting input data and makes conflicts visible to the tester (syllabus 2.1.1, 2.2.1, HO-2.2.1a)."},"obecne":"The quality and relevance of inputs directly impact the output; constraints specify how instructions apply to the input data."},"cz":{"q":"<p>Vytváříte multimodální prompt, který má odvodit akceptační kritéria pro obrazovku trvalého příkazu. Vstupními daty jsou uživatelský scénář, wireframe GUI a obchodní pravidla pro pole. Víte, že wireframe je starší než pravidla a může jim odporovat. Které omezení je NEJVHODNĚJŠÍ?<\/p>","m":["„Použij jen wireframe, protože obrázek je přesnější než text.“","„Napiš nejvýše pět akceptačních kritérií.“","„Jednej jako UX designér a ohodnoť vizuální návrh obrazovky.“","„Pokud si wireframe a obchodní pravidla odporují, platí obchodní pravidla; každý rozpor vypiš zvlášť.“"],"vys":{"a":"Špatně. Ignoruje novější pravidla a skryje známé rozpory (sylabus 2.2.1).","b":"Špatně. Omezení počtu neřeší rozporné vstupy a může snížit úplnost (sylabus 2.2.1).","c":"Špatně. Mění roli i úlohu mimo akceptační kritéria (sylabus 2.1.1).","d":"Správně. Říká modelu, jak použít instrukci na rozporná vstupní data, a zviditelní rozpory testerovi (sylabus 2.1.1, 2.2.1, HO-2.2.1a)."},"obecne":"Kvalita a relevance vstupů přímo ovlivňuje výstup; omezení určují, jak se instrukce použije na vstupní data."},"kap":{"c":"2.2.1","nazev":"2.2.1 Testovací analýza s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.1-04","n":null,"lo":"GenAI-2.2.1","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>A test analyst at an insurance company wants to find out which of 42 requirements of a claims module are not yet covered by the existing 96 test conditions. Which prompt is BEST suited?<\/p>","m":["Provide both lists and ask for a traceability matrix requirement × test conditions, marking each requirement as covered, partially covered or not covered, and counting only links based on the content of the requirement.","Provide the test conditions only and ask the LLM which requirements it thinks are typical for a claims module.","Provide the requirements only and ask the LLM to generate 96 new test conditions.","Provide both lists and ask the LLM to sort the test conditions alphabetically and remove duplicates."],"vys":{"a":"Correct. Mapping requirements to test conditions with explicit coverage status supports coverage analysis (syllabus 2.2.1).","b":"Incorrect. The model would guess requirements instead of using the actual test basis (syllabus 2.2.1).","c":"Incorrect. Without the existing conditions, coverage gaps cannot be identified (syllabus 2.2.1).","d":"Incorrect. Sorting and de-duplication do not show which requirements are uncovered (syllabus 2.2.1)."},"obecne":"Coverage analysis maps requirements and user stories to test conditions to check whether all aspects of the test basis are covered."},"cz":{"q":"<p>Test analytik pojišťovny chce zjistit, které ze 42 požadavků modulu pojistných událostí ještě nejsou pokryté existujícími 96 testovacími podmínkami. Který prompt je pro to NEJVHODNĚJŠÍ?<\/p>","m":["Dodat oba seznamy a požádat o matici trasovatelnosti požadavek × testovací podmínky se stavem pokryto, částečně, nepokryto, přičemž se počítají jen vazby podle obsahu požadavku.","Dodat jen testovací podmínky a zeptat se LLM, jaké požadavky jsou pro modul pojistných událostí typické.","Dodat jen požadavky a požádat LLM o vygenerování 96 nových testovacích podmínek.","Dodat oba seznamy a požádat LLM, aby seřadil podmínky abecedně a odstranil duplicity."],"vys":{"a":"Správně. Mapování požadavků na podmínky s výslovným stavem pokrytí podporuje analýzu pokrytí (sylabus 2.2.1).","b":"Špatně. Model by požadavky hádal místo použití skutečné testovací báze (sylabus 2.2.1).","c":"Špatně. Bez existujících podmínek nelze mezery v pokrytí určit (sylabus 2.2.1).","d":"Špatně. Řazení a odstranění duplicit neukáže, které požadavky nejsou pokryté (sylabus 2.2.1)."},"obecne":"Analýza pokrytí mapuje požadavky a uživatelské scénáře na testovací podmínky a ověřuje, zda jsou pokryté všechny aspekty testovací báze."},"kap":{"c":"2.2.1","nazev":"2.2.1 Testovací analýza s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.1-05","n":null,"lo":"GenAI-2.2.1","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>Before development starts, a tester wants an LLM to help review the requirements of a car insurance premium calculator. Which instruction is BEST suited for this test analysis task?<\/p>","m":["“Create a test execution schedule for the calculator.”","“Identify ambiguities, contradictions and missing information in the requirements and explain for each why it could lead to a defect.”","“Summarize the requirements in three sentences for management.”","“Write Playwright scripts for the calculator.”"],"vys":{"a":"Incorrect. Scheduling belongs to test implementation and needs test cases first (syllabus 2.2.2).","b":"Correct. It targets potential defects in the test basis, a typical test analysis task (syllabus 2.2.1).","c":"Incorrect. A summary does not identify defects in the test basis (syllabus 2.2.1).","d":"Incorrect. Scripts are test implementation, and the calculator does not exist yet (syllabus 2.2.2)."},"obecne":"GenAI can analyze the test basis for inconsistencies, ambiguities or incomplete information and suggest improvements."},"cz":{"q":"<p>Před začátkem vývoje chce tester s pomocí LLM revidovat požadavky na kalkulačku povinného ručení. Která instrukce je pro tuto úlohu testovací analýzy NEJVHODNĚJŠÍ?<\/p>","m":["„Vytvoř harmonogram provedení testů pro kalkulačku.“","„Najdi v požadavcích nejednoznačnosti, rozpory a chybějící informace a u každé vysvětli, proč by mohla vést k defektu.“","„Shrň požadavky do tří vět pro vedení.“","„Napiš Playwright skripty pro kalkulačku.“"],"vys":{"a":"Špatně. Harmonogram patří do implementace testování a potřebuje nejdřív testovací případy (sylabus 2.2.2).","b":"Správně. Míří na potenciální defekty v testovací bázi, typickou úlohu testovací analýzy (sylabus 2.2.1).","c":"Špatně. Shrnutí neodhalí defekty v testovací bázi (sylabus 2.2.1).","d":"Špatně. Skripty patří do implementace testování a kalkulačka ještě neexistuje (sylabus 2.2.2)."},"obecne":"GenAI může v testovací bázi hledat nekonzistence, nejednoznačnosti a neúplné informace a navrhovat zlepšení."},"kap":{"c":"2.2.1","nazev":"2.2.1 Testovací analýza s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.2-01","n":null,"lo":"GenAI-2.2.2","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>Your team writes test cases in Gherkin. You have a set of approved examples, each consisting of a user story, its test conditions and its Gherkin scenarios. You want the LLM to produce the same for a new user story about filtering invoices by price range. Which prompt is MOST appropriate?<\/p>","m":["Describe Gherkin syntax in general terms and ask for scenarios for the new story, without examples.","Include the examples but ask only for edge-case scenarios for the new story.","Include two or three of the approved examples with story, conditions and scenarios, then the new story, and ask for test conditions and Gherkin scenarios in exactly the same style, one scenario per condition.","Include only the Gherkin scenarios of the examples, without their user stories and conditions, and ask the LLM to follow best practices."],"vys":{"a":"Incorrect. This is zero-shot; it does not use the team's approved examples to fix the style (syllabus 2.1.2).","b":"Incorrect. Focusing only on edge cases would miss the main conditions of the story (syllabus 2.2.2).","c":"Correct. Few-shot examples that include story, conditions and scenarios model the expected result for the new story (syllabus 2.2.2, HO-2.2.2b).","d":"Incorrect. Without the story and conditions the examples do not show the mapping from input to output, and “best practices” is vague (syllabus 2.1.1, HO-2.2.2b)."},"obecne":"In few-shot prompting for Gherkin, each example includes the user story, test conditions and the expected Given-When-Then test cases."},"cz":{"q":"<p>Váš tým píše testovací případy v Gherkinu. Máte sadu schválených příkladů, každý obsahuje uživatelský scénář, jeho testovací podmínky a Gherkin scénáře. Chcete, aby LLM vytvořil totéž pro nový uživatelský scénář o filtrování faktur podle rozsahu ceny. Který prompt je NEJVHODNĚJŠÍ?<\/p>","m":["Obecně popsat syntaxi Gherkinu a požádat o scénáře pro nový příběh bez příkladů.","Vložit příklady, ale požádat jen o scénáře pro okrajové případy nového příběhu.","Vložit dva nebo tři schválené příklady se scénářem, podmínkami a Gherkinem, pak nový scénář, a požádat o testovací podmínky a Gherkin scénáře přesně ve stejném stylu, jeden scénář na podmínku.","Vložit jen Gherkin scénáře z příkladů bez uživatelských scénářů a podmínek a požádat LLM, aby se držel osvědčených postupů."],"vys":{"a":"Špatně. Jde o zero-shot, který nevyužije schválené příklady k ukotvení stylu (sylabus 2.1.2).","b":"Špatně. Zaměření jen na okrajové případy vynechá hlavní podmínky příběhu (sylabus 2.2.2).","c":"Správně. Few-shot příklady se scénářem, podmínkami a Gherkinem ukazují očekávaný výsledek pro nový scénář (sylabus 2.2.2, HO-2.2.2b).","d":"Špatně. Bez scénáře a podmínek příklady neukazují převod vstupu na výstup a „osvědčené postupy“ jsou vágní (sylabus 2.1.1, HO-2.2.2b)."},"obecne":"U few-shot promptu pro Gherkin obsahuje každý příklad uživatelský scénář, testovací podmínky a očekávané testovací případy Given-When-Then."},"kap":{"c":"2.2.2","nazev":"2.2.2 Návrh testů a implementace testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.2-02","n":null,"lo":"GenAI-2.2.2","k":"K3","body":2,"vyber":1,"ok":[3],"en":{"q":"<p>A tester needs 500 client records to test the registration of a banking application, including invalid and extreme values. A colleague suggests pasting 50 real client records from production into the prompt “so that the data look realistic”. Which approach is MOST appropriate?<\/p>","m":["Ask the LLM for 500 records with valid values only, because invalid values are generated by the application anyway.","Paste the 50 real records and ask the LLM to change only the surnames.","Ask the LLM to write test cases first and to invent the data later during test execution.","Describe the field rules and formats in the prompt and ask for synthetic records with an explicit share of invalid and extreme values, without using any real client data."],"vys":{"a":"Incorrect. Test data should cover invalid and extreme situations as well (syllabus 2.2.2).","b":"Incorrect. Real client data would still be exposed; the syllabus stresses privacy-preserving synthetic data (syllabus 2.2.2, chapter 3).","c":"Incorrect. Data needed for execution belong to test implementation and should be prepared before execution (syllabus 2.2.2).","d":"Correct. GenAI can synthesize representative, privacy-preserving test data covering extreme situations (syllabus 2.2.2)."},"obecne":"Synthetic test data resemble production data and cover extreme situations without exposing sensitive information."},"cz":{"q":"<p>Tester potřebuje 500 záznamů klientů pro testování registrace v bankovní aplikaci, včetně neplatných a extrémních hodnot. Kolega navrhuje vložit do promptu 50 skutečných záznamů klientů z produkce, „aby data vypadala realisticky“. Který postup je NEJVHODNĚJŠÍ?<\/p>","m":["Požádat LLM o 500 záznamů jen s platnými hodnotami, protože neplatné hodnoty vytvoří aplikace sama.","Vložit 50 skutečných záznamů a požádat LLM, aby změnil jen příjmení.","Požádat LLM nejdřív o testovací případy a data vymýšlet až při provedení testů.","Popsat v promptu pravidla a formáty polí a požádat o syntetické záznamy s daným podílem neplatných a extrémních hodnot bez použití skutečných dat klientů."],"vys":{"a":"Špatně. Testovací data mají pokrýt i neplatné a extrémní situace (sylabus 2.2.2).","b":"Špatně. Skutečná data klientů by stále byla odhalena; sylabus zdůrazňuje syntetická data chránící soukromí (sylabus 2.2.2, kapitola 3).","c":"Špatně. Data potřebná k provedení patří do implementace testování a připravují se před provedením (sylabus 2.2.2).","d":"Správně. GenAI umí syntetizovat reprezentativní data chránící soukromí, včetně extrémních situací (sylabus 2.2.2)."},"obecne":"Syntetická testovací data připomínají produkční data a pokrývají extrémní situace bez odhalení citlivých informací."},"kap":{"c":"2.2.2","nazev":"2.2.2 Návrh testů a implementace testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.2-03","n":null,"lo":"GenAI-2.2.2","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>An automation engineer asks an LLM to convert structured test cases into Playwright tests for an invoicing web application. The project uses the Page Object Model and keeps all locators in page objects. The generated tests run, but they contain locators directly in the test code. Which change to the prompt is MOST likely to fix this?<\/p>","m":["Add two existing tests and the page object interfaces as examples, and a constraint that tests may only call page object methods; missing methods must be listed separately.","Change the role to “expert Playwright engineer”.","Ask the model to generate the tests in Selenium instead of Playwright.","Accept the tests because they run, which means the execution success rate is 100 %."],"vys":{"a":"Correct. Examples of the project style plus an explicit constraint guide the model to the required structure (syllabus 2.2.2, 2.1.2).","b":"Incorrect. The role alone does not tell the model about the project's Page Object Model (syllabus 2.1.1).","c":"Incorrect. Changing the framework does not address the structure problem and breaks consistency with the project.","d":"Incorrect. Running tests do not prove they fit the project's context; relevance and maintainability also matter (syllabus 2.3.1)."},"obecne":"GenAI can generate automated test scripts from structured test cases for various frameworks; context and examples make the scripts fit the project."},"cz":{"q":"<p>Inženýr automatizace žádá LLM o převod strukturovaných testovacích případů na Playwright testy pro fakturační webovou aplikaci. Projekt používá Page Object Model a všechny lokátory drží ve stránkových objektech. Vygenerované testy se spustí, ale obsahují lokátory přímo v kódu testu. Která změna promptu to NEJSPÍŠ napraví?<\/p>","m":["Přidat dva existující testy a rozhraní stránkových objektů jako příklady a omezení, že testy smí volat jen metody stránkových objektů; chybějící metody se vypíšou zvlášť.","Změnit roli na „expert na Playwright“.","Požádat model, aby testy vygeneroval v Seleniu místo Playwrightu.","Testy přijmout, protože se spustí, a execution success rate je tedy 100 %."],"vys":{"a":"Správně. Příklady stylu projektu a výslovné omezení vedou model k požadované struktuře (sylabus 2.2.2, 2.1.2).","b":"Špatně. Samotná role modelu o Page Object Modelu projektu nic neřekne (sylabus 2.1.1).","c":"Špatně. Změna frameworku neřeší problém se strukturou a naruší konzistenci s projektem.","d":"Špatně. Spustitelnost neznamená soulad s kontextem projektu; záleží i na relevanci a udržovatelnosti (sylabus 2.3.1)."},"obecne":"GenAI umí ze strukturovaných testovacích případů generovat automatizované skripty pro různé frameworky; kontext a příklady zajistí, že sedí do projektu."},"kap":{"c":"2.2.2","nazev":"2.2.2 Návrh testů a implementace testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.2-04","n":null,"lo":"GenAI-2.2.2","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>A test suite of 40 test cases has priorities, risks and dependencies (some test cases prepare data for others). In a single prompt, the LLM produced an execution order sorted by risk, but several test cases were scheduled before the test cases they depend on. Which approach is MOST appropriate?<\/p>","m":["Ask the LLM for a meta prompt and use its output as the final schedule.","Use prompt chaining: first let the LLM extract all dependencies and verify them manually, then ask for an order by risk that respects the verified dependencies, and verify the result again.","Repeat the same prompt until an order without violations appears.","Remove the dependencies from the input data so the model can focus on risk."],"vys":{"a":"Incorrect. A meta prompt produces a prompt, not a verified schedule (syllabus 2.1.2).","b":"Correct. Multi-criteria tasks benefit from decomposition with manual verification of the LLM's reasoning (syllabus 2.2.2, HO-2.2.2c).","c":"Incorrect. Repeating does not address the reasoning error and gives no assurance (syllabus 2.2.2, 2.3.2).","d":"Incorrect. Dependencies are a required criterion of the schedule (syllabus 2.2.2)."},"obecne":"Test execution scheduling considers priority, risks, dependencies and resources; results must be verified to detect reasoning errors."},"cz":{"q":"<p>Testovací sada 40 testovacích případů má priority, rizika a závislosti (některé případy připravují data pro jiné). V jednom promptu LLM vytvořil pořadí provedení seřazené podle rizika, ale několik případů zařadil před případy, na kterých závisí. Který postup je NEJVHODNĚJŠÍ?<\/p>","m":["Požádat LLM o meta prompt a jeho výstup použít jako konečný harmonogram.","Použít řetězení: nejdřív nechat LLM vypsat všechny závislosti a ručně je ověřit, pak požádat o pořadí podle rizika, které ověřené závislosti dodrží, a výsledek znovu ověřit.","Opakovat stejný prompt, dokud nevyjde pořadí bez porušení.","Odstranit závislosti ze vstupních dat, aby se model mohl soustředit na riziko."],"vys":{"a":"Špatně. Meta prompt vytvoří prompt, ne ověřený harmonogram (sylabus 2.1.2).","b":"Správně. Úlohy s více kritérii těží z rozkladu s ručním ověřením uvažování modelu (sylabus 2.2.2, HO-2.2.2c).","c":"Špatně. Opakování neřeší chybu v uvažování a nedává žádnou jistotu (sylabus 2.2.2, 2.3.2).","d":"Špatně. Závislosti jsou povinné kritérium harmonogramu (sylabus 2.2.2)."},"obecne":"Plánování provedení zohledňuje prioritu, rizika, závislosti a zdroje; výsledek je nutné ověřit kvůli chybám v uvažování."},"kap":{"c":"2.2.2","nazev":"2.2.2 Návrh testů a implementace testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.2-05","n":null,"lo":"GenAI-2.2.2","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>In the first prompt of a chain, an LLM generated functional test cases from five acceptance criteria in the requested format. What is the MOST appropriate next prompt?<\/p>","m":["Ask the LLM to delete test cases that look similar without reviewing them.","Ask the LLM to estimate how long the project will take.","Ask the LLM to create a table that shows which acceptance criterion is covered by which test case and to flag criteria without coverage.","Ask the LLM to translate the test cases into another language."],"vys":{"a":"Incorrect. Removing test cases without review may reduce coverage (syllabus 2.2.2).","b":"Incorrect. Estimation is unrelated to verifying the generated test cases.","c":"Correct. Verifying completeness with a coverage table is the next step in syllabus HO-2.2.2a (syllabus 2.2.2).","d":"Incorrect. Translation does not check whether the test cases are complete (syllabus 2.2.2)."},"obecne":"HO-2.2.2a: generate test cases, verify completeness with a coverage table, then use a meta prompt for end-to-end procedures."},"cz":{"q":"<p>V prvním promptu řetězu LLM vygeneroval z pěti akceptačních kritérií funkční testovací případy v požadovaném formátu. Jaký je NEJVHODNĚJŠÍ další prompt?<\/p>","m":["Požádat LLM o smazání podobně vypadajících případů bez kontroly.","Požádat LLM o odhad, jak dlouho projekt potrvá.","Požádat LLM o tabulku, která ukáže, které akceptační kritérium pokrývá který testovací případ, a označí kritéria bez pokrytí.","Požádat LLM o překlad testovacích případů do jiného jazyka."],"vys":{"a":"Špatně. Odstranění případů bez kontroly může snížit pokrytí (sylabus 2.2.2).","b":"Špatně. Odhad nesouvisí s ověřením vygenerovaných testovacích případů.","c":"Správně. Ověření úplnosti tabulkou pokrytí je další krok podle HO-2.2.2a (sylabus 2.2.2).","d":"Špatně. Překlad neověří úplnost testovacích případů (sylabus 2.2.2)."},"obecne":"HO-2.2.2a: vygenerovat testovací případy, ověřit úplnost tabulkou pokrytí, pak meta promptem vytvořit end-to-end procedury."},"kap":{"c":"2.2.2","nazev":"2.2.2 Návrh testů a implementace testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.3-01","n":null,"lo":"GenAI-2.2.3","k":"K3","body":2,"vyber":1,"ok":[3],"en":{"q":"<p>A regression suite for an online banking application uses a keyword-driven framework with a documented keyword library and about 50 existing scripts. You want an LLM to create scripts for 30 new test cases that are consistent with the existing ones. Which prompt is MOST appropriate?<\/p>","m":["Send the 30 test cases one by one without examples and merge the results manually.","Ask the LLM to write the scripts in Python with its own helper functions, because code is more flexible than keywords.","Describe the test cases and ask the LLM to create suitable keywords for each step.","Provide the keyword library documentation and three representative existing scripts as examples, with the constraint to use only keywords from the library and to report any missing keyword instead of inventing it."],"vys":{"a":"Incorrect. Without examples the output style is likely to vary; few-shot is recommended for this pattern (syllabus 2.2.5).","b":"Incorrect. This abandons the existing keyword-driven framework and consistency with the suite (syllabus 2.2.3).","c":"Incorrect. Inventing new keywords breaks the predefined library that represents common steps (syllabus 2.2.3).","d":"Correct. Few-shot prompting with examples and the library suits repetitive keyword-driven script generation (syllabus 2.2.3, 2.2.5, HO-2.2.3a)."},"obecne":"LLMs can map predefined keywords to test cases and generate keyword-driven scripts; few-shot prompting fits this repetitive pattern."},"cz":{"q":"<p>Regresní sada internetového bankovnictví používá framework řízený klíčovými slovy se zdokumentovanou knihovnou klíčových slov a asi 50 existujícími skripty. Chcete, aby LLM vytvořil skripty pro 30 nových testovacích případů konzistentní s existujícími. Který prompt je NEJVHODNĚJŠÍ?<\/p>","m":["Posílat 30 testovacích případů po jednom bez příkladů a výsledky ručně sloučit.","Požádat LLM o skripty v Pythonu s vlastními pomocnými funkcemi, protože kód je pružnější než klíčová slova.","Popsat testovací případy a požádat LLM, aby pro každý krok vytvořil vhodná klíčová slova.","Dodat dokumentaci knihovny klíčových slov a tři reprezentativní existující skripty jako příklady s omezením používat jen klíčová slova z knihovny a chybějící klíčové slovo nahlásit místo vymyšlení."],"vys":{"a":"Špatně. Bez příkladů bude styl výstupu kolísat; pro tento vzor se doporučuje few-shot (sylabus 2.2.5).","b":"Špatně. Tím se opustí existující framework klíčových slov a konzistence se sadou (sylabus 2.2.3).","c":"Špatně. Vymýšlení nových klíčových slov narušuje předem definovanou knihovnu běžných kroků (sylabus 2.2.3).","d":"Správně. Few-shot s příklady a knihovnou se hodí pro opakované generování skriptů řízených klíčovými slovy (sylabus 2.2.3, 2.2.5, HO-2.2.3a)."},"obecne":"LLM umí mapovat předem definovaná klíčová slova na testovací případy a generovat skripty; few-shot se na tento opakující se vzor hodí."},"kap":{"c":"2.2.3","nazev":"2.2.3 Automatizované regresní testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.3-02","n":null,"lo":"GenAI-2.2.3","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>A regression suite of an insurance policy system has 1,500 automated tests and runs for five hours. The team wants an LLM to select relevant regression tests after each merge request. The current prompt provides only the code diff and asks: “Select the regression tests that must be run.” The selection is unreliable. Which improvement is MOST effective?<\/p>","m":["Add a mapping of tests to the modules and files they cover, and instruct the LLM to identify affected areas from the diff and select tests through this mapping, listing changed files with no mapped tests as risks.","Ask the LLM to make all failing tests self-healing.","Change the output format to a dashboard with test trends.","Limit the selection to at most 100 tests so that the run takes less than 20 minutes."],"vys":{"a":"Correct. Impact analysis needs a link between code changes and tests; the mapping is the missing input data (syllabus 2.2.3).","b":"Incorrect. Self-healing addresses minor UI or API changes, not test selection (syllabus 2.2.3).","c":"Incorrect. The presentation of the result does not improve the selection itself (syllabus 2.1.1).","d":"Incorrect. A fixed limit does not make the selection better founded and may drop necessary tests (syllabus 2.2.3)."},"obecne":"GenAI can analyze code changes to identify high-risk areas and enable targeted regression testing."},"cz":{"q":"<p>Regresní sada systému pojistných smluv má 1 500 automatizovaných testů a běží pět hodin. Tým chce, aby LLM po každém merge requestu vybral relevantní regresní testy. Současný prompt dodává jen diff kódu a žádá: „Vyber regresní testy, které je nutné spustit.“ Výběr je nespolehlivý. Která úprava je NEJÚČINNĚJŠÍ?<\/p>","m":["Přidat mapu testů na moduly a soubory, které pokrývají, a instruovat LLM, aby z diffu určil ovlivněné oblasti, vybral testy přes mapu a změněné soubory bez testů uvedl jako riziko.","Požádat LLM, aby všechny padající testy udělal samoopravnými.","Změnit formát výstupu na dashboard s trendy testů.","Omezit výběr na nejvýše 100 testů, aby běh trval méně než 20 minut."],"vys":{"a":"Správně. Analýza dopadu potřebuje vazbu mezi změnami kódu a testy; mapa je chybějící vstupní data (sylabus 2.2.3).","b":"Špatně. Samooprava řeší drobné změny UI nebo API, ne výběr testů (sylabus 2.2.3).","c":"Špatně. Podoba výsledku samotný výběr nezlepší (sylabus 2.1.1).","d":"Špatně. Pevný limit nezlepší podklad výběru a může vynechat potřebné testy (sylabus 2.2.3)."},"obecne":"GenAI umí analyzovat změny v kódu, určit vysoce rizikové oblasti a zacílit regresní testování."},"kap":{"c":"2.2.3","nazev":"2.2.3 Automatizované regresní testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.3-03","n":null,"lo":"GenAI-2.2.3","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>After a UI update, many GUI regression tests fail because button locators changed. The team plans to let an LLM-based tool adapt the scripts automatically. Which way of applying this is MOST appropriate?<\/p>","m":["Delete all failing tests and ask the LLM to generate new ones from scratch.","Let the tool adapt locators for minor changes, log every adaptation with the old and new locator, and have a tester review the changes, especially for high-risk functions.","Stop running GUI regression tests and rely on API tests only.","Let the tool adapt any failing step automatically and suppress the original failure in the report."],"vys":{"a":"Incorrect. This discards maintained tests instead of adapting them to minor changes (syllabus 2.2.3).","b":"Correct. Self-healing reduces unnecessary failures, but GenAI output must be checked according to the associated risk (syllabus 2.2.3).","c":"Incorrect. The syllabus describes how GenAI helps stabilize GUI tests, not abandoning them (syllabus 2.2.3).","d":"Incorrect. Hiding failures could mask real defects; output must be checked (syllabus 2.2.3)."},"obecne":"Self-healing and adaptive tests handle minor UI or API changes; testers must check GenAI output depending on risk."},"cz":{"q":"<p>Po úpravě UI padá mnoho GUI regresních testů, protože se změnily lokátory tlačítek. Tým chce nechat nástroj postavený na LLM skripty automaticky přizpůsobit. Který způsob použití je NEJVHODNĚJŠÍ?<\/p>","m":["Smazat všechny padající testy a požádat LLM o nové od začátku.","Nechat nástroj přizpůsobit lokátory u drobných změn, každou úpravu zalogovat se starým a novým lokátorem a změny nechat zkontrolovat testerem, hlavně u rizikových funkcí.","Přestat spouštět GUI regresní testy a spoléhat jen na API testy.","Nechat nástroj automaticky přizpůsobit každý padající krok a původní selhání v reportu potlačit."],"vys":{"a":"Špatně. Tím se zahodí udržované testy místo jejich přizpůsobení drobným změnám (sylabus 2.2.3).","b":"Správně. Samooprava omezuje zbytečná selhání, ale výstup GenAI se musí kontrolovat podle souvisejícího rizika (sylabus 2.2.3).","c":"Špatně. Sylabus popisuje, jak GenAI pomáhá GUI testy stabilizovat, ne jak se jich vzdát (sylabus 2.2.3).","d":"Špatně. Skrývání selhání může zakrýt skutečné defekty; výstup je nutné kontrolovat (sylabus 2.2.3)."},"obecne":"Samoopravné a adaptivní testy zvládají drobné změny UI a API; tester musí výstup GenAI kontrolovat podle rizika."},"kap":{"c":"2.2.3","nazev":"2.2.3 Automatizované regresní testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.3-04","n":null,"lo":"GenAI-2.2.3","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>You analyze the results of a nightly regression run with structured prompts in one LLM conversation. Which sequence of steps is MOST appropriate?<\/p><ol><li>Cluster similar failures by probable common cause.<\/li><li>Analyze the test results and compare them with the test specification.<\/li><li>Cross-check that every failed test is assigned to exactly one cluster and that the findings are consistent.<\/li><li>Compare the clusters with the known anomalies list and update the list.<\/li><\/ol>","m":["1 – 2 – 3 – 4","3 – 2 – 1 – 4","2 – 1 – 4 – 3","2 – 4 – 3 – 1"],"vys":{"a":"Incorrect. Clustering before analyzing the results against the specification groups unverified failures (syllabus HO-2.2.3b).","b":"Incorrect. A cross-check needs findings to check, so it cannot come first (syllabus HO-2.2.3b).","c":"Correct. Analysis and comparison with the specification, clustering, known anomalies list, cross-check (syllabus 2.2.3, HO-2.2.3b).","d":"Incorrect. Known anomalies are compared with clusters, which do not exist yet at step 2 (syllabus HO-2.2.3b)."},"obecne":"HO-2.2.3b: analysis and comparison with the test specification, clustering of similar defects, maintenance of the known anomalies list, cross-checking."},"cz":{"q":"<p>Analyzujete výsledky nočního regresního běhu strukturovanými prompty v jedné konverzaci s LLM. Která posloupnost kroků je NEJVHODNĚJŠÍ?<\/p><ol><li>Seskupit podobná selhání podle pravděpodobné společné příčiny.<\/li><li>Analyzovat výsledky testů a porovnat je se specifikací testů.<\/li><li>Křížově zkontrolovat, že každý neúspěšný test patří právě do jedné skupiny a že zjištění jsou konzistentní.<\/li><li>Porovnat skupiny se seznamem známých anomálií a seznam aktualizovat.<\/li><\/ol>","m":["1 – 2 – 3 – 4","3 – 2 – 1 – 4","2 – 1 – 4 – 3","2 – 4 – 3 – 1"],"vys":{"a":"Špatně. Seskupování před analýzou výsledků vůči specifikaci seskupuje neověřená selhání (sylabus HO-2.2.3b).","b":"Špatně. Křížová kontrola potřebuje zjištění, která kontroluje, nemůže být první (sylabus HO-2.2.3b).","c":"Správně. Analýza a porovnání se specifikací, seskupení, seznam známých anomálií, křížová kontrola (sylabus 2.2.3, HO-2.2.3b).","d":"Špatně. Se známými anomáliemi se porovnávají skupiny, které po kroku 2 ještě neexistují (sylabus HO-2.2.3b)."},"obecne":"HO-2.2.3b: analýza a porovnání se specifikací testů, seskupení podobných defektů, údržba seznamu známých anomálií, křížová kontrola."},"kap":{"c":"2.2.3","nazev":"2.2.3 Automatizované regresní testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.3-05","n":null,"lo":"GenAI-2.2.3","k":"K3","body":2,"vyber":1,"ok":[3],"en":{"q":"<p>A tester wants an LLM to compile defect reports from failed automated regression tests. The draft prompt provides only the name of the failed test and asks: “Write a defect report.” Developers complain that the reports guess at causes and lack evidence. Which improvement is MOST appropriate?<\/p>","m":["Ask the LLM to keep the reports shorter.","Change the role to “senior developer” so that the reports sound more technical.","Ask the LLM to mark every failure as a known anomaly.","Provide the test log, screenshot, server stack trace and environment data as input, ask for the team's defect report template, and require facts from logs to be separated from root-cause hypotheses."],"vys":{"a":"Incorrect. Shorter reports would still lack evidence and contain guesses.","b":"Incorrect. A different persona does not provide the missing evidence (syllabus 2.1.1).","c":"Incorrect. This hides possible new defects instead of reporting them (syllabus 2.2.3).","d":"Correct. Comprehensive defect reports use test logs, screenshots and environment data; separating facts from hypotheses supports root cause analysis (syllabus 2.2.3)."},"obecne":"GenAI can compile comprehensive defect reports with logs, screenshots and environment data; the quality of the input decides the quality of the report."},"cz":{"q":"<p>Tester chce, aby LLM sestavoval reporty o defektech z neúspěšných automatizovaných regresních testů. Návrh promptu dodává jen název neúspěšného testu a žádá: „Napiš report o defektu.“ Vývojáři si stěžují, že reporty hádají příčiny a chybí v nich důkazy. Která úprava je NEJVHODNĚJŠÍ?<\/p>","m":["Požádat LLM o kratší reporty.","Změnit roli na „senior vývojář“, aby reporty zněly techničtěji.","Požádat LLM, aby každé selhání označil jako známou anomálii.","Dodat jako vstup log testu, snímek obrazovky, stack trace serveru a údaje o prostředí, požadovat šablonu reportu týmu a oddělit fakta z logů od hypotéz o kořenové příčině."],"vys":{"a":"Špatně. Kratší reporty budou stále bez důkazů a s domněnkami.","b":"Špatně. Jiná persona nedodá chybějící důkazy (sylabus 2.1.1).","c":"Špatně. Tím se skryjí možné nové defekty místo jejich nahlášení (sylabus 2.2.3).","d":"Správně. Úplný report o defektu využívá logy, snímky a údaje o prostředí; oddělení faktů od hypotéz podporuje analýzu kořenové příčiny (sylabus 2.2.3)."},"obecne":"GenAI umí sestavit úplné reporty o defektech s logy, snímky a údaji o prostředí; kvalita vstupu rozhoduje o kvalitě reportu."},"kap":{"c":"2.2.3","nazev":"2.2.3 Automatizované regresní testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.4-01","n":null,"lo":"GenAI-2.2.4","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>A test manager of an e-shop wants an LLM to warn her every morning about deviations from the test plan before they become problems. Her draft prompt:<\/p><pre>Role: Act as a test manager.\nContext: Acceptance testing of a new e-shop release, four weeks.\nInstruction: Summarize yesterday&#x27;s test results.\nInput data: Export of yesterday&#x27;s test results.\nConstraints: Keep it short and clear.\nOutput format: One paragraph of text.<\/pre><p>Which improvement BEST supports her goal?<\/p>","m":["Add the planned daily progress (executed tests, resolved defects) to the input data and change the instruction to compare actual progress with the plan and flag deviations above 10 %.","Extend the constraint to “keep it short, clear and professional”.","Change the role to “test manager with 15 years of experience in e-commerce”.","Add a chart of passed tests per day to the output format."],"vys":{"a":"Correct. Deviations from the plan can only be detected with the plan as input and an instruction to compare (syllabus 2.2.4).","b":"Incorrect. This only rephrases the existing constraint and adds no information.","c":"Incorrect. The persona adds no plan data to compare against (syllabus 2.1.1).","d":"Incorrect. A chart without plan values does not show deviations (syllabus 2.2.4)."},"obecne":"GenAI can analyze trends, predict risks and alert teams to deviations from the plan."},"cz":{"q":"<p>Test manažerka e-shopu chce, aby ji LLM každé ráno upozornil na odchylky od plánu testování dřív, než se z nich stanou problémy. Její návrh promptu:<\/p><pre>Role: Act as a test manager.\nContext: Acceptance testing of a new e-shop release, four weeks.\nInstruction: Summarize yesterday&#x27;s test results.\nInput data: Export of yesterday&#x27;s test results.\nConstraints: Keep it short and clear.\nOutput format: One paragraph of text.<\/pre><p>Která úprava NEJLÉPE podpoří její cíl?<\/p>","m":["Doplnit do vstupních dat plánovaný denní postup (provedené testy, vyřešené defekty) a změnit instrukci na porovnání skutečnosti s plánem a označení odchylek nad 10 %.","Rozšířit omezení na „stručně, jasně a profesionálně“.","Změnit roli na „test manažer s 15 lety praxe v e-commerce“.","Přidat do formátu výstupu graf prošlých testů po dnech."],"vys":{"a":"Správně. Odchylky od plánu lze odhalit jen s plánem na vstupu a instrukcí k porovnání (sylabus 2.2.4).","b":"Špatně. Jen jinými slovy opakuje existující omezení a nepřidává informaci.","c":"Špatně. Persona nepřidá data plánu, se kterými by se porovnávalo (sylabus 2.1.1).","d":"Špatně. Graf bez plánovaných hodnot odchylky neukáže (sylabus 2.2.4)."},"obecne":"GenAI umí analyzovat trendy, předvídat rizika a upozorňovat tým na odchylky od plánu."},"kap":{"c":"2.2.4","nazev":"2.2.4 Monitoring testování a řízení testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.4-02","n":null,"lo":"GenAI-2.2.4","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>An LLM receives the following cumulative data for one week of system testing (plan: 250 executed test cases by Friday) and is asked for test progress metrics:<\/p><pre>Executed: 200   Passed: 150   Failed: 40   Blocked: 10\nNew defects this week: 30   Closed defects this week: 18<\/pre><p>Which LLM summary is correct and therefore safe to pass on after review?<\/p>","m":["“95 % of the executed tests were completed without blocking; testing is ahead of plan.”","“80 % of the planned tests were executed; 75 % of the executed tests passed; the number of open defects grew by 12 this week.”","“Testing is on plan; 75 % of the executed tests passed; 30 open defects remain.”","“80 % of the planned tests were executed; 60 % of the executed tests passed; open defects decreased by 12.”"],"vys":{"a":"Incorrect. Testing is behind plan (200 of 250), so the conclusion is wrong (syllabus 2.2.4).","b":"Correct. 200/250 = 80 %, 150/200 = 75 %, 30 − 18 = 12. Metrics produced by an LLM must still be verified (syllabus 2.2.4, chapter 3).","c":"Incorrect. Execution is 50 tests behind plan, and the open-defect figure ignores closed defects and earlier weeks (syllabus 2.2.4).","d":"Incorrect. 60 % is 150/250, not the pass rate of executed tests, and open defects increased (syllabus 2.2.4)."},"obecne":"GenAI transforms test data into monitoring metrics such as progress and defect trends; numbers must be checked because LLMs can make reasoning errors."},"cz":{"q":"<p>LLM dostane tato kumulativní data za týden systémového testování (plán: 250 provedených testovacích případů do pátku) a má z nich vytvořit metriky postupu:<\/p><pre>Executed: 200   Passed: 150   Failed: 40   Blocked: 10\nNew defects this week: 30   Closed defects this week: 18<\/pre><p>Které shrnutí od LLM je správné, a tedy po kontrole bezpečné k předání?<\/p>","m":["„95 % provedených testů proběhlo bez blokace; testování je před plánem.“","„Provedeno 80 % plánovaných testů; 75 % provedených testů prošlo; počet otevřených defektů za týden vzrostl o 12.“","„Testování jde podle plánu; 75 % provedených testů prošlo; zbývá 30 otevřených defektů.“","„Provedeno 80 % plánovaných testů; 60 % provedených testů prošlo; otevřených defektů ubylo o 12.“"],"vys":{"a":"Špatně. Testování za plánem zaostává (200 z 250), závěr je tedy chybný (sylabus 2.2.4).","b":"Správně. 200/250 = 80 %, 150/200 = 75 %, 30 − 18 = 12. Metriky od LLM je přesto nutné ověřit (sylabus 2.2.4, kapitola 3).","c":"Špatně. Provádění zaostává o 50 testů a údaj o otevřených defektech ignoruje uzavřené defekty i předchozí týdny (sylabus 2.2.4).","d":"Špatně. 60 % je 150/250, ne podíl prošlých z provedených, a otevřených defektů přibylo (sylabus 2.2.4)."},"obecne":"GenAI převádí testovací data na metriky monitoringu, například postup a trend defektů; čísla je nutné kontrolovat, protože LLM se může v uvažování splést."},"kap":{"c":"2.2.4","nazev":"2.2.4 Monitoring testování a řízení testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.4-03","n":null,"lo":"GenAI-2.2.4","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>Halfway through a release, defects in the payment module increase sharply while two testers are still assigned to low-risk reports. The test manager wants actionable test control proposals from an LLM. Which prompt is MOST appropriate?<\/p>","m":["Ask the LLM to explain what test control means according to ISTQB.","Provide the list of testers' names and ask the LLM who should be replaced.","Provide the defect trend per module, the risk register, the remaining test cases with priorities and the testers' capacity, and ask for proposals to reprioritize tests, adjust the schedule and reallocate testers, each with a rationale.","Ask the LLM to generate a completion report for the release now."],"vys":{"a":"Incorrect. A definition does not give actionable proposals for this situation (syllabus 2.2.4).","b":"Incorrect. This lacks the data needed for test control and focuses on people rather than test priorities.","c":"Correct. Test control proposals need trends, risks, priorities and resources as input (syllabus 2.2.4).","d":"Incorrect. A completion report is produced at the end; the situation needs control actions during testing (syllabus 2.2.4)."},"obecne":"GenAI assists test control by providing insights for reprioritizing tests, adjusting schedules and reallocating resources."},"cz":{"q":"<p>V polovině releasu prudce přibývá defektů v platebním modulu, zatímco dva testeři jsou stále přiděleni na málo rizikové reporty. Test manažer chce od LLM proveditelné návrhy pro řízení testování. Který prompt je NEJVHODNĚJŠÍ?<\/p>","m":["Požádat LLM o vysvětlení, co znamená řízení testování podle ISTQB.","Dodat seznam jmen testerů a zeptat se LLM, koho vyměnit.","Dodat trend defektů po modulech, registr rizik, zbývající testovací případy s prioritami a kapacitu testerů a požádat o návrhy na změnu priorit, úpravu harmonogramu a přesun testerů, každý se zdůvodněním.","Požádat LLM, aby už teď vytvořil souhrnný report z testování pro release."],"vys":{"a":"Špatně. Definice nedá proveditelné návrhy pro tuto situaci (sylabus 2.2.4).","b":"Špatně. Chybí data potřebná k řízení testování a zaměření je na lidi místo priorit testů.","c":"Správně. Návrhy pro řízení testování potřebují na vstupu trendy, rizika, priority a zdroje (sylabus 2.2.4).","d":"Špatně. Souhrnný report vzniká na konci; situace vyžaduje opatření řízení během testování (sylabus 2.2.4)."},"obecne":"GenAI pomáhá řízení testování podklady pro změnu priorit, úpravu harmonogramu a přerozdělení zdrojů."},"kap":{"c":"2.2.4","nazev":"2.2.4 Monitoring testování a řízení testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.4-04","n":null,"lo":"GenAI-2.2.4","k":"K3","body":2,"vyber":1,"ok":[3],"en":{"q":"<p>Development team leads want a weekly report from which they can see quickly which modules need attention. The current LLM output is a single overall pass rate and a long narrative text. Which change to the prompt BEST meets their need?<\/p>","m":["Change the role to “quality director”.","Add the full raw test logs to the report so that nothing is missing.","Ask the LLM to report only the overall pass rate, because one number is easiest to understand.","Change the output format to a table per module with executed and failed tests, open defects and the trend compared with the previous week, followed by one sentence per module that needs attention."],"vys":{"a":"Incorrect. A different role does not define the per-module structure the team leads need (syllabus 2.1.1).","b":"Incorrect. Raw logs make the report harder to read and do not highlight the modules (syllabus 2.2.4).","c":"Incorrect. One overall number hides which modules need attention.","d":"Correct. The output is tailored to the audience and highlights relevant metrics per module (syllabus 2.2.4)."},"obecne":"GenAI can create dashboards and summaries that give each stakeholder access to the relevant metrics for quick decisions."},"cz":{"q":"<p>Vedoucí vývojových týmů chtějí týdenní report, ze kterého rychle poznají, které moduly potřebují pozornost. Současný výstup LLM je jedno celkové procento úspěšnosti a dlouhý souvislý text. Která změna promptu NEJLÉPE splní jejich potřebu?<\/p>","m":["Změnit roli na „ředitel kvality“.","Přidat do reportu kompletní surové logy testů, aby nic nechybělo.","Požádat LLM, aby uváděl jen celkové procento úspěšnosti, protože jedno číslo se pochopí nejsnáz.","Změnit formát výstupu na tabulku po modulech s provedenými a neúspěšnými testy, otevřenými defekty a trendem proti minulému týdnu, a pod ní jednu větu ke každému modulu, který potřebuje pozornost."],"vys":{"a":"Špatně. Jiná role neurčí strukturu po modulech, kterou vedoucí potřebují (sylabus 2.1.1).","b":"Špatně. Surové logy report znepřehlední a moduly nezvýrazní (sylabus 2.2.4).","c":"Špatně. Jedno celkové číslo skryje, které moduly potřebují pozornost.","d":"Správně. Výstup je přizpůsobený čtenářům a zvýrazní relevantní metriky po modulech (sylabus 2.2.4)."},"obecne":"GenAI umí vytvořit dashboardy a souhrny, které dají každé zainteresované straně relevantní metriky pro rychlé rozhodnutí."},"kap":{"c":"2.2.4","nazev":"2.2.4 Monitoring testování a řízení testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.4-05","n":null,"lo":"GenAI-2.2.4","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>At the end of a release, a test lead wants an LLM to help prepare a test completion report that supports improving the next test cycle. Which prompt is MOST appropriate?<\/p>","m":["Provide final metrics, exit criteria status, the defect list and the retrospective notes, and ask for a report that highlights successes and lessons learned and proposes concrete changes to the test strategy.","Provide only the list of passed tests and ask for a positive summary for marketing.","Ask the LLM to predict the defects of the next release without providing any history.","Ask the LLM to write a generic completion report template without any data."],"vys":{"a":"Correct. Completion insights and continuous learning are supported by reports that highlight successes and lessons learned (syllabus 2.2.4).","b":"Incorrect. This ignores failures and lessons learned and targets the wrong audience.","c":"Incorrect. Predictions without data are guesses and do not form a completion report (syllabus 2.2.4).","d":"Incorrect. Without project data the report cannot contain lessons learned for this release (syllabus 2.2.4)."},"obecne":"GenAI can generate test completion reports highlighting successes and lessons learned to refine test strategies."},"cz":{"q":"<p>Na konci releasu chce vedoucí testů s pomocí LLM připravit souhrnný report z testování, který pomůže zlepšit další testovací cyklus. Který prompt je NEJVHODNĚJŠÍ?<\/p>","m":["Dodat konečné metriky, stav výstupních kritérií, seznam defektů a poznámky z retrospektivy a požádat o report, který zdůrazní úspěchy a poučení a navrhne konkrétní změny strategie testování.","Dodat jen seznam prošlých testů a požádat o pozitivní shrnutí pro marketing.","Požádat LLM o předpověď defektů příštího releasu bez jakékoli historie.","Požádat LLM o obecnou šablonu souhrnného reportu bez jakýchkoli dat."],"vys":{"a":"Správně. Přehledy z dokončení a průběžné učení podporují reporty, které zdůrazní úspěchy a poučení (sylabus 2.2.4).","b":"Špatně. Ignoruje selhání i poučení a míří na nesprávné publikum.","c":"Špatně. Předpověď bez dat je hádání a není to souhrnný report (sylabus 2.2.4).","d":"Špatně. Bez dat projektu nemůže report obsahovat poučení z tohoto releasu (sylabus 2.2.4)."},"obecne":"GenAI umí vytvářet souhrnné reporty z testování s úspěchy a poučením, podle kterých se upraví strategie testování."},"kap":{"c":"2.2.4","nazev":"2.2.4 Monitoring testování a řízení testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.5-01","n":null,"lo":"GenAI-2.2.5","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>A team must rewrite about 400 existing defect reports into a new company template. The test lead has three reports already converted correctly by hand. Which prompting technique is BEST suited?<\/p>","m":["Meta prompting to discover what a defect report is","Few-shot prompting with the three converted reports as examples","Zero-shot prompting with the instruction “use the new template”","Prompt chaining with a manual review after each sentence of every report"],"vys":{"a":"Incorrect. The task and the target format are already well known; no new prompt needs to be explored (syllabus 2.2.5).","b":"Correct. A repetitive task with a specific output format and available examples fits few-shot prompting (syllabus 2.2.5).","c":"Incorrect. Without the template or examples the model cannot reproduce the format consistently (syllabus 2.1.2).","d":"Incorrect. The task is repetitive rather than complex; such fine-grained chaining adds effort without benefit (syllabus 2.2.5)."},"obecne":"Few-shot prompting is recommended for repetitive or specific/constrained output format tasks."},"cz":{"q":"<p>Tým musí přepsat asi 400 existujících reportů o defektech do nové firemní šablony. Vedoucí testů má tři reporty, které už ručně správně převedl. Která technika promptování je NEJVHODNĚJŠÍ?<\/p>","m":["Meta prompting, aby se zjistilo, co je report o defektu","Few-shot prompting se třemi převedenými reporty jako příklady","Zero-shot prompting s instrukcí „použij novou šablonu“","Prompt chaining s ruční kontrolou po každé větě každého reportu"],"vys":{"a":"Špatně. Úloha i cílový formát jsou známé; není třeba zkoumat nový prompt (sylabus 2.2.5).","b":"Správně. Opakující se úloha s pevným formátem výstupu a dostupnými příklady se hodí pro few-shot (sylabus 2.2.5).","c":"Špatně. Bez šablony nebo příkladů model formát konzistentně nevytvoří (sylabus 2.1.2).","d":"Špatně. Úloha je spíš opakující se než složitá; tak jemné řetězení přidá práci bez přínosu (sylabus 2.2.5)."},"obecne":"Few-shot se doporučuje pro opakující se úlohy a úlohy s konkrétním nebo omezeným formátem výstupu."},"kap":{"c":"2.2.5","nazev":"2.2.5 Výběr techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-2-5"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.5-02","n":null,"lo":"GenAI-2.2.5","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>A tester has to analyze performance test logs of a new streaming platform for anomalies for the first time. Nobody in the team knows which anomalies to look for or how to describe the task to an LLM. Which technique is BEST suited to start?<\/p>","m":["Few-shot prompting with examples of previously found anomalies","No GenAI at all, because LLMs cannot analyze logs","Meta prompting: describe the objective and let the LLM propose a prompt, then evaluate and refine it together","One-shot prompting with an example of a functional test case"],"vys":{"a":"Incorrect. There are no examples available yet, since the task is new (syllabus 2.2.5).","b":"Incorrect. The syllabus lists anomaly detection and report analysis as tasks suitable for meta prompting (syllabus 2.2.5).","c":"Correct. Meta prompting suits flexible, dynamic tasks such as anomaly detection when the right prompt is not yet known (syllabus 2.2.5).","d":"Incorrect. An unrelated example would mislead the model (syllabus 2.1.2)."},"obecne":"Meta prompting: a general description of the objective guides the LLM in creating the prompt; useful for complex tasks like report analysis and anomaly detection."},"cz":{"q":"<p>Tester má poprvé analyzovat logy výkonnostních testů nové streamovací platformy a hledat v nich anomálie. Nikdo v týmu neví, jaké anomálie hledat ani jak úlohu LLM popsat. Která technika je pro začátek NEJVHODNĚJŠÍ?<\/p>","m":["Few-shot prompting s příklady dříve nalezených anomálií","Vůbec nepoužít GenAI, protože LLM neumí analyzovat logy","Meta prompting: popsat cíl, nechat LLM navrhnout prompt a pak ho společně vyhodnotit a vylepšit","One-shot prompting s příkladem funkčního testovacího případu"],"vys":{"a":"Špatně. Žádné příklady zatím nejsou, úloha je nová (sylabus 2.2.5).","b":"Špatně. Sylabus uvádí detekci anomálií a analýzu reportů jako úlohy vhodné pro meta prompting (sylabus 2.2.5).","c":"Správně. Meta prompting se hodí pro pružné a dynamické úlohy, jako je detekce anomálií, když správný prompt ještě není znám (sylabus 2.2.5).","d":"Špatně. Nesouvisející příklad by model zmátl (sylabus 2.1.2)."},"obecne":"Meta prompting: obecný popis cíle vede LLM při tvorbě promptu; hodí se pro složité úlohy jako analýza reportů a detekce anomálií."},"kap":{"c":"2.2.5","nazev":"2.2.5 Výběr techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-2-5"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.5-03","n":null,"lo":"GenAI-2.2.5","k":"K3","body":2,"vyber":1,"ok":[3],"en":{"q":"<p>A bank analyzes a long specification of a mortgage process. First, ambiguities must be found; after the business analyst answers them, test conditions are derived; finally, coverage of all requirements is checked. A senior analyst must approve the result of each step before work continues. Which technique is BEST suited?<\/p>","m":["Few-shot prompting","Meta prompting","Zero-shot prompting in one prompt","Prompt chaining"],"vys":{"a":"Incorrect. The task is not about reproducing a repetitive output pattern from examples (syllabus 2.2.5).","b":"Incorrect. The steps are known; the key need is verification between steps, not creating the prompt (syllabus 2.2.5).","c":"Incorrect. A single prompt does not allow approval of intermediate results (syllabus 2.1.2).","d":"Correct. A complex task with human verification at each step fits prompt chaining (syllabus 2.2.5)."},"obecne":"Prompt chaining is recommended for complex tasks requiring precision with human verification at each step."},"cz":{"q":"<p>Banka analyzuje dlouhou specifikaci hypotečního procesu. Nejdřív je třeba najít nejasnosti, po odpovědích business analytika odvodit testovací podmínky a nakonec ověřit pokrytí všech požadavků. Výsledek každého kroku musí před pokračováním schválit senior analytik. Která technika je NEJVHODNĚJŠÍ?<\/p>","m":["Few-shot prompting","Meta prompting","Zero-shot prompting v jednom promptu","Prompt chaining"],"vys":{"a":"Špatně. Úloha není o napodobení opakujícího se vzoru z příkladů (sylabus 2.2.5).","b":"Špatně. Kroky jsou známé; hlavní potřebou je ověření mezi kroky, ne tvorba promptu (sylabus 2.2.5).","c":"Špatně. Jeden prompt neumožní schválit mezivýsledky (sylabus 2.1.2).","d":"Správně. Složitá úloha s lidským ověřením po každém kroku se hodí pro řetězení promptů (sylabus 2.2.5)."},"obecne":"Řetězení promptů se doporučuje pro složité úlohy, které vyžadují přesnost a lidské ověření po každém kroku."},"kap":{"c":"2.2.5","nazev":"2.2.5 Výběr techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-2-5"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.5-04","n":null,"lo":"GenAI-2.2.5","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>A company builds an internal LLM-powered tool that generates test cases for dozens of teams. The test lead first wants the LLM to help draft a good prompt, then enrich it with the company's approved test case examples, and finally split the generation into steps whose intermediate results are validated. Which combination does this describe?<\/p>","m":["Meta prompting to create the initial prompt, few-shot prompting with adapted examples, and prompt chaining to validate intermediate steps","Few-shot prompting only, because the company has approved examples","Prompt chaining only, because examples are not allowed in system prompts","Zero-shot prompting for all steps, because the tool is used by many teams"],"vys":{"a":"Correct. This is the combination described in syllabus 2.2.5.","b":"Incorrect. It ignores the drafting of the prompt with the LLM and the step-wise validation (syllabus 2.2.5).","c":"Incorrect. Examples can be used, and the scenario includes meta prompting as well (syllabus 2.2.5).","d":"Incorrect. The scenario explicitly uses examples and step validation (syllabus 2.2.5)."},"obecne":"Multiple techniques can be used for one use case: meta prompting for the initial prompt, few-shot examples, prompt chaining for validation."},"cz":{"q":"<p>Firma staví interní nástroj na LLM, který bude generovat testovací případy pro desítky týmů. Vedoucí testů chce nejdřív s pomocí LLM navrhnout dobrý prompt, pak ho doplnit schválenými firemními příklady testovacích případů a nakonec generování rozdělit na kroky, jejichž mezivýsledky se ověřují. Jakou kombinaci to popisuje?<\/p>","m":["Meta prompting pro vytvoření prvního promptu, few-shot s upravenými příklady a prompt chaining pro ověření mezikroků","Jen few-shot prompting, protože firma má schválené příklady","Jen prompt chaining, protože příklady nejsou v systémových promptech povoleny","Zero-shot prompting pro všechny kroky, protože nástroj používá mnoho týmů"],"vys":{"a":"Správně. Přesně tuto kombinaci popisuje sylabus 2.2.5.","b":"Špatně. Ignoruje tvorbu promptu s modelem i ověřování po krocích (sylabus 2.2.5).","c":"Špatně. Příklady použít lze a scénář obsahuje i meta prompting (sylabus 2.2.5).","d":"Špatně. Scénář výslovně používá příklady a ověřování kroků (sylabus 2.2.5)."},"obecne":"Pro jeden případ užití lze použít víc technik: meta prompting pro první prompt, few-shot příklady, prompt chaining pro ověření."},"kap":{"c":"2.2.5","nazev":"2.2.5 Výběr techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-2-5"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.5-05","n":null,"lo":"GenAI-2.2.5","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>A test suite must be prioritized according to risk, coverage of requirements and dependencies between test cases. Earlier one-prompt attempts produced orders that violated dependencies. Which technique is BEST suited?<\/p>","m":["Few-shot prompting with examples of prioritized suites from other projects","Prompt chaining with manual verification of the intermediate results","Meta prompting so that the LLM writes the final order as a prompt","Zero-shot prompting with a higher temperature"],"vys":{"a":"Incorrect. Examples from other projects do not contain this suite's dependencies and do not add verification (syllabus 2.2.5).","b":"Correct. A multi-criteria task where reasoning errors occurred needs decomposition and verification of each step (syllabus 2.2.5, HO-2.2.2c).","c":"Incorrect. Meta prompting creates prompts; it does not provide verified intermediate results (syllabus 2.1.2).","d":"Incorrect. Temperature is a model parameter and higher temperature increases variability, not correctness (chapter 3)."},"obecne":"Select the technique by the nature of the task: precision with verification (chaining), repetitive structure (few-shot), new flexible task (meta)."},"cz":{"q":"<p>Testovací sadu je třeba prioritizovat podle rizika, pokrytí požadavků a závislostí mezi testovacími případy. Dřívější pokusy s jedním promptem vedly k pořadím, která porušovala závislosti. Která technika je NEJVHODNĚJŠÍ?<\/p>","m":["Few-shot prompting s příklady prioritizovaných sad z jiných projektů","Prompt chaining s ručním ověřením mezivýsledků","Meta prompting, aby LLM napsal konečné pořadí jako prompt","Zero-shot prompting s vyšší teplotou"],"vys":{"a":"Špatně. Příklady z jiných projektů neobsahují závislosti této sady a nepřidávají ověření (sylabus 2.2.5).","b":"Správně. Úloha s více kritérii, kde došlo k chybám v uvažování, potřebuje rozklad a ověření každého kroku (sylabus 2.2.5, HO-2.2.2c).","c":"Špatně. Meta prompting vytváří prompty, nedává ověřené mezivýsledky (sylabus 2.1.2).","d":"Špatně. Teplota je parametr modelu a vyšší teplota zvyšuje proměnlivost, ne správnost (kapitola 3)."},"obecne":"Techniku vybírejte podle povahy úlohy: přesnost s ověřením (chaining), opakující se struktura (few-shot), nová pružná úloha (meta)."},"kap":{"c":"2.2.5","nazev":"2.2.5 Výběr techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-2-5"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.1-01","n":null,"lo":"GenAI-2.3.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>An LLM generated 60 Playwright scripts. 48 of them could be executed in the test environment without syntax errors or format problems; 6 of those 48 failed because they found defects. Which metric value is correct?<\/p>","m":["Execution success rate of 70 %","Time efficiency of 80 %","Execution success rate of 80 %","Recall of 80 %"],"vys":{"a":"Incorrect. 42/60 wrongly excludes the scripts that ran and found defects (syllabus 2.3.1).","b":"Incorrect. Time efficiency compares time with manual effort (syllabus 2.3.1).","c":"Correct. 48 of 60 artefacts executed as is; a test that runs and finds a defect counts as executed (syllabus 2.3.1).","d":"Incorrect. Recall concerns finding all relevant instances, not executability (syllabus 2.3.1)."},"obecne":"Execution success rate measures the proportion of generated test artefacts that can be executed successfully as is."},"cz":{"q":"<p>LLM vygeneroval 60 Playwright skriptů. 48 z nich šlo v testovacím prostředí spustit bez syntaktických chyb a problémů s formátem; 6 z těchto 48 selhalo, protože našly defekty. Která hodnota metriky je správná?<\/p>","m":["Execution success rate 70 %","Time efficiency 80 %","Execution success rate 80 %","Recall 80 %"],"vys":{"a":"Špatně. 42/60 chybně vynechává skripty, které se spustily a našly defekty (sylabus 2.3.1).","b":"Špatně. Time efficiency porovnává čas s ruční prací (sylabus 2.3.1).","c":"Správně. 48 ze 60 artefaktů se spustilo bez úprav; test, který se spustí a najde defekt, se počítá jako spuštěný (sylabus 2.3.1).","d":"Špatně. Recall se týká zachycení všech relevantních případů, ne spustitelnosti (sylabus 2.3.1)."},"obecne":"Execution success rate měří podíl vygenerovaných artefaktů, které lze spustit bez úprav."},"kap":{"c":"2.3.1","nazev":"2.3.1 Metriky pro hodnocení výsledků GenAI v testovacích úlohách","href":"kapitola-2/vyklad.html#oddil-2-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.1-02","n":null,"lo":"GenAI-2.3.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Generated test cases for an age field cover every requirement, but they include only valid equivalence partitions and none of the invalid ones. Which metric is MOST directly low?<\/p>","m":["Accuracy","Execution success rate","Time efficiency","Recall"],"vys":{"a":"Incorrect. Coverage of all specified requirements, the syllabus example of accuracy, is achieved here (syllabus 2.3.1).","b":"Incorrect. Nothing is said about executing scripts (syllabus 2.3.1).","c":"Incorrect. The problem is missing partitions, not time (syllabus 2.3.1).","d":"Correct. Recall measures whether all relevant instances, such as valid and invalid partitions, are covered (syllabus 2.3.1)."},"obecne":"Recall: the degree to which generated test cases cover valid and invalid equivalence partitions of a data class."},"cz":{"q":"<p>Vygenerované testovací případy pro pole Věk pokrývají každý požadavek, ale obsahují jen platné třídy ekvivalence a žádnou neplatnou. Která metrika je NEJPŘÍMĚJI nízká?<\/p>","m":["Accuracy","Execution success rate","Time efficiency","Recall"],"vys":{"a":"Špatně. Pokrytí všech specifikovaných požadavků, příklad accuracy ze sylabu, je tu splněno (sylabus 2.3.1).","b":"Špatně. O spouštění skriptů zadání nic neříká (sylabus 2.3.1).","c":"Špatně. Problémem jsou chybějící třídy, ne čas (sylabus 2.3.1).","d":"Správně. Recall měří, zda jsou pokryty všechny relevantní případy, například platné i neplatné třídy (sylabus 2.3.1)."},"obecne":"Recall: do jaké míry vygenerované testy pokrývají platné a neplatné třídy ekvivalence datové třídy."},"kap":{"c":"2.3.1","nazev":"2.3.1 Metriky pro hodnocení výsledků GenAI v testovacích úlohách","href":"kapitola-2/vyklad.html#oddil-2-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.1-03","n":null,"lo":"GenAI-2.3.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Test cases generated for an insurance claims portal read fluently, but several of them test a currency conversion feature that the portal does not have and that is not in the test basis. Which metric captures this problem BEST?<\/p>","m":["Relevance and contextual fit","Time efficiency","Execution success rate","Diversity"],"vys":{"a":"Correct. It determines whether output is applicable to the context and consistent with the test basis (syllabus 2.3.1).","b":"Incorrect. The issue is not the time saved (syllabus 2.3.1).","c":"Incorrect. Even executable tests can be irrelevant to the context (syllabus 2.3.1).","d":"Incorrect. Diversity concerns breadth without repetition; irrelevant tests may even look diverse (syllabus 2.3.1)."},"obecne":"Relevance and contextual fit: degree to which the generated test cases are consistent with the test basis and integrate domain-specific requirements."},"cz":{"q":"<p>Testovací případy vygenerované pro portál hlášení škod se čtou plynule, ale několik z nich testuje převod měn, který portál nemá a který není v testovací bázi. Která metrika tento problém zachytí NEJLÉPE?<\/p>","m":["Relevance and contextual fit","Time efficiency","Execution success rate","Diversity"],"vys":{"a":"Správně. Určuje, zda je výstup použitelný v kontextu a v souladu s testovací bází (sylabus 2.3.1).","b":"Špatně. Problémem není ušetřený čas (sylabus 2.3.1).","c":"Špatně. I spustitelné testy mohou být pro kontext nerelevantní (sylabus 2.3.1).","d":"Špatně. Diversity se týká šíře bez opakování; nerelevantní testy mohou dokonce působit rozmanitě (sylabus 2.3.1)."},"obecne":"Relevance a soulad s kontextem: do jaké míry jsou vygenerované testy v souladu s testovací bází a zahrnují doménové požadavky."},"kap":{"c":"2.3.1","nazev":"2.3.1 Metriky pro hodnocení výsledků GenAI v testovacích úlohách","href":"kapitola-2/vyklad.html#oddil-2-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.1-04","n":null,"lo":"GenAI-2.3.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A team evaluates an LLM by running a prompt once and calculating the metrics from that single output. Why is this approach insufficient according to the syllabus?<\/p>","m":["Because metrics are only meaningful for fine-tuned models.","Because GenAI is non-deterministic, so metrics must be based on statistically relevant data such as several runs.","Because metrics may only be calculated automatically, never by manual review.","Because only time efficiency can be measured from one output."],"vys":{"a":"Incorrect. The metrics apply to GenAI results on test tasks in general (syllabus 2.3.1).","b":"Correct. Given the non-deterministic nature of GenAI, metrics must be based on statistically relevant data (syllabus 2.3.1).","c":"Incorrect. The syllabus allows manual reviews as well as automated comparison (syllabus 2.3.1).","d":"Incorrect. All metrics can be computed from one output; the problem is that one output is not representative."},"obecne":"Metrics can be evaluated manually or automatically against a reference, and must rest on statistically relevant data."},"cz":{"q":"<p>Tým hodnotí LLM tak, že prompt spustí jednou a metriky spočítá z tohoto jediného výstupu. Proč je to podle sylabu nedostatečné?<\/p>","m":["Protože metriky mají smysl jen u doladěných (fine-tuned) modelů.","Protože GenAI je nedeterministická, metriky musí vycházet ze statisticky relevantních dat, například z více běhů.","Protože metriky se smí počítat jen automaticky, nikdy ruční revizí.","Protože z jednoho výstupu lze měřit jen time efficiency."],"vys":{"a":"Špatně. Metriky se týkají výsledků GenAI v testovacích úlohách obecně (sylabus 2.3.1).","b":"Správně. Kvůli nedeterministické povaze GenAI musí metriky vycházet ze statisticky relevantních dat (sylabus 2.3.1).","c":"Špatně. Sylabus připouští ruční revizi i automatické porovnání (sylabus 2.3.1).","d":"Špatně. Spočítat lze všechny metriky; problém je, že jeden výstup není reprezentativní."},"obecne":"Metriky lze vyhodnotit ručně nebo automaticky vůči referenci a musí stát na statisticky relevantních datech."},"kap":{"c":"2.3.1","nazev":"2.3.1 Metriky pro hodnocení výsledků GenAI v testovacích úlohách","href":"kapitola-2/vyklad.html#oddil-2-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.1-05","n":null,"lo":"GenAI-2.3.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which statement correctly distinguishes accuracy from precision as defined for evaluating GenAI results on test tasks?<\/p>","m":["Accuracy measures how many scripts can be executed; precision measures the time saved.","Accuracy measures the variety of scenarios; precision measures repetition in the output.","Accuracy measures overall correctness against a standard such as requirements or expert-written test cases; precision evaluates correctness with respect to a specific objective, such as identifying anomalies.","Accuracy and precision are the same metric with different names."],"vys":{"a":"Incorrect. These describe execution success rate and time efficiency (syllabus 2.3.1).","b":"Incorrect. Variety and repetition relate to diversity (syllabus 2.3.1).","c":"Correct. This matches the definitions and examples in syllabus 2.3.1.","d":"Incorrect. The syllabus lists them as separate metrics with different meaning (syllabus 2.3.1)."},"obecne":"Accuracy: overall correctness against standards. Precision: correctness with respect to a specific objective."},"cz":{"q":"<p>Které tvrzení správně odlišuje accuracy od precision podle definic pro hodnocení výsledků GenAI v testovacích úlohách?<\/p>","m":["Accuracy měří, kolik skriptů lze spustit; precision měří ušetřený čas.","Accuracy měří různorodost scénářů; precision měří opakování ve výstupu.","Accuracy měří celkovou správnost vůči standardu, například požadavkům nebo testům od odborníka; precision hodnotí správnost vzhledem ke konkrétnímu cíli, například k identifikaci anomálií.","Accuracy a precision jsou stejná metrika s jinými názvy."],"vys":{"a":"Špatně. To popisuje execution success rate a time efficiency (sylabus 2.3.1).","b":"Špatně. Různorodost a opakování se týkají diversity (sylabus 2.3.1).","c":"Správně. Odpovídá definicím a příkladům v sylabu 2.3.1.","d":"Špatně. Sylabus je uvádí jako samostatné metriky s různým významem (sylabus 2.3.1)."},"obecne":"Accuracy: celková správnost vůči standardu. Precision: správnost vzhledem ke konkrétnímu cíli."},"kap":{"c":"2.3.1","nazev":"2.3.1 Metriky pro hodnocení výsledků GenAI v testovacích úlohách","href":"kapitola-2/vyklad.html#oddil-2-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.2-01","n":null,"lo":"GenAI-2.3.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Testers report that the test cases generated by an LLM contain too many detailed UI steps and are hard to maintain. Which technique for refining the prompt does this situation BEST illustrate?<\/p>","m":["A/B testing of prompts","Execution success rate","Meta prompting","Integrate user feedback"],"vys":{"a":"Incorrect. No competing prompt versions are compared here (syllabus 2.3.2).","b":"Incorrect. This is a metric, not a refinement technique (syllabus 2.3.1).","c":"Incorrect. Meta prompting is a prompting technique, not one of the evaluation and refinement techniques of 2.3.2.","d":"Correct. Testers' input on usefulness and level of detail is analyzed and used to refine the prompt (syllabus 2.3.2)."},"obecne":"Integrate user feedback: gather testers' input on usefulness and clarity, e.g. level of detail, and refine prompts accordingly."},"cz":{"q":"<p>Testeři hlásí, že testovací případy vygenerované LLM obsahují příliš mnoho podrobných kroků v UI a špatně se udržují. Kterou techniku ladění promptu tato situace NEJLÉPE ilustruje?<\/p>","m":["A/B testing of prompts","Execution success rate","Meta prompting","Integrate user feedback (zapracování zpětné vazby uživatelů)"],"vys":{"a":"Špatně. Neporovnávají se tu žádné verze promptu (sylabus 2.3.2).","b":"Špatně. To je metrika, ne technika ladění (sylabus 2.3.1).","c":"Špatně. Meta prompting je technika promptování, ne jedna z technik hodnocení a ladění z 2.3.2.","d":"Správně. Názory testerů na užitečnost a úroveň detailu se analyzují a použijí k úpravě promptu (sylabus 2.3.2)."},"obecne":"Zapracování zpětné vazby: sebrat od testerů názory na užitečnost a srozumitelnost, např. úroveň detailu, a podle nich prompt upravit."},"kap":{"c":"2.3.2","nazev":"2.3.2 Techniky hodnocení a iterativního ladění promptů","href":"kapitola-2/vyklad.html#oddil-2-3-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.2-02","n":null,"lo":"GenAI-2.3.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A team has two versions of a prompt for generating test data. It runs each version ten times and compares the share of invalid partitions covered and the number of duplicate records. Which technique is this?<\/p>","m":["A/B testing of prompts","Prompt chaining","Output analysis","Integrate user feedback"],"vys":{"a":"Correct. Multiple prompt versions are evaluated against predefined metrics (syllabus 2.3.2).","b":"Incorrect. Prompt chaining decomposes a task; it is not a prompt evaluation technique (syllabus 2.1.2).","c":"Incorrect. Output analysis examines errors in output to understand them, not to compare versions (syllabus 2.3.2).","d":"Incorrect. The comparison is based on metrics, not on users' opinions (syllabus 2.3.2)."},"obecne":"A/B testing creates multiple versions of prompts and evaluates which performs better based on predefined metrics."},"cz":{"q":"<p>Tým má dvě verze promptu pro generování testovacích dat. Každou spustí desetkrát a porovná podíl pokrytých neplatných tříd a počet duplicitních záznamů. O jakou techniku jde?<\/p>","m":["A/B testing of prompts","Prompt chaining","Output analysis","Integrate user feedback"],"vys":{"a":"Správně. Víc verzí promptu se hodnotí podle předem daných metrik (sylabus 2.3.2).","b":"Špatně. Řetězení rozkládá úlohu, není to technika hodnocení promptu (sylabus 2.1.2).","c":"Špatně. Analýza výstupu zkoumá chyby, aby je pochopila, nesrovnává verze (sylabus 2.3.2).","d":"Špatně. Srovnání stojí na metrikách, ne na názorech uživatelů (sylabus 2.3.2)."},"obecne":"A/B testování vytvoří víc verzí promptu a podle předem daných metrik vyhodnotí, která dává lepší výsledky."},"kap":{"c":"2.3.2","nazev":"2.3.2 Techniky hodnocení a iterativního ladění promptů","href":"kapitola-2/vyklad.html#oddil-2-3-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.2-03","n":null,"lo":"GenAI-2.3.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which is a benefit of sharing prompt libraries and organizing prompt evaluation sessions across a test organization?<\/p>","m":["It replaces the need to define metrics for evaluation.","It helps standardize prompting techniques, maintain consistent quality and avoid repeated errors.","It makes the LLM deterministic.","It removes the need to review LLM output, because shared prompts are always correct."],"vys":{"a":"Incorrect. Evaluation sessions build on metrics; they do not replace them (syllabus 2.3.2).","b":"Correct. The syllabus names standardization, consistent quality, a culture of learning and avoiding repeated errors (syllabus 2.3.2).","c":"Incorrect. Sharing prompts does not change the non-deterministic nature of LLMs (syllabus 2.3.1).","d":"Incorrect. Output must still be evaluated; shared prompts do not guarantee correctness (syllabus 2.3)."},"obecne":"Sharing practices and prompt libraries standardizes techniques, keeps quality consistent and promotes a culture of learning and iterative improvement."},"cz":{"q":"<p>Jaký je přínos sdílení knihoven promptů a pořádání session pro hodnocení promptů v celé testovací organizaci?<\/p>","m":["Nahradí potřebu definovat metriky pro hodnocení.","Pomáhá standardizovat techniky promptování, udržet stejnou kvalitu a neopakovat chyby.","Udělá z LLM deterministický model.","Odpadne nutnost kontrolovat výstup LLM, protože sdílené prompty jsou vždy správné."],"vys":{"a":"Špatně. Session pro hodnocení na metrikách stavějí, nenahrazují je (sylabus 2.3.2).","b":"Správně. Sylabus uvádí standardizaci, stejnou kvalitu, kulturu učení a neopakování chyb (sylabus 2.3.2).","c":"Špatně. Sdílení promptů nezmění nedeterministickou povahu LLM (sylabus 2.3.1).","d":"Špatně. Výstup je nutné dál hodnotit; sdílené prompty správnost nezaručují (sylabus 2.3)."},"obecne":"Sdílení postupů a knihoven promptů standardizuje techniky, drží kvalitu a podporuje kulturu učení a postupného zlepšování."},"kap":{"c":"2.3.2","nazev":"2.3.2 Techniky hodnocení a iterativního ladění promptů","href":"kapitola-2/vyklad.html#oddil-2-3-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.2-04","n":null,"lo":"GenAI-2.3.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A very long and detailed prompt produces test cases that closely follow the given examples but miss new situations described in a changed user story. What should the tester try FIRST?<\/p>","m":["Add even more examples copied from the old user story.","Increase the number of runs without changing the prompt.","Adjust prompt length and specificity, e.g. try a shorter, less prescriptive version and compare the results.","Stop using GenAI for test design."],"vys":{"a":"Incorrect. More old examples would strengthen the narrow pattern even further (syllabus 2.3.2).","b":"Incorrect. More runs give more statistics but do not fix the narrowness of the prompt (syllabus 2.3.1).","c":"Correct. Sometimes shorter prompts generalize better; experimenting with length and detail is a refinement technique (syllabus 2.3.2).","d":"Incorrect. The problem can be addressed by refining the prompt (syllabus 2.3.2)."},"obecne":"Adjust prompt length and specificity: adding context can help, but in other cases shorter prompts yield better generalization."},"cz":{"q":"<p>Velmi dlouhý a podrobný prompt dává testovací případy, které věrně kopírují dané příklady, ale vynechávají nové situace popsané ve změněném uživatelském scénáři. Co by měl tester zkusit NEJDŘÍV?<\/p>","m":["Přidat ještě víc příkladů zkopírovaných ze starého uživatelského scénáře.","Zvýšit počet běhů bez změny promptu.","Upravit délku a konkrétnost promptu, například zkusit kratší a méně předepisující verzi a porovnat výsledky.","Přestat GenAI pro návrh testů používat."],"vys":{"a":"Špatně. Další staré příklady by úzký vzor ještě posílily (sylabus 2.3.2).","b":"Špatně. Víc běhů dá víc statistiky, ale úzkost promptu neodstraní (sylabus 2.3.1).","c":"Správně. Kratší prompt někdy lépe zobecní; experiment s délkou a detailem je technika ladění (sylabus 2.3.2).","d":"Špatně. Problém lze řešit úpravou promptu (sylabus 2.3.2)."},"obecne":"Úprava délky a konkrétnosti: víc kontextu někdy pomůže, jindy kratší prompt lépe zobecní."},"kap":{"c":"2.3.2","nazev":"2.3.2 Techniky hodnocení a iterativního ladění promptů","href":"kapitola-2/vyklad.html#oddil-2-3-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.2-05","n":null,"lo":"GenAI-2.3.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester examines a batch of LLM-generated test cases and classifies the errors: wrong boundaries, invented UI elements and expected results that contradict the test basis. She then changes the prompt to prevent these error types. Which technique is she applying?<\/p>","m":["Few-shot prompting","A/B testing of prompts","Integrate user feedback","Output analysis"],"vys":{"a":"Incorrect. Few-shot is a prompting technique, not an evaluation technique (syllabus 2.1.2).","b":"Incorrect. She does not compare several prompt versions (syllabus 2.3.2).","c":"Incorrect. She analyzes the output herself instead of collecting opinions of other users (syllabus 2.3.2).","d":"Correct. Examining output for inaccuracies and understanding error types to refine the prompt is output analysis (syllabus 2.3.2)."},"obecne":"Output analysis: examine AI output for inaccuracies or inconsistencies; understanding error types helps refine prompts."},"cz":{"q":"<p>Testerka prochází dávku testovacích případů vygenerovaných LLM a třídí chyby: špatné hranice, vymyšlené prvky UI a očekávané výsledky v rozporu s testovací bází. Pak prompt upraví, aby se tyto typy chyb neopakovaly. Jakou techniku používá?<\/p>","m":["Few-shot prompting","A/B testing of prompts","Integrate user feedback","Output analysis (analýza výstupu)"],"vys":{"a":"Špatně. Few-shot je technika promptování, ne technika hodnocení (sylabus 2.1.2).","b":"Špatně. Neporovnává víc verzí promptu (sylabus 2.3.2).","c":"Špatně. Výstup analyzuje sama, nesbírá názory jiných uživatelů (sylabus 2.3.2).","d":"Správně. Zkoumání výstupu kvůli nepřesnostem a pochopení typů chyb pro úpravu promptu je analýza výstupu (sylabus 2.3.2)."},"obecne":"Analýza výstupu: zkoumat výstup AI kvůli nepřesnostem a nekonzistencím; pochopení typů chyb pomůže upravit prompt."},"kap":{"c":"2.3.2","nazev":"2.3.2 Techniky hodnocení a iterativního ladění promptů","href":"kapitola-2/vyklad.html#oddil-2-3-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.1-01","n":null,"lo":"GenAI-3.1.1","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following BEST describes a hallucination in LLM output used for a test task?<\/p>","m":["The LLM produces output that is factually incorrect or irrelevant to the given task, for example a test case for a feature that is not in the requirements.","The LLM reaches an incorrect conclusion from correct input data because it misinterprets conditional logic.","The LLM systematically prefers certain kinds of test data because of imbalances in its training data.","The LLM returns a different set of test cases each time the same prompt is submitted."],"vys":{"a":"Correct. This matches the definition of hallucination in syllabus section 3.1.1.","b":"Incorrect. This describes a reasoning error (syllabus 3.1.1).","c":"Incorrect. This describes bias (syllabus 3.1.1).","d":"Incorrect. This describes non-deterministic behavior (syllabus 1.1.2 and 3.1.4), not a hallucination."},"obecne":"Hallucination = factually incorrect or irrelevant output (syllabus 3.1.1)."},"cz":{"q":"<p>Který z následujících popisů NEJLÉPE vystihuje halucinaci ve výstupu LLM použitém pro testovací úlohu?<\/p>","m":["LLM vytvoří výstup, který je fakticky nesprávný nebo nesouvisí se zadanou úlohou, například testovací případ pro funkci, která v požadavcích není.","LLM dojde ke špatnému závěru ze správných vstupních dat, protože chybně vyloží podmínku.","LLM systematicky upřednostňuje určitý druh testovacích dat kvůli nerovnováze v trénovacích datech.","LLM vrátí při každém odeslání stejného promptu jinou sadu testovacích případů."],"vys":{"a":"Správně. Odpovídá to definici halucinace v oddílu 3.1.1 sylabu.","b":"Nesprávně. To je chyba v uvažování (sylabus 3.1.1).","c":"Nesprávně. To je zkreslení (sylabus 3.1.1).","d":"Nesprávně. To je nedeterministické chování (sylabus 1.1.2 a 3.1.4), ne halucinace."},"obecne":"Halucinace = fakticky nesprávný nebo nesouvisející výstup (sylabus 3.1.1)."},"kap":{"c":"3.1.1","nazev":"3.1.1 Tři druhy vad ve výstupu LLM","href":"kapitola-3/vyklad.html#oddil-3-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.1-02","n":null,"lo":"GenAI-3.1.1","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which statement BEST describes a reasoning error in LLM output?<\/p>","m":["The model invents an acceptance criterion that is not present in the user story.","The model misinterprets a logical structure, such as cause and effect or a step-by-step procedure, and reaches a wrong conclusion.","The model generates mostly happy-path tests because such tests dominate the data it was trained on.","The model cuts off its answer because the output exceeds the maximum number of tokens."],"vys":{"a":"Incorrect. Inventing content that is not in the input is a hallucination (syllabus 3.1.1).","b":"Correct. Syllabus 3.1.1 defines reasoning errors as misinterpretation of logical structures leading to incorrect conclusions.","c":"Incorrect. A systematic preference rooted in training data is bias (syllabus 3.1.1).","d":"Incorrect. A truncated output caused by token limits is not one of the three defect types described in syllabus 3.1.1."},"obecne":"LLMs rely on pattern matching rather than true logical reasoning, which leads to reasoning errors (syllabus 3.1.1)."},"cz":{"q":"<p>Které tvrzení NEJLÉPE popisuje chybu v uvažování ve výstupu LLM?<\/p>","m":["Model si vymyslí akceptační kritérium, které v uživatelském scénáři není.","Model chybně vyloží logickou strukturu, například příčinu a následek nebo postup po krocích, a dojde ke špatnému závěru.","Model generuje hlavně testy šťastné cesty, protože takové testy převažují v datech, na kterých se učil.","Model odpověď useká, protože výstup překročí maximální počet tokenů."],"vys":{"a":"Nesprávně. Vymyšlený obsah, který ve vstupu není, je halucinace (sylabus 3.1.1).","b":"Správně. Sylabus 3.1.1 definuje chybu v uvažování jako chybný výklad logické struktury, který vede ke špatnému závěru.","c":"Nesprávně. Systematický sklon z trénovacích dat je zkreslení (sylabus 3.1.1).","d":"Nesprávně. Useknutý výstup kvůli limitu tokenů nepatří mezi tři druhy vad z oddílu 3.1.1."},"obecne":"LLM spoléhá na rozpoznávání vzorů místo skutečného logického uvažování, odtud chyby v uvažování (sylabus 3.1.1)."},"kap":{"c":"3.1.1","nazev":"3.1.1 Tři druhy vad ve výstupu LLM","href":"kapitola-3/vyklad.html#oddil-3-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.1-03","n":null,"lo":"GenAI-3.1.1","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>According to the syllabus, where do biases in LLM output originate?<\/p>","m":["From the size of the model's context window.","From the temperature setting used during inference.","From the data on which the model was trained.","From the use of prompt chaining by the tester."],"vys":{"a":"Incorrect. The context window determines how much text the model can consider (syllabus 1.1.2); it is not named as the origin of bias.","b":"Incorrect. Temperature influences randomness of the output (syllabus 3.1.4), not the origin of bias.","c":"Correct. Syllabus 3.1.1 states that LLM biases originate from the training data.","d":"Incorrect. Prompt chaining is a mitigation technique (syllabus 3.1.3), not a source of bias."},"obecne":"Example from the syllabus: models trained mainly on English data may underrepresent non-English perspectives."},"cz":{"q":"<p>Odkud podle sylabu pochází zkreslení ve výstupu LLM?<\/p>","m":["Z velikosti kontextového okna modelu.","Z nastavení teploty během inference.","Z dat, na kterých byl model trénován.","Z toho, že tester použije řetězení promptů."],"vys":{"a":"Nesprávně. Kontextové okno určuje, kolik textu model zohlední (sylabus 1.1.2). Sylabus ho jako původ zkreslení neuvádí.","b":"Nesprávně. Teplota ovlivňuje náhodnost výstupu (sylabus 3.1.4), nikoli původ zkreslení.","c":"Správně. Sylabus 3.1.1 uvádí, že zkreslení pochází z trénovacích dat.","d":"Nesprávně. Řetězení promptů je technika zmírnění (sylabus 3.1.3), ne zdroj zkreslení."},"obecne":"Příklad ze sylabu: model trénovaný hlavně na anglických datech může upozaďovat neanglické pohledy."},"kap":{"c":"3.1.1","nazev":"3.1.1 Tři druhy vad ve výstupu LLM","href":"kapitola-3/vyklad.html#oddil-3-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.1-04","n":null,"lo":"GenAI-3.1.1","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which test task is MOST likely to be affected by reasoning errors of an LLM?<\/p>","m":["Suggesting alternative labels for buttons as ideas for exploratory testing.","Translating test case titles from English into Czech.","Rewording a defect report so that it is easier to read.","Prioritizing test cases based on risk scores and dependencies between features."],"vys":{"a":"Incorrect. This is a creative task; it does not depend on cause-and-effect or step-by-step logic.","b":"Incorrect. Translation relies on language patterns, which LLMs handle well; it is not a typical reasoning task.","c":"Incorrect. Rewording is a language task with little logical reasoning; hallucinations are a bigger risk here than reasoning errors.","d":"Correct. Syllabus 3.1.1 names test planning and test case prioritization as tasks requiring logical reasoning where LLMs can make reasoning errors."},"obecne":"Tasks such as test planning, estimation and prioritization require logical reasoning (syllabus 3.1.1)."},"cz":{"q":"<p>Kterou testovací úlohu NEJSPÍŠ ovlivní chyby LLM v uvažování?<\/p>","m":["Návrh alternativních popisků tlačítek jako nápadů pro explorativní testování.","Překlad názvů testovacích případů z angličtiny do češtiny.","Přeformulování reportu o defektu, aby se lépe četl.","Prioritizace testovacích případů podle skóre rizika a závislostí mezi funkcemi."],"vys":{"a":"Nesprávně. Je to kreativní úloha, nezávisí na logice příčiny a následku ani na postupu po krocích.","b":"Nesprávně. Překlad stojí na jazykových vzorech, které LLM zvládá dobře. Není to typická úloha na uvažování.","c":"Nesprávně. Přeformulování je jazyková úloha s malým podílem logiky. Spíš tu hrozí halucinace.","d":"Správně. Sylabus 3.1.1 jmenuje plánování testování a prioritizaci testovacích případů jako úlohy, které vyžadují logické uvažování."},"obecne":"Úlohy jako plánování, odhad a prioritizace vyžadují logické uvažování (sylabus 3.1.1)."},"kap":{"c":"3.1.1","nazev":"3.1.1 Tři druhy vad ve výstupu LLM","href":"kapitola-3/vyklad.html#oddil-3-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.1-05","n":null,"lo":"GenAI-3.1.1","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>According to the syllabus, what are the causes of hallucinations, reasoning errors and biases in GenAI output?<\/p>","m":["The nature of the training data and the inherent limitations of the transformer model.","Missing encryption of the data transmitted to the LLM.","Insufficient computing power of the tester's local device.","The use of structured data formats in prompts."],"vys":{"a":"Correct. Syllabus 3.1.1 attributes all three defect types to the training data and the limitations of the transformer model.","b":"Incorrect. Encryption relates to data security (syllabus 3.2.3), not to the quality defects of the output.","c":"Incorrect. The syllabus does not mention local computing power as a cause.","d":"Incorrect. Clear, structured formats are a mitigation technique (syllabus 3.1.3)."},"obecne":"Plausible is not necessarily correct: the transformer generates statistically plausible text (syllabus 1.1.2, 3.1.1)."},"cz":{"q":"<p>Co jsou podle sylabu příčiny halucinací, chyb v uvažování a zkreslení ve výstupu generativní AI?<\/p>","m":["Povaha trénovacích dat a vnitřní omezení modelu transformer.","Chybějící šifrování dat posílaných do LLM.","Nedostatečný výpočetní výkon testerova počítače.","Použití strukturovaných formátů dat v promptech."],"vys":{"a":"Správně. Sylabus 3.1.1 přisuzuje všechny tři vady trénovacím datům a omezením architektury transformer.","b":"Nesprávně. Šifrování souvisí s bezpečností dat (sylabus 3.2.3), ne s vadami kvality výstupu.","c":"Nesprávně. Sylabus výkon lokálního zařízení jako příčinu neuvádí.","d":"Nesprávně. Jasné strukturované formáty jsou technika zmírnění (sylabus 3.1.3)."},"obecne":"Věrohodné neznamená správné: transformer vytváří statisticky věrohodný text (sylabus 1.1.2, 3.1.1)."},"kap":{"c":"3.1.1","nazev":"3.1.1 Tři druhy vad ve výstupu LLM","href":"kapitola-3/vyklad.html#oddil-3-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.2-01","n":null,"lo":"GenAI-3.1.2","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>A tester gives an LLM the following user story and receives the output shown.<\/p><pre>User story: As a user, I want to change my password.\nAC1: The new password has at least 12 characters.\nAC2: The new password must differ from the current password.\nAC3: The user must enter the current password.\n\nLLM output:\nTC-01 New password with 11 characters is rejected (AC1)\nTC-02 New password with 12 characters is accepted (AC1)\nTC-03 New password identical to the current one is rejected (AC2)\nTC-04 Wrong current password is rejected (AC3)\nTC-05 After a successful change, a push notification is sent to the user&#x27;s phone (AC2)<\/pre><p>Which statement BEST identifies the defect in the LLM output?<\/p>","m":["TC-03 is a hallucination, because AC2 does not refer to the current password.","TC-05 is a hallucination, because it verifies a push notification that is not part of any acceptance criterion.","TC-01 and TC-02 contain a reasoning error, because boundary value analysis for a minimum of 12 requires the values 12 and 13.","The output shows bias, because all test cases are negative tests."],"vys":{"a":"Incorrect. AC2 explicitly requires the new password to differ from the current one, so TC-03 is grounded in the input.","b":"Correct. No acceptance criterion mentions a notification; the LLM invented it and linked it to AC2. Cross-verification against the user story reveals it (syllabus 3.1.1, 3.1.2).","c":"Incorrect. For a minimum length of 12, the values 11 (invalid) and 12 (valid) are the correct two-value boundary values.","d":"Incorrect. TC-02 and TC-05 are positive tests, so the claim is false; there is no systematic one-sidedness here."},"obecne":"Check each test case against the input: whatever has no basis in the acceptance criteria is a candidate hallucination."},"cz":{"q":"<p>Tester zadá LLM následující uživatelský scénář a dostane uvedený výstup.<\/p><pre>Uživatelský scénář: Jako uživatel chci změnit heslo.\nAC1: Nové heslo má aspoň 12 znaků.\nAC2: Nové heslo se musí lišit od současného.\nAC3: Uživatel musí zadat současné heslo.\n\nVýstup LLM:\nTC-01 Nové heslo s 11 znaky je odmítnuto (AC1)\nTC-02 Nové heslo s 12 znaky je přijato (AC1)\nTC-03 Nové heslo shodné se současným je odmítnuto (AC2)\nTC-04 Chybné současné heslo je odmítnuto (AC3)\nTC-05 Po úspěšné změně přijde uživateli na telefon push notifikace (AC2)<\/pre><p>Které tvrzení NEJLÉPE určuje vadu ve výstupu LLM?<\/p>","m":["TC-03 je halucinace, protože AC2 se současného hesla netýká.","TC-05 je halucinace, protože ověřuje push notifikaci, která není v žádném akceptačním kritériu.","TC-01 a TC-02 obsahují chybu v uvažování, protože analýza hraničních hodnot pro minimum 12 vyžaduje hodnoty 12 a 13.","Výstup ukazuje zkreslení, protože všechny testovací případy jsou negativní."],"vys":{"a":"Nesprávně. AC2 výslovně požaduje, aby se nové heslo lišilo od současného. TC-03 má oporu ve vstupu.","b":"Správně. Žádné kritérium notifikaci nezmiňuje, model ji vymyslel a přiřadil k AC2. Odhalí to křížové ověření se scénářem (sylabus 3.1.1, 3.1.2).","c":"Nesprávně. Pro minimální délku 12 jsou správné dvoubodové hraniční hodnoty 11 (neplatná) a 12 (platná).","d":"Nesprávně. TC-02 a TC-05 jsou pozitivní testy, tvrzení neplatí a systematická jednostrannost tu není."},"obecne":"Každý testovací případ porovnejte se vstupem. Co nemá oporu v akceptačních kritériích, je kandidát na halucinaci."},"kap":{"c":"3.1.2","nazev":"3.1.2 Jak vady ve výstupu poznat","href":"kapitola-3/vyklad.html#oddil-3-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.2-02","n":null,"lo":"GenAI-3.1.2","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>An LLM created the following decision table from a business rule.<\/p><pre>Rule: Shipping is free if (order total &gt;= 1,000 CZK AND the customer is logged in)\n      OR the customer has a premium membership.\n\nLLM decision table:\nRow  Total  Logged in  Premium  Free shipping\n1    1,200  yes        no       yes\n2      800  yes        yes      no\n3    1,500  no         no       no\n4      500  no         no       no<\/pre><p>Which type of defect does the output contain, and which detection approach reveals it MOST directly?<\/p>","m":["Bias in rows 3 and 4; review of the test data against the coverage requirements.","A hallucination in row 1; consultation with a domain expert on shipping rules.","A reasoning error in row 2; logical validation of each row against the rule.","A hallucination in row 2; cross-verification against the requirements, because premium membership is not part of the rule."],"vys":{"a":"Incorrect. Rows 3 and 4 are evaluated correctly, and four rows do not show a systematic preference.","b":"Incorrect. Row 1 meets the first part of the rule (total >= 1,000 and logged in), so free shipping is correct.","c":"Correct. A premium member gets free shipping regardless of the other conditions, so row 2 should be 'yes'. The input values are correct, the logic is wrong. Logical validation detects reasoning errors (syllabus 3.1.1, 3.1.2).","d":"Incorrect. Premium membership is explicitly part of the rule, so nothing was invented."},"obecne":"Correct facts plus a wrong conclusion indicate a reasoning error (syllabus 3.1.1); logical validation and output testing detect it (3.1.2)."},"cz":{"q":"<p>LLM vytvořil z obchodního pravidla následující rozhodovací tabulku.<\/p><pre>Pravidlo: Doprava je zdarma, když (objednávka &gt;= 1 000 Kč A zákazník je přihlášen)\n         NEBO má zákazník prémiové členství.\n\nRozhodovací tabulka od LLM:\nŘádek  Objednávka  Přihlášen  Prémium  Doprava zdarma\n1      1 200       ano        ne       ano\n2        800       ano        ano      ne\n3      1 500       ne         ne       ne\n4        500       ne         ne       ne<\/pre><p>Jaký druh vady výstup obsahuje a která metoda detekce ji odhalí NEJPŘÍMĚJI?<\/p>","m":["Zkreslení v řádcích 3 a 4; revize testovacích dat proti požadavkům na pokrytí.","Halucinace v řádku 1; konzultace s doménovým expertem na pravidla dopravy.","Chyba v uvažování v řádku 2; logická validace každého řádku proti pravidlu.","Halucinace v řádku 2; křížové ověření s požadavky, protože prémiové členství v pravidle není."],"vys":{"a":"Nesprávně. Řádky 3 a 4 jsou vyhodnoceny správně a čtyři řádky neukazují systematický sklon.","b":"Nesprávně. Řádek 1 splňuje první část pravidla (objednávka >= 1 000 a přihlášen), doprava zdarma je správně.","c":"Správně. Zákazník s prémiovým členstvím má dopravu zdarma bez ohledu na ostatní podmínky, řádek 2 má být „ano“. Údaje jsou správné, selhala logika. Chyby v uvažování odhaluje logická validace (sylabus 3.1.1, 3.1.2).","d":"Nesprávně. Prémiové členství v pravidle výslovně je, nic nebylo vymyšleno."},"obecne":"Správná fakta a chybný závěr znamenají chybu v uvažování (sylabus 3.1.1). Odhalí ji logická validace a testování výstupu (3.1.2)."},"kap":{"c":"3.1.2","nazev":"3.1.2 Jak vady ve výstupu poznat","href":"kapitola-3/vyklad.html#oddil-3-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.2-03","n":null,"lo":"GenAI-3.1.2","k":"K3","body":2,"vyber":1,"ok":[3],"en":{"q":"<p>A tester asks an LLM for synthetic test data and receives the following output.<\/p><pre>Prompt: Generate 8 test customers for the registration form of a Czech bank.\n\nLLM output (excerpt, all 8 records follow the same pattern):\n{&quot;first_name&quot;: &quot;James&quot;, &quot;last_name&quot;: &quot;Wilson&quot;, &quot;phone&quot;: &quot;+1 202 555 0143&quot;,\n &quot;zip&quot;: &quot;10001&quot;, &quot;birth_date&quot;: &quot;04/23/1987&quot;, &quot;currency&quot;: &quot;USD&quot;}\n{&quot;first_name&quot;: &quot;Emma&quot;, &quot;last_name&quot;: &quot;Taylor&quot;, &quot;phone&quot;: &quot;+1 312 555 0198&quot;,\n &quot;zip&quot;: &quot;60601&quot;, &quot;birth_date&quot;: &quot;11/02/1992&quot;, &quot;currency&quot;: &quot;USD&quot;}<\/pre><p>Which statement BEST describes the defect and how it should be detected?<\/p>","m":["No defect; synthetic data must differ from the real customer population for privacy reasons.","Reasoning error; validate the logical flow of the steps used to generate the records.","Hallucination, because the customers do not exist; cross-verify the records against the production customer database.","Bias; review whether the generated data represents the customer population defined in the test strategy."],"vys":{"a":"Incorrect. Synthetic data must not contain real personal data, but it should still be representative of the population defined in the test strategy (syllabus 2.2.2, 3.1.2).","b":"Incorrect. Nothing is calculated or concluded here; the problem is a systematic preference, not faulty logic.","c":"Incorrect. Synthetic data is supposed to be fictitious, so invented persons are not a defect. Comparing with production data would also create a data privacy risk (syllabus 3.2).","d":"Correct. All records follow US patterns (names, phone codes, ZIP codes, date format, currency) although the target is a Czech bank. This systematic one-sidedness is bias, detected by reviewing synthetic data against the test strategy and coverage (syllabus 3.1.1, 3.1.2)."},"obecne":"Bias shows as a repeated pattern across many outputs (syllabus 3.1.1); detection reviews testware against the test strategy (3.1.2)."},"cz":{"q":"<p>Tester požádá LLM o syntetická testovací data a dostane následující výstup.<\/p><pre>Prompt: Vygeneruj 8 testovacích zákazníků pro registrační formulář české banky.\n\nVýstup LLM (výřez, všech 8 záznamů má stejný vzor):\n{&quot;first_name&quot;: &quot;James&quot;, &quot;last_name&quot;: &quot;Wilson&quot;, &quot;phone&quot;: &quot;+1 202 555 0143&quot;,\n &quot;zip&quot;: &quot;10001&quot;, &quot;birth_date&quot;: &quot;04/23/1987&quot;, &quot;currency&quot;: &quot;USD&quot;}\n{&quot;first_name&quot;: &quot;Emma&quot;, &quot;last_name&quot;: &quot;Taylor&quot;, &quot;phone&quot;: &quot;+1 312 555 0198&quot;,\n &quot;zip&quot;: &quot;60601&quot;, &quot;birth_date&quot;: &quot;11/02/1992&quot;, &quot;currency&quot;: &quot;USD&quot;}<\/pre><p>Které tvrzení NEJLÉPE popisuje vadu a způsob, jak ji odhalit?<\/p>","m":["Žádná vada; syntetická data se musí od skutečné populace zákazníků lišit kvůli ochraně dat.","Chyba v uvažování; ověřit logický tok kroků, kterými záznamy vznikly.","Halucinace, protože zákazníci neexistují; ověřit záznamy proti produkční databázi zákazníků.","Zkreslení; revize, zda vygenerovaná data odpovídají populaci zákazníků definované v testovací strategii."],"vys":{"a":"Nesprávně. Syntetická data nesmí obsahovat skutečné osobní údaje, ale mají být reprezentativní vůči populaci ze strategie (sylabus 2.2.2, 3.1.2).","b":"Nesprávně. Nic se tu nepočítá ani neodvozuje. Problém je systematický sklon, ne chybná logika.","c":"Nesprávně. Syntetická data mají být smyšlená, vymyšlené osoby nejsou vada. Porovnání s produkcí by navíc vytvořilo riziko pro ochranu dat (sylabus 3.2).","d":"Správně. Všechny záznamy mají americké vzory (jména, předvolby, PSČ, formát data, měna), přestože cílem je česká banka. Systematická jednostrannost je zkreslení. Odhalí ji revize syntetických dat proti strategii a pokrytí (sylabus 3.1.1, 3.1.2)."},"obecne":"Zkreslení se projeví opakujícím se vzorem napříč výstupy (sylabus 3.1.1). Detekce porovná testware se strategií (3.1.2)."},"kap":{"c":"3.1.2","nazev":"3.1.2 Jak vady ve výstupu poznat","href":"kapitola-3/vyklad.html#oddil-3-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.2-04","n":null,"lo":"GenAI-3.1.2","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>A test manager uses an LLM to estimate test effort.<\/p><pre>Input: 120 test cases, 4 testers, each tester executes 10 test cases per day.\nThe test environment needs 1 day of setup, which must be finished before execution starts.\n\nLLM output:\nTeam capacity: 4 x 10 = 40 test cases per day.\nExecution: 120 / 40 = 3 days.\nSince 4 testers are available, the environment setup can be shared among them\nand done in parallel with execution. Total duration: 3 days.<\/pre><p>Which statement BEST evaluates the LLM output?<\/p>","m":["It contains a reasoning error: the setup must precede execution, so the total duration is 4 days.","It contains a hallucination, because environment setup was not part of the input.","It is correct, because four testers can perform the setup in a quarter of a day.","It shows bias, because LLMs systematically produce optimistic estimates."],"vys":{"a":"Correct. The calculations of capacity and execution time are right, but the LLM ignores the stated dependency (cause and effect). The correct result is 1 + 3 = 4 days (syllabus 3.1.1, 3.1.2).","b":"Incorrect. The environment setup is explicitly stated in the input.","c":"Incorrect. The input says the setup needs 1 day and must be finished before execution; nothing indicates it can be split.","d":"Incorrect. The defect is a single logical mistake about the order of activities, not a systematic preference shown across outputs."},"obecne":"Test planning and estimation are typical tasks where LLMs make reasoning errors (syllabus 3.1.1, HO-3.1.2b)."},"cz":{"q":"<p>Testovací manažer použije LLM k odhadu pracnosti testování.<\/p><pre>Vstup: 120 testovacích případů, 4 testeři, každý provede 10 testovacích případů za den.\nTestovací prostředí potřebuje 1 den přípravy, která musí skončit před začátkem provádění.\n\nVýstup LLM:\nKapacita týmu: 4 x 10 = 40 testovacích případů za den.\nProvedení: 120 / 40 = 3 dny.\nProtože jsou k dispozici 4 testeři, přípravu prostředí si rozdělí\na udělají ji souběžně s prováděním. Celková doba: 3 dny.<\/pre><p>Které tvrzení NEJLÉPE hodnotí výstup LLM?<\/p>","m":["Obsahuje chybu v uvažování: příprava musí předcházet provádění, celková doba je tedy 4 dny.","Obsahuje halucinaci, protože příprava prostředí ve vstupu nebyla.","Je správně, protože čtyři testeři zvládnou přípravu za čtvrt dne.","Ukazuje zkreslení, protože LLM systematicky vytváří optimistické odhady."],"vys":{"a":"Správně. Výpočet kapacity i doby provádění sedí, ale LLM přehlédl zadanou závislost (příčina a následek). Správně je 1 + 3 = 4 dny (sylabus 3.1.1, 3.1.2).","b":"Nesprávně. Příprava prostředí ve vstupu výslovně je.","c":"Nesprávně. Vstup říká, že příprava trvá 1 den a musí skončit před prováděním. Nic neříká, že ji lze rozdělit.","d":"Nesprávně. Vada je jednorázová logická chyba v pořadí činností, ne systematický sklon napříč výstupy."},"obecne":"Plánování a odhad pracnosti jsou typické úlohy s chybami v uvažování (sylabus 3.1.1, HO-3.1.2b)."},"kap":{"c":"3.1.2","nazev":"3.1.2 Jak vady ve výstupu poznat","href":"kapitola-3/vyklad.html#oddil-3-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.2-05","n":null,"lo":"GenAI-3.1.2","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>A tester asks an LLM to generate an API test with the Python library requests. Running the generated test gives the result shown.<\/p><pre>import requests\n\ndef test_get_policy_status():\n    response = requests.get(&quot;https://api.test.local/policies/12345&quot;)\n    assert response.status_ok()\n    assert response.json()[&quot;status&quot;] == &quot;ACTIVE&quot;\n\nTest run:\nAttributeError: &#x27;Response&#x27; object has no attribute &#x27;status_ok&#x27;<\/pre><p>Which statement BEST describes the defect in the generated test?<\/p>","m":["It is bias, because the LLM prefers the requests library over other HTTP clients.","It is a hallucination: the script calls a method that does not exist in the library.","It is non-deterministic behavior, because the same prompt might produce a working script next time.","It is a reasoning error, because status code 200 is not the expected response to a GET request."],"vys":{"a":"Incorrect. Choosing a common library is not a defect, and a single wrong method call is not a systematic preference.","b":"Correct. The requests library offers, for example, response.ok or raise_for_status(), but no status_ok() method. A non-functioning script calling a non-existent function is a hallucination (syllabus 3.1.1). Cross-verification with the library documentation would find it before execution (3.1.2).","c":"Incorrect. Non-determinism explains why outputs vary, but the defect in this output is the non-existent method, i.e. a hallucination.","d":"Incorrect. 200 is the usual success code for GET, and the script does not even check a specific code; the failure is caused by a non-existent method."},"obecne":"Generated scripts that call non-existent functions are a typical hallucination in testing (syllabus 3.1.1)."},"cz":{"q":"<p>Tester požádá LLM o API test v Pythonu s knihovnou requests. Spuštění vygenerovaného testu dá uvedený výsledek.<\/p><pre>import requests\n\ndef test_get_policy_status():\n    response = requests.get(&quot;https://api.test.local/policies/12345&quot;)\n    assert response.status_ok()\n    assert response.json()[&quot;status&quot;] == &quot;ACTIVE&quot;\n\nTest run:\nAttributeError: &#x27;Response&#x27; object has no attribute &#x27;status_ok&#x27;<\/pre><p>Které tvrzení NEJLÉPE popisuje vadu ve vygenerovaném testu?<\/p>","m":["Je to zkreslení, protože LLM upřednostňuje knihovnu requests před jinými HTTP klienty.","Je to halucinace: skript volá metodu, která v knihovně neexistuje.","Je to nedeterministické chování, protože stejný prompt by příště mohl vytvořit funkční skript.","Je to chyba v uvažování, protože kód 200 není očekávaná odpověď na GET."],"vys":{"a":"Nesprávně. Volba běžné knihovny není vada a jedno chybné volání metody není systematický sklon.","b":"Správně. Knihovna requests nabízí například response.ok nebo raise_for_status(), ale metodu status_ok() nemá. Nefunkční skript s neexistující funkcí je halucinace (sylabus 3.1.1). Křížové ověření s dokumentací by ji odhalilo i před spuštěním (3.1.2).","c":"Nesprávně. Nedeterminismus vysvětluje, proč se výstupy liší. Vadou v tomto výstupu je ale neexistující metoda, tedy halucinace.","d":"Nesprávně. 200 je běžný kód úspěchu pro GET a skript konkrétní kód ani nekontroluje. Selhání způsobila neexistující metoda."},"obecne":"Vygenerované skripty volající neexistující funkce jsou typická halucinace v testování (sylabus 3.1.1)."},"kap":{"c":"3.1.2","nazev":"3.1.2 Jak vady ve výstupu poznat","href":"kapitola-3/vyklad.html#oddil-3-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.3-01","n":null,"lo":"GenAI-3.1.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A tester asks an LLM to generate test cases from a feature title only. The LLM adds several business rules that the product does not have. Which mitigation technique addresses this problem MOST directly?<\/p>","m":["Rewrite the prompt as an unstructured narrative so that the LLM can interpret it freely.","Ask the LLM to generate many more test cases, so the invented ones form a small share.","Provide complete context, such as the user story, acceptance criteria and constraints, in the prompt.","Increase the temperature so that the LLM explores more alternatives."],"vys":{"a":"Incorrect. The syllabus recommends clear, interpretable formats; free interpretation increases misunderstandings (syllabus 3.1.3).","b":"Incorrect. More output does not remove invented rules; it increases review effort.","c":"Correct. Hallucinations are more likely when relevant contextual input is missing; providing complete context reduces the room for invention (syllabus 3.1.3, 2.1.1).","d":"Incorrect. A higher temperature increases randomness (syllabus 3.1.4) and does not supply the missing information."},"obecne":"Defects are more likely when prompts are poorly designed or relevant context is missing (syllabus 3.1.3)."},"cz":{"q":"<p>Tester žádá LLM o testovací případy jen podle názvu funkce. LLM přidá několik obchodních pravidel, která produkt nemá. Která technika zmírnění řeší tento problém NEJPŘÍMĚJI?<\/p>","m":["Přepsat prompt jako volné vyprávění, aby ho LLM mohl vykládat volně.","Požádat LLM o mnohem víc testovacích případů, aby vymyšlené tvořily jen malý podíl.","Dodat do promptu úplný kontext, například uživatelský scénář, akceptační kritéria a omezení.","Zvýšit teplotu, aby LLM prozkoumal víc variant."],"vys":{"a":"Nesprávně. Sylabus doporučuje jasné, srozumitelné formáty. Volný výklad nedorozumění zvyšuje (sylabus 3.1.3).","b":"Nesprávně. Víc výstupu vymyšlená pravidla neodstraní, jen zvýší pracnost revize.","c":"Správně. Halucinace jsou pravděpodobnější, když chybí relevantní kontext. Úplný kontext zmenší prostor pro výmysly (sylabus 3.1.3, 2.1.1).","d":"Nesprávně. Vyšší teplota zvyšuje náhodnost (sylabus 3.1.4) a chybějící informace nedodá."},"obecne":"Vady jsou pravděpodobnější u špatně navrženého promptu nebo při chybějícím kontextu (sylabus 3.1.3)."},"kap":{"c":"3.1.3","nazev":"3.1.3 Jak vadám předcházet","href":"kapitola-3/vyklad.html#oddil-3-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.3-02","n":null,"lo":"GenAI-3.1.3","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which statement BEST explains why dividing a complex prompt into smaller steps helps to mitigate LLM defects?<\/p>","m":["Smaller prompts remove the need for human review of the final result.","Splitting the prompt guarantees deterministic output of the LLM.","Smaller prompts always consume fewer tokens in total, which eliminates hallucinations.","Each intermediate output can be verified before it is used in the next step, so reasoning errors are detected early."],"vys":{"a":"Incorrect. Human review remains essential (syllabus 3.1.2, 3.2.3).","b":"Incorrect. Prompt chaining does not remove non-determinism; complete reproducibility cannot be guaranteed (syllabus 3.1.4).","c":"Incorrect. A chain of prompts may use more tokens in total, and no technique eliminates hallucinations completely.","d":"Correct. Syllabus 3.1.3 describes prompt chaining with systematic verification of each output, which helps detect reasoning errors early."},"obecne":"Prompt chaining (syllabus 2.1.2) is applied as a mitigation technique in 3.1.3."},"cz":{"q":"<p>Které tvrzení NEJLÉPE vysvětluje, proč rozdělení složitého promptu na menší kroky pomáhá zmírnit vady LLM?<\/p>","m":["Menší prompty odstraní potřebu lidské revize výsledku.","Rozdělení promptu zaručí deterministický výstup LLM.","Menší prompty vždy spotřebují celkem méně tokenů, a tím odstraní halucinace.","Každý mezivýsledek lze ověřit dřív, než se použije v dalším kroku, takže se chyby v uvažování odhalí brzy."],"vys":{"a":"Nesprávně. Lidská revize zůstává nezbytná (sylabus 3.1.2, 3.2.3).","b":"Nesprávně. Řetězení promptů nedeterminismus neodstraní, úplnou reprodukovatelnost zaručit nelze (sylabus 3.1.4).","c":"Nesprávně. Řetězec promptů může celkem spotřebovat víc tokenů a žádná technika halucinace zcela neodstraní.","d":"Správně. Sylabus 3.1.3 popisuje řetězení promptů s ověřením každého výstupu, které pomáhá odhalit chyby v uvažování brzy."},"obecne":"Řetězení promptů (sylabus 2.1.2) se v 3.1.3 používá jako technika zmírnění."},"kap":{"c":"3.1.3","nazev":"3.1.3 Jak vadám předcházet","href":"kapitola-3/vyklad.html#oddil-3-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.3-03","n":null,"lo":"GenAI-3.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following is an example of using a clear, interpretable data format to reduce hallucinations and reasoning errors?<\/p>","m":["Providing acceptance criteria as a table with ID, condition and expected result instead of a free-text paragraph.","Letting the LLM decide which input format it prefers.","Attaching a photo of a handwritten whiteboard sketch so that the LLM sees the original source.","Merging requirements, logs and e-mails into one long text block so that no context is lost."],"vys":{"a":"Correct. Structured, straightforward formats help the model focus on the essential aspects of the task (syllabus 3.1.3).","b":"Incorrect. The tester should choose a clear format; leaving it open does not reduce ambiguity.","c":"Incorrect. Handwritten sketches are hard to interpret and ambiguous, which the syllabus advises to avoid.","d":"Incorrect. Context should be complete, but an unstructured mixture is hard to interpret and conflicts with the advice on clear formats."},"obecne":"Avoid formats that are ambiguous or hard for GenAI to interpret (syllabus 3.1.3)."},"cz":{"q":"<p>Který z následujících příkladů ukazuje použití jasného a srozumitelného formátu dat ke snížení halucinací a chyb v uvažování?<\/p>","m":["Dodat akceptační kritéria jako tabulku s ID, podmínkou a očekávaným výsledkem místo souvislého odstavce.","Nechat LLM rozhodnout, jaký formát vstupu preferuje.","Přiložit fotografii ručně kresleného náčrtu z tabule, aby LLM viděl původní zdroj.","Spojit požadavky, logy a e-maily do jednoho dlouhého bloku textu, aby se neztratil kontext."],"vys":{"a":"Správně. Strukturované, přímočaré formáty pomáhají modelu soustředit se na podstatu úlohy (sylabus 3.1.3).","b":"Nesprávně. Jasný formát má zvolit tester. Ponechat to otevřené nejednoznačnost nesníží.","c":"Nesprávně. Ruční náčrt je těžko čitelný a nejednoznačný, a toho se má tester podle sylabu vyvarovat.","d":"Nesprávně. Kontext má být úplný, ale nestrukturovaná směs je těžko čitelná a odporuje doporučení k jasným formátům."},"obecne":"Vyhnout se formátům, které jsou nejednoznačné nebo pro generativní AI těžko čitelné (sylabus 3.1.3)."},"kap":{"c":"3.1.3","nazev":"3.1.3 Jak vadám předcházet","href":"kapitola-3/vyklad.html#oddil-3-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.3-04","n":null,"lo":"GenAI-3.1.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A test manager wants to find unreliable parts of an LLM-generated test strategy for a safety-related function. Which technique addresses this need MOST directly?<\/p>","m":["Raise the temperature to obtain more alternatives from a single model.","Evaluate the same prompt with several LLMs and compare their outputs.","Use the same model with a fixed seed, so that the strategy is reproducible.","Shorten the prompt by removing the description of the safety function."],"vys":{"a":"Incorrect. More randomness from one model does not show which parts are reliable.","b":"Correct. Comparing results across models helps detect output errors and select the most reliable results (syllabus 3.1.3).","c":"Incorrect. A seed improves reproducibility (syllabus 3.1.4), but a reproducible output can still be wrong.","d":"Incorrect. Removing context increases the risk of hallucinations (syllabus 3.1.3)."},"obecne":"Differences between models point to output that needs careful review (syllabus 3.1.3)."},"cz":{"q":"<p>Testovací manažer chce najít nespolehlivá místa v testovací strategii vygenerované LLM pro funkci související s bezpečností. Která technika tuto potřebu řeší NEJPŘÍMĚJI?<\/p>","m":["Zvýšit teplotu a získat víc variant od jednoho modelu.","Vyhodnotit stejný prompt na několika LLM a porovnat jejich výstupy.","Použít stejný model s pevným semínkem, aby byla strategie reprodukovatelná.","Zkrátit prompt vynecháním popisu bezpečnostní funkce."],"vys":{"a":"Nesprávně. Víc náhody od jednoho modelu neukáže, které části jsou spolehlivé.","b":"Správně. Porovnání výsledků více modelů pomáhá odhalit chyby ve výstupu a vybrat nejspolehlivější výsledek (sylabus 3.1.3).","c":"Nesprávně. Semínko zlepší opakovatelnost (sylabus 3.1.4), ale opakovatelný výstup může být stále chybný.","d":"Nesprávně. Odebrání kontextu zvyšuje riziko halucinací (sylabus 3.1.3)."},"obecne":"Rozdíly mezi modely ukazují na výstup, který potřebuje pečlivou revizi (sylabus 3.1.3)."},"kap":{"c":"3.1.3","nazev":"3.1.3 Jak vadám předcházet","href":"kapitola-3/vyklad.html#oddil-3-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.3-05","n":null,"lo":"GenAI-3.1.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which statement about mitigating hallucinations, reasoning errors and biases is consistent with the syllabus?<\/p>","m":["Once a hallucination is fixed in one conversation, it does not reappear with the same LLM.","RAG and fine-tuning remove the need to review LLM output.","These defects are more likely when prompts are poorly designed or relevant contextual data is missing.","A general-purpose model is always the best choice, because it has seen the most data."],"vys":{"a":"Incorrect. Because of non-determinism, defects may reappear in another conversation (syllabus 3.1).","b":"Incorrect. The syllabus mentions RAG and fine-tuning as complementary techniques (chapter 4); review remains necessary.","c":"Correct. Syllabus 3.1.3 states this as the starting point for the mitigation techniques.","d":"Incorrect. The syllabus recommends selecting a model appropriate for the task (syllabus 3.1.3, 5.1.3)."},"obecne":"Mitigation techniques: complete context, prompt segmentation, clear formats, appropriate model, comparing models (syllabus 3.1.3)."},"cz":{"q":"<p>Které tvrzení o zmírnění halucinací, chyb v uvažování a zkreslení odpovídá sylabu?<\/p>","m":["Když se halucinace v jedné konverzaci opraví, se stejným LLM se už neobjeví.","RAG a fine-tuning odstraní potřebu revidovat výstup LLM.","Tyto vady jsou pravděpodobnější, když je prompt špatně navržený nebo chybí relevantní kontextová data.","Obecný model je vždy nejlepší volba, protože viděl nejvíc dat."],"vys":{"a":"Nesprávně. Kvůli nedeterminismu se vady mohou v jiné konverzaci vrátit (sylabus 3.1).","b":"Nesprávně. Sylabus RAG a fine-tuning uvádí jako doplňkové techniky (kapitola 4). Revize zůstává nutná.","c":"Správně. Sylabus 3.1.3 to uvádí jako výchozí bod pro techniky zmírnění.","d":"Nesprávně. Sylabus doporučuje vybrat model vhodný pro úlohu (sylabus 3.1.3, 5.1.3)."},"obecne":"Techniky zmírnění: úplný kontext, rozdělení promptu, jasné formáty, vhodný model, porovnání modelů (sylabus 3.1.3)."},"kap":{"c":"3.1.3","nazev":"3.1.3 Jak vadám předcházet","href":"kapitola-3/vyklad.html#oddil-3-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.4-01","n":null,"lo":"GenAI-3.1.4","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester lowers the temperature of an LLM to obtain more consistent regression test cases. Which side effect should the tester expect?<\/p>","m":["The training data of the model are updated.","The outputs become more creative.","The context window of the model is enlarged.","The outputs become more repetitive and less diverse."],"vys":{"a":"Incorrect. Temperature acts during inference and does not change training data.","b":"Incorrect. Creativity increases with higher, not lower, temperature.","c":"Incorrect. Temperature has no influence on the size of the context window.","d":"Correct. Lowering temperature reduces randomness but also limits creativity and diversity (syllabus 3.1.4)."},"obecne":"Temperature controls randomness or creativity of LLM output (syllabus 3.1.4, Appendix D)."},"cz":{"q":"<p>Tester sníží teplotu LLM, aby dostal konzistentnější regresní testovací případy. Jaký vedlejší účinek má očekávat?<\/p>","m":["Aktualizují se trénovací data modelu.","Výstupy budou kreativnější.","Zvětší se kontextové okno modelu.","Výstupy budou víc opakující se a méně rozmanité."],"vys":{"a":"Nesprávně. Teplota působí při inferenci a trénovací data nemění.","b":"Nesprávně. Kreativita roste s vyšší teplotou, ne s nižší.","c":"Nesprávně. Teplota velikost kontextového okna neovlivňuje.","d":"Správně. Nižší teplota snižuje náhodnost, ale omezuje i kreativitu a rozmanitost (sylabus 3.1.4)."},"obecne":"Teplota řídí náhodnost nebo kreativitu výstupu LLM (sylabus 3.1.4, příloha D)."},"kap":{"c":"3.1.4","nazev":"3.1.4 Nedeterministické chování a jak ho omezit","href":"kapitola-3/vyklad.html#oddil-3-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.4-02","n":null,"lo":"GenAI-3.1.4","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>What is the purpose of setting a random seed when using an LLM?<\/p>","m":["To make the model use the same pseudo-random sequence, which improves reproducibility.","To reduce the number of tokens in the output.","To restrict the answers of the model to a specific domain, such as medicine.","To guarantee that the output is factually correct."],"vys":{"a":"Correct. Syllabus 3.1.4: a seed ensures the same pseudo-random sequence is used, which improves reproducibility.","b":"Incorrect. Output length is not controlled by the seed.","c":"Incorrect. A seed does not restrict topics; domain focus comes from the prompt, RAG or fine-tuning.","d":"Incorrect. A reproducible output can still contain hallucinations."},"obecne":"Only some LLM implementations allow setting a seed (syllabus 3.1.4)."},"cz":{"q":"<p>K čemu slouží nastavení náhodného semínka (random seed) při použití LLM?<\/p>","m":["Aby model použil stejnou pseudonáhodnou posloupnost, což zlepší opakovatelnost.","Aby snížilo počet tokenů ve výstupu.","Aby omezilo odpovědi modelu na určitou oblast, například medicínu.","Aby zaručilo, že výstup je fakticky správný."],"vys":{"a":"Správně. Sylabus 3.1.4: semínko zajistí stejnou pseudonáhodnou posloupnost a tím lepší opakovatelnost.","b":"Nesprávně. Délku výstupu semínko neřídí.","c":"Nesprávně. Semínko témata neomezuje. Zaměření na doménu dává prompt, RAG nebo fine-tuning.","d":"Nesprávně. Opakovatelný výstup může stále obsahovat halucinace."},"obecne":"Nastavení semínka umožňují jen některé implementace LLM (sylabus 3.1.4)."},"kap":{"c":"3.1.4","nazev":"3.1.4 Nedeterministické chování a jak ho omezit","href":"kapitola-3/vyklad.html#oddil-3-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.4-03","n":null,"lo":"GenAI-3.1.4","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which statement about the non-deterministic behavior of LLMs is correct?<\/p>","m":["It occurs only when the LLM is accessed through a web browser.","It results from probabilistic sampling during inference, and the risk of variability increases with longer outputs.","It is caused by the model being retrained after each prompt.","Long outputs reduce variability because random effects average out."],"vys":{"a":"Incorrect. Non-determinism is inherent to LLM inference, regardless of the access channel.","b":"Correct. Syllabus 3.1.4 states both the cause (probabilistic sampling during inference) and that long outputs increase the risk of variability.","c":"Incorrect. Models are not retrained after each prompt; variability arises from sampling.","d":"Incorrect. The syllabus states the opposite: long outputs increase the risk of variability."},"obecne":"Same input, different outputs: probabilistic sampling during inference (syllabus 1.1.2, 3.1.4)."},"cz":{"q":"<p>Které tvrzení o nedeterministickém chování LLM je správné?<\/p>","m":["Projevuje se jen při přístupu k LLM přes webový prohlížeč.","Vzniká pravděpodobnostním výběrem při inferenci a riziko odchylek roste s délkou výstupu.","Vzniká tím, že se model po každém promptu znovu trénuje.","Dlouhé výstupy odchylky snižují, protože se náhodné vlivy zprůměrují."],"vys":{"a":"Nesprávně. Nedeterminismus patří k inferenci LLM bez ohledu na způsob přístupu.","b":"Správně. Sylabus 3.1.4 uvádí příčinu (pravděpodobnostní výběr při inferenci) i to, že delší výstup zvyšuje riziko odchylek.","c":"Nesprávně. Model se po každém promptu netrénuje, odchylky vznikají výběrem tokenů.","d":"Nesprávně. Sylabus uvádí opak: dlouhý výstup riziko odchylek zvyšuje."},"obecne":"Stejný vstup, různé výstupy: pravděpodobnostní výběr při inferenci (sylabus 1.1.2, 3.1.4)."},"kap":{"c":"3.1.4","nazev":"3.1.4 Nedeterministické chování a jak ho omezit","href":"kapitola-3/vyklad.html#oddil-3-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.4-04","n":null,"lo":"GenAI-3.1.4","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which combination of measures does the syllabus list to reduce variability of LLM outputs?<\/p>","m":["Increasing the temperature, enlarging the context window, and removing the system prompt.","Using only zero-shot prompts and avoiding structured output formats.","Lowering the temperature, setting a random seed, and automating aspects of output verification.","Fine-tuning the model after each run, requesting longer outputs, and disabling seeds."],"vys":{"a":"Incorrect. A higher temperature increases randomness; the other measures are not listed.","b":"Incorrect. These are not measures against non-determinism in the syllabus; structured outputs actually ease automated verification.","c":"Correct. Syllabus 3.1.4 lists adjusting temperature and setting seeds, and adds automating some aspects of output verification for structured, consistent evaluation.","d":"Incorrect. Longer outputs increase variability, and disabling seeds reduces reproducibility."},"obecne":"Complete reproducibility cannot be guaranteed, but variability can be reduced (syllabus 3.1.4)."},"cz":{"q":"<p>Kterou kombinaci opatření uvádí sylabus ke snížení variability výstupů LLM?<\/p>","m":["Zvýšení teploty, zvětšení kontextového okna a odstranění systémového promptu.","Používat jen zero-shot prompty a vyhýbat se strukturovaným formátům výstupu.","Snížení teploty, nastavení semínka a automatizace části ověřování výstupu.","Fine-tuning modelu po každém běhu, delší výstupy a vypnutí semínek."],"vys":{"a":"Nesprávně. Vyšší teplota náhodnost zvyšuje, ostatní opatření sylabus neuvádí.","b":"Nesprávně. Sylabus tato opatření proti nedeterminismu neuvádí. Strukturovaný výstup naopak usnadní automatické ověření.","c":"Správně. Sylabus 3.1.4 uvádí úpravu teploty a nastavení semínka a přidává automatizaci části ověření výstupu pro strukturované a konzistentní hodnocení.","d":"Nesprávně. Delší výstupy variabilitu zvyšují a vypnutí semínka zhoršuje opakovatelnost."},"obecne":"Úplnou reprodukovatelnost zaručit nelze, variabilitu lze snížit (sylabus 3.1.4)."},"kap":{"c":"3.1.4","nazev":"3.1.4 Nedeterministické chování a jak ho omezit","href":"kapitola-3/vyklad.html#oddil-3-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.4-05","n":null,"lo":"GenAI-3.1.4","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester sets the temperature to its minimum value and uses a fixed seed. What can the tester expect?<\/p>","m":["Hallucinations are eliminated.","The model refuses all creative tasks.","Identical output is guaranteed for all future runs and model versions.","Variability is reduced, but complete reproducibility cannot be guaranteed."],"vys":{"a":"Incorrect. Lower randomness does not make the content correct; hallucinations can still occur.","b":"Incorrect. Creativity and diversity are reduced, but the model does not refuse tasks.","c":"Incorrect. No setting guarantees identical output, especially across model versions.","d":"Correct. Syllabus 3.1.4 states that complete reproducibility cannot be guaranteed, although these strategies reduce variability."},"obecne":"Temperature and seed reduce variability; they do not eliminate it (syllabus 3.1.4)."},"cz":{"q":"<p>Tester nastaví teplotu na minimum a použije pevné semínko. Co může očekávat?<\/p>","m":["Halucinace zmizí.","Model odmítne všechny kreativní úlohy.","Stejný výstup je zaručen pro všechny budoucí běhy i verze modelu.","Variabilita se sníží, ale úplnou reprodukovatelnost zaručit nelze."],"vys":{"a":"Nesprávně. Menší náhodnost neznamená správný obsah, halucinace se mohou objevit dál.","b":"Nesprávně. Kreativita a rozmanitost klesne, ale model úlohy neodmítá.","c":"Nesprávně. Žádné nastavení stejný výstup nezaručí, tím méně mezi verzemi modelu.","d":"Správně. Sylabus 3.1.4 uvádí, že úplnou reprodukovatelnost zaručit nelze, i když tato opatření variabilitu snižují."},"obecne":"Teplota a semínko variabilitu snižují, neodstraní ji (sylabus 3.1.4)."},"kap":{"c":"3.1.4","nazev":"3.1.4 Nedeterministické chování a jak ho omezit","href":"kapitola-3/vyklad.html#oddil-3-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.1-01","n":null,"lo":"GenAI-3.2.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A tester pastes a production log into an LLM to generate test cases. The generated test cases, stored in the test management tool, contain the names and account numbers of real customers from the log. Which risk does this illustrate MOST directly?<\/p>","m":["Unintentional data exposure.","An attack on the LLM-powered test infrastructure.","Lack of control over data usage.","Bias in the generated test cases."],"vys":{"a":"Correct. The output accidentally reveals sensitive information (syllabus 3.2.1).","b":"Incorrect. No attacker is involved; the exposure results from careless data handling.","c":"Incorrect. This concerns the GenAI tool storing or processing data without consent or control; the scenario focuses on the output revealing data.","d":"Incorrect. Bias is a quality defect from training data (syllabus 3.1.1), not a data privacy risk."},"obecne":"Data privacy concerns: unintentional data exposure, lack of control over data usage, compliance risks (syllabus 3.2.1)."},"cz":{"q":"<p>Tester vloží do LLM produkční log, aby z něj vytvořil testovací případy. Vygenerované testovací případy uložené v nástroji pro správu testů obsahují jména a čísla účtů skutečných klientů z logu. Které riziko to ilustruje NEJPŘÍMĚJI?<\/p>","m":["Neúmyslné vyzrazení dat.","Útok na testovací infrastrukturu postavenou na LLM.","Ztráta kontroly nad použitím dat.","Zkreslení ve vygenerovaných testovacích případech."],"vys":{"a":"Správně. Výstup nechtěně odhaluje citlivé informace (sylabus 3.2.1).","b":"Nesprávně. Není tu žádný útočník, vyzrazení vzniklo neopatrným zacházením s daty.","c":"Nesprávně. To se týká ukládání a zpracování dat nástrojem bez souhlasu nebo kontroly. Situace ale popisuje výstup, který data odhaluje.","d":"Nesprávně. Zkreslení je vada kvality pocházející z trénovacích dat (sylabus 3.1.1), ne riziko pro ochranu dat."},"obecne":"Rizika pro ochranu dat: neúmyslné vyzrazení, ztráta kontroly nad použitím dat, nesoulad s předpisy (sylabus 3.2.1)."},"kap":{"c":"3.2.1","nazev":"3.2.1 Rizika pro ochranu dat a bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.1-02","n":null,"lo":"GenAI-3.2.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which situation is an example of lack of control over data usage?<\/p>","m":["An attacker gains access to the test tool through a weak password.","A free GenAI tool stores the prompts on its servers and may use them for training, and the organization cannot restrict this.","The LLM output contains an access token that was included in the prompt.","The LLM generates test data that underrepresents older users."],"vys":{"a":"Incorrect. This is a security risk to the LLM-powered test infrastructure (unauthorized access).","b":"Correct. GenAI tools may store and process data without explicit consent or control of the user (syllabus 3.2.1).","c":"Incorrect. This is unintentional data exposure in the output.","d":"Incorrect. This is bias (syllabus 3.1.1)."},"obecne":"Lack of control may lead to misuse or unauthorized access (syllabus 3.2.1)."},"cz":{"q":"<p>Která situace je příkladem ztráty kontroly nad použitím dat?<\/p>","m":["Útočník se dostane do testovacího nástroje přes slabé heslo.","Bezplatný nástroj generativní AI ukládá prompty na svých serverech a může je použít k tréninku, a organizace to nemůže omezit.","Výstup LLM obsahuje přístupový token, který byl v promptu.","LLM generuje testovací data, ve kterých jsou málo zastoupeni starší uživatelé."],"vys":{"a":"Nesprávně. To je bezpečnostní riziko pro testovací infrastrukturu (neoprávněný přístup).","b":"Správně. Nástroje generativní AI mohou data ukládat a zpracovávat bez výslovného souhlasu nebo kontroly uživatele (sylabus 3.2.1).","c":"Nesprávně. To je neúmyslné vyzrazení dat ve výstupu.","d":"Nesprávně. To je zkreslení (sylabus 3.1.1)."},"obecne":"Ztráta kontroly může vést ke zneužití nebo neoprávněnému přístupu (sylabus 3.2.1)."},"kap":{"c":"3.2.1","nazev":"3.2.1 Rizika pro ochranu dat a bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.1-03","n":null,"lo":"GenAI-3.2.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Why can using a GenAI tool with real customer data in testing lead to compliance risks?<\/p>","m":["Because GenAI tools always produce hallucinations when processing personal data.","Because GDPR explicitly prohibits any use of GenAI.","Processing personal data without meeting the requirements of data protection regulations such as GDPR can result in legal disputes.","Because the NIST AI RMF is binding law in the EU."],"vys":{"a":"Incorrect. Hallucinations are a quality issue, not the reason for compliance risks.","b":"Incorrect. Data protection regulations do not explicitly restrict GenAI but provide safeguards (syllabus 3.2.3).","c":"Correct. Syllabus 3.2.1 names compliance risks with regulations such as GDPR, which could lead to legal disputes.","d":"Incorrect. The NIST AI RMF is a US framework, not a regulation (syllabus 3.4.1)."},"obecne":"GDPR = Regulation (EU) 2016/679 (syllabus 3.2.1)."},"cz":{"q":"<p>Proč může použití nástroje generativní AI se skutečnými daty klientů při testování vést k riziku nesouladu s předpisy?<\/p>","m":["Protože nástroje generativní AI při zpracování osobních údajů vždy halucinují.","Protože GDPR výslovně zakazuje jakékoli použití generativní AI.","Zpracování osobních údajů bez splnění požadavků předpisů o ochraně dat, jako je GDPR, může vést k právním sporům.","Protože NIST AI RMF je v EU závazný zákon."],"vys":{"a":"Nesprávně. Halucinace jsou problém kvality, nejsou důvodem rizika nesouladu.","b":"Nesprávně. Předpisy o ochraně dat generativní AI výslovně neomezují, obsahují ale pojistky (sylabus 3.2.3).","c":"Správně. Sylabus 3.2.1 jmenuje riziko nesouladu s předpisy, jako je GDPR, které může vést k právním sporům.","d":"Nesprávně. NIST AI RMF je americký rámec, ne předpis (sylabus 3.4.1)."},"obecne":"GDPR = nařízení (EU) 2016/679 (sylabus 3.2.1)."},"kap":{"c":"3.2.1","nazev":"3.2.1 Rizika pro ochranu dat a bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.1-04","n":null,"lo":"GenAI-3.2.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which of the following is a SECURITY risk, rather than a data privacy concern, when testing with GenAI?<\/p>","m":["A GenAI tool is used without complying with GDPR.","The output of the LLM accidentally reveals sensitive information.","A GenAI tool stores sensitive data without explicit consent of the user.","Attackers intentionally introduce malicious input data to mislead the LLM used in the test infrastructure."],"vys":{"a":"Incorrect. This is the data privacy concern 'compliance risks'.","b":"Incorrect. This is the data privacy concern 'unintentional data exposure'.","c":"Incorrect. This is the data privacy concern 'lack of control over data usage'.","d":"Correct. Syllabus 3.2.1 lists this among the specific security risks."},"obecne":"Syllabus 3.2.1 separates data privacy concerns from security risks."},"cz":{"q":"<p>Které z následujících je BEZPEČNOSTNÍ riziko, a ne obava týkající se ochrany dat, při testování s generativní AI?<\/p>","m":["Nástroj generativní AI se používá bez souladu s GDPR.","Výstup LLM nechtěně odhalí citlivou informaci.","Nástroj generativní AI ukládá citlivá data bez výslovného souhlasu uživatele.","Útočníci úmyslně vnášejí škodlivá vstupní data, aby zmátli LLM v testovací infrastruktuře."],"vys":{"a":"Nesprávně. To je obava o ochranu dat „riziko nesouladu s předpisy“.","b":"Nesprávně. To je obava o ochranu dat „neúmyslné vyzrazení dat“.","c":"Nesprávně. To je obava o ochranu dat „ztráta kontroly nad použitím dat“.","d":"Správně. Sylabus 3.2.1 to uvádí mezi specifickými bezpečnostními riziky."},"obecne":"Sylabus 3.2.1 odděluje obavy o ochranu dat od bezpečnostních rizik."},"kap":{"c":"3.2.1","nazev":"3.2.1 Rizika pro ochranu dat a bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.1-05","n":null,"lo":"GenAI-3.2.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which statement BEST explains why LLM-powered test infrastructure needs security attention?<\/p>","m":["It can be vulnerable to data breaches and unauthorized access, and attackers can exploit LLM vulnerabilities to change its behavior or extract sensitive information.","It never processes production data, so the risk is only theoretical.","Security risks arise only while the model is trained, not while it is used.","LLMs encrypt all processed data by default, so only the network needs protection."],"vys":{"a":"Correct. This summarizes the security risks in syllabus 3.2.1.","b":"Incorrect. Test data, logs and testware often contain sensitive information.","c":"Incorrect. Several attack vectors act during use, for example request manipulation (syllabus 3.2.2).","d":"Incorrect. Encryption and access controls must be implemented deliberately (syllabus 3.2.3)."},"obecne":"Robust data protection is needed to prevent breaches, unauthorized access and exposure of confidential data (syllabus 3.2)."},"cz":{"q":"<p>Které tvrzení NEJLÉPE vysvětluje, proč testovací infrastruktura postavená na LLM vyžaduje pozornost z hlediska bezpečnosti?<\/p>","m":["Může být zranitelná vůči únikům dat a neoprávněnému přístupu a útočníci mohou zneužít zranitelnosti LLM ke změně jeho chování nebo k získání citlivých informací.","Nikdy nezpracovává produkční data, takže riziko je jen teoretické.","Bezpečnostní rizika vznikají jen při tréninku modelu, ne při jeho používání.","LLM ve výchozím stavu šifrují všechna zpracovaná data, takže chránit je potřeba jen síť."],"vys":{"a":"Správně. Shrnuje to bezpečnostní rizika ze sylabu 3.2.1.","b":"Nesprávně. Testovací data, logy a testware často citlivé informace obsahují.","c":"Nesprávně. Několik vektorů útoku působí při používání, například manipulace s požadavkem (sylabus 3.2.2).","d":"Nesprávně. Šifrování a řízení přístupu je potřeba zavést záměrně (sylabus 3.2.3)."},"obecne":"Je potřeba robustní ochrana dat proti únikům, neoprávněnému přístupu a vyzrazení důvěrných dat (sylabus 3.2)."},"kap":{"c":"3.2.1","nazev":"3.2.1 Rizika pro ochranu dat a bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-01","n":null,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>An attacker sends extremely long prompts to an LLM-based test assistant until the assistant starts to output fragments of documents it was trained on. Which attack vector does this describe?<\/p>","m":["Request manipulation","Context manipulation","Malicious code generation","Data poisoning"],"vys":{"a":"Incorrect. Request manipulation means introducing data that disrupts the AI's output during use (syllabus 3.2.2).","b":"Correct. Context manipulation means sending requests designed to extract confidential training data (syllabus 3.2.2). Overloading the context window to reveal training data is the syllabus example.","c":"Incorrect. Malicious code generation means manipulating an LLM to generate backdoors, e.g. external command calls, during use (syllabus 3.2.2).","d":"Incorrect. Data poisoning means manipulating training data (syllabus 3.2.2)."},"obecne":"The four attack vectors in syllabus 3.2.2: context manipulation, request manipulation, data poisoning, malicious code generation."},"cz":{"q":"<p>Útočník posílá testovacímu asistentovi postavenému na LLM extrémně dlouhé prompty, dokud asistent nezačne vypisovat útržky dokumentů, na kterých se učil. Který vektor útoku to popisuje?<\/p>","m":["Manipulace s požadavkem (request manipulation)","Manipulace s kontextem (context manipulation)","Generování škodlivého kódu (malicious code generation)","Otrávení dat (data poisoning)"],"vys":{"a":"Nesprávně. Manipulace s požadavkem znamená vložit data, která při použití naruší výstup AI (sylabus 3.2.2).","b":"Správně. Manipulace s kontextem znamená posílat požadavky, které mají z modelu vytáhnout důvěrná trénovací data (sylabus 3.2.2). Zahlcení kontextového okna, po kterém model odhalí trénovací data, je příklad ze sylabu.","c":"Nesprávně. Generování škodlivého kódu znamená zmanipulovat LLM, aby při použití vytvořil zadní vrátka, např. volání externích příkazů (sylabus 3.2.2).","d":"Nesprávně. Otrávení dat znamená manipulaci s trénovacími daty (sylabus 3.2.2)."},"obecne":"Čtyři vektory útoku ze sylabu 3.2.2: manipulace s kontextem, manipulace s požadavkem, otrávení dat, generování škodlivého kódu."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-02","n":null,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A defect report contains a screenshot with almost invisible text. When the LLM-based tool processes the report, it proposes acceptance criteria that are unrelated to the feature. Which attack vector does this describe?<\/p>","m":["Malicious code generation","Context manipulation","Request manipulation","Data poisoning"],"vys":{"a":"Incorrect. Malicious code generation means manipulating an LLM to generate backdoors, e.g. external command calls, during use (syllabus 3.2.2).","b":"Incorrect. Context manipulation means sending requests designed to extract confidential training data (syllabus 3.2.2).","c":"Correct. Request manipulation means introducing data that disrupts the AI's output during use (syllabus 3.2.2). An image that lures the AI into a different context and provokes hallucinated acceptance criteria matches the syllabus example.","d":"Incorrect. Data poisoning means manipulating training data (syllabus 3.2.2)."},"obecne":"Request manipulation acts on the input during use; its goal is a disrupted output."},"cz":{"q":"<p>Report o defektu obsahuje snímek obrazovky s téměř neviditelným textem. Když ho zpracuje nástroj postavený na LLM, navrhne akceptační kritéria, která s funkcí nesouvisejí. Který vektor útoku to popisuje?<\/p>","m":["Generování škodlivého kódu (malicious code generation)","Manipulace s kontextem (context manipulation)","Manipulace s požadavkem (request manipulation)","Otrávení dat (data poisoning)"],"vys":{"a":"Nesprávně. Generování škodlivého kódu znamená zmanipulovat LLM, aby při použití vytvořil zadní vrátka, např. volání externích příkazů (sylabus 3.2.2).","b":"Nesprávně. Manipulace s kontextem znamená posílat požadavky, které mají z modelu vytáhnout důvěrná trénovací data (sylabus 3.2.2).","c":"Správně. Manipulace s požadavkem znamená vložit data, která při použití naruší výstup AI (sylabus 3.2.2). Obrázek, který AI zavede do jiného kontextu a vyvolá halucinovaná akceptační kritéria, odpovídá příkladu ze sylabu.","d":"Nesprávně. Otrávení dat znamená manipulaci s trénovacími daty (sylabus 3.2.2)."},"obecne":"Manipulace s požadavkem působí na vstup při použití, cílem je narušený výstup."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-03","n":null,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A GenAI test case generator is regularly retrained on test cases that users have marked as accepted. A competitor creates many accounts and marks deliberately flawed test cases as accepted. Which attack vector does this describe?<\/p>","m":["Context manipulation","Request manipulation","Malicious code generation","Data poisoning"],"vys":{"a":"Incorrect. Context manipulation means sending requests designed to extract confidential training data (syllabus 3.2.2).","b":"Incorrect. Request manipulation means introducing data that disrupts the AI's output during use (syllabus 3.2.2).","c":"Incorrect. Malicious code generation means manipulating an LLM to generate backdoors, e.g. external command calls, during use (syllabus 3.2.2).","d":"Correct. Data poisoning means manipulating training data (syllabus 3.2.2). The attacker manipulates the data the model is trained on, similar to fake evaluations in the syllabus example."},"obecne":"Data poisoning targets the data used for training, not a single interaction."},"cz":{"q":"<p>Generátor testovacích případů s generativní AI se pravidelně přeučuje na testovacích případech, které uživatelé označili jako přijaté. Konkurent si založí mnoho účtů a označuje záměrně vadné testovací případy jako přijaté. Který vektor útoku to popisuje?<\/p>","m":["Manipulace s kontextem (context manipulation)","Manipulace s požadavkem (request manipulation)","Generování škodlivého kódu (malicious code generation)","Otrávení dat (data poisoning)"],"vys":{"a":"Nesprávně. Manipulace s kontextem znamená posílat požadavky, které mají z modelu vytáhnout důvěrná trénovací data (sylabus 3.2.2).","b":"Nesprávně. Manipulace s požadavkem znamená vložit data, která při použití naruší výstup AI (sylabus 3.2.2).","c":"Nesprávně. Generování škodlivého kódu znamená zmanipulovat LLM, aby při použití vytvořil zadní vrátka, např. volání externích příkazů (sylabus 3.2.2).","d":"Správně. Otrávení dat znamená manipulaci s trénovacími daty (sylabus 3.2.2). Útočník manipuluje s daty, na kterých se model učí, podobně jako falešná hodnocení v příkladu ze sylabu."},"obecne":"Otrávení dat míří na data pro trénink, ne na jednu interakci."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-04","n":null,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>During review, a tester finds that an LLM-generated test setup function downloads a shell script from an external IP address and executes it. Which attack vector is MOST likely involved?<\/p>","m":["Malicious code generation","Request manipulation","Context manipulation","Data poisoning"],"vys":{"a":"Correct. Malicious code generation means manipulating an LLM to generate backdoors, e.g. external command calls, during use (syllabus 3.2.2). Downloading and executing code from an external address is a backdoor through external command calls.","b":"Incorrect. Request manipulation means introducing data that disrupts the AI's output during use (syllabus 3.2.2).","c":"Incorrect. Context manipulation means sending requests designed to extract confidential training data (syllabus 3.2.2).","d":"Incorrect. Data poisoning means manipulating training data (syllabus 3.2.2)."},"obecne":"Generated code must be reviewed before execution (syllabus 3.2.3)."},"cz":{"q":"<p>Při revizi tester zjistí, že funkce pro přípravu testů vygenerovaná LLM stahuje shellový skript z externí IP adresy a spouští ho. Který vektor útoku je NEJSPÍŠ ve hře?<\/p>","m":["Generování škodlivého kódu (malicious code generation)","Manipulace s požadavkem (request manipulation)","Manipulace s kontextem (context manipulation)","Otrávení dat (data poisoning)"],"vys":{"a":"Správně. Generování škodlivého kódu znamená zmanipulovat LLM, aby při použití vytvořil zadní vrátka, např. volání externích příkazů (sylabus 3.2.2). Stažení a spuštění kódu z externí adresy jsou zadní vrátka přes volání externích příkazů.","b":"Nesprávně. Manipulace s požadavkem znamená vložit data, která při použití naruší výstup AI (sylabus 3.2.2).","c":"Nesprávně. Manipulace s kontextem znamená posílat požadavky, které mají z modelu vytáhnout důvěrná trénovací data (sylabus 3.2.2).","d":"Nesprávně. Otrávení dat znamená manipulaci s trénovacími daty (sylabus 3.2.2)."},"obecne":"Vygenerovaný kód je nutné před spuštěním revidovat (sylabus 3.2.3)."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-05","n":null,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which statement BEST distinguishes data poisoning from the other attack vectors described in the syllabus?<\/p>","m":["Data poisoning aims to extract confidential training data from the model.","Data poisoning targets the data the model learns from, while the other vectors act on the model while it is used.","Data poisoning makes the model generate code with backdoors.","Data poisoning works only with image inputs."],"vys":{"a":"Incorrect. Extracting training data is context manipulation.","b":"Correct. Data poisoning is manipulating training data; context manipulation, request manipulation and malicious code generation happen during use (syllabus 3.2.2).","c":"Incorrect. Generating backdoors is malicious code generation.","d":"Incorrect. The syllabus example involves fake evaluations, not images; images are the example for request manipulation."},"obecne":"Ask what the attacker manipulates: training data (poisoning) or the interaction during use (other vectors)."},"cz":{"q":"<p>Které tvrzení NEJLÉPE odlišuje otrávení dat od ostatních vektorů útoku popsaných v sylabu?<\/p>","m":["Cílem otrávení dat je získat z modelu důvěrná trénovací data.","Otrávení dat míří na data, ze kterých se model učí, zatímco ostatní vektory působí na model při používání.","Otrávení dat přiměje model generovat kód se zadními vrátky.","Otrávení dat funguje jen s obrazovými vstupy."],"vys":{"a":"Nesprávně. Získání trénovacích dat je manipulace s kontextem.","b":"Správně. Otrávení dat je manipulace s trénovacími daty. Manipulace s kontextem, s požadavkem i generování škodlivého kódu probíhají při použití (sylabus 3.2.2).","c":"Nesprávně. Generování zadních vrátek je generování škodlivého kódu.","d":"Nesprávně. Příklad v sylabu jsou falešná hodnocení, ne obrázky. Obrázky jsou příklad manipulace s požadavkem."},"obecne":"Ptejte se, s čím útočník manipuluje: s trénovacími daty (otrávení), nebo s interakcí při použití (ostatní vektory)."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-06","n":null,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which example BEST illustrates context manipulation?<\/p>","m":["A requirements document contains hidden text that makes the LLM skip tests for authorization.","The LLM is manipulated into adding a hidden call to an external command in a test script.","Crafted requests make a model fine-tuned on internal defect reports reveal customer e-mail addresses contained in those reports.","Users systematically give top ratings to poor AI-generated test reports to influence future training."],"vys":{"a":"Incorrect. Introducing data that disrupts the output is request manipulation.","b":"Incorrect. Backdoors via external command calls are malicious code generation.","c":"Correct. The requests aim to extract confidential data the model was trained on (syllabus 3.2.2).","d":"Incorrect. Manipulating training data through fake ratings is data poisoning."},"obecne":"Context manipulation is a GenAI-specific keyword of chapter 3."},"cz":{"q":"<p>Který příklad NEJLÉPE ilustruje manipulaci s kontextem?<\/p>","m":["Dokument s požadavky obsahuje skrytý text, kvůli kterému LLM vynechá testy autorizace.","LLM je zmanipulován, aby do testovacího skriptu přidal skryté volání externího příkazu.","Cíleně sestavené požadavky přimějí model doladěný na interních reportech o defektech vyzradit e-mailové adresy klientů, které v reportech byly.","Uživatelé systematicky dávají nejlepší hodnocení špatným AI reportům o testování, aby ovlivnili další trénink."],"vys":{"a":"Nesprávně. Vložení dat, která naruší výstup, je manipulace s požadavkem.","b":"Nesprávně. Zadní vrátka přes volání externích příkazů jsou generování škodlivého kódu.","c":"Správně. Požadavky mají z modelu vytáhnout důvěrná data, na kterých byl trénován (sylabus 3.2.2).","d":"Nesprávně. Manipulace s trénovacími daty přes falešná hodnocení je otrávení dat."},"obecne":"Manipulace s kontextem je klíčové slovo kapitoly 3 specifické pro generativní AI."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-07","n":null,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester reviews LLM-generated automation code before it is merged. Which finding indicates malicious code generation?<\/p>","m":["The test names are in English although the team uses Czech names.","One assertion contains a wrong expected value.","The script uses an existing but deprecated method of the test framework.","A helper function sends all environment variables of the CI job to a hard-coded external IP address."],"vys":{"a":"Incorrect. This is a style issue, possibly a sign of bias, but not malicious code.","b":"Incorrect. A wrong expected value is a defect in the testware (hallucination or reasoning error), not a backdoor.","c":"Incorrect. This is a maintainability issue, not a backdoor.","d":"Correct. Opening a communication channel to a specific external address is the syllabus example of a backdoor (syllabus 3.2.2)."},"obecne":"Warning signs: external command calls, downloads, hard-coded addresses, sending secrets."},"cz":{"q":"<p>Tester reviduje automatizační kód vygenerovaný LLM před sloučením. Které zjištění ukazuje na generování škodlivého kódu?<\/p>","m":["Názvy testů jsou anglicky, přestože tým používá české názvy.","Jedna aserce obsahuje chybnou očekávanou hodnotu.","Skript používá existující, ale zastaralou metodu testovacího frameworku.","Pomocná funkce posílá všechny proměnné prostředí úlohy v CI na pevně zadanou externí IP adresu."],"vys":{"a":"Nesprávně. To je otázka stylu, nanejvýš projev zkreslení, ne škodlivý kód.","b":"Nesprávně. Chybná očekávaná hodnota je vada testwaru (halucinace nebo chyba v uvažování), ne zadní vrátka.","c":"Nesprávně. To je problém udržovatelnosti, ne zadní vrátka.","d":"Správně. Otevření komunikačního kanálu na konkrétní externí adresu je příklad zadních vrátek ze sylabu (sylabus 3.2.2)."},"obecne":"Varovné znaky: volání externích příkazů, stahování, pevné adresy, odesílání tajných údajů."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-08","n":null,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which pair correctly matches an attack vector with its description?<\/p>","m":["Request manipulation – introducing data, such as misleading images, that disrupts the AI's output.","Context manipulation – inserting backdoors into generated code.","Malicious code generation – manipulating training data with fake ratings.","Data poisoning – extracting confidential training data with very long prompts."],"vys":{"a":"Correct. This matches the description and example in syllabus 3.2.2.","b":"Incorrect. Backdoors belong to malicious code generation; context manipulation extracts training data.","c":"Incorrect. Fake ratings in training data are data poisoning.","d":"Incorrect. Extracting training data with long prompts is context manipulation."},"obecne":"Learn each vector with its goal and the syllabus example (syllabus 3.2.2)."},"cz":{"q":"<p>Která dvojice správně přiřazuje vektor útoku k jeho popisu?<\/p>","m":["Manipulace s požadavkem – vložení dat, například zavádějících obrázků, která naruší výstup AI.","Manipulace s kontextem – vložení zadních vrátek do generovaného kódu.","Generování škodlivého kódu – manipulace s trénovacími daty pomocí falešných hodnocení.","Otrávení dat – získání důvěrných trénovacích dat velmi dlouhými prompty."],"vys":{"a":"Správně. Odpovídá to popisu a příkladu ze sylabu 3.2.2.","b":"Nesprávně. Zadní vrátka patří ke generování škodlivého kódu. Manipulace s kontextem získává trénovací data.","c":"Nesprávně. Falešná hodnocení v trénovacích datech jsou otrávení dat.","d":"Nesprávně. Získání trénovacích dat dlouhými prompty je manipulace s kontextem."},"obecne":"Naučte se ke každému vektoru jeho cíl a příklad ze sylabu (sylabus 3.2.2)."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-09","n":null,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A requirements document processed by an LLM-based test tool contains hidden instructions telling the model to omit all tests for user authorization. Which attack vector from the syllabus does this MOST closely correspond to?<\/p>","m":["Malicious code generation","Request manipulation","Data poisoning","Context manipulation"],"vys":{"a":"Incorrect. Malicious code generation means manipulating an LLM to generate backdoors, e.g. external command calls, during use (syllabus 3.2.2).","b":"Correct. Request manipulation means introducing data that disrupts the AI's output during use (syllabus 3.2.2). The hidden instructions are data introduced at use time that disrupt the output; nothing in the training data is changed.","c":"Incorrect. Data poisoning means manipulating training data (syllabus 3.2.2).","d":"Incorrect. Context manipulation means sending requests designed to extract confidential training data (syllabus 3.2.2)."},"obecne":"Outside the syllabus, this is known as (indirect) prompt injection."},"cz":{"q":"<p>Dokument s požadavky, který zpracuje testovací nástroj postavený na LLM, obsahuje skryté pokyny, ať model vynechá všechny testy autorizace uživatelů. Kterému vektoru útoku ze sylabu to NEJVÍC odpovídá?<\/p>","m":["Generování škodlivého kódu (malicious code generation)","Manipulace s požadavkem (request manipulation)","Otrávení dat (data poisoning)","Manipulace s kontextem (context manipulation)"],"vys":{"a":"Nesprávně. Generování škodlivého kódu znamená zmanipulovat LLM, aby při použití vytvořil zadní vrátka, např. volání externích příkazů (sylabus 3.2.2).","b":"Správně. Manipulace s požadavkem znamená vložit data, která při použití naruší výstup AI (sylabus 3.2.2). Skryté pokyny jsou data vložená při použití, která naruší výstup. Trénovací data se nemění.","c":"Nesprávně. Otrávení dat znamená manipulaci s trénovacími daty (sylabus 3.2.2).","d":"Nesprávně. Manipulace s kontextem znamená posílat požadavky, které mají z modelu vytáhnout důvěrná trénovací data (sylabus 3.2.2)."},"obecne":"Mimo sylabus se tomu říká (nepřímý) prompt injection."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.3-01","n":null,"lo":"GenAI-3.2.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which statement about data protection regulations such as GDPR and the use of GenAI in testing is consistent with the syllabus?<\/p>","m":["They apply only to the training of LLMs, not to the data in prompts.","GDPR is a best-practice framework published by NIST.","They do not explicitly restrict GenAI, but their safeguards, such as lawfulness and purpose limitation, can limit what can be done.","They explicitly ban uploading any test data to an LLM."],"vys":{"a":"Incorrect. Any processing of personal data, including in prompts, is subject to data protection rules.","b":"Incorrect. GDPR is Regulation (EU) 2016/679; NIST publishes the AI RMF (syllabus 3.4.1).","c":"Correct. This is stated in syllabus 3.2.3.","d":"Incorrect. The syllabus states that they do not restrict GenAI explicitly."},"obecne":"Regulations and standards emerge to mitigate GenAI risks (syllabus 3.2.3, 3.4.1)."},"cz":{"q":"<p>Které tvrzení o předpisech na ochranu dat, jako je GDPR, a o použití generativní AI v testování odpovídá sylabu?<\/p>","m":["Vztahují se jen na trénink LLM, ne na data v promptech.","GDPR je rámec osvědčených postupů, který vydal NIST.","Generativní AI výslovně neomezují, ale jejich pojistky, například zákonnost a omezení účelu, mohou omezit, co lze dělat.","Výslovně zakazují nahrát do LLM jakákoli testovací data."],"vys":{"a":"Nesprávně. Pravidla ochrany dat platí pro každé zpracování osobních údajů, i v promptu.","b":"Nesprávně. GDPR je nařízení (EU) 2016/679. NIST vydává AI RMF (sylabus 3.4.1).","c":"Správně. Přesně to uvádí sylabus 3.2.3.","d":"Nesprávně. Sylabus uvádí, že generativní AI výslovně neomezují."},"obecne":"Předpisy a standardy vznikají, aby zmírnily rizika generativní AI (sylabus 3.2.3, 3.4.1)."},"kap":{"c":"3.2.3","nazev":"3.2.3 Jak chránit data a posílit bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.3-02","n":null,"lo":"GenAI-3.2.3","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester designs tests for a loan application form with an LLM. Which practice is an example of data minimization?<\/p>","m":["Comparing the generated tests with the output of another LLM.","Encrypting the connection between the test tool and the LLM provider.","Training the test team on the policy for using GenAI tools.","Giving the LLM only field definitions and business rules instead of real customer applications."],"vys":{"a":"Incorrect. This is evaluation by comparison with another LLM, which targets output quality.","b":"Incorrect. This is secure data transmission.","c":"Incorrect. This is resources training.","d":"Correct. Data minimization means using only the necessary amount of non-sensitive data (syllabus 3.2.3)."},"obecne":"Data privacy measures: minimization, anonymization/pseudonymization, secure storage and transmission, resources training (syllabus 3.2.3)."},"cz":{"q":"<p>Tester navrhuje s pomocí LLM testy pro formulář žádosti o úvěr. Který postup je příkladem minimalizace dat?<\/p>","m":["Porovnat vygenerované testy s výstupem jiného LLM.","Zašifrovat spojení mezi testovacím nástrojem a poskytovatelem LLM.","Proškolit testovací tým v pravidlech pro používání nástrojů generativní AI.","Dát LLM jen definice polí a obchodní pravidla místo skutečných žádostí klientů."],"vys":{"a":"Nesprávně. To je hodnocení porovnáním s jiným LLM, míří na kvalitu výstupu.","b":"Nesprávně. To je bezpečný přenos dat.","c":"Nesprávně. To je školení lidí.","d":"Správně. Minimalizace dat znamená použít jen nezbytné množství necitlivých dat (sylabus 3.2.3)."},"obecne":"Opatření na ochranu dat: minimalizace, anonymizace a pseudonymizace, bezpečné uložení a přenos, školení (sylabus 3.2.3)."},"kap":{"c":"3.2.3","nazev":"3.2.3 Jak chránit data a posílit bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.3-03","n":null,"lo":"GenAI-3.2.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A bank requires that no test data leave its own data center. Which choice of a secure operational environment fits this requirement?<\/p>","m":["Installing the LLM in the organization's own infrastructure.","Using a free public chatbot with the chat history switched off.","Using a commercial, secure offering of an LLM provider.","Letting each tester choose a GenAI tool and documenting the choice afterwards."],"vys":{"a":"Correct. This is one of the three options in syllabus 3.2.3 and keeps data inside the bank.","b":"Incorrect. The data still leave the bank, and the organization has no contractual control.","c":"Incorrect. A secure commercial offering is a valid option in general, but the data are processed by the provider outside the bank's data center.","d":"Incorrect. This is uncontrolled use (shadow AI, chapter 5) and does not ensure the requirement."},"obecne":"Options in the syllabus: commercial secure offering, secure cloud, or the organization's own infrastructure, depending on the confidentiality level."},"cz":{"q":"<p>Banka požaduje, aby žádná testovací data neopustila její vlastní datové centrum. Která volba bezpečného provozního prostředí tomuto požadavku odpovídá?<\/p>","m":["Nainstalovat LLM do vlastní infrastruktury organizace.","Použít bezplatný veřejný chatbot s vypnutou historií konverzací.","Použít komerční zabezpečenou nabídku poskytovatele LLM.","Nechat každého testera vybrat si nástroj generativní AI a volbu zdokumentovat dodatečně."],"vys":{"a":"Správně. Je to jedna ze tří možností ze sylabu 3.2.3 a data zůstanou v bance.","b":"Nesprávně. Data i tak opustí banku a organizace nemá smluvní kontrolu.","c":"Nesprávně. Komerční nabídka je obecně platná možnost, ale data zpracuje poskytovatel mimo datové centrum banky.","d":"Nesprávně. To je nekontrolované použití (stínová AI, kapitola 5) a požadavek nezajistí."},"obecne":"Možnosti ze sylabu: komerční zabezpečená nabídka, zabezpečený cloud, nebo vlastní infrastruktura, podle požadované důvěrnosti."},"kap":{"c":"3.2.3","nazev":"3.2.3 Jak chránit data a posílit bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.3-04","n":null,"lo":"GenAI-3.2.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which statement about mitigation strategies for data privacy and security is consistent with the syllabus?<\/p>","m":["Security audits are needed only once, before the first use of the tool.","The strategies are complementary and usually need to be combined; involving security engineers, legal counsel, the CTO or the CISO is recommended.","A single strategy, such as encryption, is sufficient for GenAI in testing.","Individual testers should decide on mitigation without involving other roles."],"vys":{"a":"Incorrect. The syllabus recommends regular security audits and vulnerability assessments.","b":"Correct. Syllabus 3.2.3 states that a combination is required and recommends involving these roles.","c":"Incorrect. The syllabus states that a combination is required.","d":"Incorrect. The syllabus recommends involving senior security and legal roles."},"obecne":"Mitigation strategies are complementary (syllabus 3.2.3)."},"cz":{"q":"<p>Které tvrzení o strategiích zmírnění rizik pro ochranu dat a bezpečnost odpovídá sylabu?<\/p>","m":["Bezpečnostní audit je potřeba jen jednou, před prvním použitím nástroje.","Strategie se doplňují a obvykle je nutné je kombinovat. Doporučuje se zapojit bezpečnostní inženýry, právníky, CTO nebo CISO.","Jedna strategie, například šifrování, pro generativní AI v testování stačí.","O zmírnění mají rozhodovat jednotliví testeři bez zapojení dalších rolí."],"vys":{"a":"Nesprávně. Sylabus doporučuje pravidelné audity a hodnocení zranitelností.","b":"Správně. Sylabus 3.2.3 uvádí, že je potřeba kombinace, a doporučuje tyto role zapojit.","c":"Nesprávně. Sylabus uvádí, že je potřeba kombinace.","d":"Nesprávně. Sylabus doporučuje zapojit zkušené bezpečnostní a právní role."},"obecne":"Strategie zmírnění se doplňují (sylabus 3.2.3)."},"kap":{"c":"3.2.3","nazev":"3.2.3 Jak chránit data a posílit bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.3-05","n":null,"lo":"GenAI-3.2.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A team uses an LLM to generate automation scripts that run in the CI pipeline with access to test databases. Which mitigation BEST reduces the risk of executing malicious generated code?<\/p>","m":["Limiting unnecessary interactions with the model.","Lowering the temperature of the LLM.","Systematic human review of the generated scripts before they are executed.","Anonymizing the test data before it is sent to the LLM."],"vys":{"a":"Incorrect. This is a best practice for energy consumption (syllabus 3.3.1).","b":"Incorrect. Temperature affects variability, not whether code contains backdoors.","c":"Correct. Human evaluation of the generated output is essential (syllabus 3.2.3) and catches backdoors before execution.","d":"Incorrect. Anonymization protects personal data but does not detect malicious code."},"obecne":"Additional strategies include systematic review, comparison with another LLM, a secure environment, audits and staying updated (syllabus 3.2.3)."},"cz":{"q":"<p>Tým používá LLM k generování automatizačních skriptů, které běží v CI s přístupem k testovacím databázím. Které opatření NEJLÉPE sníží riziko spuštění škodlivého vygenerovaného kódu?<\/p>","m":["Omezit zbytečné interakce s modelem.","Snížit teplotu LLM.","Systematická lidská revize vygenerovaných skriptů před jejich spuštěním.","Anonymizovat testovací data před odesláním do LLM."],"vys":{"a":"Nesprávně. To je osvědčený postup pro spotřebu energie (sylabus 3.3.1).","b":"Nesprávně. Teplota ovlivňuje variabilitu, ne to, zda kód obsahuje zadní vrátka.","c":"Správně. Lidské hodnocení výstupu je nezbytné (sylabus 3.2.3) a zachytí zadní vrátka před spuštěním.","d":"Nesprávně. Anonymizace chrání osobní údaje, ale škodlivý kód neodhalí."},"obecne":"Doplňková opatření: systematická revize, porovnání s jiným LLM, bezpečné prostředí, audity a sledování osvědčených postupů (sylabus 3.2.3)."},"kap":{"c":"3.2.3","nazev":"3.2.3 Jak chránit data a posílit bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.3.1-01","n":null,"lo":"GenAI-3.3.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which GenAI-supported test task is likely to consume the MOST energy per generated output?<\/p>","m":["Summarizing a short defect report.","Classifying a single log line as error or warning.","Generating ten test case titles from a user story.","Generating images of user interface states for visual comparison tests."],"vys":{"a":"Incorrect. This is a short text task with low computational effort.","b":"Incorrect. This is a very small text task.","c":"Incorrect. This is a short text generation task.","d":"Correct. Generating an image can consume as much energy as fully charging a smartphone, while text generation needs only a small fraction (syllabus 3.3.1)."},"obecne":"The complexity of the task and the computational resources required influence energy consumption (syllabus 3.3.1)."},"cz":{"q":"<p>Která testovací úloha s podporou generativní AI pravděpodobně spotřebuje NEJVÍC energie na jeden vygenerovaný výstup?<\/p>","m":["Shrnutí krátkého reportu o defektu.","Klasifikace jednoho řádku logu jako chyby nebo varování.","Vygenerování deseti názvů testovacích případů z uživatelského scénáře.","Generování obrázků stavů uživatelského rozhraní pro vizuální srovnávací testy."],"vys":{"a":"Nesprávně. Je to krátká textová úloha s malou výpočetní náročností.","b":"Nesprávně. Je to velmi malá textová úloha.","c":"Nesprávně. Je to krátké generování textu.","d":"Správně. Vygenerování obrázku může spotřebovat tolik energie jako nabití telefonu, generování textu jen zlomek (sylabus 3.3.1)."},"obecne":"Spotřebu energie ovlivňuje složitost úlohy a potřebné výpočetní zdroje (sylabus 3.3.1)."},"kap":{"c":"3.3.1","nazev":"3.3.1 Vliv generativní AI na spotřebu energie a emise CO₂","href":"kapitola-3/vyklad.html#oddil-3-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.3.1-02","n":null,"lo":"GenAI-3.3.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which statement BEST explains why the energy consumption of text-based GenAI test tasks should not be ignored?<\/p>","m":["Although one text generation seems negligible, the cumulative use by millions of users leads to significant energy use and CO₂ emissions.","Exact energy values for every prompt are published, so teams can easily calculate them.","Only the training of LLMs consumes energy; usage is free of emissions.","Text generation uses more energy per output than image generation."],"vys":{"a":"Correct. Syllabus 3.3.1 emphasizes the cumulative effect across millions of users.","b":"Incorrect. The syllabus notes that accurate data is hard to obtain.","c":"Incorrect. The syllabus states that usage increases the load on devices, networks and data centers (syllabus 3.3).","d":"Incorrect. The syllabus states the opposite."},"obecne":"Energy consumption rises sharply as usage increases (syllabus 3.3.1)."},"cz":{"q":"<p>Které tvrzení NEJLÉPE vysvětluje, proč se spotřeba energie textových testovacích úloh s generativní AI nemá přehlížet?<\/p>","m":["Jedno vygenerování textu se zdá zanedbatelné, ale souhrnné použití milionů uživatelů vede k velké spotřebě energie a emisím CO₂.","Přesné hodnoty energie pro každý prompt jsou zveřejněné, takže je tým snadno spočítá.","Energii spotřebuje jen trénink LLM, používání je bez emisí.","Generování textu spotřebuje na jeden výstup víc energie než generování obrázku."],"vys":{"a":"Správně. Sylabus 3.3.1 zdůrazňuje souhrnný účinek přes miliony uživatelů.","b":"Nesprávně. Sylabus uvádí, že přesná data se získávají těžko.","c":"Nesprávně. Sylabus uvádí, že používání zatěžuje zařízení, sítě a datová centra (sylabus 3.3).","d":"Nesprávně. Sylabus uvádí opak."},"obecne":"Spotřeba energie prudce roste s rostoucím používáním (sylabus 3.3.1)."},"kap":{"c":"3.3.1","nazev":"3.3.1 Vliv generativní AI na spotřebu energie a emise CO₂","href":"kapitola-3/vyklad.html#oddil-3-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.3.1-03","n":null,"lo":"GenAI-3.3.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Every night, a team sends the same prompt five times for each of 2,000 regression test cases to the largest available LLM to check output consistency, even when nothing has changed. Which change would MOST reduce energy consumption while keeping the purpose?<\/p>","m":["Increase the temperature so that fewer runs are needed.","Run the consistency check only when the prompt or model changes, and use a smaller model if it is sufficient for the task.","Ask the model to return a screenshot-like image instead of text.","Add the full test logs to every prompt to give more context."],"vys":{"a":"Incorrect. A higher temperature increases variability, which would require more checking, not less.","b":"Correct. Fewer unnecessary interactions and a model with lower resource needs reduce consumption; this reflects the impact of model usage (syllabus 3.3.1).","c":"Incorrect. Image generation is far more energy-intensive than text generation.","d":"Incorrect. More tokens in the context increase computational effort (syllabus 1.1.2)."},"obecne":"Best practice: limit unnecessary model interactions (syllabus 3.3.1)."},"cz":{"q":"<p>Tým každou noc posílá největšímu dostupnému LLM stejný prompt pětkrát pro každý z 2 000 regresních testovacích případů, aby ověřil konzistenci výstupu, i když se nic nezměnilo. Která změna NEJVÍC sníží spotřebu energie a zachová účel?<\/p>","m":["Zvýšit teplotu, aby bylo potřeba méně běhů.","Spouštět kontrolu konzistence jen při změně promptu nebo modelu a použít menší model, pokud na úlohu stačí.","Požádat model o výstup v podobě obrázku místo textu.","Přidat do každého promptu celé testovací logy, aby měl model víc kontextu."],"vys":{"a":"Nesprávně. Vyšší teplota zvyšuje variabilitu, kontroly by bylo potřeba víc, ne méně.","b":"Správně. Méně zbytečných interakcí a model s menšími nároky spotřebu sníží. Odráží to vliv způsobu použití modelu (sylabus 3.3.1).","c":"Nesprávně. Generování obrázků je mnohem náročnější na energii než generování textu.","d":"Nesprávně. Víc tokenů v kontextu zvyšuje výpočetní náročnost (sylabus 1.1.2)."},"obecne":"Osvědčený postup: omezit zbytečné interakce s modelem (sylabus 3.3.1)."},"kap":{"c":"3.3.1","nazev":"3.3.1 Vliv generativní AI na spotřebu energie a emise CO₂","href":"kapitola-3/vyklad.html#oddil-3-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.3.1-04","n":null,"lo":"GenAI-3.3.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which factors does the syllabus name as influencing the energy consumption of GenAI?<\/p>","m":["The tester's experience and the number of defects found.","The programming language of the test object.","The complexity of the task and the computational resources required.","The number of acceptance criteria per user story only."],"vys":{"a":"Incorrect. These are not named as factors of energy consumption.","b":"Incorrect. The syllabus does not mention the programming language of the test object.","c":"Correct. Syllabus 3.3.1 names these two factors.","d":"Incorrect. This is not a factor named in the syllabus."},"obecne":"Example: an image consumes much more energy than text (syllabus 3.3.1)."},"cz":{"q":"<p>Které faktory podle sylabu ovlivňují spotřebu energie generativní AI?<\/p>","m":["Zkušenost testera a počet nalezených defektů.","Programovací jazyk testovaného objektu.","Složitost úlohy a potřebné výpočetní zdroje.","Jen počet akceptačních kritérií v uživatelském scénáři."],"vys":{"a":"Nesprávně. Sylabus je jako faktory spotřeby energie neuvádí.","b":"Nesprávně. Programovací jazyk testovaného objektu sylabus nezmiňuje.","c":"Správně. Sylabus 3.3.1 jmenuje právě tyto dva faktory.","d":"Nesprávně. Takový faktor sylabus neuvádí."},"obecne":"Příklad: obrázek spotřebuje mnohem víc energie než text (sylabus 3.3.1)."},"kap":{"c":"3.3.1","nazev":"3.3.1 Vliv generativní AI na spotřebu energie a emise CO₂","href":"kapitola-3/vyklad.html#oddil-3-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.3.1-05","n":null,"lo":"GenAI-3.3.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which statement about the available data on the environmental impact of GenAI is consistent with the syllabus?<\/p>","m":["Only image generation contributes to CO₂ emissions; text generation does not.","Because the data is uncertain, environmental impact can be ignored when planning GenAI use in testing.","Energy consumption decreases as usage of GenAI increases, due to economies of scale.","Accurate data is hard to obtain, but energy-intensive operations clearly contribute collectively to significant CO₂ emissions."],"vys":{"a":"Incorrect. Text generation consumes less, but its cumulative impact is significant.","b":"Incorrect. The syllabus states that the impact should not be underestimated.","c":"Incorrect. The syllabus states that energy consumption rises sharply as usage increases.","d":"Correct. Syllabus 3.3.1 states both points (Luccioni 2024b, Berthelot 2024)."},"obecne":"Do not underestimate the environmental impact of GenAI (syllabus 3.3.1)."},"cz":{"q":"<p>Které tvrzení o dostupných datech o dopadu generativní AI na životní prostředí odpovídá sylabu?<\/p>","m":["K emisím CO₂ přispívá jen generování obrázků, generování textu ne.","Protože jsou data nejistá, lze dopad na životní prostředí při plánování použití generativní AI v testování přehlížet.","Spotřeba energie s rostoucím používáním generativní AI klesá díky úsporám z rozsahu.","Přesná data se získávají těžko, ale energeticky náročné operace zjevně dohromady přispívají k významným emisím CO₂."],"vys":{"a":"Nesprávně. Text spotřebuje méně, ale jeho souhrnný dopad je značný.","b":"Nesprávně. Sylabus uvádí, že dopad se nemá podceňovat.","c":"Nesprávně. Sylabus uvádí, že spotřeba s používáním prudce roste.","d":"Správně. Sylabus 3.3.1 uvádí obojí (Luccioni 2024b, Berthelot 2024)."},"obecne":"Dopad generativní AI na životní prostředí se nemá podceňovat (sylabus 3.3.1)."},"kap":{"c":"3.3.1","nazev":"3.3.1 Vliv generativní AI na spotřebu energie a emise CO₂","href":"kapitola-3/vyklad.html#oddil-3-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.4.1-01","n":null,"lo":"GenAI-3.4.1","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which document specifies requirements for managing AI systems within an organization?<\/p>","m":["ISO/IEC 42001:2023","NIST AI Risk Management Framework","ISO/IEC 25010:2023","ISO/IEC 23053:2022"],"vys":{"a":"Correct. ISO/IEC 42001 specifies requirements for an AI management system (syllabus 3.4.1).","b":"Incorrect. The NIST AI RMF offers guidelines for managing AI risks; it is a framework, not management system requirements.","c":"Incorrect. ISO/IEC 25010 is a product quality model known from CTFL and is not listed in syllabus 3.4.1.","d":"Incorrect. ISO/IEC 23053 provides a framework for AI systems using machine learning and their lifecycle."},"obecne":"Syllabus 3.4.1 lists ISO/IEC 42001, ISO/IEC 23053, the EU AI Act and the NIST AI RMF."},"cz":{"q":"<p>Který dokument stanoví požadavky na řízení AI systémů v organizaci?<\/p>","m":["ISO/IEC 42001:2023","NIST AI Risk Management Framework","ISO/IEC 25010:2023","ISO/IEC 23053:2022"],"vys":{"a":"Správně. ISO/IEC 42001 stanoví požadavky na systém řízení AI (sylabus 3.4.1).","b":"Nesprávně. NIST AI RMF nabízí doporučení k řízení rizik AI. Je to rámec, ne požadavky na systém řízení.","c":"Nesprávně. ISO/IEC 25010 je model kvality produktu známý ze CTFL a v sylabu 3.4.1 není.","d":"Nesprávně. ISO/IEC 23053 dává rámec pro AI systémy se strojovým učením a jejich životní cyklus."},"obecne":"Sylabus 3.4.1 uvádí ISO/IEC 42001, ISO/IEC 23053, EU AI Act a NIST AI RMF."},"kap":{"c":"3.4.1","nazev":"3.4.1 Předpisy, standardy a rámce relevantní pro generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-4-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.4.1-02","n":null,"lo":"GenAI-3.4.1","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following is a regulation that classifies AI applications by risk level?<\/p>","m":["NIST AI Risk Management Framework","EU AI Act","ISO/IEC/IEEE 29119-2:2021","ISO/IEC 42001:2023"],"vys":{"a":"Incorrect. The NIST AI RMF is a US framework, not a regulation.","b":"Correct. The EU AI Act establishes a legal framework and classifies applications by risk level (syllabus 3.4.1).","c":"Incorrect. This is a standard for test processes known from CTFL and is not listed in syllabus 3.4.1.","d":"Incorrect. ISO/IEC 42001 is a standard for AI management systems."},"obecne":"Types in syllabus 3.4.1: standard (42001, 23053), regulation (EU AI Act), framework (NIST AI RMF)."},"cz":{"q":"<p>Který z následujících dokumentů je předpis, který dělí AI aplikace podle úrovně rizika?<\/p>","m":["NIST AI Risk Management Framework","EU AI Act","ISO/IEC/IEEE 29119-2:2021","ISO/IEC 42001:2023"],"vys":{"a":"Nesprávně. NIST AI RMF je americký rámec, ne předpis.","b":"Správně. EU AI Act zavádí právní rámec a dělí aplikace podle úrovně rizika (sylabus 3.4.1).","c":"Nesprávně. Je to standard pro testovací procesy známý ze CTFL, v sylabu 3.4.1 není.","d":"Nesprávně. ISO/IEC 42001 je standard pro systém řízení AI."},"obecne":"Typy ze sylabu 3.4.1: standard (42001, 23053), předpis (EU AI Act), rámec (NIST AI RMF)."},"kap":{"c":"3.4.1","nazev":"3.4.1 Předpisy, standardy a rámce relevantní pro generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-4-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.4.1-03","n":null,"lo":"GenAI-3.4.1","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which document is a US framework offering guidelines for managing AI risks with a focus on fairness, transparency and security?<\/p>","m":["EU AI Act","ISO/IEC 23053:2022","NIST AI Risk Management Framework","General Data Protection Regulation (GDPR)"],"vys":{"a":"Incorrect. The EU AI Act is a European regulation.","b":"Incorrect. ISO/IEC 23053 is an international standard with a framework for ML-based AI systems.","c":"Correct. This matches the description in syllabus 3.4.1.","d":"Incorrect. GDPR is an EU regulation on personal data protection."},"obecne":"NIST AI RMF supports fairness and helps prevent biased test results (syllabus 3.4.1)."},"cz":{"q":"<p>Který dokument je americký rámec s doporučeními pro řízení rizik AI se zaměřením na férovost, transparentnost a bezpečnost?<\/p>","m":["EU AI Act","ISO/IEC 23053:2022","NIST AI Risk Management Framework","Obecné nařízení o ochraně osobních údajů (GDPR)"],"vys":{"a":"Nesprávně. EU AI Act je evropský předpis.","b":"Nesprávně. ISO/IEC 23053 je mezinárodní standard s rámcem pro AI systémy se strojovým učením.","c":"Správně. Odpovídá to popisu v sylabu 3.4.1.","d":"Nesprávně. GDPR je nařízení EU o ochraně osobních údajů."},"obecne":"NIST AI RMF podporuje férovost a pomáhá předcházet zkresleným výsledkům testů (sylabus 3.4.1)."},"kap":{"c":"3.4.1","nazev":"3.4.1 Předpisy, standardy a rámce relevantní pro generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-4-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.4.1-04","n":null,"lo":"GenAI-3.4.1","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which standard provides a framework for AI lifecycle processes for systems using machine learning, emphasizing safety and transparency?<\/p>","m":["ISO/IEC 25010:2023","ISO/IEC 42001:2023","ISO/IEC/IEEE 29119-3:2021","ISO/IEC 23053:2022"],"vys":{"a":"Incorrect. ISO/IEC 25010 is a product quality model and is not listed in syllabus 3.4.1.","b":"Incorrect. ISO/IEC 42001 specifies requirements for managing AI systems within an organization.","c":"Incorrect. This standard covers test documentation and is not listed in syllabus 3.4.1.","d":"Correct. This matches the description in syllabus 3.4.1."},"obecne":"In testing, ISO/IEC 23053 provides a framework for data quality, transparency and safety (syllabus 3.4.1)."},"cz":{"q":"<p>Který standard poskytuje rámec pro procesy životního cyklu AI systémů se strojovým učením s důrazem na bezpečnost a transparentnost?<\/p>","m":["ISO/IEC 25010:2023","ISO/IEC 42001:2023","ISO/IEC/IEEE 29119-3:2021","ISO/IEC 23053:2022"],"vys":{"a":"Nesprávně. ISO/IEC 25010 je model kvality produktu a v sylabu 3.4.1 není.","b":"Nesprávně. ISO/IEC 42001 stanoví požadavky na řízení AI systémů v organizaci.","c":"Nesprávně. Tento standard se týká testovací dokumentace a v sylabu 3.4.1 není.","d":"Správně. Odpovídá to popisu v sylabu 3.4.1."},"obecne":"V testování dává ISO/IEC 23053 rámec pro kvalitu dat, transparentnost a bezpečnost (sylabus 3.4.1)."},"kap":{"c":"3.4.1","nazev":"3.4.1 Předpisy, standardy a rámce relevantní pro generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-4-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.4.1-05","n":null,"lo":"GenAI-3.4.1","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Why should test organizations keep track of AI regulations, standards and frameworks?<\/p>","m":["Because AI technologies and their regulatory landscape keep evolving, including regulations, standards, national laws and best-practice frameworks.","Because an organization certified to ISO/IEC 42001 no longer has to comply with GDPR.","Because the EU AI Act applies only to companies based in the United States.","Because the listed standards replace the need for defined test processes."],"vys":{"a":"Correct. Syllabus 3.4.1 states that test organizations need to stay updated as the landscape evolves.","b":"Incorrect. A standard certification does not replace legal obligations.","c":"Incorrect. The EU AI Act is a European regulation.","d":"Incorrect. The standards support responsible use of GenAI; they do not replace test processes."},"obecne":"Addressing GenAI risks should consider regulations, standards and best-practice frameworks (syllabus 3.4)."},"cz":{"q":"<p>Proč mají testovací organizace sledovat předpisy, standardy a rámce pro AI?<\/p>","m":["Protože se technologie AI i oblast předpisů stále vyvíjejí, včetně předpisů, standardů, národních zákonů a rámců osvědčených postupů.","Protože organizace certifikovaná podle ISO/IEC 42001 už nemusí dodržovat GDPR.","Protože EU AI Act platí jen pro firmy se sídlem v USA.","Protože uvedené standardy nahrazují potřebu definovaných testovacích procesů."],"vys":{"a":"Správně. Sylabus 3.4.1 uvádí, že testovací organizace musí držet krok s vývojem.","b":"Nesprávně. Certifikace podle standardu nenahrazuje zákonné povinnosti.","c":"Nesprávně. EU AI Act je evropský předpis.","d":"Nesprávně. Standardy podporují odpovědné použití generativní AI, testovací procesy nenahrazují."},"obecne":"Při řešení rizik generativní AI je třeba brát v úvahu předpisy, standardy a rámce osvědčených postupů (sylabus 3.4)."},"kap":{"c":"3.4.1","nazev":"3.4.1 Předpisy, standardy a rámce relevantní pro generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-4-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.1-01","n":null,"lo":"GenAI-4.1.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following statements BEST explains why an LLM-powered test infrastructure goes beyond a traditional client-server model?<\/p>","m":["The responses are selected from a library of scripted answers that testers maintain for each type of query.","The LLM interprets and reasons about testware and generates test insights dynamically from context such as requirements, code or test results.","The LLM replaces the relational database as the primary storage for structured test data.","The front-end stores the test cases locally, so a back-end is no longer required to process user input."],"vys":{"a":"Incorrect. Scripted answers describe rule-based chatbots, which the syllabus contrasts with LLM-powered test infrastructure (4.1.1).","b":"Correct. Section 4.1.1 describes the LLM as a smart processing component that reasons based on testware and generates insights dynamically from context, unlike a plain server.","c":"Incorrect. Relational databases remain one of the data sources integrated by the back-end. The LLM generates responses, it is not a data store (4.1.1).","d":"Incorrect. The back-end remains essential: it handles authentication, data retrieval, prompt preparation and interaction with the LLM (4.1.1)."},"obecne":"The four differences from a client-server model in 4.1.1: the LLM reasons about testware, responses are generated dynamically from context, the back-end integrates multiple data sources, and the back-end post-processes the output."},"cz":{"q":"<p>Které z následujících tvrzení NEJLÉPE vysvětluje, proč infrastruktura testování postavená na LLM přesahuje tradiční model klient-server?<\/p>","m":["Odpovědi se vybírají z knihovny předem napsaných odpovědí, kterou testeři udržují pro každý typ dotazu.","LLM interpretuje testware, uvažuje nad ním a vytváří poznatky dynamicky z kontextu, jako jsou požadavky, kód nebo výsledky testů.","LLM nahrazuje relační databázi jako hlavní úložiště strukturovaných testovacích dat.","Front-end ukládá testovací případy lokálně, takže back-end už vstup uživatele zpracovávat nemusí."],"vys":{"a":"Špatně. Předem napsané odpovědi jsou znakem chatbotů založených na pravidlech, se kterými sylabus infrastrukturu s LLM srovnává (4.1.1).","b":"Správně. Oddíl 4.1.1 popisuje LLM jako chytrou zpracovávající komponentu, která uvažuje nad testwarem a vytváří poznatky dynamicky z kontextu.","c":"Špatně. Relační databáze zůstává jedním ze zdrojů dat back-endu. LLM generuje odpovědi, není to úložiště (4.1.1).","d":"Špatně. Back-end zůstává nezbytný: ověřuje uživatele, vyhledává data, připravuje prompt a komunikuje s LLM (4.1.1)."},"obecne":"Čtyři rozdíly oproti klientovi a serveru v 4.1.1: LLM uvažuje nad testwarem, odpovědi vznikají dynamicky z kontextu, back-end spojuje více zdrojů dat a back-end upravuje výstup modelu."},"kap":{"c":"4.1.1","nazev":"4.1.1 Architektonické komponenty a koncepty","href":"kapitola-4/vyklad.html#oddil-4-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.1-02","n":null,"lo":"GenAI-4.1.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A test team uses an in-house LLM-powered tool to derive test cases from user stories. Testers report that the generated test cases appear in varying layouts and sometimes reference requirement identifiers that do not exist in the requirements repository.<\/p><p>Which architectural function addresses this problem MOST directly?<\/p>","m":["Adding more input fields to the front-end so testers can describe the layout.","Authentication performed by the back-end before the prompt is sent.","Post-processing of the LLM's raw output by the back-end before it is presented on the front-end.","Hosting the LLM as a third-party service instead of an in-house model."],"vys":{"a":"Incorrect. More input fields may help the prompt, but the front-end only collects input and displays results. Checking and refining output is a back-end function (4.1.1).","b":"Incorrect. Authentication controls who can use the system and which data they may access. It does not change the content of the output (4.1.1).","c":"Correct. Section 4.1.1 states that the back-end enhances the raw output through post-processing so that it aligns with the test conditions of the test process before presenting it, for example by applying a template and checking references.","d":"Incorrect. Moving the LLM to a third-party service does not ensure a consistent layout or valid references. The raw output would still need refining (4.1.1)."},"obecne":"Post-processing is the back-end function that aligns LLM output with the test process before the user sees it."},"cz":{"q":"<p>Testovací tým používá vlastní nástroj postavený na LLM, který odvozuje testovací případy z uživatelských scénářů. Testeři hlásí, že vygenerované testovací případy mají pokaždé jinou úpravu a někdy odkazují na identifikátory požadavků, které v repozitáři požadavků neexistují.<\/p><p>Která funkce architektury řeší tento problém NEJPŘÍMĚJI?<\/p>","m":["Přidání dalších vstupních polí do front-endu, aby testeři mohli popsat požadovanou úpravu.","Autentizace, kterou back-end provede před odesláním promptu.","Následné zpracování surového výstupu LLM v back-endu, než se zobrazí ve front-endu.","Hostování LLM jako služby třetí strany místo vlastního modelu."],"vys":{"a":"Špatně. Další pole mohou zlepšit prompt, ale front-end jen sbírá vstup a zobrazuje výsledek. Kontrola a úprava výstupu je funkce back-endu (4.1.1).","b":"Špatně. Autentizace řídí, kdo systém používá a k jakým datům má přístup. Obsah výstupu nemění (4.1.1).","c":"Správně. Podle 4.1.1 back-end vylepšuje surový výstup následným zpracováním, aby odpovídal testovacím podmínkám, a teprve pak ho předá front-endu. Například použije šablonu a ověří odkazy.","d":"Špatně. Přesun LLM ke třetí straně nezajistí jednotnou úpravu ani platné odkazy. Surový výstup by bylo stále potřeba upravit (4.1.1)."},"obecne":"Post-processing je funkce back-endu, která sladí výstup LLM s testovacím procesem dřív, než ho uvidí uživatel."},"kap":{"c":"4.1.1","nazev":"4.1.1 Architektonické komponenty a koncepty","href":"kapitola-4/vyklad.html#oddil-4-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.1-03","n":null,"lo":"GenAI-4.1.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>The back-end of an LLM-powered test tool integrates several data sources. Which of the following statements correctly describes the role of these data sources?<\/p>","m":["A vector database stores test execution results in tables so that exact queries such as counts of failed tests can be answered.","A vector database handles user authentication, while a relational database prepares the prompt.","A relational database provides semantic retrieval of related content by comparing embeddings.","A relational database holds structured data such as existing test cases, while a vector database enables retrieval of related content by meaning using embeddings."],"vys":{"a":"Incorrect. Tables and exact queries describe a relational database. A vector database stores high-dimensional vectors for similarity search (4.1.1, 4.1.2).","b":"Incorrect. Authentication and prompt preparation are functions of the back-end, not of the databases (4.1.1).","c":"Incorrect. The roles are swapped. Semantic retrieval using embeddings is the purpose of a vector database (4.1.1).","d":"Correct. Section 4.1.1 lists relational databases for structured data used in testing, such as test cases, and vector databases for semantic retrieval of related content using embeddings."},"obecne":"Relational database: structured data, exact queries. Vector database: embeddings, retrieval by semantic similarity."},"cz":{"q":"<p>Back-end testovacího nástroje postaveného na LLM spojuje několik zdrojů dat. Které z následujících tvrzení správně popisuje roli těchto zdrojů?<\/p>","m":["Vektorová databáze ukládá výsledky běhů testů do tabulek, aby šlo odpovídat na přesné dotazy, například kolik testů selhalo.","Vektorová databáze zajišťuje autentizaci uživatelů a relační databáze připravuje prompt.","Relační databáze umožňuje sémantické vyhledávání souvisejícího obsahu porovnáváním embeddingů.","Relační databáze drží strukturovaná data, například existující testovací případy, a vektorová databáze umožňuje vyhledat související obsah podle významu pomocí embeddingů."],"vys":{"a":"Špatně. Tabulky a přesné dotazy popisují relační databázi. Vektorová databáze ukládá vektory pro vyhledávání podle podobnosti (4.1.1, 4.1.2).","b":"Špatně. Autentizace a příprava promptu jsou funkce back-endu, ne databází (4.1.1).","c":"Špatně. Role jsou prohozené. Sémantické vyhledávání pomocí embeddingů je úloha vektorové databáze (4.1.1).","d":"Správně. Oddíl 4.1.1 uvádí relační databáze pro strukturovaná data, například testovací případy, a vektorové databáze pro sémantické vyhledávání pomocí embeddingů."},"obecne":"Relační databáze: strukturovaná data a přesné dotazy. Vektorová databáze: embeddingy a vyhledávání podle významu."},"kap":{"c":"4.1.1","nazev":"4.1.1 Architektonické komponenty a koncepty","href":"kapitola-4/vyklad.html#oddil-4-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.1-04","n":null,"lo":"GenAI-4.1.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A bank plans to build an LLM-powered test tool. Its compliance department does not allow requirement specifications to leave the bank's own infrastructure.<\/p><p>Which of the following options for the LLM component is consistent with this constraint and with the architecture described in the syllabus?<\/p>","m":["Use a custom in-house model operated within the bank's infrastructure.","Use a third-party LLM accessed via API, because back-end authentication prevents the specifications from leaving the bank.","Rely on post-processing to remove sensitive content from the LLM's responses before they are displayed.","Move prompt preparation to the front-end, so that the specifications never reach the back-end."],"vys":{"a":"Correct. Section 4.1.1 states that the LLM may be hosted as a third-party service accessed via API or as a custom in-house model. An in-house model keeps the prompts, including specifications, inside the bank.","b":"Incorrect. Authentication controls access to the tool. It does not stop data in the prompt from being sent to an external provider (4.1.1).","c":"Incorrect. Post-processing works on the response. By then the specifications would already have been sent to the LLM in the prompt (4.1.1).","d":"Incorrect. Prompt preparation is a back-end function, and the location of prompt preparation does not change where the LLM is hosted. The prompt would still go to the LLM (4.1.1)."},"obecne":"The LLM component can be a third-party service via API or an in-house model. The choice affects where prompt data is processed."},"cz":{"q":"<p>Banka plánuje postavit testovací nástroj na LLM. Oddělení compliance nedovoluje, aby specifikace požadavků opustily vlastní infrastrukturu banky.<\/p><p>Která z následujících možností pro komponentu LLM odpovídá tomuto omezení i architektuře popsané v sylabu?<\/p>","m":["Použít vlastní model provozovaný v infrastruktuře banky.","Použít LLM třetí strany přes API, protože autentizace v back-endu zabrání, aby specifikace banku opustily.","Spolehnout se na následné zpracování, které z odpovědí LLM před zobrazením odstraní citlivý obsah.","Přesunout přípravu promptu do front-endu, aby se specifikace k back-endu vůbec nedostaly."],"vys":{"a":"Správně. Podle 4.1.1 může LLM běžet jako služba třetí strany přes API nebo jako vlastní model. Vlastní model udrží prompty včetně specifikací uvnitř banky.","b":"Špatně. Autentizace řídí přístup k nástroji. Nezabrání tomu, aby data v promptu odešla k externímu poskytovateli (4.1.1).","c":"Špatně. Následné zpracování pracuje s odpovědí. Specifikace by v té chvíli už byly odeslané modelu v promptu (4.1.1).","d":"Špatně. Příprava promptu je funkce back-endu a její umístění nemění, kde běží LLM. Prompt by k LLM odešel stejně (4.1.1)."},"obecne":"Komponenta LLM může být služba třetí strany přes API nebo vlastní model. Volba určuje, kde se data z promptu zpracovávají."},"kap":{"c":"4.1.1","nazev":"4.1.1 Architektonické komponenty a koncepty","href":"kapitola-4/vyklad.html#oddil-4-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.1-05","n":null,"lo":"GenAI-4.1.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following statements BEST describes the difference between a traditional AI chatbot and an LLM-powered test tool?<\/p>","m":["An AI chatbot always includes a vector database in its back-end, whereas an LLM-powered test tool uses only the knowledge of the LLM.","An LLM-powered test tool is designed to support testing by processing test-related queries, analyzing requirements, generating test cases and evaluating outputs, whereas an AI chatbot focuses primarily on conversational interaction.","An LLM-powered test tool cannot use third-party LLMs, whereas an AI chatbot always does.","An AI chatbot uses an LLM, whereas an LLM-powered test tool relies on a rule-based engine to guarantee consistent results."],"vys":{"a":"Incorrect. The syllabus mentions vector databases as a data source of the LLM-powered test infrastructure back-end, not as a mandatory part of chatbots (4.1.1).","b":"Correct. This matches the definition in 4.1.1: the chatbot focuses on conversation, while the test tool supports test activities such as requirements analysis, test case generation and output evaluation.","c":"Incorrect. Section 4.1.1 explicitly allows the LLM of a test tool to be a third-party service accessed via API.","d":"Incorrect. Both use an LLM. The syllabus contrasts LLM-powered infrastructure with rule-based chatbots, not the other way round (4.1.1)."},"obecne":"See also 1.2.2: chatbots offer conversational interaction, LLM-powered applications integrate LLMs via APIs for well-defined testing tasks."},"cz":{"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje rozdíl mezi tradičním AI chatbotem a testovacím nástrojem postaveným na LLM?<\/p>","m":["AI chatbot má v back-endu vždy vektorovou databázi, kdežto testovací nástroj na LLM používá jen znalosti modelu.","Testovací nástroj na LLM je navržený na podporu testování: zpracovává testovací dotazy, analyzuje požadavky, generuje testovací případy a vyhodnocuje výstupy. AI chatbot se soustředí hlavně na konverzaci.","Testovací nástroj na LLM nemůže používat LLM třetích stran, kdežto AI chatbot je používá vždy.","AI chatbot používá LLM, kdežto testovací nástroj na LLM se kvůli konzistentním výsledkům opírá o systém pravidel."],"vys":{"a":"Špatně. Vektorovou databázi sylabus uvádí jako zdroj dat back-endu infrastruktury testování s LLM, ne jako povinnou součást chatbotu (4.1.1).","b":"Správně. Odpovídá to definici v 4.1.1: chatbot se soustředí na konverzaci, testovací nástroj podporuje testovací činnosti, jako je analýza požadavků, generování testovacích případů a vyhodnocení výstupů.","c":"Špatně. Oddíl 4.1.1 výslovně připouští, že LLM testovacího nástroje je služba třetí strany přes API.","d":"Špatně. Oba používají LLM. Sylabus staví infrastrukturu s LLM do protikladu k chatbotům založeným na pravidlech, ne naopak (4.1.1)."},"obecne":"Viz také 1.2.2: chatboty nabízejí konverzaci, aplikace na LLM zapojují model přes API do jasně definovaných testovacích úloh."},"kap":{"c":"4.1.1","nazev":"4.1.1 Architektonické komponenty a koncepty","href":"kapitola-4/vyklad.html#oddil-4-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.2-01","n":null,"lo":"GenAI-4.1.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following BEST describes what a RAG system does when a tester submits a query at runtime?<\/p>","m":["It splits the project documents into chunks and encodes each chunk into an embedding.","It replaces the tester's query with the retrieved chunks, so that the LLM answers only from the documents and ignores the query.","It encodes the query, retrieves the chunks that are most semantically similar to it, and passes them to the LLM as context for generating the response.","It updates the weights of the LLM with the retrieved chunks so that the model remembers them for future queries."],"vys":{"a":"Incorrect. Chunking and encoding the documents belong to preprocessing, which takes place before queries are processed (4.1.2).","b":"Incorrect. The retrieved chunks are added as context. The query remains part of the prompt and the LLM combines its existing knowledge with the new data (4.1.2).","c":"Correct. Section 4.1.2 describes the user prompt processing phase as retrieval based on semantic similarity followed by generation, in which the retrieved information is fed to the LLM.","d":"Incorrect. RAG does not change model weights. Updating weights through further training is fine-tuning (4.1.2, 4.2.1)."},"obecne":"Two phases of RAG: preprocessing (chunk, clean, embed, store) and user prompt processing (retrieval, generation)."},"cz":{"q":"<p>Co z následujícího NEJLÉPE popisuje, co systém RAG udělá, když tester za běhu zadá dotaz?<\/p>","m":["Rozdělí dokumenty projektu na části a každou část převede na embedding.","Nahradí dotaz testera vyhledanými částmi, takže LLM odpovídá jen z dokumentů a dotaz ignoruje.","Zakóduje dotaz, vyhledá části, které jsou mu sémanticky nejpodobnější, a předá je LLM jako kontext pro vytvoření odpovědi.","Aktualizuje váhy LLM podle vyhledaných částí, aby si je model zapamatoval pro další dotazy."],"vys":{"a":"Špatně. Rozdělení a převod dokumentů patří do předzpracování, které proběhne před zpracováním dotazů (4.1.2).","b":"Špatně. Vyhledané části se přidávají jako kontext. Dotaz zůstává součástí promptu a LLM kombinuje své znalosti s novými daty (4.1.2).","c":"Správně. Oddíl 4.1.2 popisuje zpracování promptu jako vyhledání podle sémantické podobnosti a následné generování, při kterém LLM dostane vyhledané informace.","d":"Špatně. RAG váhy modelu nemění. Úprava vah dalším tréninkem je fine-tuning (4.1.2, 4.2.1)."},"obecne":"Dvě fáze RAG: předzpracování (rozdělit, vyčistit, převést na embeddingy, uložit) a zpracování dotazu (vyhledání, generování)."},"kap":{"c":"4.1.2","nazev":"4.1.2 Retrieval-Augmented Generation (RAG)","href":"kapitola-4/vyklad.html#oddil-4-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.2-02","n":null,"lo":"GenAI-4.1.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A team prepares its test basis documents for a RAG system. Consider the following preprocessing steps:<\/p><ol><li>Store the embeddings in a vector database<\/li><li>Split the documents into chunks<\/li><li>Encode each chunk into an embedding<\/li><li>Clean and process each chunk<\/li><\/ol><p>Which of the following represents the correct order?<\/p>","m":["2 – 3 – 4 – 1","4 – 2 – 1 – 3","2 – 4 – 1 – 3","2 – 4 – 3 – 1"],"vys":{"a":"Incorrect. Each chunk is cleaned and processed before it is encoded into an embedding (4.1.2).","b":"Incorrect. Cleaning is done on chunks, so splitting comes first. Storing must also follow encoding (4.1.2).","c":"Incorrect. Embeddings can only be stored after they have been created (4.1.2).","d":"Correct. According to 4.1.2, documents are broken into chunks, each chunk is cleaned and processed, encoded into an embedding, and the embeddings are stored in a vector database."},"obecne":"Preprocessing order: chunk, clean and process, embed, store."},"cz":{"q":"<p>Tým připravuje dokumenty testovací báze pro systém RAG. Uvažujte tyto kroky předzpracování:<\/p><ol><li>Uložit embeddingy do vektorové databáze<\/li><li>Rozdělit dokumenty na části<\/li><li>Převést každou část na embedding<\/li><li>Vyčistit a zpracovat každou část<\/li><\/ol><p>Které pořadí je správné?<\/p>","m":["2 – 3 – 4 – 1","4 – 2 – 1 – 3","2 – 4 – 1 – 3","2 – 4 – 3 – 1"],"vys":{"a":"Špatně. Každá část se vyčistí a zpracuje dřív, než se převede na embedding (4.1.2).","b":"Špatně. Čistí se jednotlivé části, takže rozdělení je první. Uložení musí následovat až po převodu (4.1.2).","c":"Špatně. Embeddingy lze uložit až poté, co vzniknou (4.1.2).","d":"Správně. Podle 4.1.2 se dokumenty rozdělí na části, každá část se vyčistí a zpracuje, převede na embedding a embeddingy se uloží do vektorové databáze."},"obecne":"Pořadí předzpracování: rozdělit, vyčistit a zpracovat, převést na embedding, uložit."},"kap":{"c":"4.1.2","nazev":"4.1.2 Retrieval-Augmented Generation (RAG)","href":"kapitola-4/vyklad.html#oddil-4-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.2-03","n":null,"lo":"GenAI-4.1.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>An automotive supplier uses an LLM to derive test conditions for an electronic control unit. The requirements are updated every week, and the generated test conditions often contain limit values from older requirement versions.<\/p><p>How would introducing RAG MOST likely improve the results?<\/p>","m":["RAG retrieves relevant chunks of the current requirements at query time and provides them to the LLM as context, so that the test conditions are grounded in the latest specification.","RAG replaces the model's pre-existing knowledge with the documents, which guarantees that the output contains no hallucinations.","RAG retrains the LLM every week on the updated requirements, so that the new limit values become part of the model's parameters.","RAG lowers the temperature of the LLM, so that the generated limit values become deterministic."],"vys":{"a":"Correct. Section 4.1.2 states that RAG gives LLM-powered test infrastructure access to enterprise data sources in real time, ensuring that test analysis and test design are aligned with the latest specifications and requirements.","b":"Incorrect. The LLM combines its existing knowledge with the retrieved data (4.1.2). RAG increases accuracy and relevance but does not guarantee the absence of hallucinations.","c":"Incorrect. Retraining the model describes fine-tuning. RAG supplies retrieved data during inference without changing the model (4.1.2, 4.2.1).","d":"Incorrect. Temperature is a mitigation for non-deterministic behaviour (3.1.4). It does not provide current requirement values."},"obecne":"RAG grounds the response in current data retrieved at runtime. It reduces, but does not eliminate, the risk of incorrect output."},"cz":{"q":"<p>Dodavatel pro automotive používá LLM k odvození testovacích podmínek pro řídicí jednotku. Požadavky se mění každý týden a vygenerované testovací podmínky často obsahují mezní hodnoty ze starších verzí požadavků.<\/p><p>Jak by zavedení RAG NEJSPÍŠ zlepšilo výsledky?<\/p>","m":["RAG při dotazu vyhledá relevantní části aktuálních požadavků a předá je LLM jako kontext, takže testovací podmínky vycházejí z nejnovější specifikace.","RAG nahradí dosavadní znalosti modelu dokumenty, což zaručí, že výstup nebude obsahovat halucinace.","RAG každý týden znovu natrénuje LLM na aktualizovaných požadavcích, takže nové mezní hodnoty se stanou součástí parametrů modelu.","RAG sníží teplotu LLM, takže vygenerované mezní hodnoty budou deterministické."],"vys":{"a":"Správně. Podle 4.1.2 dává RAG infrastruktuře testování přístup k firemním zdrojům dat v reálném čase, takže testovací analýza a návrh testů odpovídají nejnovějším specifikacím a požadavkům.","b":"Špatně. LLM kombinuje své znalosti s vyhledanými daty (4.1.2). RAG zvyšuje přesnost a relevanci, ale nepřítomnost halucinací nezaručuje.","c":"Špatně. Opakovaný trénink popisuje fine-tuning. RAG dodává vyhledaná data při inferenci a model nemění (4.1.2, 4.2.1).","d":"Špatně. Teplota je opatření proti nedeterministickému chování (3.1.4). Aktuální hodnoty z požadavků nedodá."},"obecne":"RAG podkládá odpověď aktuálními daty vyhledanými za běhu. Riziko chybného výstupu snižuje, ale neodstraňuje."},"kap":{"c":"4.1.2","nazev":"4.1.2 Retrieval-Augmented Generation (RAG)","href":"kapitola-4/vyklad.html#oddil-4-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.2-04","n":null,"lo":"GenAI-4.1.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A tester asks a RAG-enabled test tool: 'What should happen when someone tries many passwords in a row?' The relevant requirement states: 'After three failed login attempts, the account is locked for 15 minutes.' The tool retrieves this requirement.<\/p><p>Which of the following statements BEST explains why the requirement was retrieved?<\/p>","m":["The requirement was retrieved because it was part of the data the LLM was originally trained on.","The embeddings of the query and of the requirement chunk are close to each other, because the two texts have a similar meaning.","The LLM first generates an answer, and the answer is then compared with the requirements stored in the relational database.","The retrieval step searches only for chunks that contain the exact keywords of the query."],"vys":{"a":"Incorrect. RAG retrieves information from the vector database created during preprocessing, not from the model's training data (4.1.2).","b":"Correct. Section 4.1.2 states that retrieval is typically based on semantic similarity between the embeddings of the prompt and those of the chunks. Texts with similar meaning have embeddings that are close together (1.1).","c":"Incorrect. Retrieval happens before generation, and it uses the vector database, not the relational database (4.1.2).","d":"Incorrect. The query and the requirement share almost no keywords. RAG retrieval is based on semantic similarity, not on exact keyword matches (4.1.2)."},"obecne":"Semantic retrieval finds related content even when the wording differs."},"cz":{"q":"<p>Tester se zeptá testovacího nástroje s RAG: „Co se má stát, když někdo zkouší mnoho hesel za sebou?“ Relevantní požadavek zní: „Po třech neúspěšných pokusech o přihlášení se účet na 15 minut zablokuje.“ Nástroj tento požadavek vyhledá.<\/p><p>Které z následujících tvrzení NEJLÉPE vysvětluje, proč byl požadavek nalezen?<\/p>","m":["Požadavek byl nalezen, protože byl součástí dat, na kterých byl LLM původně natrénován.","Embeddingy dotazu a části s požadavkem leží blízko sebe, protože oba texty mají podobný význam.","LLM nejdřív vygeneruje odpověď a ta se pak porovná s požadavky uloženými v relační databázi.","Krok vyhledání hledá jen části, které obsahují přesně stejná klíčová slova jako dotaz."],"vys":{"a":"Špatně. RAG vyhledává ve vektorové databázi vytvořené při předzpracování, ne v trénovacích datech modelu (4.1.2).","b":"Správně. Podle 4.1.2 je vyhledání obvykle založené na sémantické podobnosti mezi embeddingy promptu a embeddingy částí. Texty s podobným významem mají blízké embeddingy (1.1).","c":"Špatně. Vyhledání probíhá před generováním a používá vektorovou databázi, ne relační (4.1.2).","d":"Špatně. Dotaz a požadavek nemají skoro žádná společná slova. Vyhledávání v RAG je založené na sémantické podobnosti, ne na shodě klíčových slov (4.1.2)."},"obecne":"Sémantické vyhledávání najde související obsah, i když je formulovaný jinými slovy."},"kap":{"c":"4.1.2","nazev":"4.1.2 Retrieval-Augmented Generation (RAG)","href":"kapitola-4/vyklad.html#oddil-4-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.2-05","n":null,"lo":"GenAI-4.1.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following statements BEST describes a grounded response in the context of RAG?<\/p>","m":["A response that is guaranteed to be correct because all of its content comes from the vector database.","A response that the LLM generates only from its training data, without any additional context.","A response rooted in relevant, accurate and contextually appropriate information gathered during retrieval and combined with the model's pre-existing knowledge.","A response that always contains links to public internet sources found by a search engine."],"vys":{"a":"Incorrect. The LLM combines retrieved data with its own knowledge, and LLM risks such as hallucinations remain (3.1, 4.1.2). Correctness is not guaranteed.","b":"Incorrect. This describes an LLM without RAG. A grounded response is enriched with data retrieved for the prompt (4.1.2).","c":"Correct. Section 4.1.2 describes a relevant response as rooted in information gathered during retrieval, not only based on the model's pre-existing training.","d":"Incorrect. RAG in the syllabus retrieves from prepared data sources such as enterprise documentation in a vector database, not necessarily from the internet (4.1.2)."},"obecne":"Grounding means the answer is supported by retrieved data. It improves accuracy and relevance but does not replace review."},"cz":{"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje podloženou odpověď (grounded response) v kontextu RAG?<\/p>","m":["Odpověď, která je zaručeně správná, protože veškerý její obsah pochází z vektorové databáze.","Odpověď, kterou LLM vytvoří jen ze svých trénovacích dat bez dalšího kontextu.","Odpověď, která vychází z relevantních, přesných a kontextově vhodných informací získaných při vyhledávání a spojených s dosavadními znalostmi modelu.","Odpověď, která vždy obsahuje odkazy na veřejné zdroje na internetu nalezené vyhledávačem."],"vys":{"a":"Špatně. LLM spojuje vyhledaná data se svými znalostmi a rizika LLM, jako jsou halucinace, trvají (3.1, 4.1.2). Správnost zaručená není.","b":"Špatně. To popisuje LLM bez RAG. Podložená odpověď je obohacená o data vyhledaná k promptu (4.1.2).","c":"Správně. Oddíl 4.1.2 popisuje relevantní odpověď jako zakotvenou v informacích získaných při vyhledávání, ne jen v tom, co se model naučil při trénování.","d":"Špatně. RAG v sylabu vyhledává v připravených zdrojích, například ve firemní dokumentaci ve vektorové databázi, nemusí jít o internet (4.1.2)."},"obecne":"Podložená odpověď je opřená o vyhledaná data. Zvyšuje přesnost a relevanci, ale kontrolu nenahrazuje."},"kap":{"c":"4.1.2","nazev":"4.1.2 Retrieval-Augmented Generation (RAG)","href":"kapitola-4/vyklad.html#oddil-4-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.3-01","n":null,"lo":"GenAI-4.1.3","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which capability MOST clearly distinguishes an LLM-powered agent from a traditional AI chatbot?<\/p>","m":["Understanding and generating natural language.","Following a system prompt that defines its tone and boundaries.","Processing longer prompts because of a larger context window.","Invoking a predefined set of functions (tools) to interact with and manipulate external systems."],"vys":{"a":"Incorrect. Both chatbots and agents rely on LLMs for natural language understanding and generation (4.1.3).","b":"Incorrect. System prompts are used in chatbots as well (2.1). They do not let the application act on external systems.","c":"Incorrect. The size of the context window depends on the model, not on whether it is used in an agent or a chatbot.","d":"Correct. Section 4.1.3 states that, unlike chatbots focused on question-response interaction, agents can act by invoking predefined functions called tools."},"obecne":"Agents act through tools. Chatbots answer questions."},"cz":{"q":"<p>Která schopnost NEJZŘETELNĚJI odlišuje agenta postaveného na LLM od tradičního AI chatbotu?<\/p>","m":["Porozumění přirozenému jazyku a jeho generování.","Dodržování systémového promptu, který určuje tón a hranice odpovědí.","Zpracování delších promptů díky většímu kontextovému oknu.","Volání předem definované sady funkcí (nástrojů), pomocí kterých pracuje s externími systémy a mění je."],"vys":{"a":"Špatně. Chatboty i agenti využívají LLM k porozumění jazyku a jeho generování (4.1.3).","b":"Špatně. Systémové prompty používají i chatboty (2.1). Nedávají aplikaci možnost jednat v externích systémech.","c":"Špatně. Velikost kontextového okna závisí na modelu, ne na tom, zda je použit v agentovi nebo chatbotu.","d":"Správně. Podle 4.1.3 agenti na rozdíl od chatbotů, kteří se soustředí na otázky a odpovědi, umí jednat voláním předem definovaných funkcí, nástrojů."},"obecne":"Agent jedná přes nástroje. Chatbot odpovídá na otázky."},"kap":{"c":"4.1.3","nazev":"4.1.3 Agenti postavení na LLM v automatizaci testovacích procesů","href":"kapitola-4/vyklad.html#oddil-4-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.3-02","n":null,"lo":"GenAI-4.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>An insurance company introduces an LLM-powered agent that analyses failed regression tests of its claims-handling system and creates defect reports in the defect tracker. Developers complain that some reports describe failures that do not exist.<\/p><p>Which action is MOST consistent with the syllabus?<\/p>","m":["Run the agent semi-autonomously, so that a tester reviews proposed defect reports before they are created, and add automated checks of the agent's results.","Switch the agent to fully autonomous operation with reinforcement learning, so that it learns to avoid false reports without human involvement.","Keep the agent as it is, because agents that use tools do not suffer from hallucinations.","Replace the defect tracker integration with a larger context window, so that the agent can see all test logs at once."],"vys":{"a":"Correct. Section 4.1.3 recommends mitigating agent risks by automated verification of the agents' results or by using semi-autonomous agents for critical tasks.","b":"Incorrect. Autonomous operation reduces human oversight, which is the opposite of what the syllabus recommends for critical tasks (4.1.3).","c":"Incorrect. Agents suffer from the same problems as LLMs, including hallucinations, reasoning errors and biases (4.1.3, 3.1).","d":"Incorrect. A larger context window does not address the risk of incorrect results. The syllabus names verification and human oversight as mitigations (4.1.3)."},"obecne":"Agent risks are mitigated by automated verification and by semi-autonomous operation for critical tasks."},"cz":{"q":"<p>Pojišťovna zavede agenta postaveného na LLM, který analyzuje selhané regresní testy systému pro likvidaci pojistných událostí a zakládá reporty o defektech v nástroji pro správu defektů. Vývojáři si stěžují, že některé reporty popisují selhání, která neexistují.<\/p><p>Který krok NEJLÉPE odpovídá sylabu?<\/p>","m":["Provozovat agenta poloautonomně, aby tester navržené reporty před založením zkontroloval, a doplnit automatické kontroly výsledků agenta.","Přepnout agenta na plně autonomní provoz s učením posilováním, aby se falešným reportům naučil vyhnout bez účasti člověka.","Ponechat agenta beze změny, protože agenti, kteří používají nástroje, nehalucinují.","Nahradit napojení na nástroj pro správu defektů větším kontextovým oknem, aby agent viděl všechny logy najednou."],"vys":{"a":"Správně. Oddíl 4.1.3 doporučuje rizika agentů zmírnit automatickou verifikací jejich výsledků nebo použitím poloautonomních agentů pro kritické úlohy.","b":"Špatně. Autonomní provoz omezuje lidský dohled, tedy opak toho, co sylabus doporučuje u kritických úloh (4.1.3).","c":"Špatně. Agenti mají stejné problémy jako LLM: halucinace, chyby v uvažování a zkreslení (4.1.3, 3.1).","d":"Špatně. Větší kontextové okno riziko chybných výsledků neřeší. Sylabus jako opatření uvádí verifikaci a lidský dohled (4.1.3)."},"obecne":"Rizika agentů se zmírňují automatickou verifikací a poloautonomním provozem u kritických úloh."},"kap":{"c":"4.1.3","nazev":"4.1.3 Agenti postavení na LLM v automatizaci testovacích procesů","href":"kapitola-4/vyklad.html#oddil-4-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.3-03","n":null,"lo":"GenAI-4.1.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A test organization sets up one agent that analyses requirements, a second agent that generates automated test scripts, and a third agent that evaluates test results and writes the test report. A coordinating component passes the outputs from one agent to the next.<\/p><p>What does the syllabus call this coordinated effort among multiple agents?<\/p>","m":["Retrieval-augmented generation","Orchestration","Prompt chaining","Fine-tuning"],"vys":{"a":"Incorrect. RAG adds retrieved data to the prompt (4.1.2). It does not describe collaboration of agents.","b":"Correct. Section 4.1.3 describes multi-agent architectures in which agents with specialized roles communicate and coordinate. This coordinated effort is called orchestration.","c":"Incorrect. Prompt chaining uses the output of one prompt as the input of another (2.1.2). It describes a prompting technique, not coordination of several specialized agents.","d":"Incorrect. Fine-tuning adapts a model by further training on a targeted dataset (4.2.1)."},"obecne":"Multi-agent architecture with specialized roles and coordination is orchestration."},"cz":{"q":"<p>Testovací organizace nastaví jednoho agenta, který analyzuje požadavky, druhého, který generuje automatizované testovací skripty, a třetího, který vyhodnocuje výsledky testů a píše report. Koordinační komponenta předává výstupy od jednoho agenta k dalšímu.<\/p><p>Jak sylabus nazývá tuto koordinovanou spolupráci více agentů?<\/p>","m":["Retrieval-augmented generation","Orchestrace (orchestration)","Řetězení promptů (prompt chaining)","Fine-tuning"],"vys":{"a":"Špatně. RAG přidává do promptu vyhledaná data (4.1.2). Spolupráci agentů nepopisuje.","b":"Správně. Oddíl 4.1.3 popisuje multiagentní architektury, kde agenti se specializovanými rolemi komunikují a koordinují se. Této spolupráci se říká orchestrace.","c":"Špatně. Řetězení promptů používá výstup jednoho promptu jako vstup dalšího (2.1.2). Je to technika promptování, ne koordinace specializovaných agentů.","d":"Špatně. Fine-tuning přizpůsobuje model dalším tréninkem na cílené datové sadě (4.2.1)."},"obecne":"Multiagentní architektura se specializovanými rolemi a jejich koordinací je orchestrace."},"kap":{"c":"4.1.3","nazev":"4.1.3 Agenti postavení na LLM v automatizaci testovacích procesů","href":"kapitola-4/vyklad.html#oddil-4-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.3-04","n":null,"lo":"GenAI-4.1.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following statements BEST describes how AI assistants based on LLM-powered agents change test automation, according to the syllabus?<\/p>","m":["They are limited to test execution, because test analysis and test design cannot be supported by agents.","They move test automation from goal-driven agents back to precisely scripted test execution, which improves repeatability.","They shift test automation from script-based execution to goal-driven, agent-based automation that semi-autonomously supports activities from test analysis to test reporting.","They make testers unnecessary, because they perform all test activities fully autonomously."],"vys":{"a":"Incorrect. The syllabus lists test analysis, test design, test implementation, test execution and test reporting (4.1.3).","b":"Incorrect. The direction is reversed. The syllabus describes a shift from script-based execution to goal-driven, agent-based automation (4.1.3).","c":"Correct. Section 4.1.3 states that assistants transform user stories or requirements into test artefacts across the test lifecycle and shift test automation from script-based execution to goal-driven, agent-based test automation.","d":"Incorrect. The syllabus describes these assistants as working in a semi-autonomous manner and stresses verification and human oversight (4.1.3)."},"obecne":"Benefits named in the syllabus: less manual effort, shorter feedback cycles, end-to-end automation workflow."},"cz":{"q":"<p>Které z následujících tvrzení podle sylabu NEJLÉPE popisuje, jak AI asistenti založení na agentech s LLM mění automatizaci testování?<\/p>","m":["Omezují se na provedení testů, protože testovací analýzu a návrh testů agenti podporovat nemohou.","Vracejí automatizaci od agentů řízených cílem zpět k přesně naskriptovanému provádění testů, což zlepšuje opakovatelnost.","Posouvají automatizaci od provádění skriptů k automatizaci řízené cílem a postavené na agentech, která poloautonomně podporuje činnosti od testovací analýzy po reportování.","Testery už nepotřebujeme, protože asistenti provádějí všechny testovací činnosti plně autonomně."],"vys":{"a":"Špatně. Sylabus vyjmenovává testovací analýzu, návrh testů, implementaci testů, provedení testů i reportování (4.1.3).","b":"Špatně. Směr je opačný. Sylabus popisuje posun od skriptů k automatizaci řízené cílem a postavené na agentech (4.1.3).","c":"Správně. Podle 4.1.3 asistenti převádějí uživatelské scénáře nebo požadavky na testware v celém procesu a posouvají automatizaci od provádění skriptů k automatizaci řízené cílem a postavené na agentech.","d":"Špatně. Sylabus popisuje tyto asistenty jako poloautonomní a zdůrazňuje verifikaci a lidský dohled (4.1.3)."},"obecne":"Přínosy podle sylabu: méně ruční práce, kratší zpětná vazba, souvislý automatizovaný tok práce."},"kap":{"c":"4.1.3","nazev":"4.1.3 Agenti postavení na LLM v automatizaci testovacích procesů","href":"kapitola-4/vyklad.html#oddil-4-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.3-05","n":null,"lo":"GenAI-4.1.3","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which of the following statements correctly contrasts autonomous and semi-autonomous LLM-powered agents?<\/p>","m":["Autonomous agents are always part of a multi-agent architecture, whereas semi-autonomous agents always work alone.","Autonomous agents do not produce hallucinations because their adaptive feedback loops correct every error, whereas semi-autonomous agents need human review for this reason.","Semi-autonomous agents cannot invoke tools and therefore only provide recommendations, whereas autonomous agents can act on external systems.","Autonomous agents operate independently with minimal human intervention, using predefined rules, reinforcement learning and adaptive feedback loops, whereas semi-autonomous agents work with periodic human oversight to ensure the output meets user-defined goals."],"vys":{"a":"Incorrect. The degree of autonomy and the multi-agent architecture are independent concepts in 4.1.3. Both types can work alone or together with other agents.","b":"Incorrect. All LLM-powered agents can produce hallucinations, reasoning errors and biases (4.1.3).","c":"Incorrect. Both types are agents and can invoke tools. The difference lies in the level of human oversight (4.1.3).","d":"Correct. This matches the two degrees of autonomy described in section 4.1.3."},"obecne":"The degree of autonomy is defined by how much a human is involved."},"cz":{"q":"<p>Které z následujících tvrzení správně porovnává autonomní a poloautonomní agenty postavené na LLM?<\/p>","m":["Autonomní agenti jsou vždy součástí multiagentní architektury, kdežto poloautonomní agenti pracují vždy sami.","Autonomní agenti nehalucinují, protože adaptivní zpětnovazební smyčky opraví každou chybu. Poloautonomní agenti kvůli tomu potřebují lidskou kontrolu.","Poloautonomní agenti nemohou volat nástroje, a proto jen doporučují. Autonomní agenti umí jednat v externích systémech.","Autonomní agenti pracují samostatně s minimálním zásahem člověka a využívají předem daná pravidla, učení posilováním a adaptivní zpětnovazební smyčky. Poloautonomní agenti pracují s pravidelným lidským dohledem, aby výstup odpovídal cílům uživatele."],"vys":{"a":"Špatně. Úroveň autonomie a multiagentní architektura jsou v 4.1.3 nezávislé pojmy. Oba typy mohou pracovat samostatně i s dalšími agenty.","b":"Špatně. Všichni agenti postavení na LLM mohou halucinovat, chybovat v uvažování a být zkreslení (4.1.3).","c":"Špatně. Oba typy jsou agenti a mohou volat nástroje. Liší se mírou lidského dohledu (4.1.3).","d":"Správně. Odpovídá to dvěma úrovním autonomie popsaným v oddílu 4.1.3."},"obecne":"Úroveň autonomie určuje míra zapojení člověka."},"kap":{"c":"4.1.3","nazev":"4.1.3 Agenti postavení na LLM v automatizaci testovacích procesů","href":"kapitola-4/vyklad.html#oddil-4-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.1-01","n":null,"lo":"GenAI-4.2.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>In which of the following situations is fine-tuning a language model MOST appropriate?<\/p>","m":["An organization wants a model to generate test cases from user stories consistently in its own output format and terminology, and it has a large set of user stories with approved test cases.","The answers must always reflect requirement documents that change every day.","Testers want each answer to cite the exact passage of the source document it was based on.","A tester needs a one-off summary of a single defect report."],"vys":{"a":"Correct. Section 4.2.1 gives this example: training the model on the organization's user stories and test cases aligns it with the organization's test process and terminology.","b":"Incorrect. Frequently changing facts are better supplied at runtime through RAG (4.1.2). A fine-tuned model would quickly become outdated.","c":"Incorrect. Linking answers to source passages is a strength of RAG, where retrieved chunks are known (4.1.2). Knowledge learned through fine-tuning cannot be traced to a specific passage.","d":"Incorrect. A one-off task is handled by a suitable prompt (chapter 2). Fine-tuning requires a dataset and significant effort (4.2.1)."},"obecne":"Fine-tuning suits a narrow, recurring task with a stable output format and domain vocabulary and with good training data."},"cz":{"q":"<p>Ve které z následujících situací je fine-tuning jazykového modelu NEJVHODNĚJŠÍ?<\/p>","m":["Organizace chce, aby model generoval testovací případy z uživatelských scénářů vždy ve vlastním výstupním formátu a terminologii, a má velkou sadu scénářů se schválenými testovacími případy.","Odpovědi musí vždy odpovídat dokumentům s požadavky, které se mění každý den.","Testeři chtějí, aby každá odpověď citovala přesnou pasáž zdrojového dokumentu, ze které vychází.","Tester potřebuje jednorázové shrnutí jednoho reportu o defektu."],"vys":{"a":"Správně. Oddíl 4.2.1 uvádí právě tento příklad: trénink na uživatelských scénářích a testovacích případech organizace sladí model s jejím testovacím procesem a terminologií.","b":"Špatně. Často se měnící fakta je lepší dodávat za běhu přes RAG (4.1.2). Doladěný model by rychle zastaral.","c":"Špatně. Navázání odpovědi na zdrojovou pasáž je silná stránka RAG, kde jsou nalezené části známé (4.1.2). Znalost získanou doladěním nelze dohledat ke konkrétní pasáži.","d":"Špatně. Jednorázovou úlohu vyřeší vhodný prompt (kapitola 2). Fine-tuning vyžaduje datovou sadu a značné úsilí (4.2.1)."},"obecne":"Fine-tuning se hodí na úzkou opakovanou úlohu se stálým formátem a doménovým slovníkem, pokud jsou k dispozici kvalitní trénovací data."},"kap":{"c":"4.2.1","nazev":"4.2.1 Fine-tuning LLM pro testovací úlohy","href":"kapitola-4/vyklad.html#oddil-4-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.1-02","n":null,"lo":"GenAI-4.2.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following statements correctly describes a difference between fine-tuning and RAG?<\/p>","m":["Both fine-tuning and RAG modify the weights of the model, but RAG does so only for the retrieved documents.","Fine-tuning updates the model's parameters through further training on a targeted dataset, whereas RAG supplies retrieved data as context at inference time without changing the model.","Fine-tuning changes only the system prompt of the model, whereas RAG retrains the model on enterprise data.","RAG trains the embedding layer of the LLM on enterprise documents, whereas fine-tuning does not involve any training."],"vys":{"a":"Incorrect. RAG does not modify the model's weights. It adds retrieved information to the prompt (4.1.2).","b":"Correct. Fine-tuning involves further training the model on a targeted dataset (4.2.1, Appendix D: updating LLM weights). RAG retrieves relevant chunks at runtime and feeds them to the LLM (4.1.2).","c":"Incorrect. Changing the system prompt is prompt engineering, and RAG does not retrain the model (2.1, 4.1.2).","d":"Incorrect. RAG uses a pre-trained embedding model to encode chunks but does not train the LLM. Fine-tuning is a training process (4.1.2, 4.2.1)."},"obecne":"Fine-tuning changes the model. RAG changes what the model receives in the prompt."},"cz":{"q":"<p>Které z následujících tvrzení správně popisuje rozdíl mezi fine-tuningem a RAG?<\/p>","m":["Fine-tuning i RAG upravují váhy modelu, RAG to ale dělá jen pro vyhledané dokumenty.","Fine-tuning upravuje parametry modelu dalším tréninkem na cílené datové sadě, kdežto RAG dodává vyhledaná data jako kontext při inferenci a model nemění.","Fine-tuning mění jen systémový prompt modelu, kdežto RAG model znovu trénuje na firemních datech.","RAG trénuje vrstvu embeddingů LLM na firemních dokumentech, kdežto fine-tuning žádný trénink nezahrnuje."],"vys":{"a":"Špatně. RAG váhy modelu nemění. Přidává vyhledané informace do promptu (4.1.2).","b":"Správně. Fine-tuning znamená další trénink modelu na cílené datové sadě (4.2.1, Appendix D: úprava vah LLM). RAG za běhu vyhledá relevantní části a předá je LLM (4.1.2).","c":"Špatně. Změna systémového promptu je prompt engineering a RAG model netrénuje (2.1, 4.1.2).","d":"Špatně. RAG používá k převodu částí předtrénovaný model pro embeddingy, ale LLM netrénuje. Fine-tuning je trénink (4.1.2, 4.2.1)."},"obecne":"Fine-tuning mění model. RAG mění to, co model dostane v promptu."},"kap":{"c":"4.2.1","nazev":"4.2.1 Fine-tuning LLM pro testovací úlohy","href":"kapitola-4/vyklad.html#oddil-4-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.1-03","n":null,"lo":"GenAI-4.2.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A team fine-tunes an SLM exclusively on test cases for the payment module of a web shop. On examples from that module, the model produces excellent results. When it is asked to generate test cases for the new loyalty programme module, it produces poor test cases that repeat payment-specific steps.<\/p><p>Which challenge of fine-tuning does this situation illustrate?<\/p>","m":["Opacity","Insufficient computational resources","Overfitting","Prompt injection"],"vys":{"a":"Incorrect. Opacity is the lack of transparency in how the model reaches its outputs (4.2.1). The described problem is the poor performance on new data, not a lack of explanation.","b":"Incorrect. The model was trained successfully and performs well on familiar data. The problem is not a lack of computing power (4.2.1).","c":"Correct. Section 4.2.1 defines overfitting as the model becoming too specialized to the training data, negatively impacting its performance on new, unseen data.","d":"Incorrect. Prompt injection is a manipulative attack (3.2.2), not a challenge of the fine-tuning process."},"obecne":"Good results on training data and poor results on new scenarios are the typical sign of overfitting."},"cz":{"q":"<p>Tým doladí SLM výhradně na testovacích případech platebního modulu e-shopu. Na příkladech z tohoto modulu dává model výborné výsledky. Když má vygenerovat testovací případy pro nový modul věrnostního programu, vytvoří slabé testy, které opakují kroky typické pro platby.<\/p><p>Kterou výzvu fine-tuningu tato situace ilustruje?<\/p>","m":["Neprůhlednost (opacity)","Nedostatečné výpočetní zdroje","Přeučení (overfitting)","Prompt injection"],"vys":{"a":"Špatně. Neprůhlednost znamená, že není vidět, jak model k výstupu dospěl (4.2.1). Popsaný problém je slabý výkon na nových datech, ne chybějící vysvětlení.","b":"Špatně. Model se úspěšně natrénoval a na známých datech funguje dobře. Nejde o nedostatek výpočetního výkonu (4.2.1).","c":"Správně. Oddíl 4.2.1 definuje přeučení jako stav, kdy je model příliš specializovaný na trénovací data a na nových, neviděných datech funguje hůř.","d":"Špatně. Prompt injection je manipulativní útok (3.2.2), ne výzva procesu doladění."},"obecne":"Dobré výsledky na trénovacích datech a slabé na nových scénářích jsou typický znak přeučení."},"kap":{"c":"4.2.1","nazev":"4.2.1 Fine-tuning LLM pro testovací úlohy","href":"kapitola-4/vyklad.html#oddil-4-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.1-04","n":null,"lo":"GenAI-4.2.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A test team wants a language model that classifies incoming defect reports into five fixed categories. The task is narrow and repetitive. The team considers fine-tuning a small language model (SLM) instead of a large one.<\/p><p>Which of the following statements BEST supports this choice?<\/p>","m":["SLMs cannot be fine-tuned, so the team can use them directly without preparing any training data.","Fine-tuning an SLM removes the opacity of the model, so every classification can be fully explained.","SLMs do not require a training dataset, because they learn the categories from the first prompt.","A fine-tuned SLM can achieve high performance on a specific task without the computational overhead required to fine-tune an LLM."],"vys":{"a":"Incorrect. The syllabus explicitly states that SLMs can be fine-tuned (4.2.1).","b":"Incorrect. Opacity is listed as a challenge of fine-tuning in general. Using an SLM does not remove it (4.2.1).","c":"Incorrect. Fine-tuning always involves further training on a targeted dataset, for SLMs as well (4.2.1).","d":"Correct. Section 4.2.1 states that fine-tuning can be applied to SLMs, which are less resource intensive, and that a fine-tuned SLM can achieve higher performance for specific tasks without the overhead of LLMs."},"obecne":"The choice between LLM and SLM depends on the requirements of the task. SLMs offer efficiency for narrow tasks."},"cz":{"q":"<p>Testovací tým chce jazykový model, který bude třídit příchozí reporty o defektech do pěti pevných kategorií. Úloha je úzká a opakovaná. Tým zvažuje, že místo velkého modelu doladí malý jazykový model (SLM).<\/p><p>Které z následujících tvrzení tuto volbu NEJLÉPE podporuje?<\/p>","m":["SLM nelze doladit, takže je tým může použít rovnou bez přípravy trénovacích dat.","Doladění SLM odstraní neprůhlednost modelu, takže každé zařazení půjde plně vysvětlit.","SLM nepotřebují trénovací datovou sadu, protože se kategorie naučí z prvního promptu.","Doladěný SLM může u konkrétní úlohy dosáhnout vysokého výkonu bez výpočetních nároků, které vyžaduje doladění LLM."],"vys":{"a":"Špatně. Sylabus výslovně uvádí, že SLM doladit lze (4.2.1).","b":"Špatně. Neprůhlednost je výzva fine-tuningu obecně. Použití SLM ji neodstraní (4.2.1).","c":"Špatně. Fine-tuning vždy znamená další trénink na cílené datové sadě, i u SLM (4.2.1).","d":"Správně. Podle 4.2.1 lze doladit i SLM, které jsou méně náročné na zdroje, a doladěný SLM může u konkrétních úloh dosáhnout vyššího výkonu bez nákladů spojených s LLM."},"obecne":"Volba mezi LLM a SLM závisí na požadavcích úlohy. SLM jsou efektivní u úzkých úloh."},"kap":{"c":"4.2.1","nazev":"4.2.1 Fine-tuning LLM pro testovací úlohy","href":"kapitola-4/vyklad.html#oddil-4-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.1-05","n":null,"lo":"GenAI-4.2.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following is NOT one of the challenges of fine-tuning a GenAI model for software testing described in the syllabus?<\/p>","m":["Losing the ability to process natural language input after the model has been fine-tuned.","Avoiding biased or inaccurate results by ensuring high-quality, task-specific training datasets.","Addressing the lack of transparency in the model's reasoning, which complicates debugging and validation.","Managing the significant computational resources required for fine-tuning LLMs."],"vys":{"a":"Correct choice. The syllabus does not list this. Fine-tuning adapts the model to a task or domain; it does not remove its basic language capabilities (4.2.1).","b":"Incorrect choice. Biased or inaccurate results caused by poor training data are the first challenge listed in 4.2.1.","c":"Incorrect choice. Opacity is one of the listed challenges (4.2.1).","d":"Incorrect choice. Computational resources for fine-tuning LLMs are one of the listed challenges (4.2.1)."},"obecne":"The four challenges in 4.2.1: biased or inaccurate results, overfitting, opacity, computational resources."},"cz":{"q":"<p>Co z následujícího NENÍ jednou z výzev fine-tuningu modelu generativní AI pro testování, které popisuje sylabus?<\/p>","m":["Ztráta schopnosti zpracovat vstup v přirozeném jazyce poté, co je model doladěn.","Vyhnout se zkresleným nebo nepřesným výsledkům zajištěním kvalitních trénovacích dat zaměřených na úlohu.","Řešit chybějící průhlednost uvažování modelu, která komplikuje ladění a validaci.","Zvládnout značné výpočetní zdroje potřebné k doladění LLM."],"vys":{"a":"Správná volba. Tuto výzvu sylabus neuvádí. Fine-tuning přizpůsobuje model úloze nebo doméně, základní jazykové schopnosti mu nebere (4.2.1).","b":"Nesprávná volba. Zkreslené nebo nepřesné výsledky kvůli špatným datům jsou první výzva v 4.2.1.","c":"Nesprávná volba. Neprůhlednost je jedna z uvedených výzev (4.2.1).","d":"Nesprávná volba. Výpočetní zdroje pro doladění LLM jsou jedna z uvedených výzev (4.2.1)."},"obecne":"Čtyři výzvy v 4.2.1: zkreslené nebo nepřesné výsledky, přeučení, neprůhlednost, výpočetní zdroje."},"kap":{"c":"4.2.1","nazev":"4.2.1 Fine-tuning LLM pro testovací úlohy","href":"kapitola-4/vyklad.html#oddil-4-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.2-01","n":null,"lo":"GenAI-4.2.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>An organization decides to activate the GenAI features of its commercial test management tool to generate test case proposals from requirements.<\/p><p>Which LLMOps consideration is specific to this approach, in addition to data privacy, security and operational cost?<\/p>","m":["Choosing between an LLM-as-a-Service platform and an open-source LLM deployed for a chatbot.","Evaluating the data security and performance assurances offered by the test tool provider, supported by a cost-benefit analysis and risk assessment.","None, because the tool provider is responsible for all LLMOps decisions.","Planning GPU capacity, data storage and staff training for developing and hosting its own model."],"vys":{"a":"Incorrect. This choice is described for the AI chatbot approach (4.2.2).","b":"Correct. Section 4.2.2 states that for test tools with GenAI capabilities, organizations must also evaluate the data security and performance assurances of the provider, and that a thorough cost-benefit analysis and risk assessment is required.","c":"Incorrect. The organization still has to assess the provider and the risks. LLMOps decisions depend on the chosen approach, but they do not disappear (4.2.2).","d":"Incorrect. Planning computational resources, storage and staff training is emphasized for in-house development (4.2.2)."},"obecne":"Each of the three approaches in 4.2.2 has its own emphasis."},"cz":{"q":"<p>Organizace se rozhodne zapnout funkce generativní AI ve svém komerčním nástroji pro správu testů, aby generovaly návrhy testovacích případů z požadavků.<\/p><p>Která úvaha LLMOps je pro tento přístup specifická, vedle ochrany dat, bezpečnosti a provozních nákladů?<\/p>","m":["Vybrat mezi platformou LLM jako služba a open-source LLM nasazeným pro chatbot.","Posoudit záruky poskytovatele testovacího nástroje k bezpečnosti dat a výkonu, podložené analýzou nákladů a přínosů a posouzením rizik.","Žádná, protože za všechna rozhodnutí LLMOps odpovídá poskytovatel nástroje.","Naplánovat kapacitu GPU, úložiště dat a školení lidí pro vývoj a provoz vlastního modelu."],"vys":{"a":"Špatně. Tuto volbu sylabus popisuje u přístupu s AI chatbotem (4.2.2).","b":"Správně. Podle 4.2.2 musí organizace u testovacích nástrojů s GenAI navíc posoudit záruky poskytovatele k bezpečnosti dat a výkonu a provést důkladnou analýzu nákladů a přínosů a posouzení rizik.","c":"Špatně. Organizace musí poskytovatele i rizika posoudit sama. Rozhodnutí LLMOps závisí na přístupu, ale nemizí (4.2.2).","d":"Špatně. Plánování výpočetního výkonu, úložiště a školení sylabus zdůrazňuje u vlastního vývoje (4.2.2)."},"obecne":"Každý ze tří přístupů v 4.2.2 má jiný důraz."},"kap":{"c":"4.2.2","nazev":"4.2.2 LLMOps při nasazení a správě LLM pro testování","href":"kapitola-4/vyklad.html#oddil-4-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.2-02","n":null,"lo":"GenAI-4.2.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A bank decides to develop its own GenAI-based test tool in-house. Which of the following considerations does the syllabus emphasize for this approach?<\/p>","m":["Optimizing only the cost of tokens, because data privacy risks do not apply to in-house tools.","Skipping validation processes, because an internally developed tool is under the bank's full control.","Careful planning of computational resources, data storage and staff training, together with structured processes for validating and maintaining the GenAI-specific developments.","Relying primarily on the vendor's assurances regarding data privacy and model performance."],"vys":{"a":"Incorrect. In-house development emphasizes comprehensive control of data privacy and security risks; these risks still have to be managed (4.2.2).","b":"Incorrect. The syllabus explicitly requires structured processes for validating and maintaining GenAI developments (4.2.2).","c":"Correct. Section 4.2.2 lists resource planning (computational resources, data storage, staff training), structured validation and maintenance processes and the necessary expertise for in-house development.","d":"Incorrect. Vendor assurances are relevant when using external services or tools. In-house development emphasizes the organization's own control (4.2.2)."},"obecne":"In-house development gives the most control, but it requires resources, processes and expertise."},"cz":{"q":"<p>Banka se rozhodne vyvinout vlastní testovací nástroj založený na generativní AI. Kterou z následujících úvah sylabus u tohoto přístupu zdůrazňuje?<\/p>","m":["Optimalizovat jen cenu tokenů, protože rizika ochrany dat se vlastních nástrojů netýkají.","Vynechat procesy validace, protože interně vyvinutý nástroj má banka plně pod kontrolou.","Pečlivě plánovat výpočetní výkon, úložiště dat a školení lidí a zavést strukturované procesy validace a údržby vývoje specifického pro GenAI.","Spolehnout se hlavně na záruky dodavatele týkající se ochrany dat a výkonu modelu."],"vys":{"a":"Špatně. Vlastní vývoj zdůrazňuje plnou kontrolu nad riziky ochrany dat a bezpečnosti. Tato rizika je stále potřeba řídit (4.2.2).","b":"Špatně. Sylabus strukturované procesy validace a údržby výslovně vyžaduje (4.2.2).","c":"Správně. Oddíl 4.2.2 u vlastního vývoje uvádí plánování zdrojů (výpočetní výkon, úložiště, školení), strukturované procesy validace a údržby a potřebnou odbornost.","d":"Špatně. Záruky dodavatele jsou podstatné u externích služeb nebo nástrojů. Vlastní vývoj stojí na vlastní kontrole organizace (4.2.2)."},"obecne":"Vlastní vývoj dává nejvíc kontroly, ale vyžaduje zdroje, procesy a odbornost."},"kap":{"c":"4.2.2","nazev":"4.2.2 LLMOps při nasazení a správě LLM pro testování","href":"kapitola-4/vyklad.html#oddil-4-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.2-03","n":null,"lo":"GenAI-4.2.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A test organization uses an approved AI chatbot for brainstorming test ideas and, at the same time, develops an in-house GenAI tool for tasks involving confidential data.<\/p><p>Which statement about this situation is correct according to the syllabus?<\/p>","m":["This is not recommended, because an organization should choose one approach to keep its LLMOps decisions consistent.","Combining the approaches is possible only if both use the same LLM provider.","The in-house tool removes the need to assess the data privacy risks of the chatbot.","The approaches are not mutually exclusive, can be implemented simultaneously depending on the test activities, and can be enhanced with RAG and fine-tuning."],"vys":{"a":"Incorrect. Section 4.2.2 explicitly states that the approaches are not mutually exclusive.","b":"Incorrect. The syllabus sets no such condition (4.2.2).","c":"Incorrect. Each approach has its own considerations. The chatbot still requires assessment of data privacy and security risks (4.2.2).","d":"Correct. Section 4.2.2 states that an organization might use an AI chatbot for some tasks while developing custom tools for others, and that the approaches can incorporate RAG and fine-tuning."},"obecne":"Organizations can mix approaches per test activity."},"cz":{"q":"<p>Testovací organizace používá schválený AI chatbot na hledání nápadů na testy a současně vyvíjí vlastní nástroj s GenAI pro úlohy s důvěrnými daty.<\/p><p>Které tvrzení o této situaci je podle sylabu správné?<\/p>","m":["Nedoporučuje se to, protože organizace má zvolit jeden přístup, aby rozhodnutí LLMOps byla konzistentní.","Kombinace přístupů je možná jen tehdy, když oba používají stejného poskytovatele LLM.","Vlastní nástroj odstraňuje potřebu posuzovat rizika ochrany dat u chatbotu.","Přístupy se nevylučují, mohou běžet současně podle testovacích činností a lze je rozšířit o RAG a fine-tuning."],"vys":{"a":"Špatně. Oddíl 4.2.2 výslovně říká, že se přístupy nevylučují.","b":"Špatně. Žádnou takovou podmínku sylabus neuvádí (4.2.2).","c":"Špatně. Každý přístup má své úvahy. U chatbotu je stále potřeba posoudit rizika ochrany dat a bezpečnosti (4.2.2).","d":"Správně. Podle 4.2.2 může organizace používat AI chatbot pro některé úlohy a vlastní nástroje pro jiné a přístupy mohou zahrnovat RAG a fine-tuning."},"obecne":"Organizace může přístupy kombinovat podle testovacích činností."},"kap":{"c":"4.2.2","nazev":"4.2.2 LLMOps při nasazení a správě LLM pro testování","href":"kapitola-4/vyklad.html#oddil-4-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.2-04","n":null,"lo":"GenAI-4.2.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following activities is part of LLMOps for an LLM used in a test tool?<\/p>","m":["Monitoring and maintaining the LLM after it has been deployed to production, for example by tracking the quality and cost of its responses.","Writing user stories that describe the functions of the LLM for the product owner.","Designing a new transformer architecture for a foundation model.","Selecting black-box test techniques for the system under test."],"vys":{"a":"Correct. LLMOps covers the development, deployment and maintenance of LLMs in production (4.2.2). The syllabus definition in Appendix D explicitly includes monitoring.","b":"Incorrect. Writing user stories is a requirements activity, not an LLMOps practice (4.2.2).","c":"Incorrect. Designing model architectures is research and model development, not operating LLMs in production (4.2.2).","d":"Incorrect. Selecting test techniques is a test design activity (CTFL). It does not concern operating LLMs."},"obecne":"LLMOps covers the lifecycle of LLMs in production: development, deployment, monitoring and maintenance."},"cz":{"q":"<p>Která z následujících činností patří do LLMOps pro LLM používaný v testovacím nástroji?<\/p>","m":["Monitoring a údržba LLM po nasazení do provozu, například sledování kvality a ceny jeho odpovědí.","Psaní uživatelských scénářů, které popisují funkce LLM pro vlastníka produktu.","Návrh nové architektury transformeru pro foundation model.","Výběr technik testování černé skříňky pro testovaný systém."],"vys":{"a":"Správně. LLMOps pokrývá vývoj, nasazení a údržbu LLM v provozu (4.2.2). Definice v Appendixu D výslovně zahrnuje monitoring.","b":"Špatně. Psaní uživatelských scénářů je práce s požadavky, ne praxe LLMOps (4.2.2).","c":"Špatně. Návrh architektury modelu je výzkum a vývoj modelu, ne provoz LLM (4.2.2).","d":"Špatně. Výběr technik testování je součást návrhu testů (CTFL). S provozem LLM nesouvisí."},"obecne":"LLMOps pokrývá životní cyklus LLM v provozu: vývoj, nasazení, monitoring a údržbu."},"kap":{"c":"4.2.2","nazev":"4.2.2 LLMOps při nasazení a správě LLM pro testování","href":"kapitola-4/vyklad.html#oddil-4-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.2-05","n":null,"lo":"GenAI-4.2.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A test team wants to start using an AI chatbot to support test analysis. Which of the following BEST describes the primary LLMOps considerations for this approach?<\/p>","m":["Evaluating only the performance assurances of the test management tool provider.","Managing data privacy and security risks while optimizing cost, for example by using an LLM-as-a-Service platform with adequate assurances or an in-house deployment of an open-source LLM.","Fine-tuning the chatbot's model on the team's test cases before any use.","Planning staff training and data storage for the development of the team's own foundation model."],"vys":{"a":"Incorrect. Assurances of a test tool provider belong to the approach of using a test tool with GenAI capabilities (4.2.2).","b":"Correct. Section 4.2.2 names data privacy and security risks and cost optimization as primary considerations for AI chatbots, with the options of LLM-as-a-Service or in-house infrastructure using open-source LLMs.","c":"Incorrect. Fine-tuning can enhance any approach, but the syllabus does not require it for chatbot use (4.2.2).","d":"Incorrect. Resource planning and staff training are emphasized for in-house development of a test tool (4.2.2)."},"obecne":"Chatbot: privacy, security, cost; vendor assurances or internal capabilities must be assessed."},"cz":{"q":"<p>Testovací tým chce začít používat AI chatbot na podporu testovací analýzy. Co z následujícího NEJLÉPE popisuje hlavní úvahy LLMOps u tohoto přístupu?<\/p>","m":["Posoudit jen záruky výkonu od poskytovatele nástroje pro správu testů.","Řídit rizika ochrany dat a bezpečnosti a optimalizovat náklady, například použitím platformy LLM jako služba s dostatečnými zárukami nebo vlastním nasazením open-source LLM.","Před jakýmkoli použitím doladit model chatbotu na testovacích případech týmu.","Naplánovat školení lidí a úložiště dat pro vývoj vlastního foundation modelu týmu."],"vys":{"a":"Špatně. Záruky poskytovatele testovacího nástroje patří k přístupu s testovacím nástrojem s GenAI (4.2.2).","b":"Správně. Oddíl 4.2.2 uvádí u AI chatbotů jako hlavní úvahy rizika ochrany dat a bezpečnosti a optimalizaci nákladů, s možností LLM jako služby nebo vlastní infrastruktury s open-source LLM.","c":"Špatně. Fine-tuning může rozšířit kterýkoli přístup, ale sylabus ho pro použití chatbotu nevyžaduje (4.2.2).","d":"Špatně. Plánování zdrojů a školení sylabus zdůrazňuje u vlastního vývoje testovacího nástroje (4.2.2)."},"obecne":"Chatbot: ochrana dat, bezpečnost, náklady. Je nutné posoudit záruky dodavatele nebo vlastní schopnosti."},"kap":{"c":"4.2.2","nazev":"4.2.2 LLMOps při nasazení a správě LLM pro testování","href":"kapitola-4/vyklad.html#oddil-4-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.1-01","n":null,"lo":"GenAI-5.1.1","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following is identified in the syllabus as a risk of shadow AI?<\/p>","m":["Shadow AI increases the energy consumption of the organization's approved LLMs","Approved enterprise AI tools may produce more hallucinations than personal AI tools","Unclear licensing terms of AI tools may expose users to intellectual property disputes","Testers using shadow AI may lose the ability to apply traditional test techniques"],"vys":{"a":"Incorrect. Energy consumption is discussed in section 3.3.1, not as a risk of shadow AI in section 5.1.1.","b":"Incorrect. The syllabus does not compare hallucination rates of approved and personal tools. Hallucinations are covered in section 3.1, not as a shadow AI risk.","c":"Correct. Vague intellectual property is one of the three risks of shadow AI listed in section 5.1.1.","d":"Incorrect. Loss of test skills is not one of the shadow AI risks in section 5.1.1."},"obecne":"Section 5.1.1 lists three risks of shadow AI: information security and data privacy weaknesses, compliance and regulatory issues, and vague intellectual property."},"cz":{"q":"<p>Které z následujících tvrzení sylabus uvádí jako riziko stínové AI?<\/p>","m":["Stínová AI zvyšuje spotřebu energie schválených LLM v organizaci","Schválené firemní AI nástroje mohou halucinovat víc než osobní AI nástroje","Nejasné licenční podmínky AI nástrojů mohou uživatele vystavit sporům o duševní vlastnictví","Testeři, kteří používají stínovou AI, mohou ztratit schopnost používat tradiční testovací techniky"],"vys":{"a":"Špatně. Spotřebu energie řeší oddíl 3.3.1, ne oddíl 5.1.1 o stínové AI.","b":"Špatně. Sylabus míru halucinací schválených a osobních nástrojů neporovnává. Halucinace řeší oddíl 3.1, ne jako riziko stínové AI.","c":"Správně. Nejasné duševní vlastnictví je jedno ze tří rizik stínové AI v oddílu 5.1.1.","d":"Špatně. Ztráta testovacích dovedností mezi riziky stínové AI v 5.1.1 není."},"obecne":"Oddíl 5.1.1 uvádí tři rizika stínové AI: slabiny v informační bezpečnosti a ochraně dat, problémy s compliance a regulací a nejasné duševní vlastnictví."},"kap":{"c":"5.1.1","nazev":"5.1.1 Rizika stínové AI","href":"kapitola-5/vyklad.html#oddil-5-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.1-02","n":null,"lo":"GenAI-5.1.1","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester copies extracts from a customer database into a free online chatbot using a personal account to get help with a data conversion defect. The tool has not been reviewed by the organization.<\/p><p>Which risk of shadow AI does this situation MOST directly illustrate?<\/p>","m":["Reasoning errors, because the chatbot may misunderstand the conversion logic","Non-deterministic behavior, because the chatbot may give different answers each time","Vague intellectual property, because the chatbot output may be protected by copyright","Information security and data privacy weaknesses, because personal tools may lack robust security and lead to data breaches"],"vys":{"a":"Incorrect. Reasoning errors are a general GenAI risk from section 3.1, not one of the shadow AI risks in section 5.1.1.","b":"Incorrect. Non-deterministic behavior is a property of LLMs in general, not a shadow AI risk listed in section 5.1.1.","c":"Incorrect. Intellectual property may also be a concern, but the most direct risk here is that customer data leaves the protected environment.","d":"Correct. Section 5.1.1 states that personal AI tools may lack robust security, leading to potential data breaches. Customer data in a personal account is the typical example."},"obecne":"When sensitive data is entered into an unapproved personal tool, the main shadow AI risk is the information security and data privacy weakness (section 5.1.1)."},"cz":{"q":"<p>Tester zkopíruje výňatky ze zákaznické databáze do volného online chatbotu přes osobní účet, aby mu pomohl s defektem při konverzi dat. Organizace nástroj neprověřila.<\/p><p>Které riziko stínové AI tato situace ilustruje NEJPŘÍMĚJI?<\/p>","m":["Chyby v uvažování, protože chatbot může logice konverze špatně porozumět","Nedeterministické chování, protože chatbot může pokaždé odpovědět jinak","Nejasné duševní vlastnictví, protože výstup chatbotu může být chráněn autorským právem","Slabiny v informační bezpečnosti a ochraně dat, protože osobní nástroje nemusí být dobře zabezpečené a hrozí únik dat"],"vys":{"a":"Špatně. Chyby v uvažování jsou obecné riziko GenAI z oddílu 3.1, ne riziko stínové AI z 5.1.1.","b":"Špatně. Nedeterministické chování je obecná vlastnost LLM, ne riziko stínové AI z 5.1.1.","c":"Špatně. Duševní vlastnictví může hrát roli, ale nejpřímějším rizikem je, že zákaznická data opustila chráněné prostředí.","d":"Správně. Oddíl 5.1.1 uvádí, že osobní AI nástroje nemusí mít dostatečné zabezpečení a hrozí únik dat. Zákaznická data v osobním účtu jsou typický příklad."},"obecne":"Když se citlivá data vloží do neschváleného osobního nástroje, hlavním rizikem stínové AI je slabina v informační bezpečnosti a ochraně dat (5.1.1)."},"kap":{"c":"5.1.1","nazev":"5.1.1 Rizika stínové AI","href":"kapitola-5/vyklad.html#oddil-5-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.1-03","n":null,"lo":"GenAI-5.1.1","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following is NOT one of the risks of shadow AI described in the syllabus?<\/p>","m":["Potential degradation of LLM performance caused by too many simultaneous users","Potential data breaches because personal AI tools may lack robust security","Potential legal consequences due to non-compliance with industry standards and regulations","Potential intellectual property disputes when copyrighted data is processed without proper authorization"],"vys":{"a":"Correct. Performance degradation due to load is not mentioned as a shadow AI risk in section 5.1.1.","b":"Incorrect. This is the information security and data privacy risk of shadow AI from section 5.1.1.","c":"Incorrect. This is the compliance and regulatory risk of shadow AI from section 5.1.1.","d":"Incorrect. This is the vague intellectual property risk of shadow AI from section 5.1.1."},"obecne":"The three shadow AI risks are security and data privacy, compliance and regulatory issues, and vague intellectual property (section 5.1.1)."},"cz":{"q":"<p>Které z následujících NENÍ jedním z rizik stínové AI popsaných v sylabu?<\/p>","m":["Možné zhoršení výkonu LLM kvůli příliš mnoha souběžným uživatelům","Možný únik dat, protože osobní AI nástroje nemusí být dobře zabezpečené","Možné právní následky kvůli nesouladu s oborovými normami a předpisy","Možné spory o duševní vlastnictví, když se bez oprávnění zpracovávají data chráněná autorským právem"],"vys":{"a":"Správně. Zhoršení výkonu kvůli zátěži oddíl 5.1.1 jako riziko stínové AI neuvádí.","b":"Špatně. Jde o riziko bezpečnosti a ochrany dat z oddílu 5.1.1.","c":"Špatně. Jde o riziko compliance a regulace z oddílu 5.1.1.","d":"Špatně. Jde o riziko nejasného duševního vlastnictví z oddílu 5.1.1."},"obecne":"Tři rizika stínové AI jsou bezpečnost a ochrana dat, compliance a regulace a nejasné duševní vlastnictví (5.1.1)."},"kap":{"c":"5.1.1","nazev":"5.1.1 Rizika stínové AI","href":"kapitola-5/vyklad.html#oddil-5-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.1-04","n":null,"lo":"GenAI-5.1.1","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>According to the syllabus, which risk of shadow AI is MOST closely associated with AI tools whose licensing agreements are unclear?<\/p>","m":["Data poisoning","Vague intellectual property","Compliance with transparency obligations","Information security weaknesses"],"vys":{"a":"Incorrect. Data poisoning is a security attack described in section 3.2, not a shadow AI risk tied to licensing.","b":"Correct. Section 5.1.1 links unclear licensing agreements to intellectual property disputes.","c":"Incorrect. Transparency obligations are part of process guidelines in section 5.1.2, not a shadow AI risk.","d":"Incorrect. Security weaknesses relate to the lack of robust security in personal tools, not to licensing."},"obecne":"Licensing is the key word for the intellectual property risk of shadow AI (section 5.1.1)."},"cz":{"q":"<p>Které riziko stínové AI sylabus NEJVÍC spojuje s AI nástroji, jejichž licenční podmínky jsou nejasné?<\/p>","m":["Otrávení dat (data poisoning)","Nejasné duševní vlastnictví","Dodržení povinností transparentnosti","Slabiny v informační bezpečnosti"],"vys":{"a":"Špatně. Data poisoning je bezpečnostní útok z oddílu 3.2, ne riziko stínové AI spojené s licencemi.","b":"Správně. Oddíl 5.1.1 spojuje nejasné licenční podmínky se spory o duševní vlastnictví.","c":"Špatně. Povinnosti transparentnosti jsou součást procesních pravidel z 5.1.2, ne riziko stínové AI.","d":"Špatně. Slabiny v bezpečnosti souvisejí s nedostatečným zabezpečením osobních nástrojů, ne s licencemi."},"obecne":"Licence jsou poznávací znamení rizika duševního vlastnictví u stínové AI (5.1.1)."},"kap":{"c":"5.1.1","nazev":"5.1.1 Rizika stínové AI","href":"kapitola-5/vyklad.html#oddil-5-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.1-05","n":null,"lo":"GenAI-5.1.1","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which statement BEST describes what the syllabus recommends to help test organizations avoid the risks of shadow AI?<\/p>","m":["Use only open source LLMs because they have no licensing restrictions","Prohibit all use of GenAI tools in test activities until regulations are final","Define a strategy and steps for integrating and deploying GenAI in the organization","Allow each tester to choose their preferred AI tool as long as outputs are reviewed"],"vys":{"a":"Incorrect. Open source models also have licenses, and the syllabus does not recommend restricting the choice to open source.","b":"Incorrect. The syllabus does not recommend a ban. A complete ban tends to push people towards unapproved tools.","c":"Correct. Section 5.1.1 ends by stating that a strategy and steps for integrating and deploying GenAI help test organizations avoid the risk of shadow AI.","d":"Incorrect. Reviewing outputs does not remove the security, compliance or IP risks of using unapproved tools."},"obecne":"The answer to shadow AI in the syllabus is a managed adoption: strategy and steps for integrating and deploying GenAI (section 5.1.1)."},"cz":{"q":"<p>Které tvrzení NEJLÉPE popisuje, co sylabus doporučuje, aby se testovací organizace vyhnuly rizikům stínové AI?<\/p>","m":["Používat jen open source LLM, protože nemají licenční omezení","Zakázat jakékoli použití nástrojů GenAI v testování, dokud nebudou předpisy hotové","Definovat strategii a kroky pro integraci a nasazení GenAI v organizaci","Dovolit každému testerovi vybrat si oblíbený AI nástroj, pokud se výstupy revidují"],"vys":{"a":"Špatně. I open source modely mají licence a sylabus výběr na open source neomezuje.","b":"Špatně. Sylabus zákaz nedoporučuje. Plošný zákaz spíš tlačí lidi k neschváleným nástrojům.","c":"Správně. Oddíl 5.1.1 končí tím, že strategie a kroky pro integraci a nasazení GenAI pomáhají riziku stínové AI předejít.","d":"Špatně. Revize výstupů neodstraní bezpečnostní, regulatorní ani licenční rizika neschválených nástrojů."},"obecne":"Odpovědí sylabu na stínovou AI je řízené zavedení: strategie a kroky pro integraci a nasazení GenAI (5.1.1)."},"kap":{"c":"5.1.1","nazev":"5.1.1 Rizika stínové AI","href":"kapitola-5/vyklad.html#oddil-5-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.2-01","n":null,"lo":"GenAI-5.1.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A test manager writes the following objective for a GenAI initiative: 'Use GenAI wherever possible to make testing more modern.'<\/p><p>Why is this objective weak from the perspective of a GenAI strategy for software testing?<\/p>","m":["Because the objective does not name the specific LLM that will be used","Because objectives for GenAI should focus on reducing the number of testers","Because the objective should be defined only after the GenAI tools are fully integrated","Because the objective is not measurable, so it is not possible to evaluate whether GenAI brings the intended benefit"],"vys":{"a":"Incorrect. LLM selection should follow from the objectives, not be part of them (section 5.1.2).","b":"Incorrect. The syllabus examples are productivity, shorter test cycles and quality, not headcount reduction.","c":"Incorrect. Objectives come first; the strategy begins with them (section 5.1.2).","d":"Correct. Section 5.1.2 starts with defining measurable test objectives such as increased productivity, shorter test cycles and improved test quality. 'More modern' cannot be measured."},"obecne":"A GenAI strategy begins with measurable test objectives; without them metrics cannot show whether the strategy works (section 5.1.2)."},"cz":{"q":"<p>Test manažer napíše pro iniciativu s GenAI tento cíl: „Používat GenAI všude, kde to jde, aby testování bylo modernější.“<\/p><p>Proč je tento cíl z pohledu strategie GenAI pro testování slabý?<\/p>","m":["Protože cíl neuvádí konkrétní LLM, který se použije","Protože cíle pro GenAI se mají zaměřit na snížení počtu testerů","Protože cíl se má stanovit až poté, co jsou nástroje GenAI plně integrované","Protože cíl není měřitelný, takže nejde vyhodnotit, jestli GenAI přináší zamýšlený přínos"],"vys":{"a":"Špatně. Výběr LLM má vycházet z cílů, není jejich součástí (5.1.2).","b":"Špatně. Příklady v sylabu jsou produktivita, kratší cykly a kvalita, ne snižování počtu lidí.","c":"Špatně. Cíle jsou první, strategie jimi začíná (5.1.2).","d":"Správně. Oddíl 5.1.2 začíná definicí měřitelných cílů testování, například vyšší produktivity, kratších cyklů a vyšší kvality. „Modernější“ změřit nejde."},"obecne":"Strategie GenAI začíná měřitelnými cíli testování, bez nich metriky neukážou, jestli strategie funguje (5.1.2)."},"kap":{"c":"5.1.2","nazev":"5.1.2 Klíčové aspekty strategie GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.2-02","n":null,"lo":"GenAI-5.1.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A test organization plans to feed requirements into an LLM to generate test cases. The requirements repository contains outdated, contradictory and duplicated items.<\/p><p>Which aspect of a GenAI strategy addresses this issue MOST directly, and why?<\/p>","m":["Data quality, because the effectiveness of LLM-powered testing depends on accurate and relevant input data","Metrics, because time efficiency will show that the requirements are of poor quality","Training programs, because testers must learn ethical skills before using requirements","LLM selection, because a larger model can resolve contradictions in the input automatically"],"vys":{"a":"Correct. Section 5.1.2 states that LLM-powered testing depends on accurate, relevant input data and that high-quality input is key to trustworthy results.","b":"Incorrect. Metrics may reveal poor results later, but they do not address the quality of the input itself.","c":"Incorrect. Training is important, but ethical skills do not fix poor input data.","d":"Incorrect. A larger model cannot reliably fix contradictory input; the syllabus links trustworthy results to input data quality."},"obecne":"Inaccurate or irrelevant input leads to untrustworthy output. Data quality is an explicit aspect of a GenAI strategy (section 5.1.2)."},"cz":{"q":"<p>Testovací organizace chce vkládat požadavky do LLM a generovat z nich testovací případy. Úložiště požadavků obsahuje zastaralé, rozporné a duplicitní položky.<\/p><p>Který aspekt strategie GenAI tento problém řeší NEJPŘÍMĚJI a proč?<\/p>","m":["Kvalita dat, protože účinnost testování s LLM závisí na přesných a relevantních vstupních datech","Metriky, protože time efficiency ukáže, že požadavky jsou nekvalitní","Školení, protože testeři se musí naučit etické dovednosti, než použijí požadavky","Výběr LLM, protože větší model rozpory ve vstupu vyřeší automaticky"],"vys":{"a":"Správně. Oddíl 5.1.2 říká, že testování s LLM závisí na přesných a relevantních vstupních datech a že kvalitní vstup je podmínkou důvěryhodných výsledků.","b":"Špatně. Metriky mohou později ukázat špatné výsledky, ale kvalitu samotného vstupu neřeší.","c":"Špatně. Školení je důležité, ale etické dovednosti nekvalitní vstupní data neopraví.","d":"Špatně. Větší model rozporný vstup spolehlivě neopraví. Sylabus spojuje důvěryhodné výsledky s kvalitou vstupních dat."},"obecne":"Nepřesný nebo nerelevantní vstup dává nedůvěryhodný výstup. Kvalita dat je výslovný aspekt strategie GenAI (5.1.2)."},"kap":{"c":"5.1.2","nazev":"5.1.2 Klíčové aspekty strategie GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.2-03","n":null,"lo":"GenAI-5.1.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following is an example of a process guideline that a GenAI strategy for software testing should include?<\/p>","m":["Generated test scripts are executed directly in production to save time","Test cases generated by GenAI are labelled as such and pass a review before being added to the regression test suite","All available project data is sent to the LLM to maximize the context for each prompt","Each tester may decide individually whether generated testware needs to be reviewed"],"vys":{"a":"Incorrect. Skipping review and testing in production contradicts the quality gates described in section 5.1.2.","b":"Correct. Section 5.1.2 mentions transparency obligations (what was generated using GenAI) and quality gates with review of generated testware.","c":"Incorrect. Guidelines should include rules for the use of sensitive data; sending all data contradicts this and data quality means relevant data, not maximum data.","d":"Incorrect. Quality gates with review should be defined as an organizational rule, not left to individual choice."},"obecne":"Process guidelines in section 5.1.2 cover sensitive data rules, transparency obligations and quality gates with review of generated testware."},"cz":{"q":"<p>Které z následujících je příkladem procesního pravidla, které má strategie GenAI pro testování obsahovat?<\/p>","m":["Vygenerované testovací skripty se kvůli úspoře času spouštějí rovnou v produkci","Testovací případy vygenerované GenAI se tak označí a před zařazením do regresní sady projdou revizí","Do LLM se posílají všechna dostupná data projektu, aby každý prompt měl co největší kontext","Každý tester se sám rozhodne, jestli vygenerovaný testware potřebuje revizi"],"vys":{"a":"Špatně. Vynechat revizi a testovat v produkci odporuje quality gates z 5.1.2.","b":"Správně. Oddíl 5.1.2 uvádí povinnosti transparentnosti (co vzniklo pomocí GenAI) a quality gates s revizí vygenerovaného testwaru.","c":"Špatně. Pravidla mají obsahovat zásady pro citlivá data. Posílat všechno jim odporuje a kvalita dat znamená relevantní data, ne co nejvíc dat.","d":"Špatně. Quality gates s revizí mají být pravidlem organizace, ne volbou jednotlivce."},"obecne":"Procesní pravidla v 5.1.2 zahrnují pravidla pro citlivá data, povinnosti transparentnosti a quality gates s revizí vygenerovaného testwaru."},"kap":{"c":"5.1.2","nazev":"5.1.2 Klíčové aspekty strategie GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.2-04","n":null,"lo":"GenAI-5.1.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>An organization has trained its testers and introduced an LLM for test case generation. After six months, management asks whether the investment has improved test productivity, but nobody can answer.<\/p><p>Which aspect of the GenAI strategy was MOST likely neglected?<\/p>","m":["Establishing transparency obligations for generated testware","Ensuring compatibility of the LLM with existing test infrastructure","Collecting specific metrics to measure the effectiveness of GenAI results","Selecting an LLM that supports multimodal input"],"vys":{"a":"Incorrect. Transparency tells readers what was AI-generated but does not measure effectiveness.","b":"Incorrect. Infrastructure compatibility affects whether the LLM can be integrated, not whether the benefit can be shown.","c":"Correct. Section 5.1.2 requires collecting specific metrics (see 2.3.1) to measure the effectiveness of GenAI results. Without them the question about productivity cannot be answered.","d":"Incorrect. Multimodal input is a functional capability considered in model selection (5.1.3), not a way to evaluate benefits."},"obecne":"Measurable objectives need metrics; otherwise the organization cannot tell whether GenAI adds value (section 5.1.2)."},"cz":{"q":"<p>Organizace proškolila testery a zavedla LLM pro generování testovacích případů. Po půl roce se vedení ptá, jestli investice zvýšila produktivitu testování, ale nikdo neumí odpovědět.<\/p><p>Který aspekt strategie GenAI byl NEJSPÍŠ zanedbán?<\/p>","m":["Zavedení povinností transparentnosti pro vygenerovaný testware","Zajištění kompatibility LLM se stávající testovací infrastrukturou","Sběr konkrétních metrik, které měří účinnost výsledků GenAI","Výběr LLM, který podporuje multimodální vstup"],"vys":{"a":"Špatně. Transparentnost říká čtenáři, co vytvořila AI, ale účinnost neměří.","b":"Špatně. Kompatibilita s infrastrukturou ovlivňuje, jestli jde LLM zapojit, ne jestli jde přínos prokázat.","c":"Správně. Oddíl 5.1.2 požaduje sbírat konkrétní metriky (viz 2.3.1), které měří účinnost výsledků GenAI. Bez nich nejde na otázku o produktivitě odpovědět.","d":"Špatně. Multimodální vstup je funkční schopnost posuzovaná při výběru modelu (5.1.3), ne způsob vyhodnocení přínosu."},"obecne":"Měřitelné cíle potřebují metriky, jinak organizace nepozná, jestli GenAI přináší hodnotu (5.1.2)."},"kap":{"c":"5.1.2","nazev":"5.1.2 Klíčové aspekty strategie GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.2-05","n":null,"lo":"GenAI-5.1.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which statement BEST explains why training programs are part of a GenAI strategy for software testing?<\/p>","m":["Training ensures that each tester obtains a vendor certification for every LLM in use","Training is needed mainly so that testers can fine-tune the LLMs themselves","Training replaces the need for process guidelines, because skilled testers do not need rules","Training gives test teams the technical and ethical skills needed to use GenAI tools effectively"],"vys":{"a":"Incorrect. The syllabus does not mention vendor certifications; it focuses on technical and ethical skills.","b":"Incorrect. Fine-tuning is not the purpose of training in section 5.1.2.","c":"Incorrect. Training and process guidelines are separate aspects; both are needed (section 5.1.2).","d":"Correct. Section 5.1.2 says comprehensive training programs should ensure that test teams have the technical and ethical skills necessary to use GenAI tools effectively."},"obecne":"Training in a GenAI strategy covers both technical skills (prompting, evaluating outputs) and ethical skills (bias, transparency, data privacy) (section 5.1.2)."},"cz":{"q":"<p>Které tvrzení NEJLÉPE vysvětluje, proč jsou vzdělávací programy součástí strategie GenAI pro testování?<\/p>","m":["Školení zajistí, že každý tester získá certifikát dodavatele pro každý používaný LLM","Školení je potřeba hlavně proto, aby testeři mohli LLM sami dolaďovat","Školení nahrazuje procesní pravidla, protože zkušení testeři pravidla nepotřebují","Školení dá testovacím týmům technické a etické dovednosti potřebné k efektivnímu používání nástrojů GenAI"],"vys":{"a":"Špatně. Sylabus certifikace dodavatelů nezmiňuje, zaměřuje se na technické a etické dovednosti.","b":"Špatně. Doladění modelu není účelem školení podle 5.1.2.","c":"Špatně. Školení a procesní pravidla jsou samostatné aspekty a potřeba jsou oba (5.1.2).","d":"Správně. Oddíl 5.1.2 říká, že vzdělávací programy mají zajistit technické a etické dovednosti pro efektivní používání nástrojů GenAI."},"obecne":"Školení ve strategii GenAI pokrývá technické dovednosti (prompty, hodnocení výstupů) i etické (zkreslení, transparentnost, ochrana dat) (5.1.2)."},"kap":{"c":"5.1.2","nazev":"5.1.2 Klíčové aspekty strategie GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.3-01","n":null,"lo":"GenAI-5.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A test organization compares two LLMs for generating test cases from user stories. Model X ranks higher on a popular public leaderboard for general language tasks. Model Y achieved higher accuracy and relevance on a set of 60 of the organization's own user stories reviewed by senior testers.<\/p><p>Based on the model performance criterion, which conclusion is BEST?<\/p>","m":["Model Y should be preferred, because performance should be evaluated on the targeted test tasks against the organization's benchmarks","Both models are equivalent, because performance is not a relevant criterion for SLM/LLM selection","Neither model can be evaluated, because there are no benchmarks specific to software testing","Model X should be preferred, because public leaderboards are the most objective source for test tasks"],"vys":{"a":"Correct. Section 5.1.3 says to evaluate model performance for the targeted test tasks against the organization's benchmarks, using metrics such as those in section 2.3.1.","b":"Incorrect. Model performance is the first of the four selection criteria in section 5.1.3.","c":"Incorrect. Few public test-specific benchmarks exist, but the organization can use its own benchmarks and the metrics from section 2.3.1.","d":"Incorrect. Section 5.1.3 notes that few public benchmarks focus on test tasks; general leaderboards do not show performance on the targeted test task."},"obecne":"Model performance means quality on your own test tasks measured against your own benchmarks, not a position on a public leaderboard (section 5.1.3)."},"cz":{"q":"<p>Testovací organizace porovnává dva LLM pro generování testovacích případů z uživatelských scénářů. Model X je výš na populárním veřejném žebříčku pro obecné jazykové úlohy. Model Y dosáhl vyšší přesnosti a relevance na 60 vlastních uživatelských scénářích organizace, které hodnotili seniorní testeři.<\/p><p>Jaký závěr je podle kritéria výkonu modelu NEJLEPŠÍ?<\/p>","m":["Přednost má model Y, protože výkon se má hodnotit na cílových testovacích úlohách proti benchmarkům organizace","Oba modely jsou rovnocenné, protože výkon není pro výběr LLM/SLM relevantní kritérium","Žádný model nejde posoudit, protože neexistují benchmarky specifické pro testování","Přednost má model X, protože veřejné žebříčky jsou pro testovací úlohy nejobjektivnějším zdrojem"],"vys":{"a":"Správně. Oddíl 5.1.3 říká, že výkon se hodnotí pro cílové testovací úlohy proti benchmarkům organizace metrikami z 2.3.1.","b":"Špatně. Výkon modelu je první ze čtyř kritérií výběru v 5.1.3.","c":"Špatně. Veřejných benchmarků pro testování je málo, ale organizace může použít vlastní benchmarky a metriky z 2.3.1.","d":"Špatně. Oddíl 5.1.3 upozorňuje, že veřejných benchmarků pro testovací úlohy je málo. Obecné žebříčky výkon na cílové úloze neukazují."},"obecne":"Výkon modelu znamená kvalitu na vlastních testovacích úlohách měřenou proti vlastním benchmarkům, ne pořadí ve veřejném žebříčku (5.1.3)."},"kap":{"c":"5.1.3","nazev":"5.1.3 Výběr LLM/SLM pro testovací úlohy","href":"kapitola-5/vyklad.html#oddil-5-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.3-02","n":null,"lo":"GenAI-5.1.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A team wants an LLM to produce test cases in the organization's specific format and terminology. The team has several thousand historical user stories with matching approved test cases.<\/p><p>Which selection criterion is MOST relevant to this need?<\/p>","m":["Context window size, because a larger window removes the need for domain-specific data","Fine-tuning potential, because it should be evaluated whether the model can usefully be fine-tuned with domain-specific data","Community and support, because an active community will provide the organization's test case format","Recurring cost, because historical data reduces licensing fees"],"vys":{"a":"Incorrect. Context window size is a technical feature, not one of the four criteria, and it does not replace domain adaptation.","b":"Correct. Section 5.1.3 describes fine-tuning potential as evaluating whether it is possible and useful to fine-tune the model with domain-specific data to increase accuracy and relevance in specialized contexts.","c":"Incorrect. Community and support help with implementation and troubleshooting, not with the organization's own format.","d":"Incorrect. Historical data does not reduce licensing fees; recurring cost is a different criterion."},"obecne":"Organization-specific format and terminology with available domain data point to the fine-tuning potential criterion (sections 5.1.3 and 4.2.1)."},"cz":{"q":"<p>Tým chce, aby LLM vytvářel testovací případy ve specifickém formátu a terminologii organizace. Tým má několik tisíc historických uživatelských scénářů s odpovídajícími schválenými testovacími případy.<\/p><p>Které kritérium výběru je pro tuto potřebu NEJVÍC relevantní?<\/p>","m":["Velikost kontextového okna, protože větší okno odstraní potřebu doménových dat","Potenciál pro doladění, protože je třeba posoudit, jestli model jde užitečně doladit na doménových datech","Komunita a podpora, protože aktivní komunita dodá formát testovacích případů organizace","Opakované náklady, protože historická data snižují licenční poplatky"],"vys":{"a":"Špatně. Velikost kontextového okna je technická vlastnost, ne jedno ze čtyř kritérií, a doménové přizpůsobení nenahradí.","b":"Správně. Oddíl 5.1.3 popisuje potenciál pro doladění jako posouzení, jestli je možné a užitečné model doladit na doménových datech kvůli přesnosti a relevanci ve specializovaném kontextu.","c":"Špatně. Komunita a podpora pomáhají s nasazením a řešením problémů, ne s vlastním formátem organizace.","d":"Špatně. Historická data licenční poplatky nesnižují, opakované náklady jsou jiné kritérium."},"obecne":"Specifický formát a terminologie organizace spolu s dostupnými doménovými daty ukazují na kritérium potenciálu pro doladění (5.1.3, 4.2.1)."},"kap":{"c":"5.1.3","nazev":"5.1.3 Výběr LLM/SLM pro testovací úlohy","href":"kapitola-5/vyklad.html#oddil-5-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.3-03","n":null,"lo":"GenAI-5.1.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>When evaluating the recurring cost criterion for an LLM that will summarize nightly regression test results, which item should be included?<\/p>","m":["The cost of the initial training workshop for testers","The purchase price of laptops for new team members","Usage-based fees for input and output tokens multiplied by the expected frequency of the task","The one-time effort to migrate existing test cases into a new test management tool"],"vys":{"a":"Incorrect. An initial workshop is a one-time cost, not a recurring cost of the LLM.","b":"Incorrect. Laptops are not an operational expense of using the LLM for the task.","c":"Correct. Section 5.1.3 includes licensing fees and operational expenses in recurring cost; HO-5.1.3 estimates them from tokens, prompts and task frequency.","d":"Incorrect. A one-time migration is not a recurring cost of using the LLM."},"obecne":"Recurring cost covers expenses that repeat while the model is used: licensing, token-based fees and operational costs such as compute (section 5.1.3, HO-5.1.3)."},"cz":{"q":"<p>Při posouzení kritéria opakovaných nákladů pro LLM, který bude shrnovat noční výsledky regresních testů, co je třeba započítat?<\/p>","m":["Cenu úvodního školicího workshopu pro testery","Pořizovací cenu notebooků pro nové členy týmu","Poplatky za vstupní a výstupní tokeny vynásobené očekávanou četností úlohy","Jednorázovou práci na migraci stávajících testovacích případů do nového nástroje pro správu testů"],"vys":{"a":"Špatně. Úvodní workshop je jednorázový náklad, ne opakovaný náklad modelu.","b":"Špatně. Notebooky nejsou provozním nákladem používání LLM pro úlohu.","c":"Správně. Oddíl 5.1.3 řadí do opakovaných nákladů licenční poplatky a provozní náklady. HO-5.1.3 je odhaduje z tokenů, promptů a četnosti úlohy.","d":"Špatně. Jednorázová migrace není opakovaný náklad na používání LLM."},"obecne":"Opakované náklady jsou výdaje, které se opakují po dobu používání modelu: licence, poplatky za tokeny a provoz, třeba výpočetní výkon (5.1.3, HO-5.1.3)."},"kap":{"c":"5.1.3","nazev":"5.1.3 Výběr LLM/SLM pro testovací úlohy","href":"kapitola-5/vyklad.html#oddil-5-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.3-04","n":null,"lo":"GenAI-5.1.3","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A team is choosing between two open source SLMs with similar results on the team's own test benchmark. One has detailed documentation and an active user forum; the other has almost no documentation.<\/p><p>Which selection criterion favors the first model, and why?<\/p>","m":["Recurring cost, because documented models never have operational expenses","Model performance, because documentation improves the accuracy of generated test cases","Fine-tuning potential, because only documented models can be fine-tuned","Community and support, because active community support and detailed documentation aid implementation and troubleshooting"],"vys":{"a":"Incorrect. Any self-hosted model has operational expenses, regardless of documentation.","b":"Incorrect. Documentation does not change the model's results; both models performed similarly on the benchmark.","c":"Incorrect. Fine-tuning possibility depends on the model and its license, not on whether it is documented.","d":"Correct. Section 5.1.3 recommends choosing models with active community support and detailed documentation to aid implementation and troubleshooting."},"obecne":"When performance is comparable, community and support can decide; they reduce implementation and troubleshooting effort (section 5.1.3)."},"cz":{"q":"<p>Tým vybírá mezi dvěma open source SLM s podobnými výsledky na vlastním testovacím benchmarku. Jeden má podrobnou dokumentaci a aktivní uživatelské fórum, druhý skoro žádnou dokumentaci.<\/p><p>Které kritérium výběru zvýhodňuje první model a proč?<\/p>","m":["Opakované náklady, protože zdokumentované modely nemají provozní náklady","Výkon modelu, protože dokumentace zvyšuje přesnost vygenerovaných testovacích případů","Potenciál pro doladění, protože doladit jdou jen zdokumentované modely","Komunita a podpora, protože aktivní komunita a podrobná dokumentace usnadňují nasazení a řešení problémů"],"vys":{"a":"Špatně. Každý model provozovaný ve vlastním prostředí má provozní náklady bez ohledu na dokumentaci.","b":"Špatně. Dokumentace výsledky modelu nemění, oba modely měly na benchmarku podobné výsledky.","c":"Špatně. Možnost doladění závisí na modelu a licenci, ne na dokumentaci.","d":"Správně. Oddíl 5.1.3 doporučuje modely s aktivní komunitou a podrobnou dokumentací, které usnadní nasazení a řešení problémů."},"obecne":"Při srovnatelném výkonu může rozhodnout komunita a podpora, protože snižují práci s nasazením a řešením problémů (5.1.3)."},"kap":{"c":"5.1.3","nazev":"5.1.3 Výběr LLM/SLM pro testovací úlohy","href":"kapitola-5/vyklad.html#oddil-5-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.3-05","n":null,"lo":"GenAI-5.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A bank's test team needs to classify about 400 incoming defect reports per day into components. The reports may contain account numbers and must not leave the bank's environment. The budget for the task is limited.<\/p><p>Which approach is MOST consistent with the syllabus guidance on selecting LLMs/SLMs?<\/p>","m":["Evaluate a smaller, self-hosted SLM against the team's own classification benchmark, considering fine-tuning potential and recurring cost","Select the model with the largest context window, because context window size is the main selection criterion","Avoid language models altogether, because no benchmarks exist for defect classification","Select the largest commercial LLM available, because the most capable model always gives the best value"],"vys":{"a":"Correct. The task is narrow and frequent, data must stay internal and budget is limited. Evaluating an SLM on the team's own benchmark while weighing fine-tuning potential and recurring cost follows sections 5.1.3 and 5.2.1.","b":"Incorrect. Context window size is a technical feature that differentiates models, not the main criterion; short defect reports do not need a large window.","c":"Incorrect. Lack of public test-specific benchmarks means the organization should use its own benchmarks, not avoid models.","d":"Incorrect. The syllabus asks to weigh performance on the targeted task, fine-tuning potential, recurring cost and support; the largest model is not automatically the best fit, and right-sized models are recommended in section 5.2.1."},"obecne":"Selection depends on context: performance on your task, fine-tuning potential, recurring cost and support. Narrow, high-volume, internal tasks often suit a right-sized SLM (sections 5.1.3, 4.2.1, 5.2.1)."},"cz":{"q":"<p>Testovací tým banky potřebuje denně zatřídit asi 400 nových reportů o defektech podle komponent. Reporty mohou obsahovat čísla účtů a nesmí opustit prostředí banky. Rozpočet na úlohu je omezený.<\/p><p>Který přístup NEJVÍC odpovídá doporučením sylabu pro výběr LLM/SLM?<\/p>","m":["Vyhodnotit menší SLM provozovaný ve vlastním prostředí na vlastním benchmarku klasifikace a zvážit potenciál pro doladění a opakované náklady","Vybrat model s největším kontextovým oknem, protože velikost kontextového okna je hlavní kritérium výběru","Jazykové modely vůbec nepoužít, protože pro klasifikaci defektů neexistují benchmarky","Vybrat největší dostupný komerční LLM, protože nejschopnější model má vždy nejlepší poměr cena a přínos"],"vys":{"a":"Správně. Úloha je úzká a častá, data musí zůstat uvnitř a rozpočet je omezený. Vyhodnotit SLM na vlastním benchmarku se zvážením doladění a opakovaných nákladů odpovídá 5.1.3 a 5.2.1.","b":"Špatně. Velikost kontextového okna je technická vlastnost, podle které se modely liší, ne hlavní kritérium. Krátké reporty velké okno nepotřebují.","c":"Špatně. Chybějící veřejné benchmarky pro testování znamenají použít vlastní benchmarky, ne vzdát se modelů.","d":"Špatně. Sylabus chce zvážit výkon na cílové úloze, potenciál pro doladění, opakované náklady a podporu. Největší model není automaticky nejvhodnější a 5.2.1 doporučuje modely přiměřené velikosti."},"obecne":"Výběr závisí na kontextu: výkon na vlastní úloze, potenciál pro doladění, opakované náklady a podpora. Úzké, časté a interní úlohy často vyhovují SLM přiměřené velikosti (5.1.3, 4.2.1, 5.2.1)."},"kap":{"c":"5.1.3","nazev":"5.1.3 Výběr LLM/SLM pro testovací úlohy","href":"kapitola-5/vyklad.html#oddil-5-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.4-01","n":null,"lo":"GenAI-5.1.4","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>In which phase of GenAI adoption does a test organization primarily train test teams on GenAI concepts, provide access to LLMs/SLMs and experiment with initial use cases?<\/p>","m":["Initiation and usage definition","Discovery","Utilization and iteration","Planning and preparation"],"vys":{"a":"Incorrect. Initiation and usage definition focuses on identifying and prioritizing practical use cases.","b":"Correct. Discovery focuses on awareness and capability building through training, access to LLMs/SLMs and initial experiments (section 5.1.4).","c":"Incorrect. Utilization and iteration is the advanced phase with full integration, continuous monitoring and measurement of the transformation.","d":"Incorrect. 'Planning and preparation' is not one of the phases in section 5.1.4."},"obecne":"The three phases are Discovery, Initiation and usage definition, and Utilization and iteration (section 5.1.4)."},"cz":{"q":"<p>Ve které fázi zavedení GenAI testovací organizace hlavně školí týmy o konceptech GenAI, zpřístupňuje LLM/SLM a experimentuje s prvními případy použití?<\/p>","m":["Initiation and usage definition (zahájení a definice použití)","Discovery (objevování)","Utilization and iteration (využívání a iterace)","Planning and preparation (plánování a příprava)"],"vys":{"a":"Špatně. Initiation and usage definition se zaměřuje na identifikaci a prioritizaci praktických případů použití.","b":"Správně. Discovery se zaměřuje na povědomí a budování schopností přes školení, přístup k LLM/SLM a první experimenty (5.1.4).","c":"Špatně. Utilization and iteration je pokročilá fáze s plnou integrací, průběžným monitoringem a měřením transformace.","d":"Špatně. „Planning and preparation“ mezi fázemi v 5.1.4 není."},"obecne":"Tři fáze jsou Discovery, Initiation and usage definition a Utilization and iteration (5.1.4)."},"kap":{"c":"5.1.4","nazev":"5.1.4 Fáze zavedení GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.4-02","n":null,"lo":"GenAI-5.1.4","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A test organization's testers are familiar with GenAI. The organization now evaluates which use cases bring the most value, assesses LLM-powered test infrastructure and checks alignment with organizational needs.<\/p><p>Which adoption phase is this?<\/p>","m":["Scaling and optimization","Discovery","Initiation and usage definition","Utilization and iteration"],"vys":{"a":"Incorrect. 'Scaling and optimization' is not a phase name in the syllabus.","b":"Incorrect. Discovery is about awareness, training and initial experiments.","c":"Correct. Identifying and prioritizing use cases, evaluating LLM-powered test infrastructure, developing expertise and aligning with organizational needs describe Initiation and usage definition (section 5.1.4).","d":"Incorrect. Utilization and iteration means full integration with continuous monitoring and measurement."},"obecne":"Second phase: after basic understanding exists, the organization selects and prioritizes practical use cases (section 5.1.4)."},"cz":{"q":"<p>Testeři organizace už GenAI znají. Organizace teď posuzuje, které případy použití přinesou nejvíc, hodnotí testovací infrastrukturu s LLM a ověřuje soulad s potřebami organizace.<\/p><p>O kterou fázi zavedení jde?<\/p>","m":["Scaling and optimization (škálování a optimalizace)","Discovery (objevování)","Initiation and usage definition (zahájení a definice použití)","Utilization and iteration (využívání a iterace)"],"vys":{"a":"Špatně. „Scaling and optimization“ není název fáze v sylabu.","b":"Špatně. Discovery je o povědomí, školení a prvních pokusech.","c":"Správně. Identifikace a prioritizace případů použití, posouzení infrastruktury s LLM, rozvoj odbornosti a sladění s potřebami organizace popisují fázi Initiation and usage definition (5.1.4).","d":"Špatně. Utilization and iteration znamená plnou integraci s průběžným monitoringem a měřením."},"obecne":"Druhá fáze: po získání základního porozumění organizace vybírá a prioritizuje praktické případy použití (5.1.4)."},"kap":{"c":"5.1.4","nazev":"5.1.4 Fáze zavedení GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.4-03","n":null,"lo":"GenAI-5.1.4","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which statement about the phases of GenAI adoption is consistent with the syllabus?<\/p>","m":["The adoption is complete when the Initiation and usage definition phase ends","The phases apply only to test automation, not to other test activities","All use cases must complete Discovery before any use case can enter the next phase","Different use cases can be in different phases at the same time"],"vys":{"a":"Incorrect. The third phase, Utilization and iteration, follows and includes continuous monitoring and measurement.","b":"Incorrect. The phases apply to GenAI adoption in the test organization in general; the syllabus example compares test report analysis with test automation.","c":"Incorrect. The syllabus explicitly allows parallel phases for different use cases.","d":"Correct. Section 5.1.4 states that the phases can run in parallel for different use cases, for example test report analysis may be further along than test automation."},"obecne":"Phases belong to use cases, not to the whole organization at once; they can run in parallel (section 5.1.4)."},"cz":{"q":"<p>Které tvrzení o fázích zavedení GenAI odpovídá sylabu?<\/p>","m":["Zavedení je dokončeno koncem fáze Initiation and usage definition","Fáze se týkají jen automatizace testů, ne jiných testovacích činností","Všechny případy použití musí dokončit Discovery, než kterýkoli z nich postoupí do další fáze","Různé případy použití mohou být současně v různých fázích"],"vys":{"a":"Špatně. Následuje třetí fáze Utilization and iteration s průběžným monitoringem a měřením.","b":"Špatně. Fáze se týkají zavedení GenAI v testovací organizaci obecně. Příklad v sylabu porovnává analýzu reportů z testování s automatizací testů.","c":"Špatně. Sylabus souběh fází pro různé případy použití výslovně připouští.","d":"Správně. Oddíl 5.1.4 říká, že fáze mohou běžet souběžně pro různé případy použití, například analýza reportů z testování může být dál než automatizace testů."},"obecne":"Fáze patří případům použití, ne celé organizaci najednou, a mohou běžet souběžně (5.1.4)."},"kap":{"c":"5.1.4","nazev":"5.1.4 Fáze zavedení GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.4-04","n":null,"lo":"GenAI-5.1.4","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which human factor does the syllabus specifically mention as something to recognize and address early when adopting GenAI in a test organization?<\/p>","m":["Fear of job displacement, which can impact adoption and team morale","Lack of interest of developers in AI-generated test cases","Resistance of customers to receiving AI-generated test reports","Overconfidence of testers in their manual test design skills"],"vys":{"a":"Correct. Section 5.1.4 mentions early concerns such as fear of job displacement, which can impact adoption and team morale.","b":"Incorrect. The syllabus does not discuss developers' interest in AI-generated test cases here.","c":"Incorrect. Customer resistance is not mentioned in section 5.1.4.","d":"Incorrect. Overconfidence in manual skills is not mentioned in section 5.1.4."},"obecne":"Besides the three phases, section 5.1.4 highlights fear of job displacement as an early concern to address."},"cz":{"q":"<p>Který lidský faktor sylabus výslovně uvádí jako věc, kterou je třeba při zavádění GenAI v testovací organizaci včas rozpoznat a řešit?<\/p>","m":["Strach ze ztráty práce, který může ovlivnit zavádění i náladu v týmu","Nezájem vývojářů o testovací případy vygenerované AI","Odpor zákazníků k reportům z testování vytvořeným AI","Přehnanou důvěru testerů v jejich dovednosti ručního návrhu testů"],"vys":{"a":"Správně. Oddíl 5.1.4 zmiňuje včasné obavy, například strach ze ztráty práce, který může ovlivnit zavádění a náladu v týmu.","b":"Špatně. Zájem vývojářů o AI testovací případy sylabus na tomto místě neřeší.","c":"Špatně. Odpor zákazníků v 5.1.4 zmíněný není.","d":"Špatně. Přehnaná důvěra v ruční dovednosti v 5.1.4 zmíněná není."},"obecne":"Kromě tří fází oddíl 5.1.4 upozorňuje na strach ze ztráty práce jako obavu, kterou je třeba řešit včas."},"kap":{"c":"5.1.4","nazev":"5.1.4 Fáze zavedení GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.4-05","n":null,"lo":"GenAI-5.1.4","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which activity is MOST characteristic of the Utilization and iteration phase of GenAI adoption?<\/p>","m":["Creating a list of candidate use cases and ranking them by expected value","Continuously monitoring the progress of GenAI and related tools and measuring the transformation to ensure sustainable benefits","Giving testers first access to an LLM so they can try generating test data","Running an introductory workshop on GenAI concepts and limitations"],"vys":{"a":"Incorrect. Identifying and prioritizing use cases belongs to Initiation and usage definition.","b":"Correct. Section 5.1.4 describes Utilization and iteration as full integration with continuous monitoring and measurement and management of the transformation for sustainable benefits and scalability.","c":"Incorrect. First access and experimentation belong to Discovery.","d":"Incorrect. Training on GenAI concepts belongs to Discovery."},"obecne":"Phase 3 is about full integration, monitoring, measurement and scaling (section 5.1.4)."},"cz":{"q":"<p>Která činnost je NEJVÍC typická pro fázi Utilization and iteration?<\/p>","m":["Sestavit seznam kandidátních případů použití a seřadit je podle očekávaného přínosu","Průběžně sledovat vývoj GenAI a souvisejících nástrojů a měřit transformaci kvůli udržitelným přínosům","Dát testerům první přístup k LLM, aby si zkusili generovat testovací data","Uspořádat úvodní workshop o konceptech a omezeních GenAI"],"vys":{"a":"Špatně. Identifikace a prioritizace případů použití patří do Initiation and usage definition.","b":"Správně. Oddíl 5.1.4 popisuje Utilization and iteration jako plnou integraci s průběžným monitoringem a s měřením a řízením transformace kvůli udržitelným přínosům a škálovatelnosti.","c":"Špatně. První přístup a experimenty patří do Discovery.","d":"Špatně. Školení o konceptech GenAI patří do Discovery."},"obecne":"Třetí fáze je o plné integraci, monitoringu, měření a škálování (5.1.4)."},"kap":{"c":"5.1.4","nazev":"5.1.4 Fáze zavedení GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.1-01","n":null,"lo":"GenAI-5.2.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A tester with strong prompt engineering skills but no knowledge of insurance products uses an LLM to generate test cases for premium calculation. Several generated test cases contain incorrect expected results that the tester does not notice.<\/p><p>Which skill area from the syllabus would MOST directly have prevented this?<\/p>","m":["Selecting right-sized models to reduce energy consumption","Following privacy-preserving prompt engineering practices","Combining domain and test expertise with AI skills to evaluate LLM-driven test case generation","Understanding the context window size of the LLM"],"vys":{"a":"Incorrect. Right-sized models address cost and energy, not the correctness of expected results.","b":"Incorrect. Privacy-preserving prompting protects data, but it does not help detect incorrect expected results.","c":"Correct. Section 5.2.1 states that testers must combine domain and test expertise with AI skills to evaluate LLM-driven testing, including test case generation. Without domain knowledge, wrong expected results go unnoticed.","d":"Incorrect. Context window understanding helps with large inputs but does not let the tester judge whether expected results are correct."},"obecne":"AI skills alone are not enough; domain and test expertise are needed to evaluate AI-generated testware (section 5.2.1)."},"cz":{"q":"<p>Tester s dobrými dovednostmi v prompt engineeringu, ale bez znalosti pojistných produktů, generuje pomocí LLM testovací případy pro výpočet pojistného. Několik případů má špatně očekávané výsledky, kterých si tester nevšimne.<\/p><p>Která oblast dovedností ze sylabu by tomu NEJPŘÍMĚJI zabránila?<\/p>","m":["Výběr modelů přiměřené velikosti kvůli nižší spotřebě energie","Dodržování postupů tvorby promptů šetrné k soukromí","Spojení doménové a testovací odbornosti s AI dovednostmi při posouzení testovacích případů generovaných LLM","Porozumění velikosti kontextového okna LLM"],"vys":{"a":"Špatně. Modely přiměřené velikosti řeší náklady a energii, ne správnost očekávaných výsledků.","b":"Špatně. Prompty šetrné k soukromí chrání data, ale špatné očekávané výsledky neodhalí.","c":"Správně. Oddíl 5.2.1 říká, že testeři musí spojit doménovou a testovací odbornost s AI dovednostmi, aby posoudili testování řízené LLM včetně generování testovacích případů. Bez znalosti domény špatné očekávané výsledky projdou.","d":"Špatně. Porozumění kontextovému oknu pomáhá s velkými vstupy, ale nedovolí posoudit správnost očekávaných výsledků."},"obecne":"Samotné AI dovednosti nestačí. K posouzení testwaru od AI je potřeba doménová a testovací odbornost (5.2.1)."},"kap":{"c":"5.2.1","nazev":"5.2.1 Dovednosti a znalosti pro testování s GenAI","href":"kapitola-5/vyklad.html#oddil-5-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.1-02","n":null,"lo":"GenAI-5.2.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Before using an approved LLM to analyze a batch of production-like logs, a tester replaces customer names, account numbers and e-mail addresses with placeholders.<\/p><p>Which knowledge area from the syllabus does this activity demonstrate, and why is it important?<\/p>","m":["Environmental considerations, because masked data requires fewer tokens and less energy","Assessing LLM capabilities, because placeholders test whether the model understands masked data","Prompt refinement, because placeholders make the prompt shorter and more precise","Data sanitization, because testers should understand the data security implications of sharing testware with LLMs and remove or mask sensitive information"],"vys":{"a":"Incorrect. Any token savings are a side effect; the reason for masking is data protection.","b":"Incorrect. The purpose of masking is protection of sensitive data, not capability assessment.","c":"Incorrect. Prompt refinement is about iteratively improving instructions, not about protecting data.","d":"Correct. Section 5.2.1 says testers should understand the data security implications of sharing testware with LLMs and implement data sanitization, removing or masking sensitive, personal or confidential information."},"obecne":"Data sanitization and privacy-preserving prompt engineering are essential knowledge for testers working with GenAI, even with approved tools (section 5.2.1)."},"cz":{"q":"<p>Než tester použije schválený LLM k analýze dávky logů podobných produkčním, nahradí jména zákazníků, čísla účtů a e-mailové adresy zástupnými hodnotami.<\/p><p>Kterou oblast znalostí ze sylabu tato činnost ukazuje a proč je důležitá?<\/p>","m":["Environmentální hledisko, protože maskovaná data potřebují méně tokenů a energie","Posouzení schopností LLM, protože zástupné hodnoty ověří, jestli model rozumí maskovaným datům","Zpřesňování promptů, protože zástupné hodnoty prompt zkrátí a zpřesní","Sanitizaci dat, protože tester má rozumět dopadům sdílení testwaru s LLM na bezpečnost dat a citlivé informace odstranit nebo zamaskovat"],"vys":{"a":"Špatně. Případná úspora tokenů je vedlejší efekt, důvodem maskování je ochrana dat.","b":"Špatně. Účelem maskování je ochrana citlivých dat, ne posouzení schopností.","c":"Špatně. Zpřesňování promptů je postupné zlepšování zadání, ne ochrana dat.","d":"Správně. Oddíl 5.2.1 říká, že tester má rozumět dopadům sdílení testwaru s LLM na bezpečnost dat a provádět sanitizaci, tedy odstranit nebo zamaskovat citlivé, osobní a důvěrné informace."},"obecne":"Sanitizace dat a prompty šetrné k soukromí jsou nutná znalost testera při práci s GenAI, i se schválenými nástroji (5.2.1)."},"kap":{"c":"5.2.1","nazev":"5.2.1 Dovednosti a znalosti pro testování s GenAI","href":"kapitola-5/vyklad.html#oddil-5-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.1-03","n":null,"lo":"GenAI-5.2.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A team uses the most powerful available LLM for every task, including reformatting short test step descriptions. Which essential consideration from the syllabus is the team MOST likely ignoring?<\/p>","m":["Selecting right-sized models for test tasks and balancing the benefits of GenAI automation with cost and energy consumption","Maintaining test-specific prompt libraries","Understanding inherent risks such as hallucinations","Defining transparency obligations for generated testware"],"vys":{"a":"Correct. Section 5.2.1 lists environmental considerations: optimizing model selection and usage patterns, selecting right-sized models and balancing benefits with cost and energy consumption.","b":"Incorrect. Prompt libraries are a tester task in section 5.2.3 and do not address the choice of model size.","c":"Incorrect. Risk awareness is important, but the situation describes over-sizing the model, which is an environmental and cost issue.","d":"Incorrect. Transparency obligations are part of process guidelines in 5.1.2 and are unrelated to model size."},"obecne":"Simple tasks do not need the largest model; right-sized models reduce computational overhead, cost and energy (section 5.2.1, linked to 3.3.1)."},"cz":{"q":"<p>Tým používá na každou úlohu nejsilnější dostupný LLM, včetně přeformátování krátkých popisů testovacích kroků. Které hledisko ze sylabu tým NEJSPÍŠ přehlíží?<\/p>","m":["Výběr modelů přiměřené velikosti pro testovací úlohy a vyvážení přínosů automatizace s náklady a spotřebou energie","Údržbu knihoven promptů specifických pro testování","Porozumění neoddělitelným rizikům, například halucinacím","Definici povinností transparentnosti pro vygenerovaný testware"],"vys":{"a":"Správně. Oddíl 5.2.1 uvádí environmentální hlediska: optimalizovat výběr a používání modelu, volit modely přiměřené velikosti a vyvažovat přínosy s náklady a spotřebou energie.","b":"Špatně. Knihovny promptů jsou úloha testera z 5.2.3 a volbu velikosti modelu neřeší.","c":"Špatně. Znalost rizik je důležitá, ale situace popisuje předimenzovaný model, což je otázka nákladů a energie.","d":"Špatně. Povinnosti transparentnosti patří k procesním pravidlům z 5.1.2 a s velikostí modelu nesouvisejí."},"obecne":"Jednoduché úlohy nepotřebují největší model. Modely přiměřené velikosti snižují výpočetní zátěž, náklady i energii (5.2.1, navazuje na 3.3.1)."},"kap":{"c":"5.2.1","nazev":"5.2.1 Dovednosti a znalosti pro testování s GenAI","href":"kapitola-5/vyklad.html#oddil-5-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.1-04","n":null,"lo":"GenAI-5.2.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following is an essential skill or knowledge area for testers working with GenAI according to the syllabus?<\/p>","m":["Guaranteeing that the LLM never produces reasoning errors in test tasks","Understanding the model's context window and developing methods to review AI-generated testware","Validating the training data that the LLM vendor used to build the model","Designing the neural network architecture of the LLM used by the team"],"vys":{"a":"Incorrect. Reasoning errors cannot be fully eliminated; the syllabus expects testers to know the risks and common mitigation strategies.","b":"Correct. Section 5.2.1 names mastering prompt engineering, understanding model context windows and developing test review methods.","c":"Incorrect. Testers usually have no access to the vendor's training data; section 5.2.1 focuses on assessing model capabilities and outputs.","d":"Incorrect. Designing model architecture is the work of model developers, not a tester skill in section 5.2.1."},"obecne":"Tester skills in 5.2.1 are about using models and judging their outputs: prompting, context windows, review methods, capability assessment, risk and data awareness, right-sized models."},"cz":{"q":"<p>Která z následujících možností je podle sylabu nutnou dovedností nebo oblastí znalostí testera pracujícího s GenAI?<\/p>","m":["Zaručit, že LLM v testovacích úlohách nikdy neudělá chybu v uvažování","Rozumět kontextovému oknu modelu a vytvořit si metody revize testwaru od AI","Ověřit trénovací data, která dodavatel LLM použil při tvorbě modelu","Navrhnout architekturu neuronové sítě LLM, který tým používá"],"vys":{"a":"Špatně. Chyby v uvažování nelze úplně odstranit. Sylabus chce, aby tester znal rizika a běžné způsoby zmírnění.","b":"Správně. Oddíl 5.2.1 jmenuje ovládání prompt engineeringu, porozumění kontextovému oknu a vytvoření metod revize testů.","c":"Špatně. Tester k trénovacím datům dodavatele obvykle nemá přístup. Oddíl 5.2.1 se zaměřuje na posouzení schopností a výstupů modelu.","d":"Špatně. Návrh architektury modelu je práce vývojářů modelu, ne dovednost testera podle 5.2.1."},"obecne":"Dovednosti testera v 5.2.1 se týkají používání modelů a posuzování výstupů: prompty, kontextové okno, metody revize, posouzení schopností, rizika a data, modely přiměřené velikosti."},"kap":{"c":"5.2.1","nazev":"5.2.1 Dovednosti a znalosti pro testování s GenAI","href":"kapitola-5/vyklad.html#oddil-5-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.1-05","n":null,"lo":"GenAI-5.2.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A tester's first prompt produces test cases that miss negative scenarios. The tester adds examples of invalid inputs and an explicit instruction to include boundary values, then compares the new output with the previous one.<\/p><p>Which key competency from the syllabus is the tester applying?<\/p>","m":["Data sanitization","Establishing AI governance frameworks","Prompt refinement","Selecting right-sized models"],"vys":{"a":"Incorrect. No sensitive data is being removed or masked.","b":"Incorrect. AI governance frameworks are a test manager responsibility in section 5.2.3.","c":"Correct. Section 5.2.1 lists understanding prompt refinement techniques as a key competency; improving the prompt step by step based on the output is exactly that.","d":"Incorrect. The tester is not changing the model, only the prompt."},"obecne":"Key competencies in 5.2.1: assessing LLM capabilities, prompt refinement and evaluation of AI-generated testware."},"cz":{"q":"<p>První prompt testera dá testovací případy bez negativních scénářů. Tester doplní příklady neplatných vstupů a výslovný pokyn zahrnout hraniční hodnoty. Pak porovná nový výstup s předchozím.<\/p><p>Kterou hlavní kompetenci ze sylabu tester uplatňuje?<\/p>","m":["Sanitizaci dat","Zavádění rámců pro správu a řízení AI","Zpřesňování promptů (prompt refinement)","Výběr modelů přiměřené velikosti"],"vys":{"a":"Špatně. Žádná citlivá data se neodstraňují ani nemaskují.","b":"Špatně. Rámce pro správu a řízení AI jsou podle 5.2.3 odpovědnost test manažera.","c":"Správně. Oddíl 5.2.1 uvádí porozumění technikám zpřesňování promptů jako hlavní kompetenci. Postupné vylepšování promptu podle výstupu je přesně to.","d":"Špatně. Tester nemění model, jen prompt."},"obecne":"Hlavní kompetence v 5.2.1: posouzení schopností LLM, zpřesňování promptů a hodnocení testwaru od AI."},"kap":{"c":"5.2.1","nazev":"5.2.1 Dovednosti a znalosti pro testování s GenAI","href":"kapitola-5/vyklad.html#oddil-5-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.2-01","n":null,"lo":"GenAI-5.2.2","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which of the following does the syllabus describe as a prompt pattern?<\/p>","m":["A log of all prompts sent by the team, kept for audit purposes","A sequence of prompts where each output becomes the next input","A hidden system prompt that the LLM vendor uses to set the model's behavior","A reusable template for crafting effective prompts to guide GenAI toward consistent and reliable outputs"],"vys":{"a":"Incorrect. A prompt log may be useful for auditing, but it is not the definition of a prompt pattern.","b":"Incorrect. This describes prompt chaining (section 2.1.2).","c":"Incorrect. This describes a system prompt (chapter 2), not a prompt pattern.","d":"Correct. Section 5.2.2 defines a prompt pattern as a reusable template for crafting effective prompts to guide GenAI toward consistent and reliable outputs."},"obecne":"Prompt patterns are part of building GenAI capabilities in test teams and are shared through prompt pattern libraries (section 5.2.2)."},"cz":{"q":"<p>Co z následujícího sylabus popisuje jako prompt pattern (vzor promptu)?<\/p>","m":["Záznam všech promptů, které tým poslal, uchovávaný pro audit","Posloupnost promptů, kde výstup jednoho je vstupem dalšího","Skrytý systémový prompt, kterým dodavatel LLM nastavuje chování modelu","Znovupoužitelnou šablonu pro tvorbu účinných promptů, která vede GenAI ke konzistentním a spolehlivým výstupům"],"vys":{"a":"Špatně. Záznam promptů se hodí pro audit, ale není definicí vzoru promptu.","b":"Špatně. To je popis řetězení promptů (2.1.2).","c":"Špatně. To je popis systémového promptu (kapitola 2), ne vzoru promptu.","d":"Správně. Oddíl 5.2.2 definuje vzor promptu jako znovupoužitelnou šablonu pro tvorbu účinných promptů, která vede GenAI ke konzistentním a spolehlivým výstupům."},"obecne":"Vzory promptů jsou součást budování GenAI schopností v týmu a sdílejí se v knihovnách vzorů promptů (5.2.2)."},"kap":{"c":"5.2.2","nazev":"5.2.2 Budování schopností GenAI v testovacích týmech","href":"kapitola-5/vyklad.html#oddil-5-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.2-02","n":null,"lo":"GenAI-5.2.2","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following activities is typical of an internal community of practice for GenAI in testing, as described in the syllabus?<\/p>","m":["Holding regular meetings to highlight successful GenAI applications, discuss challenges and share prompt pattern libraries","Approving the purchase of LLM licenses for each project","Replacing structured learning paths with informal discussions","Defining the legal requirements of the EU AI Act for the organization"],"vys":{"a":"Correct. Section 5.2.2 describes regular meetings to highlight successful GenAI applications, discuss challenges, refine best practices, share prompt pattern libraries and document lessons learned.","b":"Incorrect. License approval is a management or procurement decision, not a community of practice activity in section 5.2.2.","c":"Incorrect. Communities of practice complement structured learning paths; they do not replace them.","d":"Incorrect. Defining legal requirements is not a task of a community of practice."},"obecne":"Communities of practice support ongoing knowledge sharing and continuous improvement across projects and domains (section 5.2.2)."},"cz":{"q":"<p>Která z následujících činností je podle sylabu typická pro interní komunitu praxe pro GenAI v testování?<\/p>","m":["Pravidelná setkání, kde se ukazují úspěšná použití GenAI, probírají potíže a sdílejí knihovny vzorů promptů","Schvalování nákupu licencí LLM pro jednotlivé projekty","Nahrazení strukturovaných vzdělávacích cest neformálními diskusemi","Definice právních požadavků EU AI Act pro organizaci"],"vys":{"a":"Správně. Oddíl 5.2.2 popisuje pravidelná setkání, kde se ukazují úspěšná použití, probírají potíže, zpřesňují osvědčené postupy, sdílejí knihovny vzorů promptů a dokumentují poučení.","b":"Špatně. Schválení licencí je rozhodnutí vedení nebo nákupu, ne činnost komunity praxe podle 5.2.2.","c":"Špatně. Komunity praxe strukturované vzdělávací cesty doplňují, nenahrazují.","d":"Špatně. Definice právních požadavků není úkol komunity praxe."},"obecne":"Komunity praxe podporují průběžné sdílení znalostí a neustálé zlepšování napříč projekty a doménami (5.2.2)."},"kap":{"c":"5.2.2","nazev":"5.2.2 Budování schopností GenAI v testovacích týmech","href":"kapitola-5/vyklad.html#oddil-5-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.2-03","n":null,"lo":"GenAI-5.2.2","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>According to the syllabus, how do test team members typically progress when building GenAI skills?<\/p>","m":["From test-specific prompts to general-purpose chat conversations","From mastering basic prompt creation to using more focused techniques such as test-specific prompts","From fine-tuning LLMs to writing basic prompts","From fully autonomous AI agents to supervised AI assistants"],"vys":{"a":"Incorrect. The direction is reversed; progression goes towards test-specific prompts.","b":"Correct. Section 5.2.2 states that team members progress from mastering basic prompt creation to more focused techniques, such as test-specific prompts.","c":"Incorrect. The direction is reversed and fine-tuning is not described as the starting point.","d":"Incorrect. Section 5.2.2 describes progression in prompting skills, not in agent autonomy."},"obecne":"Skill progression goes from basic prompts to test-specific prompts, supported by prompt patterns (section 5.2.2)."},"cz":{"q":"<p>Jak se podle sylabu členové testovacího týmu typicky posouvají při budování GenAI dovedností?<\/p>","m":["Od promptů specifických pro testování k obecným konverzacím v chatu","Od zvládnutí základní tvorby promptů k cílenějším technikám, jako jsou prompty specifické pro testování","Od dolaďování LLM k psaní základních promptů","Od plně autonomních AI agentů k AI asistentům pod dohledem"],"vys":{"a":"Špatně. Směr je obrácený, postup vede k promptům specifickým pro testování.","b":"Správně. Oddíl 5.2.2 říká, že členové týmu postupují od zvládnutí základní tvorby promptů k cílenějším technikám, například promptům specifickým pro testování.","c":"Špatně. Směr je obrácený a doladění se jako výchozí bod nepopisuje.","d":"Špatně. Oddíl 5.2.2 popisuje posun v dovednostech promptování, ne v autonomii agentů."},"obecne":"Dovednosti rostou od základních promptů k promptům specifickým pro testování, s oporou ve vzorech promptů (5.2.2)."},"kap":{"c":"5.2.2","nazev":"5.2.2 Budování schopností GenAI v testovacích týmech","href":"kapitola-5/vyklad.html#oddil-5-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.2-04","n":null,"lo":"GenAI-5.2.2","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following is a strategy for cultivating GenAI skills in test teams that is described in the syllabus?<\/p>","m":["Standardizing on a single LLM and training testers only on its user interface","Assigning all GenAI work to one expert so that others do not need training","Practicing with various LLMs/SLMs as part of a hands-on approach","Delaying any practical use until all testers have passed a theoretical exam"],"vys":{"a":"Incorrect. The syllabus recommends practicing with various LLMs/SLMs, not training on a single tool's interface.","b":"Incorrect. The syllabus emphasizes sharing know-how within the organization and peer learning.","c":"Correct. Section 5.2.2 says a hands-on approach is essential and includes practicing with various LLMs/SLMs.","d":"Incorrect. The syllabus emphasizes practical skills and gradual integration into daily work, not theory first."},"obecne":"Section 5.2.2: hands-on approach, various LLMs/SLMs, structured learning paths, sharing, guided exercises, peer learning, gradual integration, prompt patterns, communities of practice."},"cz":{"q":"<p>Která z následujících možností je strategií pro pěstování GenAI dovedností v testovacích týmech popsanou v sylabu?<\/p>","m":["Standardizace na jeden LLM a školení testerů jen na jeho uživatelské rozhraní","Přidělení veškeré práce s GenAI jednomu expertovi, aby ostatní nepotřebovali školení","Praxe s různými LLM/SLM jako součást praktického přístupu","Odložení praktického použití, dokud všichni testeři nesloží teoretickou zkoušku"],"vys":{"a":"Špatně. Sylabus doporučuje praxi s různými modely, ne školení na rozhraní jednoho nástroje.","b":"Špatně. Sylabus zdůrazňuje sdílení know-how v organizaci a učení od kolegů.","c":"Správně. Oddíl 5.2.2 říká, že praktický přístup je nezbytný a zahrnuje praxi s různými LLM/SLM.","d":"Špatně. Sylabus zdůrazňuje praktické dovednosti a postupné zapojení do každodenní práce, ne nejdřív teorii."},"obecne":"Oddíl 5.2.2: praktický přístup, různé LLM/SLM, strukturované vzdělávací cesty, sdílení, řízená cvičení, peer learning, postupné zapojení, vzory promptů, komunity praxe."},"kap":{"c":"5.2.2","nazev":"5.2.2 Budování schopností GenAI v testovacích týmech","href":"kapitola-5/vyklad.html#oddil-5-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.2-05","n":null,"lo":"GenAI-5.2.2","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A test lead wants to develop GenAI skills in a team of twelve testers. Which plan BEST reflects the strategies recalled in the syllabus?<\/p>","m":["Introduce GenAI into all test tasks on the same day so that the team learns under real pressure","Let each tester experiment freely with any public tool and keep successful prompts private","Send the team to a single theory lecture and then measure productivity","Follow a structured learning path with guided exercises and peer learning, and integrate AI into daily test tasks gradually"],"vys":{"a":"Incorrect. The syllabus calls for gradual integration of AI into daily test tasks, not all at once.","b":"Incorrect. Unstructured experimenting with public tools risks shadow AI, and keeping prompts private contradicts knowledge sharing.","c":"Incorrect. A single theory lecture does not provide the hands-on practice that section 5.2.2 calls essential.","d":"Correct. Section 5.2.2 lists structured learning paths, guided exercises, peer learning and gradual integration of AI into daily test tasks."},"obecne":"Capability building is hands-on, structured, gradual and shared (section 5.2.2)."},"cz":{"q":"<p>Vedoucí testů chce rozvinout GenAI dovednosti v týmu dvanácti testerů. Který plán NEJLÉPE odpovídá strategiím ze sylabu?<\/p>","m":["Zavést GenAI do všech testovacích úloh ve stejný den, aby se tým učil pod skutečným tlakem","Nechat každého testera volně experimentovat s libovolným veřejným nástrojem a úspěšné prompty si nechat pro sebe","Poslat tým na jednu teoretickou přednášku a pak měřit produktivitu","Postupovat podle strukturované vzdělávací cesty s řízenými cvičeními a učením od kolegů a zapojovat AI do každodenních úloh postupně"],"vys":{"a":"Špatně. Sylabus chce postupné zapojení AI do každodenních úloh, ne všechno najednou.","b":"Špatně. Nestrukturované experimenty s veřejnými nástroji vedou ke stínové AI a nesdílení promptů odporuje sdílení znalostí.","c":"Špatně. Jedna teoretická přednáška neposkytne praktickou zkušenost, kterou 5.2.2 označuje za nezbytnou.","d":"Správně. Oddíl 5.2.2 uvádí strukturované vzdělávací cesty, řízená cvičení, učení od kolegů a postupné zapojení AI do každodenních úloh."},"obecne":"Budování schopností je praktické, strukturované, postupné a sdílené (5.2.2)."},"kap":{"c":"5.2.2","nazev":"5.2.2 Budování schopností GenAI v testovacích týmech","href":"kapitola-5/vyklad.html#oddil-5-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.3-01","n":null,"lo":"GenAI-5.2.3","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following is identified in the syllabus as an expanded task of testers in an AI-enabled test organization?<\/p>","m":["Maintaining test-specific prompt libraries","Establishing AI governance frameworks for use cases","Coordinating GenAI-powered test agents in hybrid teams","Developing an AI-based test strategy for the organization"],"vys":{"a":"Correct. Section 5.2.3 states that testers' tasks expand to include review of the overall AI-based output, prompt refinement and maintenance of test-specific prompt libraries.","b":"Incorrect. Establishing AI governance frameworks is a test manager responsibility in section 5.2.3.","c":"Incorrect. Coordinating GenAI-powered test agents and hybrid teams is described for test managers in section 5.2.3.","d":"Incorrect. Developing an AI-based test strategy is a test manager responsibility in section 5.2.3."},"obecne":"Testers: review AI output, refine prompts, maintain prompt libraries. Test managers: strategy, risk management, monitoring and control, governance, hybrid teams (section 5.2.3)."},"cz":{"q":"<p>Která z následujících možností je podle sylabu rozšířenou úlohou testerů v testovací organizaci podporované AI?<\/p>","m":["Údržba knihoven promptů specifických pro testování","Zavádění rámců pro správu a řízení AI pro jednotlivé případy použití","Koordinace testovacích agentů poháněných GenAI v hybridních týmech","Vytvoření testovací strategie organizace založené na AI"],"vys":{"a":"Správně. Oddíl 5.2.3 říká, že úlohy testerů se rozšiřují o revizi celkového AI výstupu, zpřesňování promptů a údržbu knihoven promptů specifických pro testování.","b":"Špatně. Zavádění rámců pro správu AI je podle 5.2.3 odpovědnost test manažera.","c":"Špatně. Koordinace GenAI agentů a hybridních týmů je v 5.2.3 popsaná u test manažerů.","d":"Špatně. Vytvoření testovací strategie založené na AI je podle 5.2.3 odpovědnost test manažera."},"obecne":"Testeři: revize AI výstupu, zpřesňování promptů, knihovny promptů. Test manažeři: strategie, řízení rizik, monitoring a řízení, governance, hybridní týmy (5.2.3)."},"kap":{"c":"5.2.3","nazev":"5.2.3 Vývoj testovacích procesů v organizaci podporované AI","href":"kapitola-5/vyklad.html#oddil-5-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.3-02","n":null,"lo":"GenAI-5.2.3","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following is a new responsibility of test managers when a test organization adopts GenAI, according to the syllabus?<\/p>","m":["Writing all prompts for the test team personally","AI-based risk management","Replacing human test reviews with automated AI reviews","Retraining the foundation model on the organization's data"],"vys":{"a":"Incorrect. Prompt refinement and prompt libraries are tester tasks; the manager does not write all prompts.","b":"Correct. Section 5.2.3 lists the development of an AI-based test strategy, AI-based risk management, and monitoring and control of AI-based test processes as updated test manager responsibilities.","c":"Incorrect. The syllabus emphasizes balancing human and AI capabilities and review of AI output, not replacing human review.","d":"Incorrect. Retraining a foundation model is not a test manager responsibility in section 5.2.3."},"obecne":"Test manager additions: AI-based test strategy, AI-based risk management, monitoring and control of AI-based test processes (section 5.2.3)."},"cz":{"q":"<p>Která z následujících možností je podle sylabu novou odpovědností test manažera, když testovací organizace zavádí GenAI?<\/p>","m":["Osobně psát všechny prompty pro testovací tým","Řízení rizik spojených s AI (AI-based risk management)","Nahradit lidské revize testů automatickými revizemi AI","Přetrénovat základní model na datech organizace"],"vys":{"a":"Špatně. Zpřesňování promptů a knihovny promptů jsou úlohy testerů, manažer nepíše všechny prompty.","b":"Správně. Oddíl 5.2.3 uvádí jako rozšířené odpovědnosti test manažera vytvoření testovací strategie založené na AI, řízení rizik spojených s AI a monitoring a řízení testovacích procesů založených na AI.","c":"Špatně. Sylabus zdůrazňuje rovnováhu lidí a AI a revizi AI výstupu, ne nahrazení lidské revize.","d":"Špatně. Přetrénování základního modelu není podle 5.2.3 odpovědnost test manažera."},"obecne":"Nové u test manažera: strategie založená na AI, řízení rizik AI, monitoring a řízení AI procesů (5.2.3)."},"kap":{"c":"5.2.3","nazev":"5.2.3 Vývoj testovacích procesů v organizaci podporované AI","href":"kapitola-5/vyklad.html#oddil-5-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.3-03","n":null,"lo":"GenAI-5.2.3","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>How does the syllabus describe the evolution of the tester role in an AI-enabled test organization?<\/p>","m":["Testers evolve into test managers responsible for hybrid teams","Testers evolve from AI-assisted test specialists back into manual test execution specialists","Testers evolve from test design and test execution specialists into AI-assisted test specialists","Testers evolve into LLM developers who train models for test tasks"],"vys":{"a":"Incorrect. Leading hybrid teams is described as a test manager responsibility.","b":"Incorrect. The direction is reversed.","c":"Correct. Section 5.2.3 states that testers evolve from test design and test execution specialists to AI-assisted test specialists, combining test technique expertise with skills to guide and verify AI-generated testware.","d":"Incorrect. Training models is not described as the new tester role."},"obecne":"The tester becomes an AI-assisted test specialist who still needs test techniques (section 5.2.3)."},"cz":{"q":"<p>Jak sylabus popisuje vývoj role testera v testovací organizaci podporované AI?<\/p>","m":["Testeři se stávají test manažery odpovědnými za hybridní týmy","Testeři se mění ze specialistů na testování s podporou AI zpět na specialisty na ruční provádění testů","Testeři se mění ze specialistů na návrh a provádění testů na specialisty na testování s podporou AI","Testeři se stávají vývojáři LLM, kteří trénují modely pro testovací úlohy"],"vys":{"a":"Špatně. Vedení hybridních týmů je popsané jako odpovědnost test manažera.","b":"Špatně. Směr je obrácený.","c":"Správně. Oddíl 5.2.3 říká, že testeři se mění ze specialistů na návrh a provádění testů na specialisty na testování s podporou AI, kteří spojují testovací techniky s vedením a ověřováním testwaru od AI.","d":"Špatně. Trénování modelů se jako nová role testera nepopisuje."},"obecne":"Tester se stává specialistou na testování s podporou AI, testovací techniky přitom dál potřebuje (5.2.3)."},"kap":{"c":"5.2.3","nazev":"5.2.3 Vývoj testovacích procesů v organizaci podporované AI","href":"kapitola-5/vyklad.html#oddil-5-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.3-04","n":null,"lo":"GenAI-5.2.3","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which of the following BEST reflects what the syllabus says test managers must ensure about the competencies of their test teams?<\/p>","m":["Teams delegate AI literacy to a separate data science department","Teams focus exclusively on AI literacy, because traditional testing competencies become obsolete","Teams focus exclusively on traditional testing competencies, because AI tools are managed by vendors","Teams maintain both traditional testing competencies and AI literacy"],"vys":{"a":"Incorrect. AI literacy is expected within the test team, not delegated elsewhere.","b":"Incorrect. The syllabus does not say traditional competencies become obsolete; testers still need test techniques.","c":"Incorrect. The syllabus explicitly requires AI literacy as well.","d":"Correct. Section 5.2.3 states that test managers ensure their teams maintain both traditional testing competencies and AI literacy."},"obecne":"Balance is the theme of 5.2.3: human and AI capabilities, traditional competencies and AI literacy."},"cz":{"q":"<p>Co NEJLÉPE vystihuje, co má podle sylabu test manažer zajistit ohledně kompetencí svého týmu?<\/p>","m":["Tým přenechá AI gramotnost samostatnému oddělení datové vědy","Tým se zaměří jen na AI gramotnost, protože tradiční testovací kompetence zastarávají","Tým se zaměří jen na tradiční testovací kompetence, protože AI nástroje spravují dodavatelé","Tým si udrží tradiční testovací kompetence i AI gramotnost"],"vys":{"a":"Špatně. AI gramotnost se očekává přímo v testovacím týmu, ne jinde.","b":"Špatně. Sylabus netvrdí, že tradiční kompetence zastarávají, testeři testovací techniky dál potřebují.","c":"Špatně. Sylabus výslovně požaduje i AI gramotnost.","d":"Správně. Oddíl 5.2.3 říká, že test manažer zajišťuje, aby tým měl tradiční testovací kompetence i AI gramotnost."},"obecne":"Tématem 5.2.3 je rovnováha: schopnosti lidí a AI, tradiční kompetence a AI gramotnost."},"kap":{"c":"5.2.3","nazev":"5.2.3 Vývoj testovacích procesů v organizaci podporované AI","href":"kapitola-5/vyklad.html#oddil-5-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.3-05","n":null,"lo":"GenAI-5.2.3","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>According to the syllabus, why will test managers need new management skills in AI-enabled test organizations?<\/p>","m":["Because test managers will lead not only human testers but also coordinate GenAI-powered test agents in hybrid teams","Because test managers will no longer be responsible for monitoring and control","Because test managers will have to understand the internal mathematics of transformer models","Because test managers will be replaced by GenAI-powered test agents"],"vys":{"a":"Correct. Section 5.2.3 states that test managers will lead human testers and coordinate GenAI-powered test agents, requiring new skills for overseeing hybrid teams of people and GenAI tools.","b":"Incorrect. Monitoring and control of AI-based test processes is explicitly added to test manager responsibilities.","c":"Incorrect. Understanding the internal mathematics of models is not described as a test manager need.","d":"Incorrect. The syllabus describes coordination of agents by managers, not replacement of managers."},"obecne":"Hybrid teams of people and GenAI tools require new management skills (section 5.2.3)."},"cz":{"q":"<p>Proč budou test manažeři v testovacích organizacích podporovaných AI podle sylabu potřebovat nové manažerské dovednosti?<\/p>","m":["Protože test manažeři budou vést nejen lidské testery, ale budou i koordinovat testovací agenty poháněné GenAI v hybridních týmech","Protože test manažeři už nebudou odpovídat za monitoring a řízení","Protože test manažeři budou muset rozumět vnitřní matematice transformerových modelů","Protože test manažery nahradí testovací agenti pohánění GenAI"],"vys":{"a":"Správně. Oddíl 5.2.3 říká, že test manažeři povedou lidi a budou koordinovat testovací agenty poháněné GenAI, což vyžaduje nové dovednosti pro hybridní týmy lidí a nástrojů GenAI.","b":"Špatně. Monitoring a řízení testovacích procesů založených na AI do odpovědností test manažera výslovně přibývá.","c":"Špatně. Porozumění vnitřní matematice modelů se jako potřeba test manažera nepopisuje.","d":"Špatně. Sylabus popisuje, že manažeři agenty koordinují, ne že je agenti nahradí."},"obecne":"Hybridní týmy lidí a nástrojů GenAI vyžadují nové manažerské dovednosti (5.2.3)."},"kap":{"c":"5.2.3","nazev":"5.2.3 Vývoj testovacích procesů v organizaci podporované AI","href":"kapitola-5/vyklad.html#oddil-5-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"A-01","n":1,"lo":"GenAI-1.1.1","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Match each type of AI technology (1-4) with its CORRECT description (A-D):<\/p><ul><li>1. Symbolic AI<\/li><li>2. Classical machine learning<\/li><li>3. Deep learning<\/li><li>4. Generative AI<\/li><\/ul><ul><li>A. Uses neural networks to automatically learn features from data.<\/li><li>B. Uses rule-based systems to mimic human decision-making.<\/li><li>C. Uses deep learning to create new data by learning from its training data.<\/li><li>D. Uses a data-driven approach that requires feature selection.<\/li><\/ul>","m":["1D, 2B, 3A, 4C","1D, 2C, 3B, 4A","1C, 2B, 3D, 4A","1B, 2D, 3A, 4C"],"vys":{"a":"Is not correct.","b":"Is not correct.","c":"Is not correct.","d":"Is correct."},"obecne":"<p>Considering:<\/p><ul><li>Symbolic AI uses a rule-based system to mimic human decision-making, representing knowledge using symbols and logical rules (1B).<\/li><li>Classical machine learning uses a data-driven approach that requires data preparation, feature selection and model training (2D).<\/li><li>Deep learning uses neural networks (machine learning structures) to automatically learn features from data (3A).<\/li><li>Generative AI uses deep learning techniques to create new data by learning and mimicking patterns from its training data (4C).<\/li><\/ul>"},"cz":{"q":"<p>Přiřaď každý typ AI technologie (1–4) k jeho SPRÁVNÉMU popisu (A–D):<\/p><ul><li>1. Symbolická AI (symbolic AI)<\/li><li>2. Klasické strojové učení (classical machine learning)<\/li><li>3. Hluboké učení (deep learning)<\/li><li>4. Generativní AI (generative AI)<\/li><\/ul><ul><li>A. Používá neuronové sítě k automatickému učení příznaků (features) z dat.<\/li><li>B. Používá systémy založené na pravidlech k napodobení lidského rozhodování.<\/li><li>C. Používá hluboké učení k vytváření nových dat učením se z trénovacích dat.<\/li><li>D. Používá přístup řízený daty, který vyžaduje výběr příznaků (feature selection).<\/li><\/ul>","m":["1D, 2B, 3A, 4C","1D, 2C, 3B, 4A","1C, 2B, 3D, 4A","1B, 2D, 3A, 4C"],"vys":{"a":"Není správně.","b":"Není správně.","c":"Není správně.","d":"Je správně."},"obecne":"<p>Platí:<\/p><ul><li>Symbolická AI používá systém pravidel k napodobení lidského rozhodování; znalosti reprezentuje symboly a logickými pravidly (1B).<\/li><li>Klasické strojové učení je přístup řízený daty, který vyžaduje přípravu dat, výběr příznaků a trénování modelu (2D).<\/li><li>Hluboké učení používá neuronové sítě (struktury strojového učení) k automatickému učení příznaků z dat (3A).<\/li><li>Generativní AI používá techniky hlubokého učení k vytváření nových dat tím, že se učí a napodobuje vzory z trénovacích dat (4C).<\/li><\/ul>"},"kap":{"c":"1.1.1","nazev":"1.1.1 Spektrum AI: symbolická AI, klasické strojové učení, hluboké učení a generativní AI","href":"kapitola-1/vyklad.html#oddil-1-1-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-02","n":2,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Consider the realm of Large Language Models (LLMs). Which of the following options BEST explains why context window limitations affect LLM’s text processing capabilities?<\/p>","m":["Because context windows restrict temporal processing sequences, preventing LLMs from maintaining chronological consistency across extended text analysis.","Because context windows prevent cross-referencing capabilities, limiting LLMs’ ability to connect information across different document sources simultaneously.","Because context windows force LLMs to discard earlier information, which may contain relevant details needed for understanding later content.","Because context windows constrain parsing granularity levels, restricting LLMs from adjusting between character-level and document-level analysis approaches."],"vys":{"a":"Is not correct because context windows do not control temporal sequencing but limit the scope of text that can be simultaneously considered.","b":"Is not correct because context windows affect scope within the current input, not cross-document referencing capabilities.","c":"Is correct. When text exceeds the context window size, the model cannot simultaneously consider all parts of the document. As the model processes new tokens, it must effectively “forget” or discard tokens that fall outside its context window boundary.","d":"Is not correct because context windows do not determine parsing approaches but limit the amount of text that can be processed simultaneously."},"obecne":""},"cz":{"q":"<p>Uvažujme o oblasti velkých jazykových modelů (LLM). Která z následujících možností NEJLÉPE vysvětluje, proč omezení kontextového okna (context window) ovlivňuje schopnost LLM zpracovávat text?<\/p>","m":["Protože kontextová okna omezují časové sekvence zpracování, a LLM tak nedokáže udržet chronologickou konzistenci při rozsáhlé analýze textu.","Protože kontextová okna znemožňují křížové odkazování, a omezují tak schopnost LLM propojovat informace z různých zdrojových dokumentů současně.","Protože kontextová okna nutí LLM zahodit dřívější informace, které mohou obsahovat podstatné detaily potřebné k pochopení pozdějšího obsahu.","Protože kontextová okna omezují úroveň granularity parsování, a LLM tak nemůže přepínat mezi analýzou na úrovni znaků a na úrovni dokumentu."],"vys":{"a":"Není správně, protože kontextové okno neřídí časové pořadí, ale omezuje rozsah textu, který model může vzít v úvahu najednou.","b":"Není správně, protože kontextové okno ovlivňuje rozsah v rámci aktuálního vstupu, ne schopnost odkazovat mezi dokumenty.","c":"Je správně. Když text přesáhne velikost kontextového okna, model nemůže vzít v úvahu všechny části dokumentu současně. Při zpracování nových tokenů musí tokeny za hranicí okna v podstatě „zapomenout“ neboli zahodit.","d":"Není správně, protože kontextové okno neurčuje způsob parsování, ale omezuje množství textu, které lze zpracovat najednou."},"obecne":""},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-03","n":3,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following statements BEST describes tokenization in processing text for LLMs?<\/p>","m":["Tokenization converts tokens into high-dimensional vectors to capture their meaning.","Tokenization creates the building blocks used to understand and generate text.","Tokenization generates contextually appropriate responses using neural networks.","Tokenization predicts the next token in a sequence based on learned relationships."],"vys":{"a":"Is not correct. This describes embeddings, not tokenization.","b":"Is correct. Tokenization involves splitting text into smaller units (tokens) that represent the building blocks of natural language generation tasks and enable LLMs to understand and generate text. See also the definition of “Tokenization” in the syllabus (see “Appendix D – Generative AI Specific Terms”).","c":"Is not correct. This describes the general function of LLMs, not tokenization.","d":"Is not correct. This refers to how LLMs generate text, not tokenization."},"obecne":""},"cz":{"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje tokenizaci (tokenization) při zpracování textu v LLM?<\/p>","m":["Tokenizace převádí tokeny na vysokorozměrné vektory, které zachycují jejich význam.","Tokenizace vytváří stavební bloky, pomocí kterých model text chápe a generuje.","Tokenizace generuje kontextově vhodné odpovědi pomocí neuronových sítí.","Tokenizace předpovídá další token v sekvenci na základě naučených vztahů."],"vys":{"a":"Není správně. To popisuje embeddingy (embeddings), ne tokenizaci.","b":"Je správně. Tokenizace rozděluje text na menší jednotky (tokeny), které jsou stavebními bloky při generování přirozeného jazyka a umožňují LLM text chápat a generovat. Viz také definici „Tokenization“ v sylabu (Appendix D – Generative AI Specific Terms).","c":"Není správně. To popisuje obecnou funkci LLM, ne tokenizaci.","d":"Není správně. To se týká způsobu, jakým LLM generuje text, ne tokenizace."},"obecne":""},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-04","n":4,"lo":"GenAI-1.1.3","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>In the context of software testing, which of the following statements (i-v) about foundation, instruction-tuned, and reasoning LLMs are CORRECT?<\/p><ul><li>i. Foundation LLMs excel at generating test cases from high-level requirements without structured input.<\/li><li>ii. Reasoning LLMs excel at creating test scripts that strictly follow predefined organizational templates.<\/li><li>iii. Instruction-tuned LLMs excel at autonomously prioritizing test execution based on real-time user feedback.<\/li><li>iv. Reasoning LLMs excel at synthesizing data from defect reports to detect trends and prioritize test efforts.<\/li><li>v. Instruction-tuned LLMs excel at generating test cases that adhere to Gherkin language syntax.<\/li><\/ul>","m":["i, ii, and iii","ii, iii, and iv","i, ii, and v","iv, and v"],"vys":{"a":"Is not correct.","b":"Is not correct.","c":"Is not correct.","d":"Is correct."},"obecne":"<p>Considering:<\/p><ul><li>i. Is not correct. While foundation LLMs can generate test cases, they do not inherently “excel” at this task without structured input. Generating test cases without structured input misrepresents their capabilities.<\/li><li>ii. Is not correct. Creating template-based test scripts requires executing explicit instructions, which is the role of instruction-tuned LLMs, not reasoning LLMs. Reasoning LLMs specialize in logical inference and problem-solving, not rigid template adherence.<\/li><li>iii. Is not correct. Instruction-tuned LLMs are designed to follow structured prompts, not make autonomous decisions. Prioritizing tests based on feedback requires reasoning, which is beyond their scope.<\/li><li>iv. Is correct. Reasoning LLMs are explicitly designed for synthesizing multiple data sources and performing logical inference, problem-solving, and decision-making. Detecting trends and prioritizing test efforts aligns with their role in contextual analysis and the description provided.<\/li><li>v. Is correct. Instruction-tuned LLMs are specifically trained to follow instructions, including adhering to requested formats, styles, and syntax rules. Generating test cases conforming to Gherkin language syntax, is a task well-suited to their capabilities.<\/li><\/ul>"},"cz":{"q":"<p>Která z následujících tvrzení (i–v) o základních (foundation), na instrukce vyladěných (instruction-tuned) a uvažujících (reasoning) LLM jsou v kontextu testování softwaru SPRÁVNÁ?<\/p><ul><li>i. Základní LLM vynikají v generování testovacích případů z vysokoúrovňových požadavků bez strukturovaného vstupu.<\/li><li>ii. Uvažující LLM vynikají ve vytváření testovacích skriptů, které striktně dodržují předem definované šablony organizace.<\/li><li>iii. LLM vyladěné na instrukce vynikají v autonomní prioritizaci provádění testů na základě zpětné vazby uživatelů v reálném čase.<\/li><li>iv. Uvažující LLM vynikají ve slučování dat z reportů o defektech, v odhalování trendů a v prioritizaci testovacího úsilí.<\/li><li>v. LLM vyladěné na instrukce vynikají v generování testovacích případů, které dodržují syntaxi jazyka Gherkin.<\/li><\/ul>","m":["i, ii a iii","ii, iii a iv","i, ii a v","iv a v"],"vys":{"a":"Není správně.","b":"Není správně.","c":"Není správně.","d":"Je správně."},"obecne":"<p>Platí:<\/p><ul><li>i. Není správně. Základní LLM sice testovací případy generovat umí, ale bez strukturovaného vstupu v tom „nevynikají“. Tvrzení jejich schopnosti zkresluje.<\/li><li>ii. Není správně. Skripty podle šablony vyžadují plnění explicitních instrukcí, a to je úloha LLM vyladěných na instrukce, ne uvažujících LLM. Uvažující LLM se specializují na logické vyvozování a řešení problémů, ne na striktní dodržení šablony.<\/li><li>iii. Není správně. LLM vyladěné na instrukce jsou navržené k plnění strukturovaných promptů, ne k autonomnímu rozhodování. Prioritizace testů podle zpětné vazby vyžaduje uvažování, což je nad jejich rámec.<\/li><li>iv. Je správně. Uvažující LLM jsou navržené ke slučování více zdrojů dat, logickému vyvozování, řešení problémů a rozhodování. Odhalování trendů a prioritizace testovacího úsilí odpovídá jejich roli při kontextové analýze.<\/li><li>v. Je správně. LLM vyladěné na instrukce jsou trénované k plnění instrukcí včetně požadovaného formátu, stylu a syntaxe. Generování testovacích případů v syntaxi Gherkin jim dobře odpovídá.<\/li><\/ul>"},"kap":{"c":"1.1.3","nazev":"1.1.3 Základní, instrukční a uvažující LLM","href":"kapitola-1/vyklad.html#oddil-1-1-3"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-05","n":5,"lo":"GenAI-1.1.4","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following statements BEST describes the relation between multimodal LLMs and vision-language models?<\/p>","m":["Multimodal LLMs are a subset of vision-language models designed to handle diverse inputs.","Vision-language models are a subset of multimodal LLMs focusing on visual and textual data.","Vision-language models are unrelated to multimodal LLMs and focus only on the user interface.","Multimodal LLMs and vision-language models are interchangeable terms."],"vys":{"a":"Is not correct. Vision-language models are a subset of multimodal LLMs, not the reverse.","b":"Is correct. Vision-language models specifically integrate visual and textual data, making them a subset of multimodal LLMs.","c":"Is not correct. Vision-language models are closely related to multimodal LLMs and focus on both visual and textual data.","d":"Is not correct. Multimodal LLMs and vision-language models have distinct scopes and are not interchangeable."},"obecne":""},"cz":{"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje vztah mezi multimodálními LLM (multimodal LLMs) a modely pro obraz a jazyk (vision-language models)?<\/p>","m":["Multimodální LLM jsou podmnožinou modelů pro obraz a jazyk, navrženou pro zpracování různorodých vstupů.","Modely pro obraz a jazyk jsou podmnožinou multimodálních LLM a zaměřují se na obrazová a textová data.","Modely pro obraz a jazyk nemají s multimodálními LLM nic společného a zaměřují se jen na uživatelské rozhraní.","Multimodální LLM a modely pro obraz a jazyk jsou zaměnitelné pojmy."],"vys":{"a":"Není správně. Modely pro obraz a jazyk jsou podmnožinou multimodálních LLM, ne naopak.","b":"Je správně. Modely pro obraz a jazyk spojují obrazová a textová data, a jsou proto podmnožinou multimodálních LLM.","c":"Není správně. Modely pro obraz a jazyk s multimodálními LLM úzce souvisejí a zaměřují se na obrazová i textová data.","d":"Není správně. Oba pojmy mají jiný rozsah a nejsou zaměnitelné."},"obecne":""},"kap":{"c":"1.1.4","nazev":"1.1.4 Multimodální LLM a modely pro obraz a jazyk","href":"kapitola-1/vyklad.html#oddil-1-1-4"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-06","n":6,"lo":"GenAI-1.2.1","k":"K2","body":1,"vyber":2,"ok":[0,4],"en":{"q":"<p>Which TWO of the following options represent key capabilities of LLMs in test tasks?<\/p>","m":["Identifying ambiguities and inconsistencies in requirements.","Generating complete application code for deployment.","Automating the execution of all test scripts without human intervention.","Performing exploratory testing on software applications.","Creating diverse test data with various combinations and boundary values."],"vys":{"a":"Is correct. LLMs can analyze and clarify requirements by identifying ambiguities and inconsistencies.","b":"Is not correct. Generating complete application code is not a key capability of LLMs in test tasks.","c":"Is not correct. LLMs can support test automation by suggesting improvements to test scripts and identifying design patterns but do not directly execute test scripts or fully automate test scripts without human oversight.","d":"Is not correct. LLMs cannot perform manual exploratory testing because it is an intuitive and adaptive process that requires human creativity, experience, and decision-making.","e":"Is correct. LLMs can generate diverse test data, including combinations and boundaries."},"obecne":""},"cz":{"q":"<p>Které DVĚ z následujících možností představují klíčové schopnosti LLM při testovacích úlohách?<\/p>","m":["Identifikace nejednoznačností a nekonzistencí v požadavcích.","Generování kompletního kódu aplikace k nasazení.","Automatizace provádění všech testovacích skriptů bez lidského zásahu.","Provádění exploratorního testování softwarových aplikací.","Vytváření různorodých testovacích dat s různými kombinacemi a hraničními hodnotami."],"vys":{"a":"Je správně. LLM umí analyzovat a zpřesňovat požadavky tím, že v nich najde nejednoznačnosti a nekonzistence.","b":"Není správně. Generování kompletního kódu aplikace není klíčovou schopností LLM v testovacích úlohách.","c":"Není správně. LLM mohou podporovat automatizaci testů návrhy na zlepšení skriptů a identifikací návrhových vzorů, ale skripty přímo neprovádějí ani je plně neautomatizují bez lidského dohledu.","d":"Není správně. LLM nemohou provádět manuální exploratorní testování, protože je to intuitivní a adaptivní proces, který vyžaduje lidskou kreativitu, zkušenost a rozhodování.","e":"Je správně. LLM umí generovat různorodá testovací data včetně kombinací a hraničních hodnot."},"obecne":""},"kap":{"c":"1.2.1","nazev":"1.2.1 Hlavní schopnosti LLM pro testovací úlohy","href":"kapitola-1/vyklad.html#oddil-1-2-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-07","n":7,"lo":"GenAI-1.2.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which of the following statements BEST explains the difference between AI chatbots and LLM-powered testing applications in the context of software testing?<\/p>","m":["AI chatbots are more suited for specific test tasks, while LLM-powered testing applications focus on ad hoc interactions.","Both AI chatbots and LLM-powered testing applications are designed to perform identical tasks without any configuration differences.","LLM-powered testing applications rely on conversational prompts, while AI chatbots require integration into test tools and test processes.","AI chatbots offer conversational interfaces for ad hoc test tasks, while LLM-powered testing applications provide customized solutions for specific test tasks."],"vys":{"a":"Is not correct. AI chatbots are best suited for ad hoc interactions, not specific test tasks.","b":"Is not correct. AI chatbots and LLM-powered testing applications have distinct purposes and are not identical in functionality or configurability.","c":"Is not correct. LLM-powered testing applications focus on integration into test processes, not conversational prompts. AI chatbots do not require integration into test tools and into test processes because their primary function is to facilitate ad hoc interactions rather than performing specific test tasks.","d":"Is correct. AI chatbots provide conversational interfaces for ad hoc tasks, while LLM-powered testing applications deliver customized solutions for specific needs."},"obecne":""},"cz":{"q":"<p>Které z následujících tvrzení NEJLÉPE vysvětluje rozdíl mezi AI chatboty a testovacími aplikacemi postavenými na LLM (LLM-powered testing applications) v kontextu testování softwaru?<\/p>","m":["AI chatboti se lépe hodí pro konkrétní testovací úlohy, zatímco testovací aplikace postavené na LLM se zaměřují na ad hoc interakce.","AI chatboti i testovací aplikace postavené na LLM jsou navrženi k plnění stejných úloh bez jakýchkoli rozdílů v konfiguraci.","Testovací aplikace postavené na LLM spoléhají na konverzační prompty, zatímco AI chatboti vyžadují integraci do testovacích nástrojů a procesů testování.","AI chatboti nabízejí konverzační rozhraní pro ad hoc testovací úlohy, zatímco testovací aplikace postavené na LLM poskytují řešení přizpůsobená konkrétním testovacím úlohám."],"vys":{"a":"Není správně. AI chatboti se nejlépe hodí pro ad hoc interakce, ne pro konkrétní testovací úlohy.","b":"Není správně. AI chatboti a testovací aplikace postavené na LLM mají odlišný účel a neshodují se ve funkcích ani v možnostech konfigurace.","c":"Není správně. Testovací aplikace postavené na LLM se zaměřují na integraci do procesů testování, ne na konverzační prompty. AI chatboti integraci do testovacích nástrojů a procesů nepotřebují, protože jejich hlavní funkcí jsou ad hoc interakce, ne plnění konkrétních testovacích úloh.","d":"Je správně. AI chatboti poskytují konverzační rozhraní pro ad hoc úlohy, zatímco testovací aplikace postavené na LLM dodávají řešení přizpůsobená konkrétním potřebám."},"obecne":""},"kap":{"c":"1.2.2","nazev":"1.2.2 AI chatboti a testovací aplikace postavené na LLM","href":"kapitola-1/vyklad.html#oddil-1-2-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-08","n":8,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A tester is examining a structured prompt used to obtain LLM assistance for performance test analysis. One of the components of this prompt reads: “Test reports from performance testing tools, system monitoring logs during peak usage periods, and application performance benchmarks from previous releases”.<\/p><p>In which component of the six-part prompt structure would this description MOST LIKELY appear?<\/p>","m":["Context","Input data","Constraints","Output format"],"vys":{"a":"Is not correct. Context provides background information about the test environment or system being tested, not specific (input) data to be analyzed. While this mentions performance testing, it is listing actual data sources rather than providing background information.","b":"Is correct. The description lists specific data sources (test reports, monitoring logs, performance benchmarks) that will be processed by the LLM to perform the analysis task.","c":"Is not correct. Constraints outline restrictions or special considerations for how the task should be performed. The description lists actual data sources rather than restrictions on the analysis approach.","d":"Is not correct. Output format specifies the expected structure and characteristics of the LLM’s response. The description lists actual data sources, without any reference to how results should be presented."},"obecne":""},"cz":{"q":"<p>Tester zkoumá strukturovaný prompt, kterým získává od LLM pomoc s analýzou výkonnostního testování. Jedna ze součástí promptu zní: „Reporty z testování z nástrojů pro výkonnostní testování, logy z monitoringu systému v obdobích špičkového vytížení a výkonnostní benchmarky aplikace z předchozích vydání“.<\/p><p>Ve které součásti šestidílné struktury promptu by se tento popis NEJPRAVDĚPODOBNĚJI objevil?<\/p>","m":["Kontext (context)","Vstupní data (input data)","Omezení (constraints)","Formát výstupu (output format)"],"vys":{"a":"Není správně. Kontext poskytuje podkladové informace o testovacím prostředí nebo testovaném systému, ne konkrétní (vstupní) data k analýze. Popis sice zmiňuje výkonnostní testování, ale vyjmenovává skutečné zdroje dat, ne podkladové informace.","b":"Je správně. Popis vyjmenovává konkrétní zdroje dat (reporty z testování, logy z monitoringu, výkonnostní benchmarky), které LLM zpracuje při analýze.","c":"Není správně. Omezení popisují restrikce nebo zvláštní podmínky, jak má být úloha provedena. Popis uvádí skutečné zdroje dat, ne omezení postupu analýzy.","d":"Není správně. Formát výstupu určuje očekávanou strukturu a vlastnosti odpovědi LLM. Popis uvádí zdroje dat a nijak neříká, jak mají být výsledky prezentovány."},"obecne":""},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-09","n":9,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A tester wants an LLM to analyze a requirements specification for potential defects. In the structured prompt the tester is using, one line reads: “The potential defects must be provided in a markdown table with the following columns: ID, requirement reference, defect type, description, severity”.<\/p><p>In which component of the six-part prompt structure would this line MOST LIKELY appear?<\/p>","m":["Instructions","Constraints","Output format","Context"],"vys":{"a":"Is not correct. The given line does not describe what task to perform, but rather how to present the results. Instructions tell the LLM what to do, while this line tells the LLM how to format the output.","b":"Is not correct. The given line is not imposing restrictions or limitations on the analysis process, but rather specifying the desired presentation format. Constraints might include aspects like “exclude cosmetic issues” whereas this line is about formatting the output.","c":"Is correct. The given line matches the syllabus definition of output format specifications that guide how the LLM should format the output.","d":"Is not correct. The given line provides no background information such as the context of the requirements specification. Instead, it is about formatting the output."},"obecne":""},"cz":{"q":"<p>Tester chce, aby LLM analyzoval specifikaci požadavků a hledal v ní možné defekty. Ve strukturovaném promptu, který tester používá, je řádek: „Možné defekty uveď v tabulce v markdownu s těmito sloupci: ID, odkaz na požadavek, typ defektu, popis, závažnost“.<\/p><p>Ve které součásti šestidílné struktury promptu by se tento řádek NEJPRAVDĚPODOBNĚJI objevil?<\/p>","m":["Instrukce (instructions)","Omezení (constraints)","Formát výstupu (output format)","Kontext (context)"],"vys":{"a":"Není správně. Řádek nepopisuje, jakou úlohu provést, ale jak prezentovat výsledky. Instrukce říkají LLM, co má dělat; tento řádek říká, jak má naformátovat výstup.","b":"Není správně. Řádek neklade omezení na průběh analýzy, ale určuje požadovaný formát prezentace. Omezením by bylo třeba „vynech kosmetické vady“; tento řádek se týká formátu výstupu.","c":"Je správně. Řádek odpovídá definici formátu výstupu v sylabu: určuje, jak má LLM výstup naformátovat.","d":"Není správně. Řádek neposkytuje žádné podkladové informace, například o kontextu specifikace požadavků. Týká se formátu výstupu."},"obecne":""},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-10","n":10,"lo":"GenAI-2.1.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following BEST differentiates prompt chaining, few-shot prompting, and meta prompting techniques?<\/p>","m":["Prompt chaining focuses on providing examples, few-shot prompting breaks tasks into subtasks, and meta prompting refines prompts manually.","Few-shot prompting provides guidance with examples, prompt chaining breaks tasks into multiple prompts, and meta prompting allows the model to iteratively refine its own prompts.","Meta prompting emphasizes breaking down tasks into steps, prompt chaining uses examples, and few-shot prompting focuses on manual optimization of prompts.","Prompt chaining provides guidance without examples, few-shot provides guidance with examples, and meta prompting relies on tester-defined prompts."],"vys":{"a":"Is not correct. Prompt chaining is actually defined by decomposing a task into sequential prompts, not by “providing examples”. Few-shot prompting is the technique that supplies examples, not the one that “breaks tasks into subtasks”. Meta prompting relies on the LLM to revise prompts by itself, not on the tester “refining prompts manually”.","b":"Is correct. Few-shot prompting provides guidance with examples, prompt chaining decomposes tasks into intermediate steps (multiple prompts), and meta prompting uses AI to refine its own prompts iteratively.","c":"Is not correct. Meta prompting’s core purpose is automatic prompt refinement by the LLM, not “breaking tasks into steps”. Prompt chaining is characterized by step-by-step decomposition, not by “using examples” as stated. Few-shot prompting is the method that supplies examples to the model and it is not centered on “manual optimization of prompts”.","d":"Is not correct. Prompt chaining is defined by stepwise decomposition, not “guidance without examples”. Meta prompting relies on the LLM to generate/refine prompts, not solely on tester-defined wording."},"obecne":""},"cz":{"q":"<p>Co NEJLÉPE rozlišuje techniky řetězení promptů (prompt chaining), few-shot prompting a meta prompting?<\/p>","m":["Řetězení promptů se zaměřuje na poskytování příkladů, few-shot prompting rozkládá úlohy na dílčí úlohy a meta prompting zdokonaluje prompty ručně.","Few-shot prompting navádí model pomocí příkladů, řetězení promptů rozkládá úlohy do více promptů a meta prompting umožňuje modelu iterativně zdokonalovat vlastní prompty.","Meta prompting klade důraz na rozklad úloh do kroků, řetězení promptů používá příklady a few-shot prompting se zaměřuje na ruční optimalizaci promptů.","Řetězení promptů navádí model bez příkladů, few-shot navádí s příklady a meta prompting spoléhá na prompty definované testerem."],"vys":{"a":"Není správně. Řetězení promptů je definováno rozkladem úlohy do po sobě jdoucích promptů, ne „poskytováním příkladů“. Příklady dodává few-shot prompting, který úlohy „nerozkládá na dílčí úlohy“. Meta prompting spoléhá na to, že prompty upraví sám LLM, ne na „ruční zdokonalování“ testerem.","b":"Je správně. Few-shot prompting navádí příklady, řetězení promptů rozkládá úlohu do mezikroků (více promptů) a meta prompting využívá AI k iterativnímu zdokonalování vlastních promptů.","c":"Není správně. Hlavním účelem meta promptingu je automatické zdokonalení promptu samotným LLM, ne „rozklad úloh do kroků“. Řetězení promptů je charakteristické rozkladem krok za krokem, ne „používáním příkladů“. Příklady modelu dodává few-shot prompting a ten není zaměřen na „ruční optimalizaci promptů“.","d":"Není správně. Řetězení promptů je definováno postupným rozkladem, ne „navedením bez příkladů“. Meta prompting spoléhá na to, že prompty generuje nebo upravuje LLM, ne jen na formulace testera."},"obecne":""},"kap":{"c":"2.1.2","nazev":"2.1.2 Základní techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-1-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-11","n":11,"lo":"GenAI-2.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>What is the primary function of a system prompt in interactions with LLMs?<\/p>","m":["To provide a framework for the LLM behavior for the entire conversation.","To provide specific questions or instructions from the user to the LLM.","To adjust dynamically with each user interaction and set the conversation's context.","To include visible input from the user and set rules for the conversation."],"vys":{"a":"Is correct. The system prompt stays constant throughout the interaction session and establishes the fundamental framework for how the LLM should respond.","b":"Is not correct. This describes the function of a user prompt, not a system prompt.","c":"Is not correct. The system prompt does not adjust dynamically; it remains constant.","d":"Is not correct. The system prompt is hidden and does not include visible input from the user."},"obecne":""},"cz":{"q":"<p>Jaká je hlavní funkce systémového promptu (system prompt) při interakci s LLM?<\/p>","m":["Poskytnout rámec chování LLM pro celou konverzaci.","Předat LLM konkrétní otázky nebo instrukce od uživatele.","Dynamicky se měnit s každou interakcí uživatele a nastavovat kontext konverzace.","Obsahovat viditelný vstup od uživatele a nastavovat pravidla konverzace."],"vys":{"a":"Je správně. Systémový prompt zůstává po celou relaci stejný a vytváří základní rámec toho, jak má LLM odpovídat.","b":"Není správně. To je funkce uživatelského promptu (user prompt), ne systémového.","c":"Není správně. Systémový prompt se dynamicky nemění, zůstává stejný.","d":"Není správně. Systémový prompt je skrytý a neobsahuje viditelný vstup od uživatele."},"obecne":""},"kap":{"c":"2.1.3","nazev":"2.1.3 Systémový prompt a uživatelský prompt","href":"kapitola-2/vyklad.html#oddil-2-1-3"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-12","n":12,"lo":"GenAI-2.2.1","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>You are tasked with applying the following test approach to a set of stable requirements for a new project: generate test conditions, prioritize them based on risk level, and identify potential coverage gaps. The requirements have already been thoroughly reviewed for defects.<\/p><p>Which of the following sequences of steps (i-v) should you follow to effectively apply Generative AI to implement this test approach using a prompt chaining technique to implement this test approach?<\/p><ul><li>i. Submit the requirements to the LLM and prompt it to produce test conditions based on those requirements.<\/li><li>ii. Provide the test conditions to the LLM, ensuring it understands the context for prioritization, and prompt it to prioritize those test conditions accordingly.<\/li><li>iii. Provide the prioritized test conditions to the LLM and prompt it to analyze them to determine whether all aspects of the requirements are addressed in the test conditions.<\/li><li>iv. Submit the requirements to the LLM and prompt it to produce prioritized test conditions that address all aspects of the requirements.<\/li><li>v. Submit the requirements to the LLM and prompt it to detect inconsistencies and ambiguities in those requirements.<\/li><\/ul>","m":["i, ii, and iii","iv, and ii","i, iii, and v","v, and iv"],"vys":{"a":"Is correct.","b":"Is not correct.","c":"Is not correct.","d":"Is not correct."},"obecne":"<p>Considering:<\/p><ul><li>i. Is correct because it ensures the process begins with generating test conditions from the requirements which aligns with the syllabus description that test analysis with GenAI involves generating test conditions based on the test basis, for example on requirements.<\/li><li>ii. Is correct because it clarifies the need for acceptance criteria (test conditions) to improve LLM-generated outputs and follows the syllabus guidance that LLMs can prioritize test conditions based on risk level when provided with proper context.<\/li><li>iii. Is correct because it directs the LLM to perform coverage analysis, addressing all aspects of the requirements, which matches the syllabus statement that LLMs can perform coverage analysis to determine whether all aspects of the test basis are covered.<\/li><li>iv. Is not correct because relying on minimal input without guidance does not align with the prompt chaining technique or ensure effectiveness. This option attempts to do everything in one step rather than breaking it down.<\/li><li>v. Is not correct because defect identification is not central to the test objective of generating prioritized test conditions and identifying coverage gaps. The scenario specifically states the requirements are stable and already thoroughly reviewed for defects (which typically include ambiguities and inconsistencies).<\/li><\/ul>"},"cz":{"q":"<p>Máš za úkol použít následující testovací přístup na sadu stabilních požadavků nového projektu: vygenerovat testovací podmínky, prioritizovat je podle úrovně rizika a najít možné mezery v pokrytí. Požadavky už byly důkladně zrevidovány na defekty.<\/p><p>Kterou z následujících posloupností kroků (i–v) bys měl použít, abys tento testovací přístup efektivně realizoval pomocí generativní AI a techniky řetězení promptů (prompt chaining)?<\/p><ul><li>i. Předej LLM požadavky a nech ho z nich vytvořit testovací podmínky.<\/li><li>ii. Předej LLM testovací podmínky, zajisti, aby rozuměl kontextu prioritizace, a nech ho podmínky podle toho prioritizovat.<\/li><li>iii. Předej LLM prioritizované testovací podmínky a nech ho analyzovat, zda pokrývají všechny aspekty požadavků.<\/li><li>iv. Předej LLM požadavky a nech ho vytvořit prioritizované testovací podmínky, které pokrývají všechny aspekty požadavků.<\/li><li>v. Předej LLM požadavky a nech ho v nich najít nekonzistence a nejednoznačnosti.<\/li><\/ul>","m":["i, ii a iii","iv a ii","i, iii a v","v a iv"],"vys":{"a":"Je správně.","b":"Není správně.","c":"Není správně.","d":"Není správně."},"obecne":"<p>Platí:<\/p><ul><li>i. Je správně, protože proces začíná generováním testovacích podmínek z požadavků. To odpovídá sylabu: testovací analýza s GenAI zahrnuje generování testovacích podmínek z testovací báze, např. z požadavků.<\/li><li>ii. Je správně, protože zdůrazňuje potřebu akceptačních kritérií (testovacích podmínek) pro lepší výstup LLM a odpovídá sylabu: LLM umí prioritizovat testovací podmínky podle úrovně rizika, když dostane správný kontext.<\/li><li>iii. Je správně, protože LLM provede analýzu pokrytí všech aspektů požadavků. Sylabus uvádí, že LLM umí analýzou pokrytí zjistit, zda jsou pokryty všechny aspekty testovací báze.<\/li><li>iv. Není správně, protože minimální vstup bez navedení neodpovídá řetězení promptů a nezajistí efektivitu. Tato možnost se snaží udělat vše v jednom kroku místo rozkladu.<\/li><li>v. Není správně, protože hledání defektů není hlavním cílem (prioritizované testovací podmínky a mezery v pokrytí). Zadání navíc říká, že požadavky jsou stabilní a už byly důkladně zrevidovány na defekty (což obvykle zahrnuje nejednoznačnosti a nekonzistence).<\/li><\/ul>"},"kap":{"c":"2.2.1","nazev":"2.2.1 Testovací analýza s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-13","n":13,"lo":"GenAI-2.2.2","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>Consider applying the few-shot structured prompting technique to generate Gherkin-style test cases (i.e., scenario-based) for the following user story and acceptance criterion:<\/p><ul><li>User story: “As a user, I want to reset my password so that I can regain access to my account if I forget it.”<\/li><li>Acceptance criterion: “When a user submits a registered email address then they receive a password reset email.”<\/li><\/ul><p>You can rely on predefined examples that include user stories, acceptance criteria, and Gherkin-style test cases. Your task is to create a prompt to guide the LLM in generating accurate test cases aligned with the acceptance criterion for the user story above.<\/p><p>Which one of the following prompts is BEST suited to this task?<\/p>","m":["<b>Prompt A<\/b><br>Role: Act as a test analyst.<br>Context: You are testing a password reset functionality.<br>Instruction: Generate Gherkin-style test cases for the user story and acceptance criterion. using the following predefined examples as a guide: &lt;&lt; predefined examples &gt;&gt;.<br>Input Data: &lt;&lt;&lt; user story &gt;&gt;&gt; and &lt;&lt;&lt; acceptance criterion &gt;&gt;&gt;.<br>Constraints: Rely on best practices to create test cases.<br>Output Format: Generate test cases with expected results.","<b>Prompt B<\/b><br>Role: Act as a test analyst specializing in Gherkin-style test cases.<br>Context: You are testing a password reset functionality.<br>Instruction: Generate Gherkin-style test cases for the user story and acceptance criterion, using the following predefined examples as a guide: &lt;&lt; predefined examples &gt;&gt;.<br>Input Data: &lt;&lt;&lt; user story &gt;&gt;&gt; and &lt;&lt;&lt; acceptance criterion &gt;&gt;&gt;.<br>Constraints: Use \"Given-When-Then\" syntax and ensure alignment with the acceptance criterion.<br>Output Format: Respect the given Gherkin-style test case format.","<b>Prompt C<\/b><br>Role: Act as a test analyst.<br>Context: You are testing a password reset functionality.<br>Instruction: Generate Gherkin-style test cases for the user story and acceptance criterion. Rely on best practices to create test cases.<br>Input Data: &lt;&lt;&lt; user story &gt;&gt;&gt; and &lt;&lt;&lt; acceptance criterion &gt;&gt;&gt;.<br>Constraints: Use \"Given-When-Then\" syntax and ensure alignment with the acceptance criterion.<br>Output Format: Respect the given Gherkin-style test case format.","<b>Prompt D<\/b><br>Role: Act as a test analyst.<br>Context: You are testing a password reset functionality.<br>Instruction: Generate at least two Gherkin-style test cases for the user story and acceptance criterion. Focus on edge cases.<br>Input Data: &lt;&lt;&lt; user story &gt;&gt;&gt; and &lt;&lt;&lt; acceptance criterion &gt;&gt;&gt;.<br>Constraints: Ensure all test cases follow \"Given-When-Then\" syntax.<br>Output Format: Respect the given Gherkin-style test case format."],"vys":{"a":"Is not correct. While it specifies using predefined examples, it does not explicitly require the use of the “Given-When-Then” syntax, which is crucial for Gherkin-style test cases. It also indicates reliance on vague best practices in defining the constraints and does not specifically ensure alignment with the acceptance criterion.","b":"Is correct. Comprehensive and leverages predefined examples to guide the LLM.","c":"Is not correct. Lacks emphasis on using predefined examples and indicates reliance on vague best practices in defining the instructions.","d":"Is not correct. Focuses on edge cases but neglects comprehensive coverage and the use of examples for guidance."},"obecne":""},"cz":{"q":"<p>Uvažuj o použití techniky few-shot se strukturovaným promptem ke generování testovacích případů ve stylu Gherkin (tj. založených na scénářích) pro tento uživatelský scénář (user story) a akceptační kritérium:<\/p><ul><li>Uživatelský scénář: „Jako uživatel chci obnovit své heslo, abych mohl znovu získat přístup ke svému účtu, když ho zapomenu.“<\/li><li>Akceptační kritérium: „Když uživatel zadá registrovanou e-mailovou adresu, obdrží e-mail pro obnovení hesla.“<\/li><\/ul><p>Můžeš použít předem připravené příklady, které obsahují uživatelské scénáře, akceptační kritéria a testovací případy ve stylu Gherkin. Tvým úkolem je vytvořit prompt, který LLM navede k vygenerování přesných testovacích případů v souladu s akceptačním kritériem výše uvedeného uživatelského scénáře.<\/p><p>Který z následujících promptů se pro tuto úlohu hodí NEJLÉPE?<\/p>","m":["<b>Prompt A<\/b><br>Role: Jednej jako test analytik.<br>Kontext: Testuješ funkci obnovení hesla.<br>Instrukce: Vygeneruj testovací případy ve stylu Gherkin pro uživatelský scénář a akceptační kritérium. jako vodítko použij tyto předem připravené příklady: &lt;&lt; předem připravené příklady &gt;&gt;.<br>Vstupní data: &lt;&lt;&lt; uživatelský scénář &gt;&gt;&gt; a &lt;&lt;&lt; akceptační kritérium &gt;&gt;&gt;.<br>Omezení: Při tvorbě testovacích případů vycházej z osvědčených postupů.<br>Formát výstupu: Vygeneruj testovací případy s očekávanými výsledky.","<b>Prompt B<\/b><br>Role: Jednej jako test analytik specializovaný na testovací případy ve stylu Gherkin.<br>Kontext: Testuješ funkci obnovení hesla.<br>Instrukce: Vygeneruj testovací případy ve stylu Gherkin pro uživatelský scénář a akceptační kritérium, jako vodítko použij tyto předem připravené příklady: &lt;&lt; předem připravené příklady &gt;&gt;.<br>Vstupní data: &lt;&lt;&lt; uživatelský scénář &gt;&gt;&gt; a &lt;&lt;&lt; akceptační kritérium &gt;&gt;&gt;.<br>Omezení: Použij syntaxi „Given-When-Then“ a zajisti soulad s akceptačním kritériem.<br>Formát výstupu: Dodrž zadaný formát testovacích případů ve stylu Gherkin.","<b>Prompt C<\/b><br>Role: Jednej jako test analytik.<br>Kontext: Testuješ funkci obnovení hesla.<br>Instrukce: Vygeneruj testovací případy ve stylu Gherkin pro uživatelský scénář a akceptační kritérium. Při tvorbě testovacích případů vycházej z osvědčených postupů.<br>Vstupní data: &lt;&lt;&lt; uživatelský scénář &gt;&gt;&gt; a &lt;&lt;&lt; akceptační kritérium &gt;&gt;&gt;.<br>Omezení: Použij syntaxi „Given-When-Then“ a zajisti soulad s akceptačním kritériem.<br>Formát výstupu: Dodrž zadaný formát testovacích případů ve stylu Gherkin.","<b>Prompt D<\/b><br>Role: Jednej jako test analytik.<br>Kontext: Testuješ funkci obnovení hesla.<br>Instrukce: Vygeneruj alespoň dva testovací případy ve stylu Gherkin pro uživatelský scénář a akceptační kritérium. Zaměř se na okrajové případy.<br>Vstupní data: &lt;&lt;&lt; uživatelský scénář &gt;&gt;&gt; a &lt;&lt;&lt; akceptační kritérium &gt;&gt;&gt;.<br>Omezení: Zajisti, aby všechny testovací případy dodržovaly syntaxi „Given-When-Then“.<br>Formát výstupu: Dodrž zadaný formát testovacích případů ve stylu Gherkin."],"vys":{"a":"Není správně. Prompt sice předepisuje použití připravených příkladů, ale výslovně nevyžaduje syntaxi „Given-When-Then“, která je pro Gherkin zásadní. V omezeních se navíc odvolává na vágní „osvědčené postupy“ a nezajišťuje soulad s akceptačním kritériem.","b":"Je správně. Prompt je úplný a k navedení LLM využívá připravené příklady.","c":"Není správně. Chybí důraz na použití připravených příkladů a instrukce se odvolává na vágní „osvědčené postupy“.","d":"Není správně. Zaměřuje se na okrajové případy, ale zanedbává úplné pokrytí a navedení pomocí příkladů."},"obecne":""},"kap":{"c":"2.2.2","nazev":"2.2.2 Návrh testů a implementace testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-14","n":14,"lo":"GenAI-2.2.3","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>You are tasked with applying structured prompting to analyze regression test results. Here is an initial draft of the prompt:<\/p><p>Role: Act as a test analyst.<br>Context: Analyze raw regression test results from a recent test execution cycle.<br>Instruction: Identify discrepancies in the test results.<br>Input Data: Use the attached file containing raw test results.<br>Constraints: Use the known anomalies list for cross-checking.<br>Output Format: Provide a list of discrepancies using a table format.<\/p><p>You are asked to improve this prompt. Which of the following improvements would BEST align the prompt with structured prompt engineering best practices for comprehensive regression test report analysis?<\/p>","m":["Add a step to cluster similar issues and cross-check findings against the known anomalies list.","Specify that the role is a regression test analyst specializing in actionable insights.","Expand the instruction to include separating expected results and actual results, clustering issues, and highlighting discrepancies.","Include references to regression testing principles such as \"Given-When-Then\" in the constraints."],"vys":{"a":"Is not correct. Addresses clustering and cross-checking but misses other critical steps like separating test results.","b":"Is not correct. Improves role clarity but does not expand instructions or address structured steps.","c":"Is correct. Expands instructions to include all critical structured analysis steps. Separating expected results and actual results helps to pinpoint mismatches effectively, clustering issues facilitates better prioritization and reduces redundancy, and highlighting discrepancies helps to focus attention on the most important findings.","d":"Is not correct. Introduces irrelevant constraints, misaligning the prompt with the task requirements."},"obecne":""},"cz":{"q":"<p>Máš za úkol použít strukturovaný prompt k analýze výsledků regresních testů. Toto je první návrh promptu:<\/p><p>Role: Jednej jako test analytik.<br>Kontext: Analyzuj surové výsledky regresních testů z nedávného cyklu provádění testů.<br>Instrukce: Najdi nesrovnalosti ve výsledcích testů.<br>Vstupní data: Použij přiložený soubor se surovými výsledky testů.<br>Omezení: Ke křížové kontrole použij seznam známých anomálií.<br>Formát výstupu: Uveď seznam nesrovnalostí ve formě tabulky.<\/p><p>Máš tento prompt vylepšit. Které z následujících vylepšení NEJLÉPE sladí prompt s osvědčenými postupy strukturovaného prompt engineeringu pro úplnou analýzu reportu z regresního testování?<\/p>","m":["Přidat krok, který seskupí podobné problémy a zjištění zkontroluje proti seznamu známých anomálií.","Upřesnit roli na analytika regresních testů specializovaného na využitelné poznatky.","Rozšířit instrukci o oddělení očekávaných a skutečných výsledků, seskupení problémů a zvýraznění nesrovnalostí.","Doplnit do omezení odkazy na principy regresního testování, jako je „Given-When-Then“."],"vys":{"a":"Není správně. Řeší seskupení a křížovou kontrolu, ale chybí další důležité kroky, např. oddělení výsledků testů.","b":"Není správně. Zpřesní roli, ale nerozšíří instrukce ani nedoplní strukturované kroky.","c":"Je správně. Rozšiřuje instrukce o všechny důležité kroky strukturované analýzy. Oddělení očekávaných a skutečných výsledků pomáhá přesně najít neshody, seskupení problémů usnadní prioritizaci a omezí duplicity a zvýraznění nesrovnalostí soustředí pozornost na nejdůležitější zjištění.","d":"Není správně. Přidává nesouvisející omezení, takže prompt přestane odpovídat požadavkům úlohy."},"obecne":""},"kap":{"c":"2.2.3","nazev":"2.2.3 Automatizované regresní testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-3"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-15","n":15,"lo":"GenAI-2.2.4","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>You are using an LLM to assist in preparing actionable test metrics from raw data. The metrics include test progress, defect trends, and coverage, which are graphically displayed and explained with text. Your goal is to improve the test process to ensure the generated metrics are accurate, actionable, and easily interpretable by stakeholders.<\/p><p>Here is an initial draft of a prompt used to instruct the AI:<\/p><p>Role: Act as a test manager.<br>Context: You are provided with raw data from test tools.<br>Instruction: Generate test progress metrics, defect trend metrics, and coverage metrics from the raw data.<br>Input Data: Use the attached file containing raw test results.<br>Constraints: Ensure that the output is concise and understandable.<br>Output Format: Display metrics on a dashboard.<\/p><p>You are asked to improve this prompt. Which of the following improvements would BEST enhance the LLM’s ability to produce accurate and actionable metrics?<\/p>","m":["Specify that the role is a test manager focusing on actionable insights and decision support, ensuring comprehensive analysis of test data.","Add an instruction to include potential risks identified from the trends in the generated metrics, along with their impact assessment and priority levels.","Expand the output format to include a plain-language summary that interprets the metrics and outlines next steps for stakeholders.","Emphasize constraints that the output is also easily interpretable by stakeholders, using clear language and avoiding technical jargon throughout the response."],"vys":{"a":"Is not correct. Clarifies the role but does not add any concrete instruction that improves accuracy, actionability, or interpretability of the delivered metrics.","b":"Is not correct. Adds a risk-analysis task that could distract the model from the core metrics and still offers no mechanism for making results clear to stakeholders.","c":"Is correct. Expanding the output format with a plain-language summary that interprets the metrics and outlines next steps directly supports stakeholder understanding and actionability (see also the syllabus in section 2.2.4: “Enhanced test metrics visualization and reporting”).","d":"Is not correct. Merely re-states an existing constraint and gives no specific guidance on how the LLM should achieve stakeholder-level interpretability."},"obecne":""},"cz":{"q":"<p>Používáš LLM jako pomoc při přípravě využitelných metrik testování ze surových dat. Metriky zahrnují postup testování, trendy defektů a pokrytí; zobrazují se graficky a vysvětlují textem. Tvým cílem je zlepšit proces testování tak, aby vygenerované metriky byly přesné, využitelné a snadno srozumitelné pro zainteresované strany.<\/p><p>Toto je první návrh promptu pro AI:<\/p><p>Role: Jednej jako test manažer.<br>Kontext: Máš k dispozici surová data z testovacích nástrojů.<br>Instrukce: Ze surových dat vygeneruj metriky postupu testování, metriky trendů defektů a metriky pokrytí.<br>Vstupní data: Použij přiložený soubor se surovými výsledky testů.<br>Omezení: Zajisti, aby výstup byl stručný a srozumitelný.<br>Formát výstupu: Zobraz metriky na dashboardu.<\/p><p>Máš tento prompt vylepšit. Které z následujících vylepšení NEJLÉPE zlepší schopnost LLM vytvořit přesné a využitelné metriky?<\/p>","m":["Upřesnit roli na test manažera zaměřeného na využitelné poznatky a podporu rozhodování, který zajistí úplnou analýzu testovacích dat.","Přidat instrukci, aby výstup obsahoval možná rizika zjištěná z trendů ve vygenerovaných metrikách, včetně posouzení dopadu a úrovně priority.","Rozšířit formát výstupu o shrnutí srozumitelným jazykem, které metriky vyloží a navrhne další kroky pro zainteresované strany.","Zdůraznit v omezeních, že výstup má být srozumitelný i pro zainteresované strany, psaný jasným jazykem a bez technického žargonu."],"vys":{"a":"Není správně. Zpřesní roli, ale nepřidá žádnou konkrétní instrukci, která by zlepšila přesnost, využitelnost nebo srozumitelnost metrik.","b":"Není správně. Přidává úlohu analýzy rizik, která může model odvést od hlavních metrik, a pořád nijak nezajišťuje srozumitelnost výsledků pro zainteresované strany.","c":"Je správně. Rozšíření formátu výstupu o shrnutí srozumitelným jazykem, které metriky vyloží a navrhne další kroky, přímo podporuje porozumění zainteresovaných stran a využitelnost (viz sylabus 2.2.4: „Enhanced test metrics visualization and reporting“).","d":"Není správně. Jen opakuje existující omezení a nedává LLM konkrétní vodítko, jak srozumitelnosti pro zainteresované strany dosáhnout."},"obecne":""},"kap":{"c":"2.2.4","nazev":"2.2.4 Monitoring testování a řízení testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-4"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-16","n":16,"lo":"GenAI-2.2.5","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>Your goal is to create test cases for an AI-based system that suffers from the test oracle problem, preventing you from determining expected results. You can only count on a few existing test cases with known expected results. Through appropriate analysis, you have identified a set of well-defined transformation rules that specify how changes to inputs affect expected results. These rules can be applied to all existing test cases. You have decided to rely on Generative AI, providing a given LLM with the following information: the existing test cases with their inputs and expected results, a clear description of the transformation rules, and guidelines for generating additional test cases by precisely applying these rules to the relevant existing test cases. With the specified information, the chosen LLM can directly generate additional test cases in line with your expectations.<\/p><p>Which of the following prompting techniques is BEST suited to achieve your goal in this scenario?<\/p>","m":["Few-shot prompting","Prompt chaining","Meta prompting","Zero-shot prompting"],"vys":{"a":"Is correct. Few-shot prompting is ideal in this scenario because it allows you to provide some examples (the existing test cases with inputs and expected results) to guide the LLM. By illustrating how these transformation rules are applied to generate new test cases, few-shot prompting can help the LLM understand and replicate the process to generate additional test cases.","b":"Is not correct. While prompt chaining could be used, it could unnecessarily complicate this very straightforward task.","c":"Is not correct. While meta-prompting could be used, it is not as direct and specific as few-shot prompting to address this very straightforward task.","d":"Is not correct. Zero-shot prompting would not be effective since it would not leverage existing test cases as examples."},"obecne":""},"cz":{"q":"<p>Tvým cílem je vytvořit testovací případy pro systém založený na AI, který trpí problémem testovacího orákula (test oracle problem), takže nedokážeš určit očekávané výsledky. Můžeš se spolehnout jen na několik existujících testovacích případů se známými očekávanými výsledky. Vhodnou analýzou jsi našel sadu přesně definovaných transformačních pravidel, která určují, jak změny vstupů ovlivní očekávané výsledky. Pravidla lze použít na všechny existující testovací případy. Rozhodl ses použít generativní AI a dát zvolenému LLM tyto informace: existující testovací případy s jejich vstupy a očekávanými výsledky, jasný popis transformačních pravidel a pokyny, jak generovat další testovací případy přesným použitím pravidel na příslušné existující testovací případy. S těmito informacemi zvolený LLM dokáže přímo vygenerovat další testovací případy podle tvých očekávání.<\/p><p>Která z následujících technik promptování se k dosažení cíle v tomto scénáři hodí NEJLÉPE?<\/p>","m":["Few-shot prompting","Řetězení promptů (prompt chaining)","Meta prompting","Zero-shot prompting"],"vys":{"a":"Je správně. Few-shot prompting je zde ideální, protože LLM navede několika příklady (existující testovací případy se vstupy a očekávanými výsledky). Příklady ukazují, jak se transformační pravidla používají k tvorbě nových testovacích případů, a LLM tak postup pochopí a zopakuje.","b":"Není správně. Řetězení promptů by použít šlo, ale tuto velmi přímočarou úlohu by zbytečně komplikovalo.","c":"Není správně. Meta prompting by použít šel, ale pro tuto velmi přímočarou úlohu není tak přímý a konkrétní jako few-shot prompting.","d":"Není správně. Zero-shot prompting by nebyl účinný, protože by nevyužil existující testovací případy jako příklady."},"obecne":""},"kap":{"c":"2.2.5","nazev":"2.2.5 Výběr techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-2-5"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-17","n":17,"lo":"GenAI-2.3.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>You are leveraging Generative AI to assist in testing an entertainment software application. The Generative AI model generates test cases for user interaction scenarios, test scripts for API interactions, and synthetic test data to address edge cases.<\/p><p>To effectively evaluate the Generative AI model’s performance and to refine prompts, which combination of metrics and actions BEST ensures comprehensive assessment and improvement?<\/p>","m":["Evaluate the diversity of test cases to ensure varied input scenarios and use test execution success rate to validate the functionality of generated API test scripts.","Apply accuracy and completeness metrics to validate test cases against entertainment software requirements and rely on time efficiency to compare AI-generated test scripts with manual test efforts.","Focus on precision to ensure generated test data meets entertainment software compliance standards, while contextual fit and test execution success rate assesses the alignment and usability of test scripts.","Prioritize relevance and contextual fit for all outputs to maintain consistency with entertainment software requirements and include diversity metrics to expand edge case coverage."],"vys":{"a":"Is correct. Diversity ensures comprehensive coverage of edge cases, and test execution success rate evaluates the reliability of API test scripts (see the description and example for the \"diversity\" metric provided by the syllabus within the table in section 2.3.1).","b":"Is not correct. While accuracy and completeness are important, relying primarily on time efficiency does not fully evaluate coverage or test execution reliability.","c":"Is not correct. Precision and contextual fit are valuable but do not address diversity or thoroughly evaluate test execution success for API test scripts.","d":"Is not correct. Relevance and contextual fit are crucial, but without considering metrics like test execution success rate or accuracy, critical aspects of evaluation are missed."},"obecne":""},"cz":{"q":"<p>Využíváš generativní AI jako pomoc při testování zábavní softwarové aplikace. Model generativní AI vytváří testovací případy pro scénáře interakce uživatele, testovací skripty pro API interakce a syntetická testovací data pro okrajové případy.<\/p><p>Která kombinace metrik a činností NEJLÉPE zajistí úplné vyhodnocení výkonu modelu generativní AI a zdokonalení promptů?<\/p>","m":["Hodnotit rozmanitost (diversity) testovacích případů kvůli různorodým vstupním scénářům a míru úspěšnosti provedení (execution success rate) použít k ověření funkčnosti vygenerovaných API testovacích skriptů.","Použít metriky přesnosti (accuracy) a úplnosti k ověření testovacích případů vůči požadavkům zábavního softwaru a pro srovnání AI skriptů s ruční prací spoléhat na časovou efektivitu (time efficiency).","Zaměřit se na preciznost (precision), aby testovací data splňovala standardy shody pro zábavní software, a kontextovou vhodnost a míru úspěšnosti provedení použít k posouzení souladu a použitelnosti testovacích skriptů.","U všech výstupů upřednostnit relevanci a kontextovou vhodnost (relevance and contextual fit) kvůli souladu s požadavky zábavního softwaru a přidat metriky rozmanitosti pro rozšíření pokrytí okrajových případů."],"vys":{"a":"Je správně. Rozmanitost zajišťuje úplné pokrytí okrajových případů a míra úspěšnosti provedení hodnotí spolehlivost API testovacích skriptů (viz popis a příklad metriky „diversity“ v tabulce v sylabu 2.3.1).","b":"Není správně. Přesnost a úplnost jsou důležité, ale spoléhání hlavně na časovou efektivitu nevyhodnotí pokrytí ani spolehlivost provedení testů.","c":"Není správně. Preciznost a kontextová vhodnost jsou užitečné, ale neřeší rozmanitost ani důkladně nevyhodnotí úspěšnost provedení API testovacích skriptů.","d":"Není správně. Relevance a kontextová vhodnost jsou zásadní, ale bez metrik jako míra úspěšnosti provedení nebo přesnost chybí důležité stránky vyhodnocení."},"obecne":""},"kap":{"c":"2.3.1","nazev":"2.3.1 Metriky pro hodnocení výsledků GenAI v testovacích úlohách","href":"kapitola-2/vyklad.html#oddil-2-3-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-18","n":18,"lo":"GenAI-2.3.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following techniques for evaluating and iteratively refining prompts is BEST suited for determining why an LLM consistently generates test cases with wrong expected results that contradict the input requirements, thereby providing insights to optimize the prompt and prevent similar errors?<\/p>","m":["Output analysis","A/B testing of prompts","Adjusting prompt length and specificity","Integrating user feedback"],"vys":{"a":"Is correct. Output analysis examines LLM outputs for inaccuracies or inconsistencies. By classifying the wrong expected results that contradict the requirements, it reveals why the prompt misled the LLM and provides concrete insights for prompt refinement.","b":"Is not correct. A/B testing of prompts is better suited for comparing different prompt versions than for diagnosing the cause of wrong expected results.","c":"Is not correct. While adjusting the length and specificity of prompts can improve the quality of responses by adding or reducing context, it does not directly address the cause of wrong expected results.","d":"Is not correct. While using the insights gathered from testers about the usefulness and clarity of generated output can help refine prompts to better meet real-world testing needs, it does not directly address the cause of wrong expected results."},"obecne":""},"cz":{"q":"<p>Která z následujících technik pro vyhodnocování a iterativní zdokonalování promptů se NEJLÉPE hodí ke zjištění, proč LLM soustavně generuje testovací případy s chybnými očekávanými výsledky, které odporují vstupním požadavkům, a tím poskytne poznatky pro optimalizaci promptu a prevenci podobných chyb?<\/p>","m":["Analýza výstupu (output analysis)","A/B testování promptů (A/B testing of prompts)","Úprava délky a konkrétnosti promptu (adjusting prompt length and specificity)","Zapojení zpětné vazby uživatelů (integrating user feedback)"],"vys":{"a":"Je správně. Analýza výstupu zkoumá výstupy LLM z hlediska nepřesností a nekonzistencí. Roztřídění chybných očekávaných výsledků, které odporují požadavkům, ukáže, proč prompt LLM zavedl, a dá konkrétní podněty ke zdokonalení promptu.","b":"Není správně. A/B testování promptů se hodí spíš ke srovnání různých verzí promptu než k diagnostice příčiny chybných očekávaných výsledků.","c":"Není správně. Úprava délky a konkrétnosti promptu může zlepšit kvalitu odpovědí přidáním nebo ubráním kontextu, ale přímo neřeší příčinu chybných očekávaných výsledků.","d":"Není správně. Poznatky testerů o užitečnosti a srozumitelnosti výstupu pomáhají prompty přizpůsobit reálným potřebám testování, ale přímo neřeší příčinu chybných očekávaných výsledků."},"obecne":""},"kap":{"c":"2.3.2","nazev":"2.3.2 Techniky hodnocení a iterativního ladění promptů","href":"kapitola-2/vyklad.html#oddil-2-3-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-19","n":19,"lo":"GenAI-3.1.1","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>What is a hallucination in the context of LLM outputs?<\/p>","m":["A logical error where the LLM fails to follow a multi-step reasoning process accurately.","A bias in the LLM output caused by the training data favoring certain perspectives.","A generation of irrelevant or factually incorrect output by the LLM for a given task.","A limitation of the LLM to understand non-English perspectives in test generation tasks."],"vys":{"a":"Is not correct. This describes reasoning errors, not hallucinations.","b":"Is not correct. This describes biases in AI output, not hallucinations.","c":"Is correct. Hallucinations occur when the LLM generates output that is factually incorrect or irrelevant to a given task. See the syllabus in section 3.1.1.","d":"Is not correct. This describes biases due to underrepresentation in training data, not hallucinations."},"obecne":""},"cz":{"q":"<p>Co je halucinace (hallucination) v kontextu výstupů LLM?<\/p>","m":["Logická chyba, kdy LLM nedokáže přesně projít vícekrokovým procesem uvažování.","Zkreslení (bias) ve výstupu LLM způsobené tím, že trénovací data upřednostňují určité pohledy.","Vygenerování nerelevantního nebo fakticky nesprávného výstupu LLM pro danou úlohu.","Omezení LLM v chápání neanglických pohledů při úlohách generování testů."],"vys":{"a":"Není správně. To popisuje chyby v uvažování (reasoning errors), ne halucinace.","b":"Není správně. To popisuje zkreslení (biases) ve výstupu AI, ne halucinace.","c":"Je správně. Halucinace nastává, když LLM vygeneruje výstup, který je pro danou úlohu fakticky nesprávný nebo nerelevantní. Viz sylabus 3.1.1.","d":"Není správně. To popisuje zkreslení kvůli nedostatečnému zastoupení v trénovacích datech, ne halucinace."},"obecne":""},"kap":{"c":"3.1.1","nazev":"3.1.1 Tři druhy vad ve výstupu LLM","href":"kapitola-3/vyklad.html#oddil-3-1-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-20","n":20,"lo":"GenAI-3.1.2","k":"K3","body":2,"vyber":1,"ok":[3],"en":{"q":"<p>You are using Generative AI to create test cases for an e-commerce (e-shop) application. The following features have been explicitly mentioned in the project briefing:<\/p><ul><li>cart management<\/li><li>discount code application<\/li><li>order confirmation email generation<\/li><\/ul><p>Based on these details, which of the following AI-generated test cases MOST LIKELY represents a hallucination?<\/p>","m":["Verify that a user can add multiple items to their cart and proceed to checkout.","Verify that a user cannot apply an expired discount code during checkout.","Verify that a user receives a confirmation email after successfully placing an order.","Verify that a user can create a wishlist to save favorite items for later."],"vys":{"a":"Is not correct. Cart management is explicitly mentioned in the project briefing, making this test case relevant.","b":"Is not correct. Discount code application is explicitly mentioned in the project briefing, making this test case relevant.","c":"Is not correct. Order confirmation emails are explicitly mentioned in the project briefing, so this test case is valid.","d":"Is correct. Wishlist management is not mentioned in the project briefing, making this the most likely hallucinated test case."},"obecne":""},"cz":{"q":"<p>Pomocí generativní AI vytváříš testovací případy pro aplikaci e-shopu. V zadání projektu jsou výslovně uvedeny tyto funkce:<\/p><ul><li>správa košíku<\/li><li>uplatnění slevového kódu<\/li><li>generování e-mailu s potvrzením objednávky<\/li><\/ul><p>Který z následujících testovacích případů vygenerovaných AI NEJPRAVDĚPODOBNĚJI představuje halucinaci (hallucination)?<\/p>","m":["Ověř, že uživatel může přidat do košíku více položek a pokračovat k pokladně.","Ověř, že uživatel nemůže při placení uplatnit slevový kód s prošlou platností.","Ověř, že uživatel po úspěšném odeslání objednávky obdrží potvrzovací e-mail.","Ověř, že uživatel může vytvořit seznam přání (wishlist) a uložit si oblíbené položky na později."],"vys":{"a":"Není správně. Správa košíku je v zadání projektu výslovně uvedena, testovací případ je tedy relevantní.","b":"Není správně. Uplatnění slevového kódu je v zadání výslovně uvedeno, testovací případ je tedy relevantní.","c":"Není správně. E-maily s potvrzením objednávky jsou v zadání výslovně uvedeny, testovací případ je tedy platný.","d":"Je správně. Seznam přání v zadání projektu uveden není, proto jde nejspíš o halucinovaný testovací případ."},"obecne":""},"kap":{"c":"3.1.2","nazev":"3.1.2 Jak vady ve výstupu poznat","href":"kapitola-3/vyklad.html#oddil-3-1-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-21","n":21,"lo":"GenAI-3.1.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following options refers to a benefit that is MOST directly associated with using clear and structured input data formats when working with LLMs for test tasks?<\/p>","m":["Helps reduce the effort to fine-tune the LLMs for test tasks.","Helps LLMs generate less ambiguous outputs for test tasks.","Helps LLMs generate more context-relevant outputs for test tasks.","Helps LLMs generate more creative outputs for test tasks."],"vys":{"a":"Is not correct. The effort to fine-tune LLMs for test tasks is associated with further training of these models on a targeted dataset, enabling them to learn the domain-specific knowledge and nuances needed to perform those test tasks. The use of clear and structured input data formats does not affect this effort.","b":"Is correct. When input data is presented in a clear and structured way, potential misunderstandings are minimized. Ambiguity often arises from unclear and poorly structured data.","c":"Is not correct. Context relevance is more dependent on providing the right contextual information rather than just using clear and structured input data formats.","d":"Is not correct. The use of clear and structured input data formats does not increase the creativity of LLMs in generating outputs. In particular, the use of these formats does not encourage novel responses, as it requires LLMs to generate responses that adhere to the specified formats."},"obecne":""},"cz":{"q":"<p>Která z následujících možností uvádí přínos, který NEJPŘÍMĚJI souvisí s používáním jasných a strukturovaných formátů vstupních dat při práci s LLM na testovacích úlohách?<\/p>","m":["Pomáhá snížit úsilí potřebné k fine-tuningu (doladění) LLM pro testovací úlohy.","Pomáhá LLM generovat pro testovací úlohy méně nejednoznačné výstupy.","Pomáhá LLM generovat pro testovací úlohy kontextově relevantnější výstupy.","Pomáhá LLM generovat pro testovací úlohy kreativnější výstupy."],"vys":{"a":"Není správně. Úsilí na fine-tuning souvisí s dalším trénováním modelu na cílené datové sadě, aby se naučil doménové znalosti a nuance potřebné pro testovací úlohy. Jasné a strukturované formáty vstupních dat toto úsilí neovlivní.","b":"Je správně. Když jsou vstupní data podána jasně a strukturovaně, omezí se možná nedorozumění. Nejednoznačnost často vzniká z nejasných a špatně strukturovaných dat.","c":"Není správně. Kontextová relevance závisí spíš na dodání správných kontextových informací než jen na jasném a strukturovaném formátu vstupních dat.","d":"Není správně. Jasné a strukturované formáty kreativitu LLM nezvyšují. Nepodporují nové, neotřelé odpovědi, protože od LLM vyžadují dodržení zadaného formátu."},"obecne":""},"kap":{"c":"3.1.3","nazev":"3.1.3 Jak vadám předcházet","href":"kapitola-3/vyklad.html#oddil-3-1-3"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-22","n":22,"lo":"GenAI-3.1.4","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which strategy can help reduce variability in LLM outputs by narrowing the probability distribution during inference?<\/p>","m":["Increasing the learning rate.","Lowering the temperature setting.","Increasing the random seed.","Lowering the random seed."],"vys":{"a":"Is not correct. Learning rate is a setting (chosen before training begins) that controls the learning process of neural networks. This setting determines how much to change the model's weights during training. It is not related to inference variability. Increasing it can lead to faster convergence during training but does not affect the variability of outputs during inference.","b":"Is correct. Temperature is a parameter that controls the randomness of the output by acting on the probability distribution during inference. Lowering the temperature reduces randomness, leading to more consistent outputs.","c":"Is not correct. While setting a random seed can improve reproducibility, it does not in itself narrow the probability distribution during inference. Moreover, whether its value is high or low is irrelevant.","d":"Is not correct. While setting a random seed can improve reproducibility, it does not in itself narrow the probability distribution during inference. Moreover, whether its value is high or low is irrelevant."},"obecne":""},"cz":{"q":"<p>Která strategie pomáhá snížit variabilitu výstupů LLM tím, že během inference zužuje rozdělení pravděpodobnosti?<\/p>","m":["Zvýšení rychlosti učení (learning rate).","Snížení nastavení teploty (temperature).","Zvýšení hodnoty náhodného semínka (random seed).","Snížení hodnoty náhodného semínka (random seed)."],"vys":{"a":"Není správně. Rychlost učení je nastavení (volí se před začátkem trénování), které řídí proces učení neuronové sítě: určuje, jak moc se během trénování mění váhy modelu. S variabilitou při inferenci nesouvisí. Její zvýšení může urychlit konvergenci při trénování, ale variabilitu výstupů při inferenci neovlivní.","b":"Je správně. Teplota je parametr, který řídí náhodnost výstupu tím, že během inference působí na rozdělení pravděpodobnosti. Nižší teplota snižuje náhodnost a výstupy jsou konzistentnější.","c":"Není správně. Nastavení náhodného semínka může zlepšit reprodukovatelnost, ale samo o sobě rozdělení pravděpodobnosti při inferenci nezužuje. Navíc nezáleží na tom, zda je jeho hodnota vysoká, nebo nízká.","d":"Není správně. Nastavení náhodného semínka může zlepšit reprodukovatelnost, ale samo o sobě rozdělení pravděpodobnosti při inferenci nezužuje. Navíc nezáleží na tom, zda je jeho hodnota vysoká, nebo nízká."},"obecne":""},"kap":{"c":"3.1.4","nazev":"3.1.4 Nedeterministické chování a jak ho omezit","href":"kapitola-3/vyklad.html#oddil-3-1-4"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-23","n":23,"lo":"GenAI-3.2.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which of the following statements about data privacy concerns related to using Generative AI for software testing is INCORRECT?<\/p>","m":["Generative AI can unintentionally expose sensitive data through its outputs.","Generative AI tools may store and process sensitive data without explicit user consent, leading to misuse.","Using Generative AI tools without adhering to data protection regulations, such as General Data Protection Regulation (GDPR), can lead to legal disputes.","An LLM is likely to expose real sensitive data if it hallucinates while generating synthetic test data, regardless of the data it was trained on."],"vys":{"a":"Is not correct. This is a privacy concern, as “Unintentional data exposure” relates to generative AI (GenAI) outputs revealing sensitive information accidentally.","b":"Is not correct. This is a privacy concern, as it involves the lack of control over how sensitive data is stored or processed.","c":"Is not correct. This is a privacy concern related to non-compliance with regulations such as the General Data Protection Regulation (GDPR), leading to legal risks.","d":"Is correct. An LLM does not expose real sensitive data if it hallucinates when generating synthetic test data, as long as it was not trained on real sensitive data. In this case hallucinations would be purely synthetic and based on patterns and structures the model learned during training. The LLM could unintentionally generate synthetic test data that matches real sensitive data (and this is definitely a concern) but it would not be exposing real sensitive data. However, this unintentional generation is very unlikely."},"obecne":""},"cz":{"q":"<p>Které z následujících tvrzení o rizicích pro ochranu dat a soukromí (data privacy) při použití generativní AI v testování softwaru je NESPRÁVNÉ?<\/p>","m":["Generativní AI může svými výstupy neúmyslně odhalit citlivá data.","Nástroje generativní AI mohou ukládat a zpracovávat citlivá data bez výslovného souhlasu uživatele, což vede ke zneužití.","Používání nástrojů generativní AI bez dodržení předpisů na ochranu dat, jako je obecné nařízení o ochraně osobních údajů (GDPR), může vést k právním sporům.","LLM pravděpodobně odhalí skutečná citlivá data, když při generování syntetických testovacích dat halucinuje, bez ohledu na to, na jakých datech byl trénován."],"vys":{"a":"Není správně (tvrzení platí). Jde o riziko pro soukromí: „neúmyslné odhalení dat“ (unintentional data exposure) znamená, že výstupy GenAI omylem prozradí citlivé informace.","b":"Není správně (tvrzení platí). Jde o riziko pro soukromí: chybí kontrola nad tím, jak se citlivá data ukládají a zpracovávají.","c":"Není správně (tvrzení platí). Jde o riziko nesouladu s předpisy, jako je GDPR, s právními důsledky.","d":"Je správně (tvrzení je nesprávné). LLM při halucinaci během generování syntetických dat skutečná citlivá data neodhalí, pokud na nich nebyl trénován. Halucinace by byly čistě syntetické, založené na vzorech a strukturách naučených při trénování. LLM by sice mohl náhodou vygenerovat data shodná se skutečnými citlivými daty (a to je opravdu problém), ale skutečná data by tím neodhaloval. Taková shoda je navíc velmi nepravděpodobná."},"obecne":""},"kap":{"c":"3.2.1","nazev":"3.2.1 Rizika pro ochranu dat a bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-24","n":24,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>An attacker injects falsified test results into the training dataset of an LLM intended to recommend optimal test coverage strategies. What type of attack vector does this description BEST refer to?<\/p>","m":["Malicious code generation","Context Manipulation","Request manipulation","Data poisoning"],"vys":{"a":"Is not correct. Malicious code generation involves “manipulating an LLM to generate backdoors (e.g., external command calls) during use”, not injecting false data into training datasets.","b":"Is not correct. Context Manipulation involves “sending requests designed to extract confidential training data”, not injecting false data into training datasets.","c":"Is not correct. Request manipulation involves “introducing data that disrupts the AI’s output” during runtime use, not injecting false data into training datasets.","d":"Is correct. According to the syllabus in section 3.2.2, data poisoning involves “manipulating training data” with the specific example of “providing fake evaluations when rating the results of an AI-generated test report”. The question describes this attack vector: an attacker is injecting falsified test (execution) results into the training dataset, which directly manipulates the training data to compromise the LLM’s ability to accurately recommend optimal test coverage strategies."},"obecne":""},"cz":{"q":"<p>Útočník vloží zfalšované výsledky testů do trénovací datové sady LLM, který má doporučovat optimální strategie pokrytí testy. Na jaký typ vektoru útoku tento popis NEJLÉPE odkazuje?<\/p>","m":["Generování škodlivého kódu (malicious code generation)","Manipulace s kontextem (context manipulation)","Manipulace s požadavkem (request manipulation)","Otrávení dat (data poisoning)"],"vys":{"a":"Není správně. Generování škodlivého kódu znamená „přimět LLM, aby během používání generoval zadní vrátka (např. volání externích příkazů)“, ne vkládat falešná data do trénovací sady.","b":"Není správně. Manipulace s kontextem znamená „posílat požadavky, jejichž cílem je vytáhnout důvěrná trénovací data“, ne vkládat falešná data do trénovací sady.","c":"Není správně. Manipulace s požadavkem znamená „vložit data, která naruší výstup AI“ během používání, ne vkládat falešná data do trénovací sady.","d":"Je správně. Podle sylabu 3.2.2 je otrávení dat „manipulace s trénovacími daty“; sylabus uvádí příklad „falešné hodnocení při hodnocení výsledků reportu z testování vygenerovaného AI“. Otázka popisuje přesně tento vektor: útočník vkládá zfalšované výsledky (provedení) testů do trénovací sady, a tím přímo manipuluje trénovací data a narušuje schopnost LLM správně doporučovat strategie pokrytí."},"obecne":""},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-25","n":25,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Match each type of attack vector against an LLM (1-4) with the corresponding example (A-D):<\/p><ul><li>1. Context Manipulation<\/li><li>2. Request manipulation<\/li><li>3. Data poisoning<\/li><li>4. Malicious code generation<\/li><\/ul><ul><li>A. An attacker maliciously modifies the data associated with traceability links between requirements and test cases into the dataset used for fine-tuning an LLM, compromising its accuracy in generating test cases from requirements.<\/li><li>B. An attacker maliciously crafts and provides deceptive prompts that induce an LLM, fine-tuned to assist testers in automated test script generation, to produce vulnerable test scripts with hidden security flaws.<\/li><li>C. An attacker maliciously provides large specially crafted prompts that induce an LLM, fine-tuned to assist testers in generating test cases, to accidentally reveal confidential API keys inherited from past test projects.<\/li><li>D. An attacker maliciously submits carefully modified reference screenshots into a visual testing framework that uses an LLM for comparative visual analysis, to trick the LLM into systematically ignoring genuine UI issues during regression testing.<\/li><\/ul>","m":["1C, 2D, 3A, 4B","1B, 2D, 3A, 4C","1D, 2C, 3B, 4A","1C, 2B, 3D, 4A"],"vys":{"a":"Is correct.","b":"Is not correct.","c":"Is not correct.","d":"Is not correct."},"obecne":"<p>Considering:<\/p><ul><li>Context Manipulation is based on sending requests designed to extract confidential training data. (1C)<\/li><li>Request manipulation is based on introducing an image that disrupts the LLM output. (2D)<\/li><li>Data poisoning is based on manipulating recommendations through fake evaluations used in training. (3A)<\/li><li>Malicious code generation is based on manipulating a LLM to generate backdoors (e.g., external command calls) during use. (4B)<\/li><\/ul>"},"cz":{"q":"<p>Přiřaď každý typ vektoru útoku na LLM (1–4) k odpovídajícímu příkladu (A–D):<\/p><ul><li>1. Manipulace s kontextem (context manipulation)<\/li><li>2. Manipulace s požadavkem (request manipulation)<\/li><li>3. Otrávení dat (data poisoning)<\/li><li>4. Generování škodlivého kódu (malicious code generation)<\/li><\/ul><ul><li>A. Útočník záměrně upraví data o vazbách trasovatelnosti mezi požadavky a testovacími případy v datové sadě pro fine-tuning LLM, a naruší tak jeho přesnost při generování testovacích případů z požadavků.<\/li><li>B. Útočník záměrně vytvoří a podstrčí klamavé prompty, které LLM doladěný pro pomoc testerům s generováním automatizovaných testovacích skriptů přimějí vytvořit zranitelné skripty se skrytými bezpečnostními chybami.<\/li><li>C. Útočník záměrně posílá velké, speciálně vytvořené prompty, které LLM doladěný pro pomoc testerům s generováním testovacích případů přimějí omylem prozradit důvěrné API klíče zděděné z minulých testovacích projektů.<\/li><li>D. Útočník záměrně nahraje pečlivě upravené referenční snímky obrazovky do frameworku pro vizuální testování, který používá LLM ke srovnávací vizuální analýze, aby LLM při regresním testování soustavně přehlížel skutečné vady UI.<\/li><\/ul>","m":["1C, 2D, 3A, 4B","1B, 2D, 3A, 4C","1D, 2C, 3B, 4A","1C, 2B, 3D, 4A"],"vys":{"a":"Je správně.","b":"Není správně.","c":"Není správně.","d":"Není správně."},"obecne":"<p>Platí:<\/p><ul><li>Manipulace s kontextem spočívá v posílání požadavků, jejichž cílem je vytáhnout důvěrná trénovací data. (1C)<\/li><li>Manipulace s požadavkem spočívá ve vložení obrázku, který naruší výstup LLM. (2D)<\/li><li>Otrávení dat spočívá v manipulaci doporučení pomocí falešných hodnocení použitých při trénování. (3A)<\/li><li>Generování škodlivého kódu spočívá v tom, že LLM je během používání přiměn generovat zadní vrátka (např. volání externích příkazů). (4B)<\/li><\/ul>"},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-26","n":26,"lo":"GenAI-3.2.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following strategies BEST addresses data privacy risks in the context of Generative AI-powered software testing?<\/p>","m":["Using multiple LLMs to evaluate and compare test results for improved accuracy.","Replacing sensitive test data with an anonymized version of the same.","Allowing unrestricted access to sensitive test data to improve Generative AI model training.","Disabling encryption of sensitive test data to streamline data storage and transmission processes."],"vys":{"a":"Is not correct. While evaluating outputs by comparing multiple LLMs is a useful practice, in this case it focuses on output quality in terms of accuracy without addressing data privacy risks.","b":"Is correct. Anonymization is an effective strategy to mitigate data privacy risks.","c":"Is not correct. Unrestricted access to sensitive data increases the risk of sensitive data breach.","d":"Is not correct. Disabling encryption of sensitive data weakens security and increases the risk of sensitive data theft."},"obecne":""},"cz":{"q":"<p>Která z následujících strategií NEJLÉPE řeší rizika pro ochranu dat a soukromí (data privacy) při testování softwaru s pomocí generativní AI?<\/p>","m":["Použití více LLM k vyhodnocení a porovnání výsledků testů kvůli vyšší přesnosti.","Nahrazení citlivých testovacích dat jejich anonymizovanou verzí.","Povolení neomezeného přístupu k citlivým testovacím datům kvůli lepšímu trénování modelu generativní AI.","Vypnutí šifrování citlivých testovacích dat kvůli zjednodušení jejich ukládání a přenosu."],"vys":{"a":"Není správně. Porovnání výstupů více LLM je užitečná praxe, ale zde řeší kvalitu (přesnost) výstupu, ne rizika pro ochranu dat.","b":"Je správně. Anonymizace je účinná strategie ke zmírnění rizik pro ochranu dat a soukromí.","c":"Není správně. Neomezený přístup k citlivým datům zvyšuje riziko jejich úniku.","d":"Není správně. Vypnutí šifrování citlivých dat oslabuje bezpečnost a zvyšuje riziko jejich krádeže."},"obecne":""},"kap":{"c":"3.2.3","nazev":"3.2.3 Jak chránit data a posílit bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-3"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-27","n":27,"lo":"GenAI-3.3.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following options about the impact of LLM usage on energy consumption and CO₂ emission is CORRECT?<\/p>","m":["Image generation tasks consume substantially more energy than text generation tasks, but produce fewer CO₂ emissions.","Generative AI-powered searches consume significantly less energy than traditional web searches due to their optimized algorithms.","Image generation tasks consume substantially more energy than text generation tasks due to their higher computational complexity.","Text generation tasks consume very little energy, allowing them to be performed by millions of users without significant energy consumption."],"vys":{"a":"Is not correct. Image generation is by far much more energy- and CO₂-intensive than text generation. Energy consumption and CO₂ emissions are typically correlated unless a key factor (like energy source differences) is specified.","b":"Is not correct. On the contrary, GenAI-powered searches consume considerably more energy than traditional web searches.","c":"Is correct. Image generation requires significantly more computational resources than text generation, making it much more energy intensive.","d":"Is not correct. The cumulative impact of text generation across millions of users is not negligible."},"obecne":""},"cz":{"q":"<p>Která z následujících možností o dopadu používání LLM na spotřebu energie a emise CO₂ je SPRÁVNÁ?<\/p>","m":["Generování obrázků spotřebuje podstatně více energie než generování textu, ale produkuje méně emisí CO₂.","Vyhledávání pomocí generativní AI spotřebuje díky optimalizovaným algoritmům výrazně méně energie než tradiční webové vyhledávání.","Generování obrázků spotřebuje podstatně více energie než generování textu kvůli vyšší výpočetní náročnosti.","Generování textu spotřebuje velmi málo energie, takže ho mohou využívat miliony uživatelů bez významné spotřeby energie."],"vys":{"a":"Není správně. Generování obrázků je energeticky i emisně mnohem náročnější než generování textu. Spotřeba energie a emise CO₂ spolu obvykle souvisejí, pokud není uveden zásadní rozdíl (např. jiný zdroj energie).","b":"Není správně. Naopak, vyhledávání s generativní AI spotřebuje výrazně více energie než tradiční webové vyhledávání.","c":"Je správně. Generování obrázků vyžaduje výrazně více výpočetních prostředků než generování textu, a je proto energeticky mnohem náročnější.","d":"Není správně. Souhrnný dopad generování textu u milionů uživatelů není zanedbatelný."},"obecne":""},"kap":{"c":"3.3.1","nazev":"3.3.1 Vliv generativní AI na spotřebu energie a emise CO₂","href":"kapitola-3/vyklad.html#oddil-3-3-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-28","n":28,"lo":"GenAI-3.4.1","k":"K1","body":1,"vyber":2,"ok":[1,3],"en":{"q":"<p>Which TWO of the following standards, or parts of them, are MOST relevant to the use of Generative AI in software testing?<\/p>","m":["ISO/IEC 25010:2023","ISO/IEC 23053:2022","ISO/IEC/IEEE 29119-2:2021","ISO/IEC 42001:2023","ISO/IEC/IEEE 29119-3:2021"],"vys":{"a":"Is not correct. ISO/IEC 25010:2023 is a standard (not mentioned in the syllabus, but mentioned in the CTFL syllabus) that defines a product quality model that relate to quality properties of ICT/software products. It does not address the use of GenAI in software testing.","b":"Is correct. ISO/IEC 23053:2022 is a standard (mentioned in section 3.4.1 of the syllabus) that provides a framework for data quality, transparency, and fault tolerance when using GenAI for testing.","c":"Is not correct. ISO/IEC/IEEE 29119-2:2021 is a part (volume) of the standard (not mentioned in the syllabus, but mentioned in the CTFL syllabus) that deals with test processes. It does not address the use of GenAI in software testing.","d":"Is correct. ISO/IEC 42001:2023 is a standard (mentioned in section 3.4.1 of the syllabus) that specifies requirements for managing AI-based systems within an organization, providing best practices for GenAI in software testing and promoting consistency and reliability.","e":"Is not correct. ISO/IEC/IEEE 29119-3:2021 is a part (volume) of the standard (not mentioned in the syllabus, but mentioned in the CTFL syllabus) that deals with test documentation. It does not address the use of GenAI in software testing."},"obecne":""},"cz":{"q":"<p>Které DVA z následujících standardů (nebo jejich částí) jsou pro použití generativní AI v testování softwaru NEJRELEVANTNĚJŠÍ?<\/p>","m":["ISO/IEC 25010:2023","ISO/IEC 23053:2022","ISO/IEC/IEEE 29119-2:2021","ISO/IEC 42001:2023","ISO/IEC/IEEE 29119-3:2021"],"vys":{"a":"Není správně. ISO/IEC 25010:2023 je standard (v tomto sylabu neuvedený, zmiňuje ho sylabus CTFL), který definuje model kvality produktu, tj. charakteristiky kvality ICT a softwarových produktů. Použitím GenAI v testování se nezabývá.","b":"Je správně. ISO/IEC 23053:2022 je standard (uvedený v sylabu 3.4.1), který poskytuje rámec pro kvalitu dat, transparentnost a odolnost vůči chybám při použití GenAI v testování.","c":"Není správně. ISO/IEC/IEEE 29119-2:2021 je část standardu (v tomto sylabu neuvedená, zmiňuje ji sylabus CTFL), která se týká procesů testování. Použitím GenAI v testování se nezabývá.","d":"Je správně. ISO/IEC 42001:2023 je standard (uvedený v sylabu 3.4.1), který stanoví požadavky na řízení systémů AI v organizaci; poskytuje osvědčené postupy pro GenAI v testování a podporuje konzistenci a spolehlivost.","e":"Není správně. ISO/IEC/IEEE 29119-3:2021 je část standardu (v tomto sylabu neuvedená, zmiňuje ji sylabus CTFL), která se týká testovací dokumentace. Použitím GenAI v testování se nezabývá."},"obecne":""},"kap":{"c":"3.4.1","nazev":"3.4.1 Předpisy, standardy a rámce relevantní pro generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-4-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-29","n":29,"lo":"GenAI-4.1.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following components of an LLM-powered testing application is responsible for combining user input with structured and semantically similar data to prepare a prompt for the LLM?<\/p>","m":["Back-end","Front-end","Authentication component","Post-processing component"],"vys":{"a":"Is correct. The back-end is responsible for retrieving data from relational and vector databases, combining it with user input, and preparing the prompt tailored for the LLM.","b":"Is not correct. The front-end serves as the user interface for submitting input, but it does not prepare the prompt for the LLM.","c":"Is not correct. The authentication component ensures secure access but is unrelated to data retrieval or prompt preparation.","d":"Is not correct. The post-processing component refines the output generated by the LLM but does not handle prompt preparation."},"obecne":""},"cz":{"q":"<p>Která z následujících součástí testovací aplikace postavené na LLM odpovídá za spojení vstupu uživatele se strukturovanými a sémanticky podobnými daty a za přípravu promptu pro LLM?<\/p>","m":["Back-end","Front-end","Autentizační komponenta","Komponenta pro následné zpracování (post-processing)"],"vys":{"a":"Je správně. Back-end načítá data z relačních a vektorových databází, spojuje je se vstupem uživatele a připravuje prompt pro LLM.","b":"Není správně. Front-end slouží jako uživatelské rozhraní pro zadání vstupu, prompt pro LLM ale nepřipravuje.","c":"Není správně. Autentizační komponenta zajišťuje bezpečný přístup, s načítáním dat ani přípravou promptu nesouvisí.","d":"Není správně. Komponenta pro následné zpracování upravuje výstup vygenerovaný LLM, přípravu promptu neřeší."},"obecne":""},"kap":{"c":"4.1.1","nazev":"4.1.1 Architektonické komponenty a koncepty","href":"kapitola-4/vyklad.html#oddil-4-1-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-30","n":30,"lo":"GenAI-4.1.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>You are a tester working on a banking application that includes features such as user login, account management, and secure transactions. The system documentation, including API specifications and security requirements, is stored in a vector database, while historical test cases are stored in a relational database. Your task is to generate test cases using a Retrieval-Augmented Generation (RAG) framework to ensure alignment with the latest specifications and requirements.<\/p><p>Which of the following options represents the MOST appropriate use of the RAG framework in this scenario?<\/p>","m":["Submit a query specifying one function to be tested. The RAG framework will retrieve relevant specifications and requirements from the vector database, combine them with historical test cases, and automatically generate accurate and context-aware test cases through the LLM.","Submit a query specifying all functions to be tested. The RAG framework will retrieve relevant specifications and requirements from the vector database, combine them with historical test cases, and automatically generate accurate and context-aware test cases through the LLM.","Use the RAG framework to retrieve historical test cases from the relational database and security requirements from the vector database. Manually review the retrieved information before refining the query for the LLM to generate targeted test cases.","Rely on the LLM’s internal training data to generate test cases while using the RAG framework or reference retrieval without directly integrating retrieved information into the generation process."],"vys":{"a":"Is correct. RAG automatically retrieves the relevant specifications and historical test-case chunks and feeds them to the LLM, which then generates accurate, context-aware test cases.","b":"Is not correct. RAG is better used when asked to retrieve specific targeted information from the vector database and not the whole dataset.","c":"Is not correct. Manually reviewing and refining the query adds unnecessary effort, which contradicts RAG’s design to automate retrieval and use retrieved data dynamically in the LLM’s response generation.","d":"Is not correct. Relying on the LLM’s internal data ignores RAG’s core capability of enhancing responses by integrating external, up-to-date information."},"obecne":""},"cz":{"q":"<p>Jsi tester bankovní aplikace s funkcemi jako přihlášení uživatele, správa účtu a zabezpečené transakce. Systémová dokumentace včetně specifikací API a bezpečnostních požadavků je uložena ve vektorové databázi (vector database), historické testovací případy v relační databázi. Tvým úkolem je vygenerovat testovací případy pomocí frameworku RAG (generování rozšířené o vyhledávání, retrieval-augmented generation) tak, aby odpovídaly nejnovějším specifikacím a požadavkům.<\/p><p>Která z následujících možností představuje NEJVHODNĚJŠÍ použití frameworku RAG v tomto scénáři?<\/p>","m":["Zadat dotaz na jednu testovanou funkci. Framework RAG načte z vektorové databáze relevantní specifikace a požadavky, spojí je s historickými testovacími případy a prostřednictvím LLM automaticky vygeneruje přesné testovací případy s ohledem na kontext.","Zadat dotaz na všechny testované funkce. Framework RAG načte z vektorové databáze relevantní specifikace a požadavky, spojí je s historickými testovacími případy a prostřednictvím LLM automaticky vygeneruje přesné testovací případy s ohledem na kontext.","Pomocí frameworku RAG načíst historické testovací případy z relační databáze a bezpečnostní požadavky z vektorové databáze. Načtené informace ručně zrevidovat a teprve potom upřesnit dotaz pro LLM, aby vygeneroval cílené testovací případy.","Spolehnout se při generování testovacích případů na interní trénovací data LLM a framework RAG nebo vyhledávání referencí použít bez přímého zapojení načtených informací do generování."],"vys":{"a":"Je správně. RAG automaticky načte relevantní části specifikací a historických testovacích případů a předá je LLM, který pak vygeneruje přesné testovací případy s ohledem na kontext.","b":"Není správně. RAG se lépe uplatní při načítání konkrétních cílených informací z vektorové databáze, ne celé datové sady.","c":"Není správně. Ruční revize a upřesňování dotazu přidává zbytečnou práci a odporuje principu RAG, který vyhledávání automatizuje a načtená data dynamicky použije při generování odpovědi.","d":"Není správně. Spoléhání na interní data LLM ignoruje hlavní přínos RAG: obohacení odpovědí o externí aktuální informace."},"obecne":""},"kap":{"c":"4.1.2","nazev":"4.1.2 Retrieval-Augmented Generation (RAG)","href":"kapitola-4/vyklad.html#oddil-4-1-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-31","n":31,"lo":"GenAI-4.1.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following options BEST describes the enhancements that autonomous and semi-autonomous LLM-powered agents bring to automating test processes?<\/p>","m":["They can enhance both efficiency and quality in automating test processes through a balanced use of single-agent and multi-agent systems.","They can enhance quality in automating test processes by adding complex verification checks although at the expense of efficiency.","They can enhance both efficiency and quality in automating test processes by leveraging their ability to operate with varying levels of human interaction.","They can enhance both efficiency and quality in automating test processes while eliminating the need for verification within these test processes."],"vys":{"a":"Is not correct. Autonomous and semi-autonomous agents can be implemented as single-agent and/or multi-agent systems to improve both efficiency and quality in test processes. However, the key enhancements that these agents bring refer to increased efficiency and quality in test processes due to their ability to balance autonomy with human oversight.","b":"Is not correct. While autonomous and semi-autonomous agents incorporate verifications to ensure quality, these verifications are also designed to be efficient. The use of automated checks actually aims to streamline the test processes and enhance quality without sacrificing efficiency (and vice versa) which, in turn, is also enhanced.","c":"Is correct. Autonomous agents increase efficiency by executing test tasks within the test processes with minimal human intervention and by using automated checks designed to be efficient. Semi-autonomous agents involve strategic human oversight, which ensures the quality of test results. These two types of agents allow implementing a balanced approach to achieve both efficiency and quality by leveraging their ability to operate with varying levels of human interaction.","d":"Is not correct. The complete elimination of verification is neither realistic nor desirable. Verification remains crucial even when using advanced technologies like autonomous and semi-autonomous LLM-powered agents."},"obecne":""},"cz":{"q":"<p>Která z následujících možností NEJLÉPE popisuje zlepšení, která do automatizace procesů testování přinášejí autonomní a poloautonomní agenti postavení na LLM (LLM-powered agents)?<\/p>","m":["Mohou zvýšit efektivitu i kvalitu automatizace procesů testování vyváženým využitím jednoagentních a multiagentních systémů.","Mohou zvýšit kvalitu automatizace procesů testování přidáním složitých ověřovacích kontrol, i když na úkor efektivity.","Mohou zvýšit efektivitu i kvalitu automatizace procesů testování díky schopnosti fungovat s různou mírou lidské interakce.","Mohou zvýšit efektivitu i kvalitu automatizace procesů testování a zároveň v nich odstranit potřebu ověřování."],"vys":{"a":"Není správně. Autonomní i poloautonomní agenti mohou být realizováni jako jednoagentní nebo multiagentní systémy a zlepšit efektivitu i kvalitu. Hlavní přínos ale plyne z toho, že vyvažují autonomii s lidským dohledem.","b":"Není správně. Agenti sice obsahují ověřování kvůli kvalitě, ale i to je navrženo efektivně. Automatické kontroly mají procesy testování zefektivnit a zlepšit kvalitu bez obětování efektivity (a naopak), takže roste i efektivita.","c":"Je správně. Autonomní agenti zvyšují efektivitu tím, že provádějí testovací úlohy s minimálním lidským zásahem a s efektivními automatickými kontrolami. Poloautonomní agenti zahrnují strategický lidský dohled, který zajišťuje kvalitu výsledků. Oba typy umožňují vyvážený přístup, který díky různé míře lidské interakce dosáhne efektivity i kvality.","d":"Není správně. Úplné odstranění ověřování není realistické ani žádoucí. Ověřování zůstává zásadní i u pokročilých technologií, jako jsou autonomní a poloautonomní agenti postavení na LLM."},"obecne":""},"kap":{"c":"4.1.3","nazev":"4.1.3 Agenti postavení na LLM v automatizaci testovacích procesů","href":"kapitola-4/vyklad.html#oddil-4-1-3"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-32","n":32,"lo":"GenAI-4.2.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following statements about fine-tuning language models for specific test tasks is INCORRECT?<\/p>","m":["Fine-tuning involves training a pre-trained model on task-specific data to enhance its performance and domain knowledge.","Fine-tuning equips a language model with new capabilities by replacing its general knowledge with task-specific reasoning, ensuring the absence of overfitting.","Fine-tuning modifies a pre-trained model’s parameters using a targeted dataset to adapt it for a specific domain or task.","Fine-tuning requires high-quality, task-specific datasets to avoid biased or inaccurate results."],"vys":{"a":"Is not correct. This is a correct description of fine-tuning, which enhances a model’s performance in a specific domain through task-specific training.","b":"Is correct. This statement is incorrect because fine-tuning does not replace the model's general knowledge, and overfitting remains a potential challenge.","c":"Is not correct. This is a correct description, as fine-tuning involves parameter adjustment using targeted datasets.","d":"Is not correct. This is a correct description of the challenges associated with fine-tuning, as high-quality datasets are crucial for effective adaptation."},"obecne":""},"cz":{"q":"<p>Které z následujících tvrzení o fine-tuningu (doladění) jazykových modelů pro konkrétní testovací úlohy je NESPRÁVNÉ?<\/p>","m":["Fine-tuning znamená trénování předtrénovaného modelu na datech specifických pro úlohu, aby se zlepšil jeho výkon a doménové znalosti.","Fine-tuning dává jazykovému modelu nové schopnosti tím, že nahradí jeho obecné znalosti uvažováním specifickým pro úlohu, a zaručí tak, že nedojde k přeučení (overfitting).","Fine-tuning mění parametry předtrénovaného modelu pomocí cílené datové sady, aby se model přizpůsobil konkrétní doméně nebo úloze.","Fine-tuning vyžaduje kvalitní datové sady specifické pro úlohu, aby se předešlo zkresleným nebo nepřesným výsledkům."],"vys":{"a":"Není správně (tvrzení platí). Je to správný popis fine-tuningu, který zlepšuje výkon modelu v konkrétní doméně trénováním na úloze.","b":"Je správně (tvrzení je nesprávné). Fine-tuning nenahrazuje obecné znalosti modelu a přeučení zůstává možným problémem.","c":"Není správně (tvrzení platí). Je to správný popis: fine-tuning upravuje parametry pomocí cílených datových sad.","d":"Není správně (tvrzení platí). Je to správný popis výzev fine-tuningu: pro účinné přizpůsobení jsou kvalitní datové sady zásadní."},"obecne":""},"kap":{"c":"4.2.1","nazev":"4.2.1 Fine-tuning LLM pro testovací úlohy","href":"kapitola-4/vyklad.html#oddil-4-2-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-33","n":33,"lo":"GenAI-4.2.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following BEST describes the primary focus of Large Language Model Operations (LLMOps) when deploying and managing LLMs for test tasks?<\/p>","m":["Preventing reliance on Generative AI in test processes.","Managing LLMs effectively across their lifecycle, including privacy, security, and cost considerations.","Limiting LLM usage to chatbot-based testing solutions to reduce complexity.","Fully automating all test tasks without requiring human oversight."],"vys":{"a":"Is not correct. Large Language Model Operations (LLMOps) focuses on managing LLMs, not preventing their use.","b":"Is correct. LLMOps manages LLMs across their lifecycle, addressing privacy, security, and cost for testing.","c":"Is not correct. LLMOps applies to various applications, not just chatbot-based solutions.","d":"Is not correct. LLMOps does not aim to fully automate all test tasks or eliminate human oversight."},"obecne":""},"cz":{"q":"<p>Co NEJLÉPE popisuje hlavní zaměření LLMOps (Large Language Model Operations) při nasazování a správě LLM pro testovací úlohy?<\/p>","m":["Zabránit spoléhání na generativní AI v procesech testování.","Efektivně spravovat LLM během celého životního cyklu, včetně ohledů na ochranu dat, bezpečnost a náklady.","Omezit použití LLM na testovací řešení založená na chatbotech kvůli nižší složitosti.","Plně automatizovat všechny testovací úlohy bez potřeby lidského dohledu."],"vys":{"a":"Není správně. LLMOps se zaměřuje na správu LLM, ne na zabránění jejich použití.","b":"Je správně. LLMOps spravuje LLM během celého životního cyklu a řeší ochranu dat, bezpečnost a náklady při testování.","c":"Není správně. LLMOps se týká různých aplikací, nejen řešení založených na chatbotech.","d":"Není správně. Cílem LLMOps není plně automatizovat všechny testovací úlohy ani odstranit lidský dohled."},"obecne":""},"kap":{"c":"4.2.2","nazev":"4.2.2 LLMOps při nasazení a správě LLM pro testování","href":"kapitola-4/vyklad.html#oddil-4-2-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-34","n":34,"lo":"GenAI-5.1.1","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>Which of the following statements about shadow AI is CORRECT?<\/p>","m":["Shadow AI enforces compliance with organizational data policies and general AI regulations.","Shadow AI eliminates the need for clear licensing agreements in AI tools.","Shadow AI reduces the risk of intellectual property disputes.","Shadow AI may lead to unauthorized accesses to sensitive information."],"vys":{"a":"Is not correct. Using unapproved GenAI tools does not enforce organizational data policies.","b":"Is not correct. Shadow AI introduces risks related to unclear licensing agreements, which can lead to intellectual property disputes.","c":"Is not correct. Shadow AI increases, rather than reduces, the risk of intellectual property disputes.","d":"Is correct. Unapproved AI tools often lack robust security measures, increasing the risk of data breaches or unauthorized access."},"obecne":""},"cz":{"q":"<p>Které z následujících tvrzení o stínové AI (shadow AI) je SPRÁVNÉ?<\/p>","m":["Stínová AI vynucuje dodržování datových politik organizace a obecných předpisů pro AI.","Stínová AI odstraňuje potřebu jasných licenčních ujednání u nástrojů AI.","Stínová AI snižuje riziko sporů o duševní vlastnictví.","Stínová AI může vést k neoprávněnému přístupu k citlivým informacím."],"vys":{"a":"Není správně. Používání neschválených nástrojů GenAI datové politiky organizace nevynucuje.","b":"Není správně. Stínová AI přináší rizika nejasných licenčních ujednání, která mohou vést ke sporům o duševní vlastnictví.","c":"Není správně. Stínová AI riziko sporů o duševní vlastnictví zvyšuje, ne snižuje.","d":"Je správně. Neschválené nástroje AI často nemají dostatečné zabezpečení, a zvyšují tak riziko úniku dat nebo neoprávněného přístupu."},"obecne":""},"kap":{"c":"5.1.1","nazev":"5.1.1 Rizika stínové AI","href":"kapitola-5/vyklad.html#oddil-5-1-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-35","n":35,"lo":"GenAI-5.1.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>What is a key aspect to consider when defining a Generative AI strategy for software testing?<\/p>","m":["Prepare training programs designed to ensure that team members obtain certifications specific to each LLM they use.","Select LLMs that can be integrated appropriately with existing test environments and test tools.","Ensure that as much input data as possible is available to increase the likelihood of obtaining effective LLM outputs.","Collect standard supervised machine learning metrics to evaluate the effectiveness of LLM outputs."],"vys":{"a":"Is not correct. While certifications for specific LLMs could be useful (and more available in the future), training programs should be designed to ensure that test team members have the technical skills necessary to use GenAI tools effectively.","b":"Is correct. Selecting LLMs that are compatible with existing test infrastructure and scalability requirements is a critical aspect of a GenAI strategy. Test tools and test environments are fundamental elements of test infrastructure.","c":"Is not correct. Data quality and structured, secure input are crucial for achieving reliable results with GenAI. It is necessary to have an adequate amount of high-quality input data (according to the test objectives), not as much data as possible.","d":"Is not correct. Section 5.1.2 states that a GenAI strategy for software testing must collect task-specific metrics to measure the effectiveness of LLM outputs. The metrics listed in section 2.3.1 (e.g., relevance, execution-success rate, time efficiency) are tailored to test tasks rather than borrowed wholesale from classical supervised-machine learning."},"obecne":""},"cz":{"q":"<p>Jaký je klíčový aspekt, který je třeba zvážit při definování strategie generativní AI pro testování softwaru?<\/p>","m":["Připravit školicí programy, které zajistí, že členové týmu získají certifikace pro každý LLM, který používají.","Vybrat LLM, které lze vhodně integrovat se stávajícími testovacími prostředími a testovacími nástroji.","Zajistit co nejvíce vstupních dat, aby byla větší šance na účinné výstupy LLM.","Sbírat standardní metriky strojového učení s učitelem (supervised learning) k vyhodnocení účinnosti výstupů LLM."],"vys":{"a":"Není správně. Certifikace pro konkrétní LLM by mohly být užitečné (a v budoucnu dostupnější), ale školicí programy mají zajistit, aby členové týmu měli technické dovednosti potřebné k efektivnímu používání nástrojů GenAI.","b":"Je správně. Výběr LLM kompatibilních se stávající testovací infrastrukturou a s požadavky na škálovatelnost je zásadní součástí strategie GenAI. Testovací nástroje a testovací prostředí jsou základními prvky testovací infrastruktury.","c":"Není správně. Pro spolehlivé výsledky GenAI je zásadní kvalita dat a strukturovaný, zabezpečený vstup. Potřeba je přiměřené množství kvalitních vstupních dat (podle cílů testování), ne co nejvíce dat.","d":"Není správně. Oddíl 5.1.2 uvádí, že strategie GenAI má sbírat metriky specifické pro úlohy, které měří účinnost výstupů LLM. Metriky z oddílu 2.3.1 (např. relevance, míra úspěšnosti provedení, časová efektivita) jsou šité na testovací úlohy, nejsou převzaté z klasického strojového učení s učitelem."},"obecne":""},"kap":{"c":"5.1.2","nazev":"5.1.2 Klíčové aspekty strategie GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-36","n":36,"lo":"GenAI-5.1.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following statements BEST describes one of the key criteria to select an appropriate LLM for specific test tasks within a test organization?<\/p>","m":["A key selection criterion involves evaluating the LLM’s performance for the test tasks against the publicly available benchmarks for LLMs in code generation.","A key selection criterion involves evaluating recurring costs such as those associated with the computational resources required to run the LLM.","A key selection criterion involves evaluating the LLM against the publicly available community benchmarks to ensure full compatibility with them.","A key selection criterion involves evaluating recurring costs such as those associated with a proof of concept aimed at demonstrating the suitability of an LLM for the test tasks."],"vys":{"a":"Is not correct. A key selection criterion involves evaluating the model’s performance for the test tasks against the organization's benchmarks using metrics such as those presented in the syllabus itself (see the syllabus in section 5.1.3). The specified criterion may be relevant if the test tasks involve code generation. However, it is not applicable for other types of test tasks.","b":"Is correct. A key selection criterion involves evaluating recurring costs (see the syllabus in section 5.1.3), and this answer refers to a typical example of a recurring cost.","c":"Is not correct. Evaluating the LLM against the publicly available community benchmarks to ensure full compatibility with them is not one of the key criteria mentioned in the syllabus (in section 5.1.3) for selecting an appropriate LLM for specific test tasks.","d":"Is not correct. A key selection criterion involves evaluating recurring costs (see the syllabus in section 5.1.3), but this answer refers to a typical example of a non-recurring cost."},"obecne":""},"cz":{"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje jedno z klíčových kritérií pro výběr vhodného LLM pro konkrétní testovací úlohy v testovací organizaci?<\/p>","m":["Klíčovým kritériem je vyhodnocení výkonu LLM pro testovací úlohy vůči veřejně dostupným benchmarkům LLM pro generování kódu.","Klíčovým kritériem je vyhodnocení opakovaných nákladů, například nákladů na výpočetní prostředky potřebné k provozu LLM.","Klíčovým kritériem je vyhodnocení LLM vůči veřejně dostupným komunitním benchmarkům, aby s nimi byl plně kompatibilní.","Klíčovým kritériem je vyhodnocení opakovaných nákladů, například nákladů na proof of concept, který má prokázat vhodnost LLM pro testovací úlohy."],"vys":{"a":"Není správně. Klíčovým kritériem je vyhodnocení výkonu modelu pro testovací úlohy vůči benchmarkům organizace s metrikami, jaké uvádí sám sylabus (viz 5.1.3). Uvedené kritérium může být relevantní, pokud testovací úlohy zahrnují generování kódu, pro jiné typy úloh ale neplatí.","b":"Je správně. Klíčovým kritériem je vyhodnocení opakovaných nákladů (recurring cost, viz sylabus 5.1.3) a tato odpověď uvádí typický příklad opakovaného nákladu.","c":"Není správně. Vyhodnocení vůči veřejným komunitním benchmarkům kvůli plné kompatibilitě s nimi nepatří mezi klíčová kritéria, která sylabus v 5.1.3 uvádí.","d":"Není správně. Klíčovým kritériem je sice vyhodnocení opakovaných nákladů (viz 5.1.3), ale tato odpověď uvádí typický příklad jednorázového nákladu."},"obecne":""},"kap":{"c":"5.1.3","nazev":"5.1.3 Výběr LLM/SLM pro testovací úlohy","href":"kapitola-5/vyklad.html#oddil-5-1-3"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-37","n":37,"lo":"GenAI-5.1.4","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>What are the key phases in the adoption of Generative AI in a test organization?<\/p>","m":["Discovery, initiation and usage definition, utilization and iteration","Awareness, usage prioritization, performance monitoring","Planning, experimentation, evaluation and refinement","Training, testing, implementation, and scaling"],"vys":{"a":"Is correct: explicitly mentions all these 3 key phases.","b":"Is not correct: does not explicitly mention any of these 3 phases (only mentions some objectives and/or activities associated with these phases).","c":"Is not correct: does not explicitly mention any of these 3 phases (only mentions some objectives and/or activities associated with these phases).","d":"Is not correct: does not explicitly mention any of these 3 phases (only mentions some objectives and/or activities associated with these phases)."},"obecne":"<p>The syllabus describes the following 3 key phases:<\/p><ul><li>Discovery<\/li><li>Initiation and usage definition<\/li><li>Utilization and iteration<\/li><\/ul>"},"cz":{"q":"<p>Jaké jsou klíčové fáze zavádění generativní AI v testovací organizaci?<\/p>","m":["Objevování (discovery), zahájení a definice použití (initiation and usage definition), využití a iterace (utilization and iteration)","Povědomí, prioritizace použití, monitorování výkonu","Plánování, experimentování, vyhodnocení a zdokonalení","Školení, testování, implementace a škálování"],"vys":{"a":"Je správně: výslovně uvádí všechny 3 klíčové fáze.","b":"Není správně: neuvádí výslovně žádnou ze 3 fází (zmiňuje jen některé cíle nebo činnosti, které k fázím patří).","c":"Není správně: neuvádí výslovně žádnou ze 3 fází (zmiňuje jen některé cíle nebo činnosti, které k fázím patří).","d":"Není správně: neuvádí výslovně žádnou ze 3 fází (zmiňuje jen některé cíle nebo činnosti, které k fázím patří)."},"obecne":"<p>Sylabus popisuje tyto 3 klíčové fáze:<\/p><ul><li>Objevování (discovery)<\/li><li>Zahájení a definice použití (initiation and usage definition)<\/li><li>Využití a iterace (utilization and iteration)<\/li><\/ul>"},"kap":{"c":"5.1.4","nazev":"5.1.4 Fáze zavedení GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-4"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-38","n":38,"lo":"GenAI-5.2.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following options BEST refers to an example of knowledge and/or skills required for testers to work effectively with LLMs in test processes?<\/p>","m":["Mastering techniques specifically aimed at preventing LLMs from hallucinating and incurring reasoning errors when performing specific test tasks.","Selecting and implementing suitable test automation approaches, such as keyword-driven test automation, for automating test processes.","Choosing the most appropriate LLM based on criteria such as its capability to be adapted or customized to perform specific test tasks.","Ensuring the validation and test data used in the development of the LLMs are of the highest quality."],"vys":{"a":"Is not correct. Hallucinations in LLMs are intrinsic challenges with current AI technologies, and testers cannot prevent hallucinations and reasoning errors from occurring. Instead, testers should be able to (identify and) mitigate the risks of hallucinations and reasoning errors (and also biases) when testing with GenAI.","b":"Is not correct. While proficiency in test automation is valuable, it does not specifically address the integration of GenAI into test processes.","c":"Is correct. The syllabus names “assessing LLM capabilities” as a key competency. This naturally entails comparing candidate models and selecting the one that can be adapted or fine-tuned for particular test tasks. That is a direct example of knowledge/skills testers need to work effectively with LLMs.","d":"Is not correct. It refers to skills that are required for developing the LLMs such as AI researchers and data scientists, not testers using GenAI for test tasks. These testers focus on ensuring the quality of the test data they directly use when interacting with LLMs."},"obecne":""},"cz":{"q":"<p>Která z následujících možností NEJLÉPE uvádí příklad znalostí nebo dovedností, které testeři potřebují k efektivní práci s LLM v procesech testování?<\/p>","m":["Zvládnutí technik, které mají zabránit tomu, aby LLM při konkrétních testovacích úlohách halucinovaly a dělaly chyby v uvažování.","Výběr a zavedení vhodných přístupů k automatizaci testů, například automatizace testů řízené klíčovými slovy (keyword-driven), pro automatizaci procesů testování.","Výběr nejvhodnějšího LLM podle kritérií, jako je možnost ho přizpůsobit pro konkrétní testovací úlohy.","Zajištění nejvyšší kvality validačních a testovacích dat použitých při vývoji LLM."],"vys":{"a":"Není správně. Halucinace jsou vlastní dnešním technologiím AI a testeři jejich vzniku ani chybám v uvažování zabránit nemohou. Mají umět rizika halucinací, chyb v uvažování (a také zkreslení) při testování s GenAI rozpoznat a zmírnit.","b":"Není správně. Znalost automatizace testů je cenná, ale netýká se konkrétně začlenění GenAI do procesů testování.","c":"Je správně. Sylabus uvádí „posuzování schopností LLM“ (assessing LLM capabilities) jako klíčovou kompetenci. K tomu přirozeně patří porovnání kandidátních modelů a výběr toho, který lze přizpůsobit nebo doladit (fine-tuning) pro konkrétní testovací úlohy. To je přímý příklad znalostí a dovedností pro efektivní práci s LLM.","d":"Není správně. Jde o dovednosti potřebné při vývoji LLM (výzkumníci AI, datoví vědci), ne pro testery, kteří GenAI používají k testovacím úlohám. Ti dbají na kvalitu testovacích dat, která sami při práci s LLM používají."},"obecne":""},"kap":{"c":"5.2.1","nazev":"5.2.1 Dovednosti a znalosti pro testování s GenAI","href":"kapitola-5/vyklad.html#oddil-5-2-1"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-39","n":39,"lo":"GenAI-5.2.2","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>What is the BEST approach for cultivating skills within test teams to specifically support the adoption of Generative AI?<\/p>","m":["Rely mainly on external expert courses with hands-on practice, aiming to integrate AI into all daily test tasks at once.","Encourage independent experimentation with various LLMs without following a structured process.","Adopt a hands-on, gradual learning process supported by guided exercises, peer learning, and knowledge-sharing communities.","Rely mainly on theoretical courses from external experts, aiming to gradually integrate AI into daily test tasks in line with actual learning."],"vys":{"a":"Is not correct. While external expert courses with hands-on practice can be beneficial, mainly relying on them diminishes the importance of internal practice and community building. Moreover, integrating AI into all daily test tasks in a ‘big-bang’ fashion is not recommended.","b":"Is not correct. While experimentation is part of the learning process, independent experimentation without structure may not lead to consistent or effective skill development.","c":"Is correct. Focusing on developing practical skills through structured activities, peer learning, and knowledge-sharing communities is a recommended approach.","d":"Is not correct. Mainly relying on theoretical courses from external experts diminishes the importance of developing practical skills and know-how through sharing within the organization."},"obecne":""},"cz":{"q":"<p>Jaký je NEJLEPŠÍ přístup k rozvoji dovedností v testovacích týmech, který konkrétně podpoří zavádění generativní AI?<\/p>","m":["Spoléhat hlavně na externí odborné kurzy s praktickým cvičením a zavést AI do všech každodenních testovacích úloh najednou.","Podporovat samostatné experimentování s různými LLM bez strukturovaného postupu.","Zvolit praktický, postupný proces učení podpořený řízenými cvičeními, učením od kolegů a komunitami pro sdílení znalostí.","Spoléhat hlavně na teoretické kurzy externích odborníků a zavádět AI do každodenních testovacích úloh postupně podle skutečného pokroku v učení."],"vys":{"a":"Není správně. Externí kurzy s praktickým cvičením mohou být přínosné, ale spoléhání hlavně na ně snižuje význam interní praxe a budování komunity. Zavedení AI do všech každodenních úloh najednou („big bang“) se navíc nedoporučuje.","b":"Není správně. Experimentování k učení patří, ale samostatné experimentování bez struktury nemusí vést ke konzistentnímu ani účinnému rozvoji dovedností.","c":"Je správně. Doporučeným přístupem je rozvoj praktických dovedností pomocí strukturovaných činností, učení od kolegů a komunit pro sdílení znalostí.","d":"Není správně. Spoléhání hlavně na teoretické kurzy externích odborníků snižuje význam praktických dovedností a know-how, které vzniká sdílením uvnitř organizace."},"obecne":""},"kap":{"c":"5.2.2","nazev":"5.2.2 Budování schopností GenAI v testovacích týmech","href":"kapitola-5/vyklad.html#oddil-5-2-2"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""},{"id":"A-40","n":40,"lo":"GenAI-5.2.3","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following answers BEST describes how the roles and responsibilities of testers and test managers within a test organization are impacted by the adoption of Generative AI for software testing?<\/p>","m":["Testers shift their focus from manually designing test cases to guiding and verifying AI-generated testware.","Test managers shift their focus from managing test projects to understanding the inner working of Generative AI technologies.","Testers shift their focus from manually designing test cases to overseeing AI-based test processes.","Test managers shift their focus from relying on people to relying solely on Generative AI to boost productivity in test tasks."],"vys":{"a":"Is correct. Testers evolve into AI-assisted testing specialists, refining prompts and verifying AI outputs.","b":"Is not correct. The responsibilities of the test managers are updated to include the development of an AI-based test strategy, AI-based risk management, and oversight of AI-based test processes. Thus, their focus is still on test management and not on understanding the (technically complex) inner workings of GenAI technologies.","c":"Is not correct. Testers do not shift their focus to overseeing AI-based test processes. This oversight is the responsibility of test managers.","d":"Is not correct. Test managers must balance human and AI capabilities to achieve efficient results."},"obecne":""},"cz":{"q":"<p>Která z následujících odpovědí NEJLÉPE popisuje, jak zavedení generativní AI do testování softwaru ovlivní role a odpovědnosti testerů a test manažerů v testovací organizaci?<\/p>","m":["Testeři přesouvají pozornost od ručního návrhu testovacích případů k navádění a ověřování testwaru vygenerovaného AI.","Test manažeři přesouvají pozornost od řízení testovacích projektů k pochopení vnitřního fungování technologií generativní AI.","Testeři přesouvají pozornost od ručního návrhu testovacích případů k dohledu nad procesy testování založenými na AI.","Test manažeři přesouvají pozornost od spoléhání na lidi ke spoléhání výhradně na generativní AI kvůli vyšší produktivitě testovacích úloh."],"vys":{"a":"Je správně. Testeři se mění ve specialisty na testování s podporou AI: zdokonalují prompty a ověřují výstupy AI.","b":"Není správně. Odpovědnosti test manažerů se rozšiřují o tvorbu testovací strategie s AI, řízení rizik s AI a dohled nad procesy testování založenými na AI. Jejich pozornost tedy zůstává u řízení testování, ne u (technicky složitého) vnitřního fungování technologií GenAI.","c":"Není správně. Testeři nepřesouvají pozornost k dohledu nad procesy testování založenými na AI. Tento dohled je odpovědností test manažerů.","d":"Není správně. Test manažeři musejí vyvažovat lidské schopnosti a schopnosti AI, aby dosáhli efektivních výsledků."},"obecne":""},"kap":{"c":"5.2.3","nazev":"5.2.3 Vývoj testovacích procesů v organizaci podporované AI","href":"kapitola-5/vyklad.html#oddil-5-2-3"},"zdroj":"ISTQB® Sample Exam A v1.1","oficialni":true,"navic":false,"pozn":""}]};
